INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13259, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们应该努力塑造一只良好的国际形象。", "corrected_sentence": "我们应该努力塑造一个良好的国际形象。", "error_description": "错误：“一只国际形象”。正确：“一个国际形象”。“形象”是抽象名词，用量词“个”；“只”多用于动物或成对物品中的一个。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a0befb2-7c0f-481b-b847-2f8872445ee7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13260, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7c6b85f-3bc5-496a-a14b-a563be0173e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13260, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7c6b85f-3bc5-496a-a14b-a563be0173e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13260, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "指事物具有代表、体现某种抽象意义或性质的特点。", "primary_collocate": null, "pronunciation": "xiàng zhēng xìng", "ipa": "ɕjɑŋ˥˩ ʈʂɤŋ˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "从全球趋势看，一次性塑料禁令已超越环境议题本身，演变为国家治理能力与国际形象的象征性场域。", "target_word": "象征性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "风车作为中世纪最具象征性的技术装置，通过叶片捕捉气流动能，驱动磨坊碾磨谷物或抽排沼泽积水。", "target_word": "象征性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这座桥具有很强的象征性。", "target_word": "象征性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白鸽的象征性大家都明白，它代表和平。", "target_word": "象征性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画最有象征性的地方是那棵树。", "target_word": "象征性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红色在婚礼上有特别的象征性。", "target_word": "象征性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国旗的象征性比它的价格重要得多。", "target_word": "象征性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个雕像的象征性很明显，它代表勇气。", "target_word": "象征性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说，这个仪式的象征性很大。", "target_word": "象征性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "龙对中国人来说有很深的象征性。", "target_word": "象征性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "象征性的", "label": "复合"}, {"form": "象徵性", "label": "繁体"}], "register": "书面", "sense_fingerprint": "事物代表某种抽象意义的特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b3bbd23-8942-4e8f-b366-768ba894f710') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13260, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "象征性", "is_correct": true, "explanation": "“象征性”指事物代表抽象意义，“场域”在此指代表国家治理与国际形象的抽象含义，语义吻合。"}, {"text": "实用性", "is_correct": false, "explanation": "语义：“实用性”指有实际用处，与句中“代表国家治理能力与国际形象”的抽象意义不符。"}, {"text": "季节性", "is_correct": false, "explanation": "语义：“季节性”指随季节变化，句中讲的是政策的抽象意义，与时令无关。"}, {"text": "时效性", "is_correct": false, "explanation": "搭配：“时效性”多修饰信息、政策的有效期，不修饰“场域”这类空间概念。"}], "explanations": {"象征性": "“象征性”指事物代表抽象意义，“场域”在此指代表国家治理与国际形象的抽象含义，语义吻合。", "实用性": "语义：“实用性”指有实际用处，与句中“代表国家治理能力与国际形象”的抽象意义不符。", "季节性": "语义：“季节性”指随季节变化，句中讲的是政策的抽象意义，与时令无关。", "时效性": "搭配：“时效性”多修饰信息、政策的有效期，不修饰“场域”这类空间概念。"}, "sentence_index": 0, "correct_answer": "象征性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次选出的样本很有象征性，能反映整个城市的情况。", "explanation": "这里应该用〈代表性〉。“象征性”指代表抽象意义，“反映整体情况”要用“代表性”。"}, {"text": "这种农具的象征性很强，农民都愿意买。", "explanation": "这里应该用〈实用性〉。“象征性”指代表抽象意义，农具好不好用要看实用性，不能这样用。"}, {"text": "这台仪器的象征性很高，测量结果非常可靠。", "explanation": "这里应该用〈精确性〉。仪器的好坏看精确程度，“象征性”说的是代表意义，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7c6b85f-3bc5-496a-a14b-a563be0173e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13260, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "象征性", "is_correct": true, "explanation": "“象征性”作主语中心语，说国旗代表的抽象意义，与句意“比价格重要”相符。"}, {"text": "放射性", "is_correct": false, "explanation": "语义：“放射性”指物质释放射线的性质，与国旗无关。"}, {"text": "精密性", "is_correct": false, "explanation": "语义：“精密性”指测量或制造的精确程度，不能用来衡量国旗的象征意义。"}, {"text": "流动性", "is_correct": false, "explanation": "搭配：“流动性”多用于资金、人口，不修饰国旗这类物件。"}], "explanations": {"象征性": "“象征性”作主语中心语，说国旗代表的抽象意义，与句意“比价格重要”相符。", "放射性": "语义：“放射性”指物质释放射线的性质，与国旗无关。", "精密性": "语义：“精密性”指测量或制造的精确程度，不能用来衡量国旗的象征意义。", "流动性": "搭配：“流动性”多用于资金、人口，不修饰国旗这类物件。"}, "sentence_index": 6, "correct_answer": "象征性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种车的象征性很好，油耗很低。", "explanation": "这里应该用〈经济性〉。“象征性”指代表抽象意义，油耗低说明的是经济性，不能这样用。"}, {"text": "这款软件的象征性很强，很少出问题。", "explanation": "这里应该用〈稳定性〉。“象征性”指代表抽象意义，软件很少出问题说明的是稳定性，不能这样用。"}, {"text": "这块布料的象征性很好，穿很久都不坏。", "explanation": "这里应该用〈耐用性〉。“象征性”指代表抽象意义，穿很久不坏说明的是耐用性，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7c6b85f-3bc5-496a-a14b-a563be0173e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13260, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座塔地象征性很强，代表着城市的历史。", "corrected_sentence": "这座塔的象征性很强，代表着城市的历史。", "error_description": "错误：结构助词用错。“这座塔”作定语修饰“象征性”，中间应用“的”，应说“这座塔的象征性很强”，不能用“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7c6b85f-3bc5-496a-a14b-a563be0173e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13260, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这面旗帜的象征性地很强，代表着民族的团结。", "corrected_sentence": "这面旗帜的象征性很强，代表着民族的团结。", "error_description": "“地”错误：此处“象征性”是名词，作“的”字短语的中心语，后面不能加“地”（“象征性地”只作状语修饰动词，如“象征性地抗议”）。应去掉“地”，为“这面旗帜的象征性很强”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7c6b85f-3bc5-496a-a14b-a563be0173e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
