INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13262, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "双方通过协商达成协议或条约。", "primary_collocate": null, "pronunciation": "dì jié", "ipa": "ti˥˩ tɕjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "联合国环境规划署（UNEP）多次呼吁缔结具有法律约束力的全球协议，旨在建立跨国监管协调机制，遏制塑料污染的跨境转移。", "target_word": "缔结", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "两国代表今天在北京缔结了和平条约。", "target_word": "缔结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两个国家想缔结新的贸易协定。", "target_word": "缔结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战争结束后，双方缔结了停战协议。", "target_word": "缔结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "几个小国为了保护自己，决定缔结同盟。", "target_word": "缔结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份条约是一百年前由三国缔结的。", "target_word": "缔结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中国和很多国家缔结过友好条约。", "target_word": "缔结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "条约一旦缔结，两国都必须遵守。", "target_word": "缔结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家之间缔结条约，必须经过认真的谈判。", "target_word": "缔结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把两国缔结的协议翻译成了三种语言。", "target_word": "缔结", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "缔结了", "label": "体标"}, {"form": "缔结过", "label": "体标"}, {"form": "締結", "label": "繁体"}], "register": "书面", "sense_fingerprint": "双方经协商正式订立条约或协议（缔结条约）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1be5a6e3-5db9-4be7-88db-c287895b77cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13262, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "缔结", "is_correct": true, "explanation": "正确：「呼吁缔结」指促成双方订立协议，与「旨在建立跨国监管协调机制」的目标一致。"}, {"text": "撕毁", "is_correct": false, "explanation": "语义：呼吁撕毁具有法律约束力的协议，与「旨在建立跨国监管协调机制、遏制污染」的目的相反。"}, {"text": "发表", "is_correct": false, "explanation": "搭配：「发表」用于声明、文章，不能说发表协议。"}, {"text": "违反", "is_correct": false, "explanation": "语义：没有人会呼吁违反具有约束力的协议，这与「呼吁」的用意相矛盾。"}], "explanations": {"缔结": "正确：「呼吁缔结」指促成双方订立协议，与「旨在建立跨国监管协调机制」的目标一致。", "撕毁": "语义：呼吁撕毁具有法律约束力的协议，与「旨在建立跨国监管协调机制、遏制污染」的目的相反。", "发表": "搭配：「发表」用于声明、文章，不能说发表协议。", "违反": "语义：没有人会呼吁违反具有约束力的协议，这与「呼吁」的用意相矛盾。"}, "sentence_index": 0, "correct_answer": "缔结"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天晚上都要缔结作业，然后才去睡觉。", "explanation": "这里应该用〈完成〉。缔结指双方经协商订立条约或协议，作业不能缔结，应说完成作业。"}, {"text": "学校缔结了一个新的图书馆。", "explanation": "这里应该用〈建立〉。缔结的对象是条约、协议，建造设施或机构要用建立。"}, {"text": "我们缔结了一次谈判。", "explanation": "这里应该用〈进行〉。缔结指订立成果，谈判是过程，应说进行谈判。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c85de76-69f2-4f25-b993-5d99b43c3cc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13262, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "缔结", "is_correct": true, "explanation": "正确：「缔结过友好条约」表示曾经订立过条约，与句意相符。"}, {"text": "举办", "is_correct": false, "explanation": "搭配：「举办」用于活动、会议，不能说举办条约。"}, {"text": "播放", "is_correct": false, "explanation": "搭配：「播放」用于节目、录音，条约不能播放。"}, {"text": "种植", "is_correct": false, "explanation": "语义：「种植」的对象是植物，条约无法种植，与「友好条约」不符。"}], "explanations": {"缔结": "正确：「缔结过友好条约」表示曾经订立过条约，与句意相符。", "举办": "搭配：「举办」用于活动、会议，不能说举办条约。", "播放": "搭配：「播放」用于节目、录音，条约不能播放。", "种植": "语义：「种植」的对象是植物，条约无法种植，与「友好条约」不符。"}, "sentence_index": 6, "correct_answer": "缔结"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们缔结了一场足球赛，周末在操场上踢。", "explanation": "这里应该用〈组织〉。缔结指双方经协商订立条约、协议或同盟，比赛不能缔结，应说组织一场足球赛。"}, {"text": "妈妈缔结了一锅汤，等我们回家喝。", "explanation": "这里应该用〈炖〉。缔结指订立条约或协议，汤不能缔结，应说炖了一锅汤。"}, {"text": "他缔结了一张全家福，挂在客厅墙上。", "explanation": "这里应该用〈拍〉。缔结指双方经协商订立条约或协议，照片不能缔结，应说拍了一张全家福。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c85de76-69f2-4f25-b993-5d99b43c3cc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13262, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两国在谈判后缔结着一项新条约。", "corrected_sentence": "两国在谈判后缔结了一项新条约。", "error_description": "错误形式：缔结着。正确形式：缔结了。「缔结」是一次性完成的动作，表示完成要用「了」；「着」表示持续的状态，与此不符。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c85de76-69f2-4f25-b993-5d99b43c3cc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13262, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两国正在缔结了一个新的贸易协定。", "corrected_sentence": "两国正在缔结一个新的贸易协定。", "error_description": "错误形式：正在缔结了。正确形式：正在缔结。「正在」表示动作进行中，不能与表示完成的「了」同用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c85de76-69f2-4f25-b993-5d99b43c3cc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
