INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13263, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指对人、行为或事物起到限制或强制作用的力量或效力。", "primary_collocate": null, "pronunciation": "yuē shù lì", "ipa": "ɥe˧˥ ʂu˥˩ li˥˩", "syllable_count": 3, "sentences": [{"text": "联合国环境规划署（UNEP）多次呼吁缔结具有法律约束力的全球协议，旨在建立跨国监管协调机制，遏制塑料污染的跨境转移。", "target_word": "约束力", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这份合同对双方都有约束力。", "target_word": "约束力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律对每个人都有约束力。", "target_word": "约束力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "规定没人遵守，就没有约束力。", "target_word": "约束力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项协议对各国具有很强的约束力。", "target_word": "约束力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校规对学生的约束力越来越小了。", "target_word": "约束力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的制度缺乏足够的约束力。", "target_word": "约束力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "道德虽然不是法律，但也有约束力。", "target_word": "约束力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种口头约定没有法律约束力。", "target_word": "约束力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家长的话对孩子已经没有约束力了。", "target_word": "约束力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "约束", "label": "词根（动词）"}, {"form": "法律约束力", "label": "复合"}], "register": "书面语", "sense_fingerprint": "对人或行为起限制、强制作用的效力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8d2bbf4-79da-4014-b207-c5baecb20bf5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13263, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "约束力", "is_correct": true, "explanation": "语境正确：“法律约束力”指协议对各国具有的强制效力，与“缔结……全球协议”相合。"}, {"text": "感染力", "is_correct": false, "explanation": "语义：“感染力”指打动人心的力量，协议靠法律效力而非感染人心，句子不通。"}, {"text": "创造力", "is_correct": false, "explanation": "语义：“创造力”指创造新事物的能力，与“法律”和“全球协议”的约束性质不符。"}, {"text": "想象力", "is_correct": false, "explanation": "搭配：“法律”后常接“效力、责任、地位”等，“法律想象力”搭配不通。"}], "explanations": {"约束力": "语境正确：“法律约束力”指协议对各国具有的强制效力，与“缔结……全球协议”相合。", "感染力": "语义：“感染力”指打动人心的力量，协议靠法律效力而非感染人心，句子不通。", "创造力": "语义：“创造力”指创造新事物的能力，与“法律”和“全球协议”的约束性质不符。", "想象力": "搭配：“法律”后常接“效力、责任、地位”等，“法律想象力”搭配不通。"}, "sentence_index": 0, "correct_answer": "约束力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种药的约束力很快就显现了。", "explanation": "这里应该用〈效力〉。约束力只指对人或行为的限制，说药物的作用要用“效力”。"}, {"text": "这篇文章的约束力很大。", "explanation": "这里应该用〈影响力〉。约束力指限制或强制人和行为的作用，文章对读者的感召和带动要用“影响力”。"}, {"text": "这种炸弹的约束力很大。", "explanation": "这里应该用〈威力〉。约束力不用于形容武器的破坏能力，这里要用“威力”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a0befb2-7c0f-481b-b847-2f8872445ee7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13263, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "约束力", "is_correct": true, "explanation": "语境正确：“缺乏约束力”指制度对人没有足够的限制作用，与“公司的制度”相合。"}, {"text": "香味", "is_correct": false, "explanation": "语义：“香味”属于嗅觉对象，与公司的制度毫无关系，句子不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“缺乏”多接“能力、力量、经验”等，“缺乏颜色”搭配不通。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”指身体的温度，用来形容公司制度不合常理。"}], "explanations": {"约束力": "语境正确：“缺乏约束力”指制度对人没有足够的限制作用，与“公司的制度”相合。", "香味": "语义：“香味”属于嗅觉对象，与公司的制度毫无关系，句子不通。", "颜色": "搭配：“缺乏”多接“能力、力量、经验”等，“缺乏颜色”搭配不通。", "体温": "语义：“体温”指身体的温度，用来形容公司制度不合常理。"}, "sentence_index": 6, "correct_answer": "约束力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部电影有很强的约束力。", "explanation": "这里应该用〈感染力〉。约束力指限制作用，形容电影打动观众的力量要用“感染力”。"}, {"text": "这位画家的约束力很强。", "explanation": "这里应该用〈创造力〉。约束力指限制作用，形容画家的创作能力要用“创造力”。"}, {"text": "这个景点很有约束力。", "explanation": "这里应该用〈吸引力〉。约束力指限制作用，形容景点吸引游客要用“吸引力”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a0befb2-7c0f-481b-b847-2f8872445ee7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13263, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这项制度对员工很约束力。", "corrected_sentence": "这项制度对员工很有约束力。", "error_description": "错误：“很约束力”。正确：“很有约束力”。“约束力”是名词，不能直接受“很”修饰，要说“很有约束力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a0befb2-7c0f-481b-b847-2f8872445ee7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13263, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套规则对所有员工都是约束力。", "corrected_sentence": "这套规则对所有员工都有约束力。", "error_description": "错误：“约束力”前用了“是”。“具有、拥有”的意思要用“有”，应说“有约束力”，不能说“是约束力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a0befb2-7c0f-481b-b847-2f8872445ee7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
