INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13264, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "经过协商达成的一致意见或合同。", "primary_collocate": null, "pronunciation": "xié yì", "ipa": "ɕjɛ˧˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "两家公司签了一份协议。", "target_word": "协议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们已经达成了协议。", "target_word": "协议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "协议上写着价格和时间。", "target_word": "协议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有看过这份协议。", "target_word": "协议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "双方都要遵守协议。", "target_word": "协议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板请我在协议上签名。", "target_word": "协议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把协议带回了公司。", "target_word": "协议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "协议到下个月就到期了。", "target_word": "协议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和房东签好了协议，下月搬家。", "target_word": "协议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国今天签了协议，不再打仗。", "target_word": "协议", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一份协议", "label": "量词"}, {"form": "一项协议", "label": "量词"}, {"form": "协议书", "label": "复合"}, {"form": "協議", "label": "繁体"}], "register": "书面", "sense_fingerprint": "双方或多方协商后达成并签订的一致意见或合同", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1be5a6e3-5db9-4be7-88db-c287895b77cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13264, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "协议", "is_correct": true, "explanation": "正确：「协议」xié yì，指双方协商达成的一致意见。"}, {"text": "谢意", "is_correct": false, "explanation": "xiè（第四声）与 xié（第二声）声调不同，意思是感谢之意。"}, {"text": "写意", "is_correct": false, "explanation": "xiě（第三声）与 xié（第二声）声调不同，「写意」指不拘形似的画法。"}, {"text": "协力", "is_correct": false, "explanation": "lì 与 yì 声母不同（l 与零声母），都是第四声，意思是齐心合力。"}], "explanations": {"协议": "正确：「协议」xié yì，指双方协商达成的一致意见。", "谢意": "xiè（第四声）与 xié（第二声）声调不同，意思是感谢之意。", "写意": "xiě（第三声）与 xié（第二声）声调不同，「写意」指不拘形似的画法。", "协力": "lì 与 yì 声母不同（l 与零声母），都是第四声，意思是齐心合力。"}, "sentence_index": null, "correct_answer": "协议"}, "level_3": {"options": [{"text": "协议", "is_correct": true, "explanation": "正确：「签了一份协议」，「签」用于协议、合同等文件。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：「签」用于合同、协议，作业不能签。"}, {"text": "午餐", "is_correct": false, "explanation": "语义：午餐是饮食，不是可以签署的文件。"}, {"text": "报纸", "is_correct": false, "explanation": "搭配：报纸可以订，但不能说签一份报纸。"}], "explanations": {"协议": "正确：「签了一份协议」，「签」用于协议、合同等文件。", "作业": "搭配：「签」用于合同、协议，作业不能签。", "午餐": "语义：午餐是饮食，不是可以签署的文件。", "报纸": "搭配：报纸可以订，但不能说签一份报纸。"}, "sentence_index": 0, "correct_answer": "协议"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他没有看过这座协议。", "explanation": "这里应该用〈份〉。「座」用于山、桥、建筑等大型固定的物体，协议要用「份」。"}, {"text": "他向妈妈许下了协议。", "explanation": "这里应该用〈诺言〉。「许下」用于个人的承诺，协议是双方订立的文件或一致意见，不能说许下。"}, {"text": "他没有看过这枚协议。", "explanation": "这里应该用〈份〉。「枚」用于硬币、印章等小而扁的物件，协议要用「份」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c85de76-69f2-4f25-b993-5d99b43c3cc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13264, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "协议", "is_correct": true, "explanation": "正确：「协议」xié yì，指双方协商达成的一致意见。"}, {"text": "学艺", "is_correct": false, "explanation": "xué（第二声）与 xié（第二声）韵母不同（-ue 与 -ie），意思是学习技艺。"}, {"text": "写意", "is_correct": false, "explanation": "xiě（第三声）与 xié（第二声）声调不同，「写意」指不拘形似的画法。"}, {"text": "斜倚", "is_correct": false, "explanation": "yǐ（第三声）与 yì（第四声）声调不同，「斜倚」指身体斜靠。"}], "explanations": {"协议": "正确：「协议」xié yì，指双方协商达成的一致意见。", "学艺": "xué（第二声）与 xié（第二声）韵母不同（-ue 与 -ie），意思是学习技艺。", "写意": "xiě（第三声）与 xié（第二声）声调不同，「写意」指不拘形似的画法。", "斜倚": "yǐ（第三声）与 yì（第四声）声调不同，「斜倚」指身体斜靠。"}, "sentence_index": null, "correct_answer": "协议"}, "level_3": {"options": [{"text": "协议", "is_correct": true, "explanation": "正确：「把协议带回了公司」，协议是可以携带的文件。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海无法被带回公司，与「带回」的物理意义不符。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳是天体，不能被带回公司。"}, {"text": "高楼", "is_correct": false, "explanation": "搭配：「带回」搭配可以携带的物品，不能说带回高楼。"}], "explanations": {"协议": "正确：「把协议带回了公司」，协议是可以携带的文件。", "大海": "语义：大海无法被带回公司，与「带回」的物理意义不符。", "太阳": "语义：太阳是天体，不能被带回公司。", "高楼": "搭配：「带回」搭配可以携带的物品，不能说带回高楼。"}, "sentence_index": 6, "correct_answer": "协议"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两国今天签了一块协议，不再打仗。", "explanation": "这里应该用〈份〉。「块」用于成块的物体，协议要用「份」。"}, {"text": "两国今天签了一颗协议，不再打仗。", "explanation": "这里应该用〈份〉。「颗」用于粒状或圆形的小物体，协议要用「份」。"}, {"text": "他是我的好协议。", "explanation": "这里应该用〈朋友〉。协议是双方订立的文件或一致意见，不能指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c85de76-69f2-4f25-b993-5d99b43c3cc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13264, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两家公司今天签了一只新协议。", "corrected_sentence": "两家公司今天签了一份新协议。", "error_description": "错误形式：一只新协议。正确形式：一份新协议。「只」用于动物或成对器物中的一件，协议要用「份」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c85de76-69f2-4f25-b993-5d99b43c3cc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13264, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两国代表昨天签了一根新协议。", "corrected_sentence": "两国代表昨天签了一份新协议。", "error_description": "错误形式：一根新协议。正确形式：一份新协议。「根」用于细长的条状物，协议要用「份」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c85de76-69f2-4f25-b993-5d99b43c3cc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
