INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13265, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "表示目的或意图，相当于“目的是为了”。", "primary_collocate": null, "pronunciation": "zhǐ zài", "ipa": "ʈʂɨ˨˩ tsai˥˩", "syllable_count": 2, "sentences": [{"text": "联合国环境规划署（UNEP）多次呼吁缔结具有法律约束力的全球协议，旨在建立跨国监管协调机制，遏制塑料污染的跨境转移。", "target_word": "旨在", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这项新规定旨在保护儿童的安全。", "target_word": "旨在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校举办这次活动，旨在让学生多了解传统文化。", "target_word": "旨在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书旨在帮助孩子养成好习惯。", "target_word": "旨在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司推出新产品，旨在吸引更多年轻人。", "target_word": "旨在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次会议旨在讨论明年的工作计划。", "target_word": "旨在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府修建了新公园，旨在改善居民的生活环境。", "target_word": "旨在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个比赛旨在鼓励大家多读书。", "target_word": "旨在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院开设这门课，旨在提高病人的健康意识。", "target_word": "旨在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告旨在说明问题的原因。", "target_word": "旨在", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "引出做某事的目的或意图，书面语，后接动词性成分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4cc9c03-6209-4c9e-868b-ad46e5b5769a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13265, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "避免", "is_correct": false, "explanation": "语义：“避免”表示躲开，与前文“呼吁缔结协议”的目的相反，协议不能用来避免建立机制。"}, {"text": "旨在", "is_correct": true, "explanation": "“旨在”表示目的，后接动词性成分“建立”，说明缔结协议要达到的目标。"}, {"text": "反对", "is_correct": false, "explanation": "语义：“反对”与前文“呼吁缔结协议、遏制污染”的立场相反，读起来不通。"}, {"text": "防范", "is_correct": false, "explanation": "搭配：“防范”后接的是风险或危害，不能接“建立机制”。"}], "explanations": {"避免": "语义：“避免”表示躲开，与前文“呼吁缔结协议”的目的相反，协议不能用来避免建立机制。", "旨在": "“旨在”表示目的，后接动词性成分“建立”，说明缔结协议要达到的目标。", "反对": "语义：“反对”与前文“呼吁缔结协议、遏制污染”的立场相反，读起来不通。", "防范": "搭配：“防范”后接的是风险或危害，不能接“建立机制”。"}, "sentence_index": 0, "correct_answer": "旨在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他今天迟到了，旨在起得太晚。", "explanation": "因果：“旨在”表示想要达到的目的，不能用来说明已经发生的原因；这里应该用“因为”。"}, {"text": "我们旨在明天不下雨。", "explanation": "语义：“旨在”表示有意去达到的目的，不能用于不受人控制的天气；这里应该用“希望”。"}, {"text": "问题旨在资金不足。", "explanation": "易混：“在于”用来说明问题的所在；“旨在”表示目的，不能用来说明问题所在，这里应该用“在于”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98bc4599-a177-4ba4-9fd8-632ff3437f74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13265, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放弃", "is_correct": false, "explanation": "语义：“放弃改善居民生活环境”与修建新公园的做法相矛盾。"}, {"text": "旨在", "is_correct": true, "explanation": "“旨在”表示目的，后接动词性成分“改善”，说明修建公园的用意。"}, {"text": "破坏", "is_correct": false, "explanation": "语义：“破坏改善生活环境”自相矛盾，与修建公园的目的正好相反。"}, {"text": "化解", "is_correct": false, "explanation": "搭配：“化解”的对象是矛盾、危机，不能接“改善生活环境”。"}], "explanations": {"放弃": "语义：“放弃改善居民生活环境”与修建新公园的做法相矛盾。", "旨在": "“旨在”表示目的，后接动词性成分“改善”，说明修建公园的用意。", "破坏": "语义：“破坏改善生活环境”自相矛盾，与修建公园的目的正好相反。", "化解": "搭配：“化解”的对象是矛盾、危机，不能接“改善生活环境”。"}, "sentence_index": 6, "correct_answer": "旨在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他旨在看电视，没听见电话。", "explanation": "语义：“旨在”表示目的，不表示动作正在进行；这里应该用“正在”。"}, {"text": "注意安全，旨在受伤。", "explanation": "语义：“旨在”表示想要达到的目的，不能表示要避免的坏结果；这里应该用“以免”。"}, {"text": "他旨在喜欢这本书。", "explanation": "配价：“旨在”后接的是可以有意去做的行为，“喜欢”是心理状态，不能作为目的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98bc4599-a177-4ba4-9fd8-632ff3437f74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13265, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次培训旨在了提高员工的服务水平。", "corrected_sentence": "这次培训旨在提高员工的服务水平。", "error_description": "错误形式：“旨在”后面加了“了”。正确形式：“旨在”后直接接动词性成分，应说“这次培训旨在提高员工的服务水平。”原因：“旨在”表示尚未实现的目的，不带完成意义。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98bc4599-a177-4ba4-9fd8-632ff3437f74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13265, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司成立了新部门，很旨在提高工作效率。", "corrected_sentence": "这家公司成立了新部门，旨在提高工作效率。", "error_description": "错误形式：“旨在”前面加了副词“很”。正确形式：应说“这家公司成立了新部门，旨在提高工作效率。”原因：“很”一般修饰形容词或部分心理动词，不能修饰“旨在”这类表示目的的词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98bc4599-a177-4ba4-9fd8-632ff3437f74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13266, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "助长", "is_correct": true, "explanation": "“助长”与“遏制”意义相反：遏制是阻止不良势头，助长是促使其发展。"}, {"text": "保持", "is_correct": false, "explanation": "与“遏制”没有反义关系，“保持”表示维持原状，与阻止、控制的意义无关。"}, {"text": "调整", "is_correct": false, "explanation": "与“遏制”没有反义关系，“调整”表示改变使其适当，并不是促使坏事发展。"}, {"text": "研究", "is_correct": false, "explanation": "与“遏制”没有反义关系，“研究”表示探讨，与阻止、促进都不相关。"}], "correct_answer": "助长", "explanations": {"助长": "“助长”与“遏制”意义相反：遏制是阻止不良势头，助长是促使其发展。", "保持": "与“遏制”没有反义关系，“保持”表示维持原状，与阻止、控制的意义无关。", "调整": "与“遏制”没有反义关系，“调整”表示改变使其适当，并不是促使坏事发展。", "研究": "与“遏制”没有反义关系，“研究”表示探讨，与阻止、促进都不相关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98bc4599-a177-4ba4-9fd8-632ff3437f74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13266, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "助长", "is_correct": true, "explanation": "“助长”与“遏制”意义相反：遏制是阻止不良势头，助长是促使其发展。"}, {"text": "分析", "is_correct": false, "explanation": "与“遏制”没有反义关系，“分析”表示研究事物的构成，与阻止、促进都不相关。"}, {"text": "解决", "is_correct": false, "explanation": "与“遏制”没有反义关系，“解决”表示消除问题，并不是促使坏事发展。"}, {"text": "记录", "is_correct": false, "explanation": "与“遏制”没有反义关系，“记录”表示把事情写下来，与阻止或促进都无关。"}], "correct_answer": "助长", "explanations": {"助长": "“助长”与“遏制”意义相反：遏制是阻止不良势头，助长是促使其发展。", "分析": "与“遏制”没有反义关系，“分析”表示研究事物的构成，与阻止、促进都不相关。", "解决": "与“遏制”没有反义关系，“解决”表示消除问题，并不是促使坏事发展。", "记录": "与“遏制”没有反义关系，“记录”表示把事情写下来，与阻止或促进都无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98bc4599-a177-4ba4-9fd8-632ff3437f74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13266, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用力阻止或控制某种行为或趋势", "primary_collocate": null, "pronunciation": "è zhì", "ipa": "ɤ˥˩ ʈʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "联合国环境规划署（UNEP）多次呼吁缔结具有法律约束力的全球协议，旨在建立跨国监管协调机制，遏制塑料污染的跨境转移。", "target_word": "遏制", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "政府采取措施遏制房价上涨。", "target_word": "遏制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要想办法遏制这种坏习惯。", "target_word": "遏制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用新药遏制了病情的发展。", "target_word": "遏制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "严格的规定有效遏制了乱扔垃圾的行为。", "target_word": "遏制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校制定新办法，遏制考试作弊。", "target_word": "遏制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各国正在合作遏制病毒传播。", "target_word": "遏制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些做法很难遏制污染继续扩大。", "target_word": "遏制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府希望遏制物价上涨过快的趋势。", "target_word": "遏制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "提高罚款可以遏制乱停车的现象。", "target_word": "遏制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "遏制了", "label": "完成体"}, {"form": "遏制过", "label": "经历体"}], "register": "书面语", "sense_fingerprint": "用力量或措施阻止、控制不良的行为或发展趋势", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4cc9c03-6209-4c9e-868b-ad46e5b5769a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13266, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "促进", "is_correct": false, "explanation": "语义：“促进塑料污染的跨境转移”与句子要表达的治理目的相反。"}, {"text": "遏制", "is_correct": true, "explanation": "“遏制”表示阻止、控制不良现象，与“塑料污染的跨境转移”搭配，符合句意。"}, {"text": "扩大", "is_correct": false, "explanation": "语义：“扩大跨境转移”与前文要求建立监管机制的意图矛盾。"}, {"text": "生产", "is_correct": false, "explanation": "搭配：“生产”的宾语是产品，不能接“污染的跨境转移”。"}], "explanations": {"促进": "语义：“促进塑料污染的跨境转移”与句子要表达的治理目的相反。", "遏制": "“遏制”表示阻止、控制不良现象，与“塑料污染的跨境转移”搭配，符合句意。", "扩大": "语义：“扩大跨境转移”与前文要求建立监管机制的意图矛盾。", "生产": "搭配：“生产”的宾语是产品，不能接“污染的跨境转移”。"}, "sentence_index": 0, "correct_answer": "遏制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生想遏制病人的康复。", "explanation": "语义：“遏制”用于阻止坏的行为或趋势，不能用来阻止病人的康复；这里说反了，应该用“促进”。"}, {"text": "他遏制了那扇门。", "explanation": "搭配：“遏制”的对象是行为或趋势，不能用于门这样的物体；关门应该用“关”。"}, {"text": "我们应该遏制孩子的好习惯。", "explanation": "语义：“遏制”用于阻止不良的行为或趋势，不能用来压制好习惯，这里说反了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98bc4599-a177-4ba4-9fd8-632ff3437f74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13266, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "加快", "is_correct": false, "explanation": "语义：“加快病毒传播”与合作防疫的意图相反。"}, {"text": "推动", "is_correct": false, "explanation": "语义：“推动病毒传播”与合作防疫的目标相反，读起来不通。"}, {"text": "研制", "is_correct": false, "explanation": "搭配：“研制”的宾语是药物、设备等，不能接“病毒传播”。"}, {"text": "遏制", "is_correct": true, "explanation": "“遏制”表示控制不良现象，与“病毒传播”搭配，符合合作防疫的语境。"}], "explanations": {"加快": "语义：“加快病毒传播”与合作防疫的意图相反。", "推动": "语义：“推动病毒传播”与合作防疫的目标相反，读起来不通。", "研制": "搭配：“研制”的宾语是药物、设备等，不能接“病毒传播”。", "遏制": "“遏制”表示控制不良现象，与“病毒传播”搭配，符合合作防疫的语境。"}, "sentence_index": 6, "correct_answer": "遏制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府遏制大家多锻炼身体。", "explanation": "语义：“遏制”用于阻止不良的现象，不能用于锻炼这样的好事；这里应该用“鼓励”。"}, {"text": "我们要遏制冬天的到来。", "explanation": "搭配：“遏制”的对象是可以控制的不良现象，冬天到来不能被遏制。"}, {"text": "妈妈遏制了一碗面条。", "explanation": "搭配：“遏制”的对象是不良的行为或趋势，不能是面条这样的食物；这里应该用“煮”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98bc4599-a177-4ba4-9fd8-632ff3437f74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13266, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新规定很遏制了超速行为。", "corrected_sentence": "新规定有效遏制了超速行为。", "error_description": "错误形式：“遏制”前面加了副词“很”，“很”不能修饰动作动词“遏制”。正确形式：应说“新规定有效遏制了超速行为。”原因：“有效”修饰动作，表示效果好，可以放在“遏制”前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98bc4599-a177-4ba4-9fd8-632ff3437f74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13266, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些措施能被遏制病毒的扩散。", "corrected_sentence": "这些措施能遏制病毒的扩散。", "error_description": "错误形式：“遏制”前面多加了“被”，使“被”后直接接动词“遏制”并带宾语“病毒的扩散”，结构不合法。正确形式：“这些措施能遏制病毒的扩散。”原因：“遏制”是及物动词，受事宾语应直接放在它后面；若要用被字句，应把受事作主语，如“病毒的扩散能被这些措施遏制。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98bc4599-a177-4ba4-9fd8-632ff3437f74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
