INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13267, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "跨越国境的，指涉及不同国家之间的事务。", "primary_collocate": null, "pronunciation": "kuà jìng", "ipa": "kʰwa˥˩ tɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "联合国环境规划署（UNEP）多次呼吁缔结具有法律约束力的全球协议，旨在建立跨国监管协调机制，遏制塑料污染的跨境转移。", "target_word": "跨境", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "现在很多人喜欢跨境购物。", "target_word": "跨境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司做跨境电商。", "target_word": "跨境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跨境快递一般要等一个星期。", "target_word": "跨境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跨境运输需要很多文件。", "target_word": "跨境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察正在调查一起跨境案件。", "target_word": "跨境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在银行办理了跨境汇款。", "target_word": "跨境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跨境旅游的人越来越多。", "target_word": "跨境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个平台提供跨境支付服务。", "target_word": "跨境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跨境贸易让两国的商人都得到好处。", "target_word": "跨境", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "跨境电商", "label": "复合"}, {"form": "跨境购物", "label": "复合"}], "register": "中性", "sense_fingerprint": "涉及不同国家之间的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b3bbd23-8942-4e8f-b366-768ba894f710') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13267, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "跨境", "is_correct": true, "explanation": "“跨境”指涉及不同国家之间，句中“转移”跨越国界，语义吻合。"}, {"text": "线上", "is_correct": false, "explanation": "语义：“线上”指网络空间，与塑料污染的实物转移不符。"}, {"text": "室内", "is_correct": false, "explanation": "语义：“室内”指空间位置，句中讲的是跨越国界的转移。"}, {"text": "露天", "is_correct": false, "explanation": "搭配：“露天”说场所，不修饰“转移”这类行为。"}], "explanations": {"跨境": "“跨境”指涉及不同国家之间，句中“转移”跨越国界，语义吻合。", "线上": "语义：“线上”指网络空间，与塑料污染的实物转移不符。", "室内": "语义：“室内”指空间位置，句中讲的是跨越国界的转移。", "露天": "搭配：“露天”说场所，不修饰“转移”这类行为。"}, "sentence_index": 0, "correct_answer": "跨境"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次活动是跨境的，参加的人来自国内各地。", "explanation": "这里应该用〈跨省〉。“跨境”指涉及不同国家；来自国内各地的活动应说“跨省”或“跨地区”。"}, {"text": "这辆汽车的跨境能力很强，能爬山越岭。", "explanation": "这里应该用〈越野〉。“跨境”指涉及不同国家，汽车能否爬山越岭要看越野能力，不能这样用。"}, {"text": "这座桥跨境了整条河。", "explanation": "这里应该用〈跨越〉。“跨境”指涉及不同国家，不能表示桥横跨河流，应说“跨越”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7c6b85f-3bc5-496a-a14b-a563be0173e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13267, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "跨境", "is_correct": true, "explanation": "“跨境汇款”指汇往外国的款项，句中“办理”与之相符。"}, {"text": "木质", "is_correct": false, "explanation": "语义：“木质”指材料，与汇款不相关。"}, {"text": "高空", "is_correct": false, "explanation": "语义：“高空”指位置，不能修饰汇款。"}, {"text": "口头", "is_correct": false, "explanation": "搭配：“口头”说明方式，“口头汇款”不成立。"}], "explanations": {"跨境": "“跨境汇款”指汇往外国的款项，句中“办理”与之相符。", "木质": "语义：“木质”指材料，与汇款不相关。", "高空": "语义：“高空”指位置，不能修饰汇款。", "口头": "搭配：“口头”说明方式，“口头汇款”不成立。"}, "sentence_index": 6, "correct_answer": "跨境"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "跨境贸易让两省的商人都得到好处。", "explanation": "这里应该用〈国内〉。“跨境”指涉及不同国家，两省之间的贸易属于国内。"}, {"text": "这次比赛是跨境的，选手都来自本省。", "explanation": "这里应该用〈省内〉。“跨境”指涉及不同国家，选手都来自本省的比赛应说“省内”，不能用“跨境”。"}, {"text": "这列火车跨境了整个草原。", "explanation": "这里应该用〈穿越〉。“跨境”指涉及不同国家，不能表示火车穿过草原，应说“穿越”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7c6b85f-3bc5-496a-a14b-a563be0173e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13267, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家企业的跨境地业务规模很大。", "corrected_sentence": "这家企业的跨境业务规模很大。", "error_description": "“地”错误：“跨境”修饰名词“业务”时不加“地”（“地”用于动词前），应为“跨境业务”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7c6b85f-3bc5-496a-a14b-a563be0173e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13267, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们公司正在开发跨境地支付系统。", "corrected_sentence": "我们公司正在开发跨境支付系统。", "error_description": "“地”错误：“跨境”修饰名词“支付系统”时不加“地”（“地”用于动词前），应为“跨境支付系统”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7c6b85f-3bc5-496a-a14b-a563be0173e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
