INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13268, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "改变位置或方向，从一个地方到另一个地方。", "primary_collocate": null, "pronunciation": "zhuǎn yí", "ipa": "ʈʂwan˨˩ i˧˥", "syllable_count": 2, "sentences": [{"text": "联合国环境规划署（UNEP）多次呼吁缔结具有法律约束力的全球协议，旨在建立跨国监管协调机制，遏制塑料污染的跨境转移。", "target_word": "转移", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "火灾以后，大家马上转移到安全的地方。", "target_word": "转移", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生把病人转移到另一家医院。", "target_word": "转移", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台风来了，人们转移到高处。", "target_word": "转移", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了安全，警察把人群转移到了广场的另一边。", "target_word": "转移", "complexity_tier": "T3", "furigana": "wèile ānquán, jǐngchá bǎ rénqún zhuǎnyí dào le guǎngchǎng de lìng yì biān", "sentence_source": "generated"}, {"text": "老师带孩子们转移到楼下。", "target_word": "转移", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，比赛转移到室内进行。", "target_word": "转移", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那批货物已经转移到了仓库。", "target_word": "转移", "complexity_tier": "T3", "furigana": "nà pī huòwù yǐjīng zhuǎnyí dào le cāngkù", "sentence_source": "generated"}, {"text": "河水上涨，村里的人已经转移了。", "target_word": "转移", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪水来了，他们正在转移村民。", "target_word": "转移", "complexity_tier": "T3", "furigana": "hóngshuǐ lái le, tāmen zhèngzài zhuǎnyí cūnmín", "sentence_source": "generated"}], "morphological_forms": [{"form": "转移了", "label": "体标"}, {"form": "转移着", "label": "体标"}, {"form": "转移过", "label": "体标"}, {"form": "轉移", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人、事物或注意力改变位置或方向，由一处换到另一处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1be5a6e3-5db9-4be7-88db-c287895b77cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13268, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "转移", "is_correct": true, "explanation": "转移（zhuǎn yí，第三声、第二声）指人或事物从一处换到另一处，是正确答案。"}, {"text": "转椅", "is_correct": false, "explanation": "转椅（zhuàn yǐ）两个音节的声调都与转移（zhuǎn yí）不同，意思是可以旋转的椅子。"}, {"text": "专一", "is_correct": false, "explanation": "专一（zhuān yī）两个音节的声调都与转移（zhuǎn yí）不同，意思是专心、不分散。"}, {"text": "转义", "is_correct": false, "explanation": "转义（zhuǎn yì）只有第二个音节的声调与转移（zhuǎn yí）不同，意思是词语的引申含义。"}], "explanations": {"转移": "转移（zhuǎn yí，第三声、第二声）指人或事物从一处换到另一处，是正确答案。", "转椅": "转椅（zhuàn yǐ）两个音节的声调都与转移（zhuǎn yí）不同，意思是可以旋转的椅子。", "专一": "专一（zhuān yī）两个音节的声调都与转移（zhuǎn yí）不同，意思是专心、不分散。", "转义": "转义（zhuǎn yì）只有第二个音节的声调与转移（zhuǎn yí）不同，意思是词语的引申含义。"}, "sentence_index": null, "correct_answer": "转移"}, "level_3": {"options": [{"text": "转移", "is_correct": true, "explanation": "“遏制塑料污染的跨境转移”指塑料废物等跨国界的流动，符合句意。"}, {"text": "清理", "is_correct": false, "explanation": "语义：“清理”是去除，不指跨境流动，与“遏制跨境……”不搭。"}, {"text": "会议", "is_correct": false, "explanation": "语义：“会议”是活动，不能发生“跨境”流动，句子不通。"}, {"text": "包装", "is_correct": false, "explanation": "搭配：“跨境”修饰的是流动或迁移，不说“跨境包装”。"}], "explanations": {"转移": "“遏制塑料污染的跨境转移”指塑料废物等跨国界的流动，符合句意。", "清理": "语义：“清理”是去除，不指跨境流动，与“遏制跨境……”不搭。", "会议": "语义：“会议”是活动，不能发生“跨境”流动，句子不通。", "包装": "搭配：“跨境”修饰的是流动或迁移，不说“跨境包装”。"}, "sentence_index": 0, "correct_answer": "转移"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书被转移成了英文。", "explanation": "这里应该用〈翻译〉。转移指人或物从一处移到另一处，语言的转换不用转移。"}, {"text": "为了转移雨，我们走进了商店。", "explanation": "这里应该用〈躲避〉。转移的对象是人或物，不能用来指躲开雨。"}, {"text": "他的个子转移到了一米八。", "explanation": "这里应该用〈长〉。转移指人或物的位置变化，身高增长不用转移。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c85de76-69f2-4f25-b993-5d99b43c3cc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13268, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "转移", "is_correct": true, "explanation": "“比赛转移到室内进行”指比赛地点由室外换到室内，符合句意。"}, {"text": "结束", "is_correct": false, "explanation": "语义：“结束”与“进行”意思相反，比赛不能既结束又在进行。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡”不能指比赛的进行，“比赛睡到室内进行”无法成立。"}, {"text": "通过", "is_correct": false, "explanation": "搭配：“通过”不接“到室内”引出的地点，“通过到室内进行”搭配不通。"}], "explanations": {"转移": "“比赛转移到室内进行”指比赛地点由室外换到室内，符合句意。", "结束": "语义：“结束”与“进行”意思相反，比赛不能既结束又在进行。", "睡": "语义：“睡”不能指比赛的进行，“比赛睡到室内进行”无法成立。", "通过": "搭配：“通过”不接“到室内”引出的地点，“通过到室内进行”搭配不通。"}, "sentence_index": 6, "correct_answer": "转移"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天都转移远方的家人。", "explanation": "这里应该用〈想念〉。转移指人或物实际从一处移到另一处，心里的思念不用转移。"}, {"text": "他把桌子转移干净了。", "explanation": "这里应该用〈擦〉。转移指搬到别处，不指清洁，“转移干净”不成立。"}, {"text": "师傅转移好了自行车。", "explanation": "这里应该用〈修〉。转移不表示修理，修好自行车要用“修”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c85de76-69f2-4f25-b993-5d99b43c3cc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13268, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们把物资转移。", "corrected_sentence": "他们把物资转移到山下。", "error_description": "“把”字句中动词后要有终点，说明物资转移到哪里。应说“转移到山下”，不能只说“转移”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c85de76-69f2-4f25-b993-5d99b43c3cc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13268, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们已经把村民转移安全的地方。", "corrected_sentence": "他们已经把村民转移到安全的地方。", "error_description": "“转移”后要用介词“到”引出地点，不能直接接处所名词。应说“转移到安全的地方”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c85de76-69f2-4f25-b993-5d99b43c3cc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
