INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13269, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b143ccd7-5878-400e-8922-f929950c8fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13269, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指双方对涉及共同利益的问题进行讨论、协商，以达成一致意见。", "primary_collocate": null, "pronunciation": "tán pàn", "ipa": "tʰan³⁵ pʰan⁵¹", "syllable_count": 2, "sentences": [{"text": "经过几个月的谈判，各方终于同意就塑料污染问题制定一项新规则。", "target_word": "谈判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国代表在日内瓦谈判了三天，终于签署了协议。", "target_word": "谈判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工会和公司就工资问题进行谈判。", "target_word": "谈判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次谈判很不顺利，双方都不肯让步。", "target_word": "谈判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过长时间谈判，两家公司达成了一致。", "target_word": "谈判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府决定和对方继续谈判，不想打仗。", "target_word": "谈判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在谈判中互相让了一步。", "target_word": "谈判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谈判失败后，工人们决定罢工。", "target_word": "谈判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "双方谈判过多次，但没有结果。", "target_word": "谈判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场谈判持续了整整一个星期。", "target_word": "谈判", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "谈判了", "label": "体标（了）"}, {"form": "谈判过", "label": "体标（过）"}, {"form": "谈判桌", "label": "复合词"}, {"form": "談判", "label": "繁体"}], "register": "正式", "sense_fingerprint": "双方就共同利益问题正式协商，以求达成一致", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16a20f6b-3319-4c28-9f9a-4514a0786ce7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13269, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "谈判", "is_correct": true, "explanation": "谈判指双方协商、求得一致，与“各方终于同意制定新规则”的语境相符。"}, {"text": "旅行", "is_correct": false, "explanation": "语义：旅行是出游，与各方就规则达成一致无关，不能填入。"}, {"text": "比赛", "is_correct": false, "explanation": "语义：比赛以争胜为目的，不能使各方达成共同同意。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试是测评，与各方协商、同意制定规则不符。"}], "explanations": {"谈判": "谈判指双方协商、求得一致，与“各方终于同意制定新规则”的语境相符。", "旅行": "语义：旅行是出游，与各方就规则达成一致无关，不能填入。", "比赛": "语义：比赛以争胜为目的，不能使各方达成共同同意。", "考试": "语义：考试是测评，与各方协商、同意制定规则不符。"}, "sentence_index": 0, "correct_answer": "谈判"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和朋友谈判了这部电影的剧情。", "explanation": "这里应该用〈讨论〉。谈判指双方为利益分歧协商、求得一致，只是交流看法时用讨论。"}, {"text": "我一个人在屋里谈判了很久。", "explanation": "谈判至少需要两方，且围绕有分歧的事协商；一个人不能谈判，这种情况应说〈想了很久〉。"}, {"text": "我们正在谈判今天的天气。", "explanation": "谈判的对象必须是双方有分歧、需要达成一致的事，天气不是谈判的对象；只是闲聊时应说〈聊〉天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b143ccd7-5878-400e-8922-f929950c8fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13269, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "谈判", "is_correct": true, "explanation": "“在……中互相让步”指协商过程中的让步，“谈判”符合这一语境。"}, {"text": "考场", "is_correct": false, "explanation": "语义：考场是个人应试的场所，“互相让步”需要双方协商，二者不符。"}, {"text": "赛跑", "is_correct": false, "explanation": "语义：赛跑是争先的竞赛，选手之间不存在互相让步的关系。"}, {"text": "睡梦", "is_correct": false, "explanation": "语义：睡梦是个人睡觉时的状态，没有双方协商，不能“在睡梦中互相让步”。"}], "explanations": {"谈判": "“在……中互相让步”指协商过程中的让步，“谈判”符合这一语境。", "考场": "语义：考场是个人应试的场所，“互相让步”需要双方协商，二者不符。", "赛跑": "语义：赛跑是争先的竞赛，选手之间不存在互相让步的关系。", "睡梦": "语义：睡梦是个人睡觉时的状态，没有双方协商，不能“在睡梦中互相让步”。"}, "sentence_index": 6, "correct_answer": "谈判"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "法官每天都在两家公司之间谈判合同纠纷。", "explanation": "这里应该用〈调解〉。谈判是双方直接协商，法官作为第三方居中劝和，本身不是谈判的一方。"}, {"text": "两位老同学在咖啡馆谈判了一下午的往事。", "explanation": "这里应该用〈叙旧〉。谈判要围绕有分歧、需要达成一致的事，回忆过去不是谈判。"}, {"text": "这道数学题的答案，我和同桌谈判了很久。", "explanation": "这里应该用〈讨论〉。谈判是双方围绕有分歧、可以商量的事协商；数学题的答案是客观事实，只能讨论、核对，不能谈判。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b143ccd7-5878-400e-8922-f929950c8fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13269, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一本很重要的谈判，两国都很关心结果。", "corrected_sentence": "这是一场很重要的谈判，两国都很关心结果。", "error_description": "量词错误：“谈判”作名词指一次协商活动时，量词应用“场”，“本”用于书籍等，应说“这是一场很重要的谈判”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b143ccd7-5878-400e-8922-f929950c8fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13269, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两国代表昨天谈判着三个小时，还是没有结果。", "corrected_sentence": "两国代表昨天谈判了三个小时，还是没有结果。", "error_description": "体标错误：“着”表示动作持续的状态，不能带“三个小时”这样表示已完成时段的补语，应说“谈判了三个小时”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b143ccd7-5878-400e-8922-f929950c8fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
