INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13271, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指机关、团体或军队中使用的正式文件或公文。", "primary_collocate": null, "pronunciation": "wén shū", "ipa": "wən³⁵ ʂu⁵⁵", "syllable_count": 2, "sentences": [{"text": "这份文书需要由三位律师共同起草。", "target_word": "文书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秘书正在整理桌上的文书。", "target_word": "文书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份文书需要领导签字。", "target_word": "文书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "律师把这份文书交给了法院。", "target_word": "文书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院的文书必须写得很清楚。", "target_word": "文书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在公司负责处理各种文书。", "target_word": "文书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在文书上写清楚你的姓名和日期。", "target_word": "文书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些文书要保存十年。", "target_word": "文书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办公室里放着一大堆旧文书。", "target_word": "文书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文书写好后，要先交给经理看。", "target_word": "文书", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一份文书", "label": "量词（份）"}, {"form": "法律文书", "label": "复合词"}, {"form": "文書", "label": "繁体"}], "register": "正式", "sense_fingerprint": "机关、团体或军队使用的正式文件或公文", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16a20f6b-3319-4c28-9f9a-4514a0786ce7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13271, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "文书", "is_correct": true, "explanation": "文书指机关、团体中的正式公文，与“由律师共同起草”的语境相符。"}, {"text": "食谱", "is_correct": false, "explanation": "语义：食谱是菜谱，不是需要律师起草的公务文件。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料是饮品，不能由律师起草。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶是器物，不能由律师起草。"}], "explanations": {"文书": "文书指机关、团体中的正式公文，与“由律师共同起草”的语境相符。", "食谱": "语义：食谱是菜谱，不是需要律师起草的公务文件。", "饮料": "语义：饮料是饮品，不能由律师起草。", "花瓶": "语义：花瓶是器物，不能由律师起草。"}, "sentence_index": 0, "correct_answer": "文书"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一晚上写了一篇文书，讲述自己的童年。", "explanation": "这里应该用〈文章〉。文书指机关使用的正式公文，不指用来抒发个人感情的文章。"}, {"text": "他的字很有名，每幅文书都卖了高价。", "explanation": "这里应该用〈字画〉。文书指机关使用的正式公文，不指书法作品，不能说卖出的“文书”。"}, {"text": "她给男朋友写了一份文书，说很想他。", "explanation": "这里应该用〈情书〉。文书指机关使用的正式公文，不用于私人间表达感情的书信。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b143ccd7-5878-400e-8922-f929950c8fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13271, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "文书", "is_correct": true, "explanation": "文书是可以填写的正式纸质材料，与“写清楚姓名和日期”的语境相符。"}, {"text": "镜子", "is_correct": false, "explanation": "语义：镜子不是可以填写姓名和日期的纸质材料，“在镜子上写清楚”说不通。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲是作品，不是需要填写信息的表格或文件。"}, {"text": "花瓶", "is_correct": false, "explanation": "搭配：“写清楚”的对象须是纸张等可书写的载体，花瓶不能用来填写姓名和日期。"}], "explanations": {"文书": "文书是可以填写的正式纸质材料，与“写清楚姓名和日期”的语境相符。", "镜子": "语义：镜子不是可以填写姓名和日期的纸质材料，“在镜子上写清楚”说不通。", "歌曲": "语义：歌曲是作品，不是需要填写信息的表格或文件。", "花瓶": "搭配：“写清楚”的对象须是纸张等可书写的载体，花瓶不能用来填写姓名和日期。"}, "sentence_index": 6, "correct_answer": "文书"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在院子里写文书，表达对家乡的思念。", "explanation": "这里应该用〈诗〉。文书指机关使用的正式公文，不用来抒发个人感情，表达思念应用诗或文章。"}, {"text": "他每天睡前都写文书，记录当天的心情。", "explanation": "这里应该用〈日记〉。文书是公务用的正式文件，不用来记录个人心情。"}, {"text": "他这几年一直在写文书，讲一个小镇上的故事。", "explanation": "这里应该用〈小说〉。文书指机关、团体使用的正式公文，不是虚构的叙事作品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b143ccd7-5878-400e-8922-f929950c8fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13271, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把这只文书放进了档案柜。", "corrected_sentence": "他把这份文书放进了档案柜。", "error_description": "量词错误：“文书”是纸质公文，量词应用“份”，“只”用于动物等，应说“这份文书”，不能说“这只文书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b143ccd7-5878-400e-8922-f929950c8fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13271, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把文书我已经看过了。", "corrected_sentence": "这份文书我已经看过了。", "error_description": "量词错误：“文书”是纸质公文，量词应用“份”，“把”用于有柄的器具，应说“这份文书”，不能说“这把文书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b143ccd7-5878-400e-8922-f929950c8fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
