INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13272, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指初步写出或制定文件、方案、法律等的初稿。", "primary_collocate": null, "pronunciation": "qǐ cǎo", "ipa": "tɕʰi˨˩ tsʰɑʊ˨˩", "syllable_count": 2, "sentences": [{"text": "2022年政府间谈判委员会（INC）启动的国际文书起草进程，标志着塑料污染治理正迈向多边立法新阶段。", "target_word": "起草", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "老师让我们起草一份活动计划。", "target_word": "起草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "律师正在起草合同。", "target_word": "起草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他昨天起草了一封给市长的信。", "target_word": "起草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小组先起草方案，再请大家修改。", "target_word": "起草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "委员会起草的新法律明年开始实行。", "target_word": "起草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理请小王起草会议通知。", "target_word": "起草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们花了三天时间起草这份报告。", "target_word": "起草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你起草一份简单的说明书。", "target_word": "起草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长要求大家起草一个新学期计划。", "target_word": "起草", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "起草了", "label": "完成体"}, {"form": "起草过", "label": "经历体"}], "register": "书面语", "sense_fingerprint": "初步写出或制定文件、方案、法律等的初稿", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4cc9c03-6209-4c9e-868b-ad46e5b5769a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13272, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "销毁", "is_correct": false, "explanation": "语义：「销毁」是毁掉，与「启动」进程、「多边立法新阶段」的语境不符。"}, {"text": "起草", "is_correct": true, "explanation": "起草：初步写出文书的草稿，「国际文书起草进程」指文书草拟阶段，与句意相符。"}, {"text": "拆除", "is_correct": false, "explanation": "搭配：「拆除」搭配建筑、设施，不能用于「国际文书」。"}, {"text": "种植", "is_correct": false, "explanation": "语义：「种植」指栽培植物，与国际文书和立法进程无关。"}], "explanations": {"销毁": "语义：「销毁」是毁掉，与「启动」进程、「多边立法新阶段」的语境不符。", "起草": "起草：初步写出文书的草稿，「国际文书起草进程」指文书草拟阶段，与句意相符。", "拆除": "搭配：「拆除」搭配建筑、设施，不能用于「国际文书」。", "种植": "语义：「种植」指栽培植物，与国际文书和立法进程无关。"}, "sentence_index": 0, "correct_answer": "起草"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我上周起草了一首诗。", "explanation": "这里应该用〈写〉。起草指初步拟定文件、方案等正式文书，不用于诗歌等文学作品，写诗要用〈写〉。"}, {"text": "我们昨天起草了一张海报。", "explanation": "这里应该用〈制作〉。起草针对文字性材料，海报要设计、制作，不能说起草。"}, {"text": "这个网站是他起草的。", "explanation": "这里应该用〈设计〉。起草用于文件、方案等文字材料，网站要设计，不能说起草。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98bc4599-a177-4ba4-9fd8-632ff3437f74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13272, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "阅读", "is_correct": false, "explanation": "语义：通知还没有写出来，经理是请小王拟写，不是请他阅读；“阅读”不符合安排写作任务的语境。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：「煮」只用于食物，不能说煮「会议通知」。"}, {"text": "起草", "is_correct": true, "explanation": "起草：初步拟写会议通知，与「经理请小王」的工作安排相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」的宾语应为食物，不能说吃「会议通知」。"}], "explanations": {"阅读": "语义：通知还没有写出来，经理是请小王拟写，不是请他阅读；“阅读”不符合安排写作任务的语境。", "煮": "搭配：「煮」只用于食物，不能说煮「会议通知」。", "起草": "起草：初步拟写会议通知，与「经理请小王」的工作安排相符。", "吃": "搭配：「吃」的宾语应为食物，不能说吃「会议通知」。"}, "sentence_index": 6, "correct_answer": "起草"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校起草了一场新学期活动。", "explanation": "这里应该用〈策划〉。起草针对文件、方案的文字内容，活动要策划，不能说起草。"}, {"text": "学校起草了一场篮球比赛。", "explanation": "这里应该用〈组织〉。比赛是组织、举办的活动，不是文件，不能用起草。"}, {"text": "我们起草了一段宣传视频。", "explanation": "这里应该用〈拍摄〉。视频是拍摄、剪辑出来的，不能用起草。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98bc4599-a177-4ba4-9fd8-632ff3437f74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13272, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她正在起草了一份通知。", "corrected_sentence": "她正在起草一份通知。", "error_description": "错误：「正在」表示动作进行中，不能与完成体「了」同用。应去掉「了」，说「正在起草一份通知」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98bc4599-a177-4ba4-9fd8-632ff3437f74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13272, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我还没起草了报告。", "corrected_sentence": "我还没起草报告。", "error_description": "错误：“还没”表示动作尚未发生，后面的动词不能带完成体“了”。应去掉“了”，说“我还没起草报告。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98bc4599-a177-4ba4-9fd8-632ff3437f74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13273, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "偏废", "is_correct": true, "explanation": "偏废指只重视一方面、忽略另一方面，与“兼顾”的意思相反。"}, {"text": "思考", "is_correct": false, "explanation": "思考指动脑筋考虑问题，与“兼顾”不构成反义关系。"}, {"text": "搬运", "is_correct": false, "explanation": "搬运指把东西从一处移到另一处，与“兼顾”无关。"}, {"text": "寻找", "is_correct": false, "explanation": "寻找指设法找到某物，与“兼顾”无关。"}], "correct_answer": "偏废", "explanations": {"偏废": "偏废指只重视一方面、忽略另一方面，与“兼顾”的意思相反。", "思考": "思考指动脑筋考虑问题，与“兼顾”不构成反义关系。", "搬运": "搬运指把东西从一处移到另一处，与“兼顾”无关。", "寻找": "寻找指设法找到某物，与“兼顾”无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b143ccd7-5878-400e-8922-f929950c8fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13273, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "偏废", "is_correct": true, "explanation": "偏废指只重视一方面、忽略另一方面，与“兼顾”的意思相反。"}, {"text": "购买", "is_correct": false, "explanation": "购买指用钱换取物品，与“兼顾”无关。"}, {"text": "清洗", "is_correct": false, "explanation": "清洗指用水等去除污垢，与“兼顾”无关。"}, {"text": "批评", "is_correct": false, "explanation": "批评指指出缺点或错误，与“兼顾”无关。"}], "correct_answer": "偏废", "explanations": {"偏废": "偏废指只重视一方面、忽略另一方面，与“兼顾”的意思相反。", "购买": "购买指用钱换取物品，与“兼顾”无关。", "清洗": "清洗指用水等去除污垢，与“兼顾”无关。", "批评": "批评指指出缺点或错误，与“兼顾”无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b143ccd7-5878-400e-8922-f929950c8fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13273, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "同时照顾或注意到几个方面，使它们都得到适当的处理。", "primary_collocate": null, "pronunciation": "jiān gù", "ipa": "tɕjɛn˥ ku˥˩", "syllable_count": 2, "sentences": [{"text": "这个方案想兼顾速度和质量，所以做起来比较慢。", "target_word": "兼顾", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "她既要工作，又要带孩子，很难兼顾两头。", "target_word": "兼顾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做决定时，要兼顾公平和效率。", "target_word": "兼顾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个计划兼顾了学生和老师的需要。", "target_word": "兼顾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想兼顾学习和打工，每天都很累。", "target_word": "兼顾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的设计要兼顾美观和实用。", "target_word": "兼顾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司想兼顾发展和环保，所以选了新办法。", "target_word": "兼顾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲课要兼顾基础好和基础差的学生。", "target_word": "兼顾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路线兼顾了风景和时间，最合适。", "target_word": "兼顾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要想兼顾家庭和事业，需要好好安排时间。", "target_word": "兼顾", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "兼顾了", "label": "完成体"}, {"form": "兼顾过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "同时照顾几个方面并妥善处理，常带两个并列的宾语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16a20f6b-3319-4c28-9f9a-4514a0786ce7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13273, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "兼顾", "is_correct": true, "explanation": "兼顾指同时照顾几个方面，与“想……速度和质量”的意思相符。"}, {"text": "忽视", "is_correct": false, "explanation": "语义：忽视某一方与“想……速度和质量”的目标相矛盾，“所以做起来比较慢”也说不通。"}, {"text": "偏向", "is_correct": false, "explanation": "配价：“偏向”只带一个偏向的对象，不能与“速度和质量”两项并列。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：放弃速度与质量与句中“想……”的意图相反。"}], "explanations": {"兼顾": "兼顾指同时照顾几个方面，与“想……速度和质量”的意思相符。", "忽视": "语义：忽视某一方与“想……速度和质量”的目标相矛盾，“所以做起来比较慢”也说不通。", "偏向": "配价：“偏向”只带一个偏向的对象，不能与“速度和质量”两项并列。", "放弃": "语义：放弃速度与质量与句中“想……”的意图相反。"}, "sentence_index": 0, "correct_answer": "兼顾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他同时兼顾两家公司的顾问，忙得没有时间休息。", "explanation": "这里应该用〈兼任〉。兼任指同时担任几个职务，兼顾指同时照顾几个方面，不能用来说担任职务。"}, {"text": "这台电脑兼顾两种系统，使用很方便。", "explanation": "这里应该用〈兼容〉。兼容指两种东西能互相配合使用，兼顾不能用于机器和系统的关系。"}, {"text": "她每天都在兼顾孩子，很辛苦。", "explanation": "这里应该用〈照顾〉。兼顾须同时照顾两个以上的方面，只照顾孩子一方时用“照顾”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b143ccd7-5878-400e-8922-f929950c8fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13273, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "兼顾", "is_correct": true, "explanation": "兼顾指同时照顾发展和环保两方面，与句意相符。"}, {"text": "反对", "is_correct": false, "explanation": "语义：“反对”表示不同意，与“想……所以选了新办法”的句意不符。"}, {"text": "陪伴", "is_correct": false, "explanation": "配价：“陪伴”的对象一般是人，不能说“陪伴发展和环保”。"}, {"text": "祝贺", "is_correct": false, "explanation": "搭配：“祝贺”通常用于人或成就，不说“祝贺环保”。"}], "explanations": {"兼顾": "兼顾指同时照顾发展和环保两方面，与句意相符。", "反对": "语义：“反对”表示不同意，与“想……所以选了新办法”的句意不符。", "陪伴": "配价：“陪伴”的对象一般是人，不能说“陪伴发展和环保”。", "祝贺": "搭配：“祝贺”通常用于人或成就，不说“祝贺环保”。"}, "sentence_index": 6, "correct_answer": "兼顾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司兼顾了两家小企业，规模扩大了。", "explanation": "这里应该用〈兼并〉。兼并指把其他企业并入自己，兼顾指同时照顾几个方面。"}, {"text": "他周末兼顾做家教，收入不错。", "explanation": "这里应该用〈兼职〉。兼职指在本职工作之外再做另一份工作，兼顾不能用来说做工作。"}, {"text": "他每天都在兼顾老人，很辛苦。", "explanation": "这里应该用〈照料〉。兼顾须同时照顾两个方面，只照料老人一方时用“照料”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b143ccd7-5878-400e-8922-f929950c8fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13273, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要很兼顾质量和速度。", "corrected_sentence": "我们要兼顾质量和速度。", "error_description": "副词错误：“很”不能修饰动作动词“兼顾”，应说“要兼顾”，不说“要很兼顾”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b143ccd7-5878-400e-8922-f929950c8fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13273, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个计划已经兼顾了过质量和成本。", "corrected_sentence": "这个计划已经兼顾了质量和成本。", "error_description": "体标错误：“了”和“过”不能这样叠用，这里表示完成只用“了”，应说“兼顾了质量和成本”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b143ccd7-5878-400e-8922-f929950c8fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
