INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13279, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事物或方法能够达到预期效果的程度。", "primary_collocate": null, "pronunciation": "yǒu xiào xìng", "ipa": "joʊ˨˩˦ ɕjaʊ˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "生物降解材料的研发突破、循环经济产业链的重构、消费者行为的心理引导，均构成政策有效性的支撑要素。", "target_word": "有效性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "医生正在评估这种药物的有效性。", "target_word": "有效性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项政策的有效性还需要时间检验。", "target_word": "有效性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究人员测试了新方法的有效性。", "target_word": "有效性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种疫苗的有效性超过了百分之九十。", "target_word": "有效性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数据证明了这套教学方案的有效性。", "target_word": "有效性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们很难判断这则广告的有效性。", "target_word": "有效性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "提高管理的有效性是公司的目标。", "target_word": "有效性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验结果支持了该理论的有效性。", "target_word": "有效性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家质疑这份报告的有效性。", "target_word": "有效性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "事物或方法达到预期效果的程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '307c6c66-553a-4fd1-84cf-1f43674cbdfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13279, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有效性", "is_correct": true, "explanation": "正确。“政策有效性”指政策能达到预期效果的程度，与“支撑要素”的语境一致。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“政策颜色”无法作为“支撑要素”，与政策的内容不相关。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：“体积”用于可测量的物体，不与“政策”搭配。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”描述人的性情，不能作为政策的“支撑要素”。"}], "explanations": {"有效性": "正确。“政策有效性”指政策能达到预期效果的程度，与“支撑要素”的语境一致。", "颜色": "语义：“政策颜色”无法作为“支撑要素”，与政策的内容不相关。", "体积": "搭配：“体积”用于可测量的物体，不与“政策”搭配。", "脾气": "语义：“脾气”描述人的性情，不能作为政策的“支撑要素”。"}, "sentence_index": 0, "correct_answer": "有效性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器的有效性很重，搬起来很费力。", "explanation": "这里误用了〈重量〉的意思。有效性指方法达到效果的程度，不能用“重”来形容，“重”说的是物体的重量。"}, {"text": "他的有效性已经五十岁了。", "explanation": "这里应该用〈年龄〉。有效性不用来说明人的年龄，指人时应说年龄。"}, {"text": "这份报告的有效性很便宜。", "explanation": "这里误用了〈价格〉的意思。有效性指效果的程度，不能用“便宜”来形容，“便宜”说的是价格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503fd71d-248c-491d-8c92-75285f88227a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13279, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有效性", "is_correct": true, "explanation": "正确。“广告的有效性”指广告达到宣传效果的程度，与“判断”搭配，符合句意。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：广告没有“年龄”可以用来判断，句子不通。"}, {"text": "海拔", "is_correct": false, "explanation": "搭配：“海拔”用于地点，不说“广告的海拔”，与“广告”不搭配。"}, {"text": "血型", "is_correct": false, "explanation": "语义：“血型”是人或动物的属性，不能用来判断广告。"}], "explanations": {"有效性": "正确。“广告的有效性”指广告达到宣传效果的程度，与“判断”搭配，符合句意。", "年龄": "语义：广告没有“年龄”可以用来判断，句子不通。", "海拔": "搭配：“海拔”用于地点，不说“广告的海拔”，与“广告”不搭配。", "血型": "语义：“血型”是人或动物的属性，不能用来判断广告。"}, "sentence_index": 6, "correct_answer": "有效性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车的有效性很快。", "explanation": "这里应该用〈速度〉。有效性不用“快”来形容，“快”只用于速度。"}, {"text": "这座山的有效性很高。", "explanation": "这里应该用〈海拔〉。有效性不用来描述山的高低，“高”用于海拔等可测量的高度。"}, {"text": "这份报告的有效性很红，我们换一个吧。", "explanation": "这里误用了〈颜色〉的意思。有效性指效果的程度，不能用“红”来形容，“红”说的是颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503fd71d-248c-491d-8c92-75285f88227a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13279, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种方法很有效性，我们应该推广。", "corrected_sentence": "这种方法很有效，我们应该推广。", "error_description": "词性错误：“有效性”是名词，不能被程度副词“很”修饰；应改为形容词“有效”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503fd71d-248c-491d-8c92-75285f88227a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13279, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这则广告很有效性，产品的销量增长了不少。", "corrected_sentence": "这则广告很有效，产品的销量增长了不少。", "error_description": "词性错误：“有效性”是名词，不能被程度副词“很”修饰；应改为形容词“有效”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503fd71d-248c-491d-8c92-75285f88227a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
