INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13280, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "禁止和限制的规定，即对某些事物不允许或加以约束的条款。", "primary_collocate": null, "pronunciation": "jìn xiàn", "ipa": "tɕin˥˩ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "监管不再局限于禁限措施，更涵盖激励机制、信息透明与公众参与等多元工具。", "target_word": "禁限", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这座城市出台了新的禁限措施。", "target_word": "禁限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府公布了塑料制品禁限清单。", "target_word": "禁限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项禁限的范围将逐步扩大。", "target_word": "禁限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "企业必须遵守环保方面的禁限规定。", "target_word": "禁限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过多的禁限会影响市场活力。", "target_word": "禁限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校对手机使用制定了严格的禁限规定。", "target_word": "禁限", "complexity_tier": "T3", "furigana": "xué xiào duì shǒujī shǐyòng zhìdìng le yángé de jìnxiàn guīdìng", "sentence_source": "generated"}, {"text": "这些禁限只适用于危险化学品。", "target_word": "禁限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家认为单靠禁限无法解决污染问题。", "target_word": "禁限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新规放宽了对外资企业的禁限。", "target_word": "禁限", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "禁止和限制的规定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '307c6c66-553a-4fd1-84cf-1f43674cbdfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13280, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "禁限", "is_correct": true, "explanation": "正确：禁限 jìnxiàn，指禁止和限制的规定。"}, {"text": "尽显", "is_correct": false, "explanation": "尽显 jìnxiǎn 与 jìnxiàn 第二音节声调不同（第三声 / 第四声），意思是充分显示。"}, {"text": "尽先", "is_correct": false, "explanation": "尽先 jìnxiān 与 jìnxiàn 第二音节声调不同（第一声 / 第四声），意思是优先、首先。"}, {"text": "尽孝", "is_correct": false, "explanation": "尽孝 jìnxiào 与 jìnxiàn 第二音节韵母不同（-iao / -ian），意思是孝敬父母。"}, {"text": "金线", "is_correct": false, "explanation": "金线 jīnxiàn 与 jìnxiàn 第一音节声调不同（阴平 / 去声），意思是金色的线。"}], "explanations": {"禁限": "正确：禁限 jìnxiàn，指禁止和限制的规定。", "尽显": "尽显 jìnxiǎn 与 jìnxiàn 第二音节声调不同（第三声 / 第四声），意思是充分显示。", "尽先": "尽先 jìnxiān 与 jìnxiàn 第二音节声调不同（第一声 / 第四声），意思是优先、首先。", "尽孝": "尽孝 jìnxiào 与 jìnxiàn 第二音节韵母不同（-iao / -ian），意思是孝敬父母。", "金线": "金线 jīnxiàn 与 jìnxiàn 第一音节声调不同（阴平 / 去声），意思是金色的线。"}, "sentence_index": null, "correct_answer": "禁限"}, "level_3": {"options": [{"text": "禁限", "is_correct": true, "explanation": "正确：「局限于禁限措施」中，禁限修饰措施，指禁止和限制的规定，与监管的语境相合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以被监管的措施，与句中的监管语境冲突。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：花朵不属于监管对象，与句中的监管和措施冲突。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：玩意儿是口语，与这段书面语的论述语域不合。"}], "explanations": {"禁限": "正确：「局限于禁限措施」中，禁限修饰措施，指禁止和限制的规定，与监管的语境相合。", "天气": "语义：天气不是可以被监管的措施，与句中的监管语境冲突。", "花朵": "语义：花朵不属于监管对象，与句中的监管和措施冲突。", "玩意儿": "语域：玩意儿是口语，与这段书面语的论述语域不合。"}, "sentence_index": 0, "correct_answer": "禁限"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店的禁限很便宜。", "explanation": "这里应该用〈商品〉。禁限指禁止和限制的规定，不指卖的东西；说东西便宜应该用‘商品’作主语。"}, {"text": "这张画的禁限很漂亮。", "explanation": "这里应该用〈画〉。禁限指禁止和限制的规定，不指可以欣赏的作品；说画好看要用‘画’。"}, {"text": "这把刀的禁限很锋利。", "explanation": "这里应该用〈刀刃〉。禁限指禁止和限制的规定，不指刀的锋口；说刀锋利应以“刀刃”作主语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503fd71d-248c-491d-8c92-75285f88227a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13280, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "禁限", "is_correct": true, "explanation": "正确：禁限 jìnxiàn，指禁止和限制的规定。"}, {"text": "尽显", "is_correct": false, "explanation": "尽显 jìnxiǎn 与 jìnxiàn 声调不同（第三声 / 第四声），意思是充分显示。"}, {"text": "尽信", "is_correct": false, "explanation": "尽信 jìnxìn 与 jìnxiàn 韵母不同（-in / -ian），意思是完全相信。"}, {"text": "进项", "is_correct": false, "explanation": "进项 jìnxiàng 与 jìnxiàn 韵母不同（-iang / -ian），意思是收入。"}, {"text": "金线", "is_correct": false, "explanation": "金线 jīnxiàn 与 jìnxiàn 第一音节声调不同（阴平 / 去声），意思是金色的线。"}], "explanations": {"禁限": "正确：禁限 jìnxiàn，指禁止和限制的规定。", "尽显": "尽显 jìnxiǎn 与 jìnxiàn 声调不同（第三声 / 第四声），意思是充分显示。", "尽信": "尽信 jìnxìn 与 jìnxiàn 韵母不同（-in / -ian），意思是完全相信。", "进项": "进项 jìnxiàng 与 jìnxiàn 韵母不同（-iang / -ian），意思是收入。", "金线": "金线 jīnxiàn 与 jìnxiàn 第一音节声调不同（阴平 / 去声），意思是金色的线。"}, "sentence_index": null, "correct_answer": "禁限"}, "level_3": {"options": [{"text": "禁限", "is_correct": true, "explanation": "正确：「严格的禁限规定」中，禁限指禁止和限制，与学校对手机使用的规定相合。"}, {"text": "食堂", "is_correct": false, "explanation": "语义：食堂与手机使用无关，不能作为学校对手机使用制定规定的对象。"}, {"text": "宠物", "is_correct": false, "explanation": "语义：宠物与手机使用无关，与句中学校制定的规定对象矛盾。"}, {"text": "家伙", "is_correct": false, "explanation": "语域：家伙是口语，与书面的规定语域不合，且与手机使用的语境冲突。"}], "explanations": {"禁限": "正确：「严格的禁限规定」中，禁限指禁止和限制，与学校对手机使用的规定相合。", "食堂": "语义：食堂与手机使用无关，不能作为学校对手机使用制定规定的对象。", "宠物": "语义：宠物与手机使用无关，与句中学校制定的规定对象矛盾。", "家伙": "语域：家伙是口语，与书面的规定语域不合，且与手机使用的语境冲突。"}, "sentence_index": 6, "correct_answer": "禁限"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这片林子里的禁限很多，长得很茂盛。", "explanation": "这里应该用〈树〉。禁限指禁止和限制的规定，不是植物；“茂盛”只用于植物。"}, {"text": "这间屋子的禁限很亮，照得人睁不开眼。", "explanation": "这里应该用〈灯〉。禁限指禁止和限制的规定，不会发光；“亮”用于灯光等发光的东西。"}, {"text": "他是我们班的禁限，大家都很佩服他。", "explanation": "这里应该用〈榜样〉。禁限是规定，不指人；称赞某人作为表率要说‘榜样’。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503fd71d-248c-491d-8c92-75285f88227a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13280, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府出台了一把新的禁限。", "corrected_sentence": "政府出台了一项新的禁限。", "error_description": "量词错误：禁限是规定，应用量词‘项’（或‘条’）。‘把’用于有柄的器具，说‘一把新的禁限’是错的，正确应为‘一项新的禁限’。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503fd71d-248c-491d-8c92-75285f88227a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13280, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校放大了对体育活动的禁限。", "corrected_sentence": "学校放宽了对体育活动的禁限。", "error_description": "搭配错误：禁限应与‘放宽’或‘收紧’搭配。‘放大’多用于范围或影响，不说‘放大禁限’。正确应为‘放宽了对体育活动的禁限’。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503fd71d-248c-491d-8c92-75285f88227a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13282, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503fd71d-248c-491d-8c92-75285f88227a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
