INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13282, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "根据事物发展规律预先料到将来。", "primary_collocate": null, "pronunciation": "yù jiàn", "ipa": "y⁵¹ tɕjɛn⁵¹", "syllable_count": 2, "sentences": [{"text": "可以预见，未来立法将更强调全生命周期管理，从原料提取、产品设计到废弃物回收，形成闭环控制体系。", "target_word": "预见", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "专家预见到明年的房价会下降。", "target_word": "预见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经验丰富的医生能预见病情的发展。", "target_word": "预见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家根据数据预见了气候的变化。", "target_word": "预见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他早就预见到这家公司会遇到困难。", "target_word": "预见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人能准确预见十年后的世界。", "target_word": "预见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位经济学家成功预见了那次危机。", "target_word": "预见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "根据人口的变化，我们可以预见学校会不够用。", "target_word": "预见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的领导者要能预见未来的风险。", "target_word": "预见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁也没有预见这场大雨会下这么久。", "target_word": "预见", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "预见到", "label": "结果补语"}, {"form": "预见了", "label": "体标"}, {"form": "预见性", "label": "派生"}], "register": "书面", "sense_fingerprint": "根据规律预先料到将来的发展", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '307c6c66-553a-4fd1-84cf-1f43674cbdfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13282, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "预见", "is_correct": true, "explanation": "正确：预见 yùjiàn，指根据规律预先料到将来。"}, {"text": "物件", "is_correct": false, "explanation": "物件 wùjiàn 与 yùjiàn 韵母不同（u / ü），意思是物品。"}, {"text": "预检", "is_correct": false, "explanation": "预检 yùjiǎn 与 yùjiàn 声调不同（第三声 / 第四声），意思是事先检查。"}, {"text": "去见", "is_correct": false, "explanation": "去见 qùjiàn 与 yùjiàn 声母不同（q / 零声母），意思是前去会见。"}, {"text": "玉笺", "is_correct": false, "explanation": "玉笺 yùjiān 与 yùjiàn 第二音节声调不同（第一声 / 第四声），意思是书信用的精美笺纸。"}], "explanations": {"预见": "正确：预见 yùjiàn，指根据规律预先料到将来。", "物件": "物件 wùjiàn 与 yùjiàn 韵母不同（u / ü），意思是物品。", "预检": "预检 yùjiǎn 与 yùjiàn 声调不同（第三声 / 第四声），意思是事先检查。", "去见": "去见 qùjiàn 与 yùjiàn 声母不同（q / 零声母），意思是前去会见。", "玉笺": "玉笺 yùjiān 与 yùjiàn 第二音节声调不同（第一声 / 第四声），意思是书信用的精美笺纸。"}, "sentence_index": null, "correct_answer": "预见"}, "level_3": {"options": [{"text": "预见", "is_correct": true, "explanation": "正确：「可以预见，未来立法将更强调……」中，预见表示事先料到未来的发展，与句意相合。"}, {"text": "回顾", "is_correct": false, "explanation": "语义：回顾指向过去看，与句中‘未来立法’的语境冲突。"}, {"text": "追忆", "is_correct": false, "explanation": "语义：追忆指回想已经发生的事，与句中展望未来的语境矛盾。"}, {"text": "瞅", "is_correct": false, "explanation": "语域：瞅是口语，与这段书面的政策论述语域不合。"}], "explanations": {"预见": "正确：「可以预见，未来立法将更强调……」中，预见表示事先料到未来的发展，与句意相合。", "回顾": "语义：回顾指向过去看，与句中‘未来立法’的语境冲突。", "追忆": "语义：追忆指回想已经发生的事，与句中展望未来的语境矛盾。", "瞅": "语域：瞅是口语，与这段书面的政策论述语域不合。"}, "sentence_index": 0, "correct_answer": "预见"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈在厨房里预见了一锅汤。", "explanation": "这里应该用〈煮〉。预见指事先料到将来，不指动手烹煮食物。"}, {"text": "哥伦布在海上预见了一群海豚。", "explanation": "这里应该用〈遇见〉（同音词）。预见指事先料到将来，不指在海上碰到动物。"}, {"text": "我在街上预见了老朋友。", "explanation": "这里应该用〈遇见〉（同音词）。预见是事先推测将来，偶然碰到人要说“遇见”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503fd71d-248c-491d-8c92-75285f88227a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13282, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "预见", "is_correct": true, "explanation": "正确：预见 yùjiàn，指根据规律预先料到将来。"}, {"text": "意见", "is_correct": false, "explanation": "意见 yìjiàn 与 yùjiàn 韵母不同（i / ü），意思是看法。"}, {"text": "拒见", "is_correct": false, "explanation": "拒见 jùjiàn 与 yùjiàn 声母不同（j / 零声母），意思是拒绝接见。"}, {"text": "续建", "is_correct": false, "explanation": "续建 xùjiàn 与 yùjiàn 声母不同（x / 零声母），意思是继续建设。"}], "explanations": {"预见": "正确：预见 yùjiàn，指根据规律预先料到将来。", "意见": "意见 yìjiàn 与 yùjiàn 韵母不同（i / ü），意思是看法。", "拒见": "拒见 jùjiàn 与 yùjiàn 声母不同（j / 零声母），意思是拒绝接见。", "续建": "续建 xùjiàn 与 yùjiàn 声母不同（x / 零声母），意思是继续建设。"}, "sentence_index": null, "correct_answer": "预见"}, "level_3": {"options": [{"text": "预见", "is_correct": true, "explanation": "正确：「这位经济学家成功预见了那次危机」中，预见表示事先料到危机，与‘成功’相合。"}, {"text": "亲历", "is_correct": false, "explanation": "搭配：‘成功’说做成的事，‘亲历’指亲身经历，二者不搭，句中不说‘成功亲历危机’。"}, {"text": "撰写", "is_correct": false, "explanation": "配价：‘撰写’要求文字作品作宾语，不能带‘危机’这样的事件作宾语。"}, {"text": "清点", "is_correct": false, "explanation": "搭配：‘清点’用于物品或人数，不用于‘危机’。"}], "explanations": {"预见": "正确：「这位经济学家成功预见了那次危机」中，预见表示事先料到危机，与‘成功’相合。", "亲历": "搭配：‘成功’说做成的事，‘亲历’指亲身经历，二者不搭，句中不说‘成功亲历危机’。", "撰写": "配价：‘撰写’要求文字作品作宾语，不能带‘危机’这样的事件作宾语。", "清点": "搭配：‘清点’用于物品或人数，不用于‘危机’。"}, "sentence_index": 6, "correct_answer": "预见"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在屋里预见了一张床。", "explanation": "这里应该用〈看见〉。预见指事先料到将来，不指眼前看到家具。"}, {"text": "周末我预见了老师。", "explanation": "这里应该用〈拜访〉。预见不能表示去看望人；去看望要说‘拜访’。"}, {"text": "科学家在实验室里预见了一块石头。", "explanation": "这里应该用〈分析〉。预见指事先料到将来，不指对实物做检测。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503fd71d-248c-491d-8c92-75285f88227a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13282, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他能预见了市场的变化。", "corrected_sentence": "他能预见市场的变化。", "error_description": "了错误：‘能’表示能力或可能，后面的动词不带‘了’。‘能预见了’与可能义冲突，正确应为‘他能预见市场的变化’。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503fd71d-248c-491d-8c92-75285f88227a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13282, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "专家提前预见了到风险。", "corrected_sentence": "专家提前预见到了风险。", "error_description": "补语位置错误：结果补语‘到’应紧接动词‘预见’，‘了’放在补语之后。‘预见了到’是错的，正确应为‘预见到了风险’。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503fd71d-248c-491d-8c92-75285f88227a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13283, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503fd71d-248c-491d-8c92-75285f88227a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13283, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503fd71d-248c-491d-8c92-75285f88227a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13283, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一种自动控制方式，系统根据输出结果自动调整输入，使输出保持在设定目标。", "primary_collocate": null, "pronunciation": "bì huán kòng zhì", "ipa": "pi⁵¹ xwan³⁵ kʰʊŋ⁵¹ ʈʂʐ̩⁵¹", "syllable_count": 4, "sentences": [{"text": "电机转速的稳定依赖闭环控制：传感器持续采集实际转速，控制器据此修正输入。", "target_word": "闭环控制", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "空调用闭环控制来保持房间的温度。", "target_word": "闭环控制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "闭环控制能根据结果自动调整输入。", "target_word": "闭环控制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器使用了闭环控制，不需要人看着。", "target_word": "闭环控制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂里的机器人靠闭环控制保持速度稳定。", "target_word": "闭环控制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "闭环控制会不断检查输出的结果，再做调整。", "target_word": "闭环控制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车的自动驾驶也用到闭环控制。", "target_word": "闭环控制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "温度太高时，闭环控制会让机器自动降温。", "target_word": "闭环控制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师正在学习闭环控制的基本方法。", "target_word": "闭环控制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了闭环控制，水箱里的水位不会太高。", "target_word": "闭环控制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "闭环控制系统", "label": "复合"}], "register": "书面", "sense_fingerprint": "根据输出结果自动调整输入的控制方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '307c6c66-553a-4fd1-84cf-1f43674cbdfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13283, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "闭环控制", "is_correct": true, "explanation": "正确。句中“传感器持续采集实际转速，控制器据此修正输入”描述的正是根据输出结果自动调整输入的控制方式。"}, {"text": "开环控制", "is_correct": false, "explanation": "语义：“开环控制”不利用输出反馈，与句中“传感器采集实际转速”这一反馈环节相矛盾。"}, {"text": "齿轮传动", "is_correct": false, "explanation": "语义：“齿轮传动”是传递动力的机械方式，不是根据输出调节输入的控制方式，与“控制器修正输入”不符。"}, {"text": "温度计", "is_correct": false, "explanation": "语义：“温度计”是测量温度的工具，不能作为“转速稳定”所依赖的控制方式，与句意不符。"}], "explanations": {"闭环控制": "正确。句中“传感器持续采集实际转速，控制器据此修正输入”描述的正是根据输出结果自动调整输入的控制方式。", "开环控制": "语义：“开环控制”不利用输出反馈，与句中“传感器采集实际转速”这一反馈环节相矛盾。", "齿轮传动": "语义：“齿轮传动”是传递动力的机械方式，不是根据输出调节输入的控制方式，与“控制器修正输入”不符。", "温度计": "语义：“温度计”是测量温度的工具，不能作为“转速稳定”所依赖的控制方式，与句意不符。"}, "sentence_index": 0, "correct_answer": "闭环控制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师给了我很多闭环控制，帮助我提高了成绩。", "explanation": "这里应该用〈反馈〉。闭环控制是一种技术上的控制方式，指系统根据输出调整输入，不能用来指老师对学生的意见。"}, {"text": "我把闭环控制放进书包，带到了学校。", "explanation": "这里应该用〈遥控器〉。闭环控制是一种控制方式，不是能拿在手里、放进书包的实物。"}, {"text": "这个程序用了一种闭环控制来识别图片。", "explanation": "这里应该用〈算法〉。闭环控制是调节输入的控制方式，不是识别图像的方法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503fd71d-248c-491d-8c92-75285f88227a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13283, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "闭环控制", "is_correct": true, "explanation": "正确。汽车的自动驾驶依靠闭环控制来调节方向和速度，句子通顺。"}, {"text": "人工驾驶", "is_correct": false, "explanation": "语义：“人工驾驶”与句中的“自动驾驶”相对，说“自动驾驶也用到人工驾驶”自相矛盾。"}, {"text": "马车", "is_correct": false, "explanation": "语义：“马车”是古老的交通工具，与“汽车的自动驾驶”所指的现代技术不符。"}, {"text": "蒸汽机", "is_correct": false, "explanation": "搭配：“蒸汽机”不是现代汽车自动驾驶使用的技术，“也用到蒸汽机”搭配不当。"}], "explanations": {"闭环控制": "正确。汽车的自动驾驶依靠闭环控制来调节方向和速度，句子通顺。", "人工驾驶": "语义：“人工驾驶”与句中的“自动驾驶”相对，说“自动驾驶也用到人工驾驶”自相矛盾。", "马车": "语义：“马车”是古老的交通工具，与“汽车的自动驾驶”所指的现代技术不符。", "蒸汽机": "搭配：“蒸汽机”不是现代汽车自动驾驶使用的技术，“也用到蒸汽机”搭配不当。"}, "sentence_index": 6, "correct_answer": "闭环控制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工程师设计了一只闭环控制，用来保持水温稳定。", "explanation": "这里应该用〈种〉。闭环控制是抽象的控制方式，〈只〉多用于动物，不能用于它。"}, {"text": "工程师设计了一把闭环控制，用来保持水温稳定。", "explanation": "这里应该用〈种〉。〈把〉多用于有柄的器具，闭环控制不是器具，不能用〈把〉计量。"}, {"text": "工程师设计了一台闭环控制，用来保持水温稳定。", "explanation": "这里应该用〈种〉。〈台〉用于机器设备，闭环控制是控制方法，不是设备。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503fd71d-248c-491d-8c92-75285f88227a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13283, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂把闭环控制来稳定机器的速度。", "corrected_sentence": "工厂用闭环控制来稳定机器的速度。", "error_description": "错误形式：“把闭环控制来稳定”用“把”引出对象，但后面没有合适的动词结构；正确形式：“用闭环控制来稳定”。“闭环控制”作为工具，应用“用”引出，“把”字句不能这样用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503fd71d-248c-491d-8c92-75285f88227a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13283, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台冰箱用了一台闭环控制来保持温度。", "corrected_sentence": "这台冰箱用了一种闭环控制来保持温度。", "error_description": "量词错了。“闭环控制”是抽象的控制方式，应该用量词“种”，不能用“台”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503fd71d-248c-491d-8c92-75285f88227a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
