INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13294, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指河流的水面以下或水流之中。", "primary_collocate": null, "pronunciation": "hé li", "ipa": "xɤ˧˥ li", "syllable_count": 2, "sentences": [{"text": "脏水流到河里，鱼也会死。", "target_word": "河里", "complexity_tier": "T1", "sentence_source": "mined"}, {"text": "工厂做衣服时，也会把脏水排到河里。", "target_word": "河里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河里有很多小鱼。", "target_word": "河里", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们在河里游泳。", "target_word": "河里", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "夏天，他常常到河里洗澡。", "target_word": "河里", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "河里的水很清，能看见石头。", "target_word": "河里", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人在河里抓了一条大鱼。", "target_word": "河里", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小船在河里慢慢地漂着。", "target_word": "河里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的帽子掉进了河里。", "target_word": "河里", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们在河里发现过一只小乌龟。", "target_word": "河里", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "河裡", "label": "繁体"}], "register": "中性", "sense_fingerprint": "河流的水面以下或水流之中，表示事物所在或动作发生的处所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd34bc2cc-089b-431f-93cf-0515a2573957') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13294, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "河里", "is_correct": true, "explanation": "河里指水面以下，脏水流入水体会让鱼死亡，句意通顺。"}, {"text": "树上", "is_correct": false, "explanation": "语义：鱼生活在水中，“脏水流到树上，鱼也会死”与前后语境的因果关系不成立。"}, {"text": "房间里", "is_correct": false, "explanation": "语义：房间里没有水体，鱼不会生活在其中，与“鱼也会死”的语境冲突。"}, {"text": "盘子里", "is_correct": false, "explanation": "搭配：“脏水流到”多指流向地面或水体，“盘子里”太小，一般不这样搭配。"}], "explanations": {"河里": "河里指水面以下，脏水流入水体会让鱼死亡，句意通顺。", "树上": "语义：鱼生活在水中，“脏水流到树上，鱼也会死”与前后语境的因果关系不成立。", "房间里": "语义：房间里没有水体，鱼不会生活在其中，与“鱼也会死”的语境冲突。", "盘子里": "搭配：“脏水流到”多指流向地面或水体，“盘子里”太小，一般不这样搭配。"}, "sentence_index": 0, "correct_answer": "河里"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在河里散步，欣赏两岸的风景。", "explanation": "这里应该用〈河边〉。散步是在岸边走，「河里」指水中，二者不能互换。"}, {"text": "他躺在河里看书，看得很入迷。", "explanation": "这里应该用〈床上〉。躺着看书要在床上，「河里」指水中，不能躺在水里看书。"}, {"text": "孩子们在河里放风筝，玩得很开心。", "explanation": "这里应该用〈草地上〉。放风筝需要开阔的陆地，「河里」指水中。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13294, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "河里", "is_correct": true, "explanation": "河里指水中，老人在水中抓鱼，符合语境。"}, {"text": "沙发上", "is_correct": false, "explanation": "语义：沙发上不会有可抓的鱼，“老人在沙发上抓了一条大鱼”与常识冲突。"}, {"text": "树林里", "is_correct": false, "explanation": "语义：树林里没有鱼，“在树林里抓了一条大鱼”不成立。"}, {"text": "办公室里", "is_correct": false, "explanation": "搭配：“抓鱼”的地点应是水边或水中，“办公室里”与“抓了一条大鱼”不搭配。"}], "explanations": {"河里": "河里指水中，老人在水中抓鱼，符合语境。", "沙发上": "语义：沙发上不会有可抓的鱼，“老人在沙发上抓了一条大鱼”与常识冲突。", "树林里": "语义：树林里没有鱼，“在树林里抓了一条大鱼”不成立。", "办公室里": "搭配：“抓鱼”的地点应是水边或水中，“办公室里”与“抓了一条大鱼”不搭配。"}, "sentence_index": 6, "correct_answer": "河里"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民在河里种菜，秋天收获很多。", "explanation": "这里应该用〈田里〉。种菜要在土地上，「河里」指水中，不能在水中种菜。"}, {"text": "孩子们在河里堆城堡，玩得很开心。", "explanation": "这里应该用〈沙滩上〉。堆沙城堡要在沙地上，「河里」指水中，沙子会被冲走。"}, {"text": "爷爷在河里写字，写得很认真。", "explanation": "这里应该用〈桌上〉。写字要在桌面上，「河里」指水中，不能在水里写字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13294, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们河里玩水。", "corrected_sentence": "孩子们在河里玩水。", "error_description": "错误：「河里」前漏掉介词「在」，写成「孩子们河里玩水」。正确应为「在河里玩水」，处所词要由「在」引出，放在动词前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13294, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一条鱼在河里的慢慢游。", "corrected_sentence": "一条鱼在河里慢慢游。", "error_description": "错误：「河里」后多出结构助词「的」，使「在河里的」变成定语，「慢慢游」缺少中心语。正确应为「在河里慢慢游」，处所短语后不加「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
