INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13296, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指商品或服务吸引消费者购买的特性或优势。", "primary_collocate": null, "pronunciation": "mǎi diǎn", "ipa": "mai˨˩˦ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "这家餐厅的买点是菜好吃，环境也安静。", "target_word": "买点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手机的最大买点是电池用得久。", "target_word": "买点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "便宜是这家店的买点，所以客人很多。", "target_word": "买点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子的买点是不怕热，也不怕摔。", "target_word": "买点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板问我们：这个东西的买点是什么？", "target_word": "买点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对很多人来说，好看就是衣服的买点。", "target_word": "买点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的买点是故事有意思，字也大。", "target_word": "买点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车的买点是省油，价钱也不高。", "target_word": "买点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王写出了这个商品的三个买点。", "target_word": "买点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个广告没有说清楚房子的买点。", "target_word": "买点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "買點", "label": "繁体"}], "register": "中性", "sense_fingerprint": "买点：商品吸引消费者购买的特性或优势", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8d2bbf4-79da-4014-b207-c5baecb20bf5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13296, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "买点", "is_correct": true, "explanation": "正确：“买点”指吸引消费者购买的优势，“菜好吃，环境也安静”正是餐厅的优势。"}, {"text": "缺点", "is_correct": false, "explanation": "语义：“缺点”与“菜好吃，环境也安静”所说的优势相矛盾。"}, {"text": "地址", "is_correct": false, "explanation": "语义：“地址”指位置，不能用来说“是菜好吃”。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”不能与“是菜好吃，环境也安静”搭配，句意不通。"}], "explanations": {"买点": "正确：“买点”指吸引消费者购买的优势，“菜好吃，环境也安静”正是餐厅的优势。", "缺点": "语义：“缺点”与“菜好吃，环境也安静”所说的优势相矛盾。", "地址": "语义：“地址”指位置，不能用来说“是菜好吃”。", "价格": "搭配：“价格”不能与“是菜好吃，环境也安静”搭配，句意不通。"}, "sentence_index": 0, "correct_answer": "买点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的买点是很诚实，大家都愿意跟他合作。", "explanation": "这里应该用〈优点〉。买点只指商品或服务吸引人购买的地方，不用来说人的品质。"}, {"text": "这个电脑有三只买点，屏幕很亮。", "explanation": "这里应该用〈个〉。“只”用于动物等，买点要用“个”计量。"}, {"text": "这个手机的买点是公司能赚很多钱。", "explanation": "这里应该用〈卖点〉。买点是顾客想买的理由，卖点是商家宣传的特色；“公司能赚很多钱”站在商家角度，不是顾客想买的理由。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a0befb2-7c0f-481b-b847-2f8872445ee7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13296, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "封面", "is_correct": false, "explanation": "语义：“封面”指书的外壳，与“故事有意思，字也大”所说的内容无关，句子不通。"}, {"text": "买点", "is_correct": true, "explanation": "正确。买点指吸引人购买的优势，这里说这本书的故事有意思、字也大。"}, {"text": "页数", "is_correct": false, "explanation": "搭配：“页数”指书的张数，不能说“是故事有意思，字也大”，搭配不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”说的是岁数，与句中对书的评价不相容。"}], "explanations": {"封面": "语义：“封面”指书的外壳，与“故事有意思，字也大”所说的内容无关，句子不通。", "买点": "正确。买点指吸引人购买的优势，这里说这本书的故事有意思、字也大。", "页数": "搭配：“页数”指书的张数，不能说“是故事有意思，字也大”，搭配不通。", "年龄": "语义：“年龄”说的是岁数，与句中对书的评价不相容。"}, "sentence_index": 6, "correct_answer": "买点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "房子的买点是离地铁太远，交通不方便。", "explanation": "这里应该用〈缺点〉。买点指吸引人购买的优势，“离地铁太远”是缺点，不能叫买点。"}, {"text": "这套房子有三片买点。", "explanation": "这里应该用〈个〉。“片”用于叶子、面包等薄片状的东西，买点要用“个”计量。"}, {"text": "这家房产中介有一朵买点。", "explanation": "这里应该用〈个〉。“朵”用于花、云等，不用于买点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a0befb2-7c0f-481b-b847-2f8872445ee7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13296, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个水壶有两朵买点，价钱不高。", "corrected_sentence": "这个水壶有两个买点，价钱不高。", "error_description": "量词错误：“朵”用于花、云等，“买点”应用“个”计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a0befb2-7c0f-481b-b847-2f8872445ee7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13296, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台电视有两本买点：屏幕大，声音也好。", "corrected_sentence": "这台电视有两个买点：屏幕大，声音也好。", "error_description": "量词错误：“本”用于书本，“买点”应用“个”计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a0befb2-7c0f-481b-b847-2f8872445ee7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13297, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "浪费", "is_correct": true, "explanation": "浪费：与“省”互为反义，指不节约、随意耗用钱物。"}, {"text": "赚取", "is_correct": false, "explanation": "赚取：指获得钱财，与“省”的节约义没有反义关系。"}, {"text": "购买", "is_correct": false, "explanation": "购买：指花钱取得物品，与“省”的节约义不构成反义关系。"}, {"text": "增加", "is_correct": false, "explanation": "增加：指数量变多，与“省”的节约义没有反义关系。"}], "correct_answer": "浪费", "explanations": {"浪费": "浪费：与“省”互为反义，指不节约、随意耗用钱物。", "赚取": "赚取：指获得钱财，与“省”的节约义没有反义关系。", "购买": "购买：指花钱取得物品，与“省”的节约义不构成反义关系。", "增加": "增加：指数量变多，与“省”的节约义没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a0befb2-7c0f-481b-b847-2f8872445ee7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13297, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "浪费", "is_correct": true, "explanation": "浪费：与“省”互为反义，指不节约、随意耗用钱物。"}, {"text": "生产", "is_correct": false, "explanation": "生产：指制造物品，与“省”的节约义没有反义关系。"}, {"text": "扩大", "is_correct": false, "explanation": "扩大：指范围或规模变大，与“省”的节约义没有反义关系。"}, {"text": "出售", "is_correct": false, "explanation": "出售：指把东西卖掉，与“省”的节约义没有反义关系。"}], "correct_answer": "浪费", "explanations": {"浪费": "浪费：与“省”互为反义，指不节约、随意耗用钱物。", "生产": "生产：指制造物品，与“省”的节约义没有反义关系。", "扩大": "扩大：指范围或规模变大，与“省”的节约义没有反义关系。", "出售": "出售：指把东西卖掉，与“省”的节约义没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a0befb2-7c0f-481b-b847-2f8872445ee7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13297, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "节约，不浪费；如省钱、省时间。", "primary_collocate": null, "pronunciation": "shěng", "ipa": "ʂɤŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "坐地铁上班可以省钱。", "target_word": "省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走这条路能省不少时间。", "target_word": "省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们关灯出门，是为了省电。", "target_word": "省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很会省，每个月都存一点钱。", "target_word": "省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把吃饭的钱省下来买了一本书。", "target_word": "省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少洗一次车，也能省很多水。", "target_word": "省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在家做饭比在外面吃饭省钱。", "target_word": "省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每次买东西都会先比价，这样能省不少钱。", "target_word": "省", "complexity_tier": "T3", "furigana": "wǒ měi cì mǎi dōng xi dōu huì xiān bǐ jià, zhè yàng néng shěng bù shǎo qián.", "sentence_source": "generated"}, {"text": "为了省时间，我们坐出租车去机场。", "target_word": "省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他省了很久，终于买了新手机。", "target_word": "省", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "省了", "label": "体标"}, {"form": "省着", "label": "体标"}, {"form": "省省", "label": "重叠"}, {"form": "省钱", "label": "复合"}, {"form": "省电", "label": "复合"}], "register": "中性", "sense_fingerprint": "省：节约，不浪费钱、时间等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8d2bbf4-79da-4014-b207-c5baecb20bf5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13297, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "省", "is_correct": true, "explanation": "省（shěng）：节约，不浪费钱或时间。"}, {"text": "生", "is_correct": false, "explanation": "shēng（第一声）与 shěng（第三声）声调不同，意思是“生命、出生”。"}, {"text": "声", "is_correct": false, "explanation": "shēng（第一声）与 shěng（第三声）声调不同，意思是“声音”。"}, {"text": "剩", "is_correct": false, "explanation": "shèng（第四声）与 shěng（第三声）声调不同，意思是“剩余”。"}, {"text": "圣", "is_correct": false, "explanation": "shèng（第四声）与 shěng（第三声）声调不同，意思是“神圣”。"}, {"text": "婶", "is_correct": false, "explanation": "shěn 与 shěng 韵母不同（-n 与 -ng），意思是“婶婶”。"}, {"text": "审", "is_correct": false, "explanation": "shěn 与 shěng 韵母不同（-n 与 -ng），意思是“审查”。"}], "explanations": {"省": "省（shěng）：节约，不浪费钱或时间。", "生": "shēng（第一声）与 shěng（第三声）声调不同，意思是“生命、出生”。", "声": "shēng（第一声）与 shěng（第三声）声调不同，意思是“声音”。", "剩": "shèng（第四声）与 shěng（第三声）声调不同，意思是“剩余”。", "圣": "shèng（第四声）与 shěng（第三声）声调不同，意思是“神圣”。", "婶": "shěn 与 shěng 韵母不同（-n 与 -ng），意思是“婶婶”。", "审": "shěn 与 shěng 韵母不同（-n 与 -ng），意思是“审查”。"}, "sentence_index": null, "correct_answer": "省"}, "level_3": {"options": [{"text": "省", "is_correct": true, "explanation": "“省”表示节约钱财，“坐地铁上班可以省钱”符合句意。"}, {"text": "赔", "is_correct": false, "explanation": "语义：“赔钱”指亏本、损失钱财，与“坐地铁上班可以……钱”要表达的节省相反。"}, {"text": "亏", "is_correct": false, "explanation": "语义：“亏钱”指蚀本，句中是在说坐地铁带来的好处，两者意思相反。"}, {"text": "借", "is_correct": false, "explanation": "语义：“借钱”是向别人借入钱财，与“坐地铁上班”能省钱的语境不合。"}], "explanations": {"省": "“省”表示节约钱财，“坐地铁上班可以省钱”符合句意。", "赔": "语义：“赔钱”指亏本、损失钱财，与“坐地铁上班可以……钱”要表达的节省相反。", "亏": "语义：“亏钱”指蚀本，句中是在说坐地铁带来的好处，两者意思相反。", "借": "语义：“借钱”是向别人借入钱财，与“坐地铁上班”能省钱的语境不合。"}, "sentence_index": 0, "correct_answer": "省"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这几年这个小镇的人口省了很多。", "explanation": "这里应该用〈减少〉。“省”表示节约、少用钱物或时间，人口的下降不能说“省”。"}, {"text": "这家店的菜价省了很多。", "explanation": "这里应该用〈降低〉。“省”指节约、少用钱物，价格的下降要说“降低”或“下降”。"}, {"text": "他这个月想省三公斤。", "explanation": "这里应该用〈减〉。“省”指节约、少用钱物，体重的减少要说“减”或“减掉”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a0befb2-7c0f-481b-b847-2f8872445ee7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13297, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "省", "is_correct": true, "explanation": "省（shěng）：节约，不浪费钱或时间。"}, {"text": "胜", "is_correct": false, "explanation": "shèng（第四声）与 shěng（第三声）声调不同，意思是“胜利”。"}, {"text": "绳", "is_correct": false, "explanation": "shéng（第二声）与 shěng（第三声）声调不同，意思是“绳子”。"}, {"text": "盛", "is_correct": false, "explanation": "shèng（第四声）与 shěng（第三声）声调不同，意思是“兴盛”。"}], "explanations": {"省": "省（shěng）：节约，不浪费钱或时间。", "胜": "shèng（第四声）与 shěng（第三声）声调不同，意思是“胜利”。", "绳": "shéng（第二声）与 shěng（第三声）声调不同，意思是“绳子”。", "盛": "shèng（第四声）与 shěng（第三声）声调不同，意思是“兴盛”。"}, "sentence_index": null, "correct_answer": "省"}, "level_3": {"options": [{"text": "省", "is_correct": true, "explanation": "“省”表示节约钱财，“在家做饭比在外面吃饭省钱”符合句意。"}, {"text": "减", "is_correct": false, "explanation": "搭配：“减”不直接带“钱”作宾语，此处应说“省钱”，且“减钱”说法不通。"}, {"text": "增", "is_correct": false, "explanation": "搭配：“增”与“钱”不搭，“增钱”不通，且与句中比较节省的意思相反。"}, {"text": "花", "is_correct": false, "explanation": "语义：“花钱”指耗费钱财，与“在家做饭比在外面吃饭更省钱”的意思相反。"}], "explanations": {"省": "“省”表示节约钱财，“在家做饭比在外面吃饭省钱”符合句意。", "减": "搭配：“减”不直接带“钱”作宾语，此处应说“省钱”，且“减钱”说法不通。", "增": "搭配：“增”与“钱”不搭，“增钱”不通，且与句中比较节省的意思相反。", "花": "语义：“花钱”指耗费钱财，与“在家做饭比在外面吃饭更省钱”的意思相反。"}, "sentence_index": 6, "correct_answer": "省"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这样做可以省家里的负担。", "explanation": "这里应该用〈减轻〉。“省”用于可以节约的钱、水、电等，“负担”的减轻要说“减轻”。"}, {"text": "这次改革让城市的范围省了一半。", "explanation": "这里应该用〈缩小〉。“省”用于可以节约的钱、水、电等，范围的缩小要说“缩小”。"}, {"text": "他每个月都省一点经验。", "explanation": "这里应该用〈积累〉。“省”指节约、不浪费，经验是靠实践积累的，不能“省”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a0befb2-7c0f-481b-b847-2f8872445ee7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13297, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每个月都省上一笔钱，准备买房。", "corrected_sentence": "他每个月都省下一笔钱，准备买房。", "error_description": "错误：“省上”。正确：“省下”。“省下”表示节省后留下来，“上”不能作“省”的结果补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a0befb2-7c0f-481b-b847-2f8872445ee7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13297, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她省钱着，给家里买了一台新冰箱。", "corrected_sentence": "她省着钱，给家里买了一台新冰箱。", "error_description": "错误：“省钱着”。正确：“省着钱”。“着”是动态助词，应紧跟动词“省”，表示动作持续，不能放在宾语后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a0befb2-7c0f-481b-b847-2f8872445ee7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13300, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6656136-8fdb-431c-8fc8-e65aeaf03572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13300, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6656136-8fdb-431c-8fc8-e65aeaf03572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13300, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示动作或状态持续进行，没有中断。", "primary_collocate": null, "pronunciation": "bù tíng", "ipa": "pu˥˩ tʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "大家不停地买新衣服，这就是消费主义。", "target_word": "不停", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "雨下了一整天，到现在还在不停地下。", "target_word": "不停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子哭个不停，妈妈只好抱着他。", "target_word": "不停", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他紧张得手不停地发抖。", "target_word": "不停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电话不停地响，可是没有人接。", "target_word": "不停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她一边走一边不停地看手机。", "target_word": "不停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗见到主人，尾巴不停地摇。", "target_word": "不停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不停地咳嗽，应该去医院看看。", "target_word": "不停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们不停地练习，终于唱好了这首歌。", "target_word": "不停", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗外的风不停地吹着，我睡不着。", "target_word": "不停", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不停地", "label": "状语形式"}], "register": "通用", "sense_fingerprint": "副词，修饰动作，表示持续进行、不间断，常带“地”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ecc64df-9ac8-4c70-bd98-3637e54b903d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13300, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不停", "is_correct": true, "explanation": "不停（bù tíng）是副词，表示动作或状态持续不间断。"}, {"text": "不听", "is_correct": false, "explanation": "不听（bù tīng）与不停（bù tíng）的第二个音节声调不同：tīng 为第一声，tíng 为第二声。意思是不听。"}, {"text": "不疼", "is_correct": false, "explanation": "不疼（bù téng）与不停（bù tíng）的韵母不同：-eng 与 -ing。意思是不疼。"}, {"text": "不提", "is_correct": false, "explanation": "不提（bù tí）比不停（bù tíng）少了韵尾 -ng。意思是不提起。"}], "explanations": {"不停": "不停（bù tíng）是副词，表示动作或状态持续不间断。", "不听": "不听（bù tīng）与不停（bù tíng）的第二个音节声调不同：tīng 为第一声，tíng 为第二声。意思是不听。", "不疼": "不疼（bù téng）与不停（bù tíng）的韵母不同：-eng 与 -ing。意思是不疼。", "不提": "不提（bù tí）比不停（bù tíng）少了韵尾 -ng。意思是不提起。"}, "sentence_index": null, "correct_answer": "不停"}, "level_3": {"options": [{"text": "不停", "is_correct": true, "explanation": "不停：表示买新衣服持续不断，与“这就是消费主义”所说的过度购买相符。"}, {"text": "独自", "is_correct": false, "explanation": "语义：“大家”是群体，“独自”指一个人单独做，与句子的主语冲突。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示间或发生，与“这就是消费主义”所说的频繁购买矛盾。"}, {"text": "猛然", "is_correct": false, "explanation": "搭配：“猛然”多用于突发的动作或发现，不能修饰持续进行的购买。"}], "explanations": {"不停": "不停：表示买新衣服持续不断，与“这就是消费主义”所说的过度购买相符。", "独自": "语义：“大家”是群体，“独自”指一个人单独做，与句子的主语冲突。", "偶尔": "语义：“偶尔”表示间或发生，与“这就是消费主义”所说的频繁购买矛盾。", "猛然": "搭配：“猛然”多用于突发的动作或发现，不能修饰持续进行的购买。"}, "sentence_index": 0, "correct_answer": "不停"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个数字不停地等于五。", "explanation": "这里误用了“不停”。“不停地”描述动作或变化持续不断地进行，而这里说的是固定不变的数量关系，不会持续发生，因此不能用“不停地”修饰。"}, {"text": "他不停地参加了一次面试，结果很顺利。", "explanation": "“不停”表示动作接连不断地进行，而“参加一次面试”只发生一次，二者矛盾，这里不能用“不停”修饰。"}, {"text": "他不停地赢得了这场比赛，大家都很激动。", "explanation": "“赢得比赛”是一次完成的结果，不是能够持续不停进行的动作，不能用“不停”修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6656136-8fdb-431c-8fc8-e65aeaf03572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13300, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不停", "is_correct": true, "explanation": "不停：表示尾巴持续摆动，与“小狗见到主人”时的兴奋相符。"}, {"text": "懒洋洋", "is_correct": false, "explanation": "语义：“懒洋洋”形容懒散、没有精神，与小狗见到主人时的兴奋不协调。"}, {"text": "冷冷", "is_correct": false, "explanation": "语义：“冷冷”形容态度冷淡，与见到主人时的亲热相冲突。"}, {"text": "一动不动", "is_correct": false, "explanation": "语义：“一动不动”指完全静止，与“尾巴……地摇”的动作直接矛盾。"}], "explanations": {"不停": "不停：表示尾巴持续摆动，与“小狗见到主人”时的兴奋相符。", "懒洋洋": "语义：“懒洋洋”形容懒散、没有精神，与小狗见到主人时的兴奋不协调。", "冷冷": "语义：“冷冷”形容态度冷淡，与见到主人时的亲热相冲突。", "一动不动": "语义：“一动不动”指完全静止，与“尾巴……地摇”的动作直接矛盾。"}, "sentence_index": 6, "correct_answer": "不停"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一听到敲门声，他不停地跳了起来，去开门。", "explanation": "这里应该用〈立刻〉。“立刻”表示听到声音后马上做出的一次反应，“不停”强调持续不断，用在这里语义不通。"}, {"text": "风不停地停了下来，房间里一下子安静了。", "explanation": "这里“不停”的持续义与表示中断、停止的动作相冲突，不能用来修饰停止的动作。"}, {"text": "他不停地拿到了奖学金。", "explanation": "“拿到奖学金”是一次性的结果，不能持续不停地发生，不能用“不停”修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6656136-8fdb-431c-8fc8-e65aeaf03572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13300, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子不停得喊妈妈，声音越来越大。", "corrected_sentence": "孩子不停地喊妈妈，声音越来越大。", "error_description": "“不停地”中的“地”写成了“得”。作状语修饰动词时应用“地”；“得”用于动词或形容词之后引出补语，这里不能用“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6656136-8fdb-431c-8fc8-e65aeaf03572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13300, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈喊的不停，孩子才回家。", "corrected_sentence": "妈妈喊个不停，孩子才回家。", "error_description": "“个不停”是固定格式，中间的“个”不能换成“的”。应说“喊个不停”，不能说“喊的不停”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6656136-8fdb-431c-8fc8-e65aeaf03572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13302, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "短", "is_correct": true, "explanation": "长与短是反义词，指路线或过程的长短相反。"}, {"text": "快", "is_correct": false, "explanation": "快指速度，与长没有反义关系。"}, {"text": "厚", "is_correct": false, "explanation": "厚指物体的厚度，与长不构成反义。"}, {"text": "亮", "is_correct": false, "explanation": "亮指光线，与长没有反义关系。"}], "correct_answer": "短", "explanations": {"短": "长与短是反义词，指路线或过程的长短相反。", "快": "快指速度，与长没有反义关系。", "厚": "厚指物体的厚度，与长不构成反义。", "亮": "亮指光线，与长没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6656136-8fdb-431c-8fc8-e65aeaf03572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13302, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "短", "is_correct": true, "explanation": "长与短是反义词，指路线或过程的长短相反。"}, {"text": "宽", "is_correct": false, "explanation": "宽指宽度，与长不构成反义，宽的反义是窄。"}, {"text": "轻", "is_correct": false, "explanation": "轻指重量，与长没有反义关系。"}, {"text": "暖", "is_correct": false, "explanation": "暖指温度，与长没有反义关系。"}], "correct_answer": "短", "explanations": {"短": "长与短是反义词，指路线或过程的长短相反。", "宽": "宽指宽度，与长不构成反义，宽的反义是窄。", "轻": "轻指重量，与长没有反义关系。", "暖": "暖指温度，与长没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6656136-8fdb-431c-8fc8-e65aeaf03572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13302, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "表示路线或过程的环节多，距离远", "primary_collocate": null, "pronunciation": "cháng", "ipa": "ʈʂʰaŋ˧˥", "syllable_count": 1, "sentences": [{"text": "供应链越长，用的水越多。", "target_word": "长", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "从农场到餐桌的路线很长，要经过很多人。", "target_word": "长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条生产线太长，出问题的地方也多。", "target_word": "长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "食物运输的链条越长，价格就越贵。", "target_word": "长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "回家的路线太长了，我想换一条近的。", "target_word": "长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "审批的过程太长了，大家都等得着急。", "target_word": "长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路线不长，走路半小时就到。", "target_word": "长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手续太多，办事的过程变得很长。", "target_word": "长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "货物要坐船又坐火车，路线长，花的时间也多。", "target_word": "长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中间的流程越长，出错的机会越多。", "target_word": "长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "長", "label": "繁体"}, {"form": "长长的", "label": "重叠"}], "register": "通用", "sense_fingerprint": "形容词，读 cháng，指路线、链条、过程环节多、跨度大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ecc64df-9ac8-4c70-bd98-3637e54b903d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13302, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "长", "is_correct": true, "explanation": "cháng，意思是路线或过程的环节多、距离远。"}, {"text": "唱", "is_correct": false, "explanation": "chàng（第四声）与 cháng（第二声）声调不同，意思是唱歌。"}, {"text": "厂", "is_correct": false, "explanation": "chǎng（第三声）与 cháng（第二声）声调不同，意思是工厂。"}, {"text": "场", "is_correct": false, "explanation": "chǎng（第三声）与 cháng（第二声）声调不同，意思是场地。"}, {"text": "成", "is_correct": false, "explanation": "chéng 与 cháng 韵母不同（eng／ang），意思是成功。"}, {"text": "昌", "is_correct": false, "explanation": "chāng（第一声）与 cháng（第二声）只差声调，意思是昌盛。"}], "explanations": {"长": "cháng，意思是路线或过程的环节多、距离远。", "唱": "chàng（第四声）与 cháng（第二声）声调不同，意思是唱歌。", "厂": "chǎng（第三声）与 cháng（第二声）声调不同，意思是工厂。", "场": "chǎng（第三声）与 cháng（第二声）声调不同，意思是场地。", "成": "chéng 与 cháng 韵母不同（eng／ang），意思是成功。", "昌": "chāng（第一声）与 cháng（第二声）只差声调，意思是昌盛。"}, "sentence_index": null, "correct_answer": "长"}, "level_3": {"options": [{"text": "长", "is_correct": true, "explanation": "长：说链条的环节多、跨度大，与“越……越”句式和句意相符。"}, {"text": "甜", "is_correct": false, "explanation": "语义：甜形容味道，供应链没有味道，不能说供应链甜。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：“硬”与“供应链”不搭配，句子读来不通。"}, {"text": "亮", "is_correct": false, "explanation": "体貌：亮形容光线或外观，与供应链的长度无关。"}], "explanations": {"长": "长：说链条的环节多、跨度大，与“越……越”句式和句意相符。", "甜": "语义：甜形容味道，供应链没有味道，不能说供应链甜。", "硬": "搭配：“硬”与“供应链”不搭配，句子读来不通。", "亮": "体貌：亮形容光线或外观，与供应链的长度无关。"}, "sentence_index": 0, "correct_answer": "长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂的工人很长，需要再招一些。", "explanation": "这里应该用〈多〉。长说路线或过程的长度、环节多，人数要用多。"}, {"text": "他的个子很长，站在人群里很显眼。", "explanation": "这里应该用〈高〉。长用于路线、距离和过程，人的身高要用高。"}, {"text": "我家离学校很长，每天要走很久。", "explanation": "这里应该用〈远〉。“离……”之后要说“很远”，不说“离……很长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6656136-8fdb-431c-8fc8-e65aeaf03572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13302, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "长", "is_correct": true, "explanation": "cháng，意思是路线或过程的环节多、距离远。"}, {"text": "蝉", "is_correct": false, "explanation": "chán 与 cháng 韵母不同（an／ang），意思是蝉。"}, {"text": "潮", "is_correct": false, "explanation": "cháo 与 cháng 韵母不同（ao／ang），意思是潮水。"}, {"text": "虫", "is_correct": false, "explanation": "chóng 与 cháng 韵母不同（ong／ang），意思是虫子。"}, {"text": "缠", "is_correct": false, "explanation": "chán 与 cháng 韵母不同（an／ang），意思是缠绕。"}], "explanations": {"长": "cháng，意思是路线或过程的环节多、距离远。", "蝉": "chán 与 cháng 韵母不同（an／ang），意思是蝉。", "潮": "cháo 与 cháng 韵母不同（ao／ang），意思是潮水。", "虫": "chóng 与 cháng 韵母不同（ong／ang），意思是虫子。", "缠": "chán 与 cháng 韵母不同（an／ang），意思是缠绕。"}, "sentence_index": null, "correct_answer": "长"}, "level_3": {"options": [{"text": "长", "is_correct": true, "explanation": "长：说路线的距离远，与“不长，走路半小时就到”的句意相符。"}, {"text": "高", "is_correct": false, "explanation": "搭配：路线不说高矮，“高”与“路线”不搭配。"}, {"text": "深", "is_correct": false, "explanation": "语义：深指竖向的深度，路线不能用深来形容。"}, {"text": "厚", "is_correct": false, "explanation": "体貌：厚形容物体的厚薄，路线没有厚度。"}], "explanations": {"长": "长：说路线的距离远，与“不长，走路半小时就到”的句意相符。", "高": "搭配：路线不说高矮，“高”与“路线”不搭配。", "深": "语义：深指竖向的深度，路线不能用深来形容。", "厚": "体貌：厚形容物体的厚薄，路线没有厚度。"}, "sentence_index": 6, "correct_answer": "长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车的速度很长，一小时只能开二十公里。", "explanation": "这里应该用〈快〉。速度的快慢要用“快”，“长”不能形容速度。"}, {"text": "这种水果的价格很长，我买不起。", "explanation": "这里应该用〈贵〉。价格的高低用“贵”来说，“长”不能形容价格。"}, {"text": "这个国家的面积很长。", "explanation": "这里应该用〈大〉。长说线状的距离或环节多，面积和规模要用大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6656136-8fdb-431c-8fc8-e65aeaf03572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13302, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "运输路线长越，成本越高。", "corrected_sentence": "运输路线越长，成本越高。", "error_description": "错误：“长越”，应为“越长”。“越……越……”结构中，“越”要放在形容词前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6656136-8fdb-431c-8fc8-e65aeaf03572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13302, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条路线比那条长得，走路要多半个小时。", "corrected_sentence": "这条路线比那条长，走路要多半个小时。", "error_description": "错误：“长得”，应为“长”。“得”引出补语，这里没有补语，应去掉“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6656136-8fdb-431c-8fc8-e65aeaf03572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
