INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13305, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用洗衣液或洗衣粉和水来清洁衣服。", "primary_collocate": null, "pronunciation": "xǐ yī fu", "ipa": "ɕi˨˩ i˥ fu", "syllable_count": 3, "sentences": [{"text": "洗衣服时，也不要浪费水。", "target_word": "洗衣服", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "我用洗衣液洗衣服，衣服很香。", "target_word": "洗衣服", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈每个周末都在家洗衣服。", "target_word": "洗衣服", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把脏衣服放进盆里，开始洗衣服。", "target_word": "洗衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗衣粉用完了，我不能洗衣服了。", "target_word": "洗衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先用洗衣粉洗衣服，再用清水冲干净。", "target_word": "洗衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不会洗衣服，只好请妈妈帮忙。", "target_word": "洗衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末天气很好，我在家洗衣服、晒被子。", "target_word": "洗衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗衣服要用温水，冷水洗不干净。", "target_word": "洗衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边听音乐，一边洗衣服。", "target_word": "洗衣服", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "洗洗衣服", "label": "重叠"}, {"form": "洗过衣服", "label": "体标"}], "register": "中性", "sense_fingerprint": "用洗衣液或洗衣粉加水清洁衣服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ecc64df-9ac8-4c70-bd98-3637e54b903d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13305, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "洗衣服", "is_correct": true, "explanation": "洗衣服：指用洗衣液或洗衣粉加水清洁衣服，与“浪费水”的句意相符。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌与用水无关，“唱歌时，也不要浪费水”读来不通。"}, {"text": "下棋", "is_correct": false, "explanation": "搭配：下棋不涉及用水，“浪费水”与“下棋”没有搭配关系。"}, {"text": "写作业", "is_correct": false, "explanation": "语义：写作业与用水无关，句子的意思说不通。"}], "explanations": {"洗衣服": "洗衣服：指用洗衣液或洗衣粉加水清洁衣服，与“浪费水”的句意相符。", "唱歌": "语义：唱歌与用水无关，“唱歌时，也不要浪费水”读来不通。", "下棋": "搭配：下棋不涉及用水，“浪费水”与“下棋”没有搭配关系。", "写作业": "语义：写作业与用水无关，句子的意思说不通。"}, "sentence_index": 0, "correct_answer": "洗衣服"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把碗放进水池，开始洗衣服。", "explanation": "这里应该用〈洗碗〉。洗衣服是洗衣物，碗要用洗碗。"}, {"text": "他拿起扫帚，开始洗衣服。", "explanation": "这里应该用〈扫地〉。扫帚用于扫地，洗衣服不用扫帚。"}, {"text": "他拿起一个苹果，开始洗衣服。", "explanation": "这里应该用〈洗水果〉。洗衣服针对衣物，苹果要用洗水果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6656136-8fdb-431c-8fc8-e65aeaf03572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13305, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "洗衣服", "is_correct": true, "explanation": "洗衣服：指用洗衣液或洗衣粉清洁衣服，与“不会”“请妈妈帮忙”的句意相符。"}, {"text": "呼吸", "is_correct": false, "explanation": "语义：呼吸是本能动作，不需要别人帮忙，句子读来荒谬。"}, {"text": "微笑", "is_correct": false, "explanation": "语义：微笑是人人都会的表情，不需要请妈妈帮忙，句意不通。"}, {"text": "眨眼", "is_correct": false, "explanation": "语义：眨眼是本能动作，不需要请妈妈帮忙，句意不通。"}], "explanations": {"洗衣服": "洗衣服：指用洗衣液或洗衣粉清洁衣服，与“不会”“请妈妈帮忙”的句意相符。", "呼吸": "语义：呼吸是本能动作，不需要别人帮忙，句子读来荒谬。", "微笑": "语义：微笑是人人都会的表情，不需要请妈妈帮忙，句意不通。", "眨眼": "语义：眨眼是本能动作，不需要请妈妈帮忙，句意不通。"}, "sentence_index": 6, "correct_answer": "洗衣服"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈把青菜放进水池，开始洗衣服。", "explanation": "这里应该用〈洗菜〉。洗衣服针对衣物，青菜要用洗菜。"}, {"text": "他拿起菜刀，开始洗衣服。", "explanation": "这里应该用〈切菜〉。菜刀用于切菜，洗衣服不用刀。"}, {"text": "他把头发弄湿，倒上洗发水，开始洗衣服。", "explanation": "这里应该用〈洗头〉。洗衣服针对衣物，用洗发水洗头发要说洗头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6656136-8fdb-431c-8fc8-e65aeaf03572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13305, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他洗衣服洗地很干净。", "corrected_sentence": "他洗衣服洗得很干净。", "error_description": "错误：“洗地”，应为“洗得”。动词后面引出补语要用“得”，“地”只用于修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6656136-8fdb-431c-8fc8-e65aeaf03572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13305, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "洗衣服地时候，别忘了关窗户。", "corrected_sentence": "洗衣服的时候，别忘了关窗户。", "error_description": "错误：“地时候”，应为“的时候”。“洗衣服”修饰名词“时候”，要用“的”，“地”只修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6656136-8fdb-431c-8fc8-e65aeaf03572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13306, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13306, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13306, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "时尚指在一定时期内社会上流行的风气、习惯或样式，也指符合这种潮流的事物。", "primary_collocate": null, "pronunciation": "shí shàng", "ipa": "ʂɻ̩˧˥ ʂɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "在当代全球化经济图景中，时尚产业的崛起不仅重塑了消费者的穿衣模式，更对地球脆弱的水资源系统施加了前所未有的压力。", "target_word": "时尚", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "要破解这一困局，必须从系统层面重构时尚产业的生态逻辑。", "target_word": "时尚", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "当每一件廉价T恤背后都映射出干涸的河流与受污的土壤，我们不得不重新审视时尚的真正成本。", "target_word": "时尚", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "今年冬天的时尚是长款大衣。", "target_word": "时尚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "追逐时尚让服装公司生产越来越多的纺织品。", "target_word": "时尚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时尚的背后是强烈的消费主义文化。", "target_word": "时尚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻人总是喜欢追求时尚。", "target_word": "时尚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不懂时尚，总是穿同一件衣服。", "target_word": "时尚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "时尚每年都在变，去年的颜色今年没人穿了。", "target_word": "时尚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种帽子是十年前的时尚，现在没人戴了。", "target_word": "时尚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "快时尚", "label": "复合"}, {"form": "時尚", "label": "繁体"}], "register": "中性", "sense_fingerprint": "时尚·一段时期内流行的风气或样式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a854fec-be2f-4f93-bb5b-d6f5ac612a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13306, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "时尚", "is_correct": true, "explanation": "时尚指一段时期内社会上流行的风气或样式。"}, {"text": "史上", "is_correct": false, "explanation": "声调混淆：shǐ（第三声）与 shí（第二声），史上指历史上。"}, {"text": "世上", "is_correct": false, "explanation": "声调混淆：shì（第四声）与 shí（第二声），世上指世界上。"}, {"text": "时常", "is_correct": false, "explanation": "音近：shí cháng 与 shí shàng 只差声母 ch/sh，时常指经常。"}], "explanations": {"时尚": "时尚指一段时期内社会上流行的风气或样式。", "史上": "声调混淆：shǐ（第三声）与 shí（第二声），史上指历史上。", "世上": "声调混淆：shì（第四声）与 shí（第二声），世上指世界上。", "时常": "音近：shí cháng 与 shí shàng 只差声母 ch/sh，时常指经常。"}, "sentence_index": null, "correct_answer": "时尚"}, "level_3": {"options": [{"text": "钢铁", "is_correct": false, "explanation": "语义：钢铁产业与“消费者的穿衣模式”无关，不能重塑穿衣模式。"}, {"text": "时尚", "is_correct": true, "explanation": "正确：“时尚产业”生产流行服饰，其崛起会重塑消费者的穿衣模式，与句意相符。"}, {"text": "软件", "is_correct": false, "explanation": "语义：软件产业与穿衣模式无关，句意不通。"}, {"text": "航空", "is_correct": false, "explanation": "语义：航空产业不涉及消费者穿衣，句意不通。"}], "explanations": {"钢铁": "语义：钢铁产业与“消费者的穿衣模式”无关，不能重塑穿衣模式。", "时尚": "正确：“时尚产业”生产流行服饰，其崛起会重塑消费者的穿衣模式，与句意相符。", "软件": "语义：软件产业与穿衣模式无关，句意不通。", "航空": "语义：航空产业不涉及消费者穿衣，句意不通。"}, "sentence_index": 0, "correct_answer": "时尚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上都要时尚半个小时。", "explanation": "这里应该用〈打扮〉。“时尚”指流行的风气或样式，不是动作，不能作动词带时间。"}, {"text": "这个村子的时尚代代相传。", "explanation": "这里应该用〈风尚〉。风尚指长期形成的风气，可以代代相传；时尚变化快，不能代代相传。"}, {"text": "我每天都在时尚里上班。", "explanation": "这里应该用〈时尚行业〉。时尚指流行的风气或样式，不是场所，“在……里”不能用于它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13306, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "失败", "is_correct": false, "explanation": "语义：年轻人一般不会去追求失败，句子读起来自相矛盾。"}, {"text": "时尚", "is_correct": true, "explanation": "正确：“追求时尚”是常见搭配，指追求流行的风气或样式。"}, {"text": "疾病", "is_correct": false, "explanation": "搭配：“追求”后接理想、时尚、名利等，不搭配疾病。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾不是值得追求的东西，句子不通。"}], "explanations": {"失败": "语义：年轻人一般不会去追求失败，句子读起来自相矛盾。", "时尚": "正确：“追求时尚”是常见搭配，指追求流行的风气或样式。", "疾病": "搭配：“追求”后接理想、时尚、名利等，不搭配疾病。", "垃圾": "语义：垃圾不是值得追求的东西，句子不通。"}, "sentence_index": 6, "correct_answer": "时尚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他养成了早睡的时尚。", "explanation": "这里应该用〈习惯〉。习惯是个人长期养成的行为，时尚是社会上一段时期流行的样式或风气，不能说“养成……的时尚”。"}, {"text": "这项古老的仪式已经流行了两千年，是一种时尚。", "explanation": "这里应该用〈传统〉。时尚指一段时期内流行的风气，不能用来描述延续两千年的仪式。"}, {"text": "这道菜的时尚太咸了。", "explanation": "这里应该用〈味道〉。时尚指一段时期流行的风气或样式，不能用来形容菜的咸淡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13306, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条时尚今年很流行。", "corrected_sentence": "这种时尚今年很流行。", "error_description": "错误：量词“条”用错，应为“这种时尚”。“条”用于细长的东西，时尚指潮流，应用“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13306, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她总是喜欢追求时尚们。", "corrected_sentence": "她总是喜欢追求时尚。", "error_description": "错误：“时尚”后多加了“们”。“们”只用于指人的名词之后，“时尚”是抽象事物，应为“喜欢追求时尚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
