INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13308, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "用棉花纤维制成的质地，通常用来形容布料或衣物。", "primary_collocate": null, "pronunciation": "mián zhì", "ipa": "mi̯ɛn˧˥ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "纺织品的生产，尤其是棉质与合成纤维的加工，本质上是一个极度依赖水资源的工业流程。", "target_word": "棉质", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "例如，做一件棉质T恤可能要用掉两千升水。", "target_word": "棉质", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "这件衣服是棉质的，夏天穿很舒服。", "target_word": "棉质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我喜欢棉质的床单，睡觉很舒服。", "target_word": "棉质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "棉质比较软，小孩穿着很舒服。", "target_word": "棉质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条裤子不是棉质的，是丝绸的。", "target_word": "棉质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "棉质的衣服容易洗，也容易干。", "target_word": "棉质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈给宝宝买了棉质的帽子。", "target_word": "棉质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种面料不是棉质，所以夏天有点热。", "target_word": "棉质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗澡以后，我用一条棉质的大毛巾擦干身体。", "target_word": "棉质", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "棉質", "label": "繁体"}], "register": "中性", "sense_fingerprint": "棉质·用棉花纤维制成的布料或衣物质地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a854fec-be2f-4f93-bb5b-d6f5ac612a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13308, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "棉质", "is_correct": true, "explanation": "正确答案：棉质（mián zhì），指用棉花纤维制成的布料或衣物的质地。"}, {"text": "免职", "is_correct": false, "explanation": "免职（miǎn zhí）与棉质（mián zhì）声调不同，意思是解除职务。"}, {"text": "明智", "is_correct": false, "explanation": "明智（míng zhì）第一音节的韵母是 -ing，棉（mián）的韵母是 -ian，意思是有见识、聪明。"}, {"text": "棉纸", "is_correct": false, "explanation": "棉纸（mián zhǐ）第二音节 zhǐ（第三声）与 zhì（第四声）声调不同，意思是用棉纤维制成的纸。"}, {"text": "面值", "is_correct": false, "explanation": "面值（miàn zhí）两个音节的声调都与棉质不同，意思是票面价值。"}], "explanations": {"棉质": "正确答案：棉质（mián zhì），指用棉花纤维制成的布料或衣物的质地。", "免职": "免职（miǎn zhí）与棉质（mián zhì）声调不同，意思是解除职务。", "明智": "明智（míng zhì）第一音节的韵母是 -ing，棉（mián）的韵母是 -ian，意思是有见识、聪明。", "棉纸": "棉纸（mián zhǐ）第二音节 zhǐ（第三声）与 zhì（第四声）声调不同，意思是用棉纤维制成的纸。", "面值": "面值（miàn zhí）两个音节的声调都与棉质不同，意思是票面价值。"}, "sentence_index": null, "correct_answer": "棉质"}, "level_3": {"options": [{"text": "棉质", "is_correct": true, "explanation": "正确：指纺织材料的质地，与“合成纤维的加工”并列。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：工厂是生产场所，不是被加工的纤维材料，与“加工”的对象不符。"}, {"text": "机器", "is_correct": false, "explanation": "配价：机器是加工的工具，不能作为“加工”的对象与“合成纤维”并列。"}, {"text": "水资源", "is_correct": false, "explanation": "语义：水资源是资源，不是纺织品的原料，与句中“纺织品的生产”不符。"}], "explanations": {"棉质": "正确：指纺织材料的质地，与“合成纤维的加工”并列。", "工厂": "语义：工厂是生产场所，不是被加工的纤维材料，与“加工”的对象不符。", "机器": "配价：机器是加工的工具，不能作为“加工”的对象与“合成纤维”并列。", "水资源": "语义：水资源是资源，不是纺织品的原料，与句中“纺织品的生产”不符。"}, "sentence_index": 0, "correct_answer": "棉质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把棉质装进枕头里，睡起来很软。", "explanation": "这里应该用〈棉花〉。棉质表示布料或衣物的质地，不能作为填充物装进枕头；填充枕头的是棉花。"}, {"text": "这家工厂专门生产棉质，卖到很多国家。", "explanation": "这里应该用〈棉制品〉。棉质表示布料的质地，不是产品；工厂生产、出售的是棉制品。"}, {"text": "我买了一块棉质做窗帘。", "explanation": "这里应该用〈棉布〉。棉布可以按“块”计数，棉质表示质地，不能按“块”计数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13308, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "棉质", "is_correct": true, "explanation": "正确：指衣服的质地，与“容易洗，也容易干”相符。"}, {"text": "皮革", "is_correct": false, "explanation": "语义：皮革衣服不易清洗，与“容易洗”相矛盾。"}, {"text": "陶瓷", "is_correct": false, "explanation": "搭配：陶瓷多用于器皿，不说“陶瓷的衣服”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头做的衣服无法清洗，也不会容易干，与句意矛盾。"}], "explanations": {"棉质": "正确：指衣服的质地，与“容易洗，也容易干”相符。", "皮革": "语义：皮革衣服不易清洗，与“容易洗”相矛盾。", "陶瓷": "搭配：陶瓷多用于器皿，不说“陶瓷的衣服”。", "石头": "语义：石头做的衣服无法清洗，也不会容易干，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "棉质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "缝扣子要用一根棉质，不要用铁丝。", "explanation": "这里应该用〈棉线〉。棉质表示质地，不能用“根”计数；“一根”应搭配“棉线”。"}, {"text": "这些棉质要先纺成纱，再织成布。", "explanation": "这里应该用〈棉花〉。纺纱的原料是棉花（棉纤维），棉质是布料的质地，不能作为纺纱的原料。"}, {"text": "给被子里加了好几个棉质，盖起来会更暖。", "explanation": "这里应该用〈棉絮〉。棉质表示质地，不能用“个”计数；加在被子里的是棉絮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13308, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了一件很棉质衬衫，夏天穿很凉快。", "corrected_sentence": "我买了一件棉质衬衫，夏天穿很凉快。", "error_description": "“棉质”表示布料的质地，不能受“很”修饰；应直接说“棉质衬衫”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13308, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件衬衫是很棉质的，很透气。", "corrected_sentence": "这件衬衫是棉质的，很透气。", "error_description": "“棉质”前不能直接加“很”；作谓语时应说“是棉质的”，即“这件衬衫是棉质的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
