INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13309, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "T恤是一种短袖上衣，通常由棉布制成，穿着舒适。", "primary_collocate": null, "pronunciation": "tī xù", "ipa": "tʰi˥ ɕy˥˩", "syllable_count": 2, "sentences": [{"text": "当每一件廉价T恤背后都映射出干涸的河流与受污的土壤，我们不得不重新审视时尚的真正成本。", "target_word": "T恤", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "例如，做一件棉质T恤可能要用掉两千升水。", "target_word": "T恤", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "我有三件白色的T恤。", "target_word": "T恤", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "夏天我常常穿T恤和短裤。", "target_word": "T恤", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这件T恤太小了，我穿不下。", "target_word": "T恤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在T恤上画了一只小猫。", "target_word": "T恤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈给我买了一件红色T恤。", "target_word": "T恤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把脏T恤放进洗衣机里。", "target_word": "T恤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件T恤的价格很便宜，只要三十元。", "target_word": "T恤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他穿着一件蓝色T恤来上课。", "target_word": "T恤", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "短袖T恤", "label": "复合"}], "register": "中性", "sense_fingerprint": "T恤·棉布制成的短袖上衣", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a854fec-be2f-4f93-bb5b-d6f5ac612a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13309, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "T恤", "is_correct": true, "explanation": "正确：指衣物，与“廉价”“时尚”的语境一致。"}, {"text": "芯片", "is_correct": false, "explanation": "语义：芯片是电子元件，不属于时尚商品，与后文“时尚的真正成本”不相符。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：汽车的量词是“辆”，不能说“每一件汽车”。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：房子的量词是“套/座”，不能说“每一件房子”，也与时尚无关。"}], "explanations": {"T恤": "正确：指衣物，与“廉价”“时尚”的语境一致。", "芯片": "语义：芯片是电子元件，不属于时尚商品，与后文“时尚的真正成本”不相符。", "汽车": "搭配：汽车的量词是“辆”，不能说“每一件汽车”。", "房子": "搭配：房子的量词是“套/座”，不能说“每一件房子”，也与时尚无关。"}, "sentence_index": 0, "correct_answer": "T恤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只T恤，夏天穿正好合适。", "explanation": "这里应该用〈件〉。衣服类量词用“件”，“只”用于动物或成对物品中的一个。"}, {"text": "他用一件T恤煮了一锅汤。", "explanation": "这里应该用〈青菜〉。T恤是衣物，不能当食材煮汤；煮汤要用青菜等食材。"}, {"text": "他把T恤种在花园里，希望它快点长大。", "explanation": "这里应该用〈花〉。T恤是衣服，不能种，也不会长大；种在花园里的是花。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13309, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "T恤", "is_correct": true, "explanation": "正确：指衣服，“买了一件红色T恤”与句意相符。"}, {"text": "秘密", "is_correct": false, "explanation": "搭配：“买”不能用于秘密，“买了一件秘密”不通。"}, {"text": "事情", "is_correct": false, "explanation": "搭配：“买”不能用于事情，“买了一件事情”不通。"}, {"text": "心事", "is_correct": false, "explanation": "语义：心事不能买，也不能是红色的，与句中的购买和颜色矛盾。"}], "explanations": {"T恤": "正确：指衣服，“买了一件红色T恤”与句意相符。", "秘密": "搭配：“买”不能用于秘密，“买了一件秘密”不通。", "事情": "搭配：“买”不能用于事情，“买了一件事情”不通。", "心事": "语义：心事不能买，也不能是红色的，与句中的购买和颜色矛盾。"}, "sentence_index": 6, "correct_answer": "T恤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冬天我盖着厚厚的T恤睡觉。", "explanation": "这里应该用〈被子〉。T恤是穿在身上的衣服，不能用来盖着睡觉；盖着睡觉的是被子。"}, {"text": "他用T恤写作业。", "explanation": "这里应该用〈铅笔〉。T恤是衣服，不能用来写字；写字要用笔，如铅笔。"}, {"text": "他给T恤打了个电话，问它在哪里。", "explanation": "这里应该用〈朋友〉。T恤是衣服，没有生命，不能接电话；打电话要打给人，比如朋友。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13309, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每天穿一只T恤去跑步。", "corrected_sentence": "我每天穿一件T恤去跑步。", "error_description": "T恤是衣服，量词应用“件”；“只”不用于衣服。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13309, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他戴着一件白色T恤去公园。", "corrected_sentence": "他穿着一件白色T恤去公园。", "error_description": "T恤是上衣，动词要用“穿”；“戴”用于帽子、眼镜、手表等。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
