INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13310, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "表示需要用到某物或要做某事。", "primary_collocate": null, "pronunciation": "yào yòng", "ipa": "jɑʊ˥˩ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "例如，做一件棉质T恤可能要用掉两千升水。", "target_word": "要用", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "做蛋糕要用很多鸡蛋。", "target_word": "要用", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "写字要用笔。", "target_word": "要用", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "开门要用钥匙。", "target_word": "要用", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这件衣服太脏，要用热水洗。", "target_word": "要用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明天开会要用电脑，你带了吗？", "target_word": "要用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个周末我要用一天时间打扫房间。", "target_word": "要用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这道菜要用小火慢慢煮。", "target_word": "要用", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "包饺子要用面粉和肉。", "target_word": "要用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "煮咖啡要用热水，不能用冷水。", "target_word": "要用", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "不要用", "label": "否定"}], "register": "中性", "sense_fingerprint": "做某事需要使用某物或花费某种资源", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edc2b444-45c3-4e43-811d-0a9ab0a8e562') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13310, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "要用", "is_correct": true, "explanation": "正确答案。yào yòng 即“需要用到某物”。"}, {"text": "套用", "is_correct": false, "explanation": "tào（第四声）与 yào（第四声）声母不同，意思是套用、照搬已有的模板或方法。"}, {"text": "调用", "is_correct": false, "explanation": "diào（第四声）与 yào（第四声）声母不同，意思是调配、取用。"}, {"text": "夜用", "is_correct": false, "explanation": "yè（第四声）与 yào（第四声）韵母不同（e 与 ao），意思是夜间使用。"}], "explanations": {"要用": "正确答案。yào yòng 即“需要用到某物”。", "套用": "tào（第四声）与 yào（第四声）声母不同，意思是套用、照搬已有的模板或方法。", "调用": "diào（第四声）与 yào（第四声）声母不同，意思是调配、取用。", "夜用": "yè（第四声）与 yào（第四声）韵母不同（e 与 ao），意思是夜间使用。"}, "sentence_index": null, "correct_answer": "要用"}, "level_3": {"options": [{"text": "要用", "is_correct": true, "explanation": "正确答案。做一件棉质T恤需要耗费水，“要用掉”与句意相符。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”指饮用，做衣服的过程不会喝水，与“做一件棉质T恤”的语境不合。"}, {"text": "倒", "is_correct": false, "explanation": "语义：“倒掉”指把水倒走，句子说的是生产过程耗水，并非倒水。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不能以“水”的数量作宾语，说“洗掉两千升水”不通。"}], "explanations": {"要用": "正确答案。做一件棉质T恤需要耗费水，“要用掉”与句意相符。", "喝": "语义：“喝”指饮用，做衣服的过程不会喝水，与“做一件棉质T恤”的语境不合。", "倒": "语义：“倒掉”指把水倒走，句子说的是生产过程耗水，并非倒水。", "洗": "搭配：“洗”不能以“水”的数量作宾语，说“洗掉两千升水”不通。"}, "sentence_index": 0, "correct_answer": "要用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个问题要用仔细研究。", "explanation": "这里应该用〈需要〉。“要用”后接的是可以拿来使用的物品或资源，「仔细研究」是动作，不能被“用”带出。"}, {"text": "你要用按时交作业。", "explanation": "这里应该用〈必须〉。“要用”表示需要使用某物，不能接「按时交作业」这样的动作。"}, {"text": "我明天要用去上海出差。", "explanation": "这里应该用〈要〉。“要用”表示需要使用某物，后面不能直接接「去上海出差」这样的打算。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2a68c4-ed6c-459b-815e-decf2ac36fdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13310, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "要用", "is_correct": true, "explanation": "正确答案。yào yòng 即“需要用到某物”。"}, {"text": "有用", "is_correct": false, "explanation": "有用 yǒu yòng 的第一音节 yǒu 与 yào 韵母和声调都不同（yǒu 第三声，yào 第四声），意思是有用处。"}, {"text": "要员", "is_correct": false, "explanation": "要员 yào yuán 的第二音节 yuán 与 yòng 韵母和声调都不同，意思是重要的官员。"}, {"text": "要冲", "is_correct": false, "explanation": "要冲 yào chōng 的第二音节 chōng 与 yòng 声母和声调都不同，意思是重要的交通要道。"}], "explanations": {"要用": "正确答案。yào yòng 即“需要用到某物”。", "有用": "有用 yǒu yòng 的第一音节 yǒu 与 yào 韵母和声调都不同（yǒu 第三声，yào 第四声），意思是有用处。", "要员": "要员 yào yuán 的第二音节 yuán 与 yòng 韵母和声调都不同，意思是重要的官员。", "要冲": "要冲 yào chōng 的第二音节 chōng 与 yòng 声母和声调都不同，意思是重要的交通要道。"}, "sentence_index": null, "correct_answer": "要用"}, "level_3": {"options": [{"text": "要用", "is_correct": true, "explanation": "正确答案。这里表示打扫房间需要花费一天时间，与“时间”搭配，符合句意。"}, {"text": "要睡", "is_correct": false, "explanation": "语义：“睡”与“打扫房间”的行为相冲突，不能用来说明要花的时间。"}, {"text": "要洗", "is_correct": false, "explanation": "搭配：“洗”的宾语是衣物等物品，不能直接带“一天时间”作宾语。"}, {"text": "要玩", "is_correct": false, "explanation": "语义：“玩”表示娱乐，与“打扫房间”的任务相矛盾。"}], "explanations": {"要用": "正确答案。这里表示打扫房间需要花费一天时间，与“时间”搭配，符合句意。", "要睡": "语义：“睡”与“打扫房间”的行为相冲突，不能用来说明要花的时间。", "要洗": "搭配：“洗”的宾语是衣物等物品，不能直接带“一天时间”作宾语。", "要玩": "语义：“玩”表示娱乐，与“打扫房间”的任务相矛盾。"}, "sentence_index": 6, "correct_answer": "要用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份报告要用我感动。", "explanation": "这里应该用〈让〉。“要用”后接的是可以拿来使用的东西，「感动」是心理状态，不能被“用”带出。"}, {"text": "这间屋子要用安静。", "explanation": "这里应该用〈保持〉。“要用”后接的是可以拿来使用的东西，「安静」是状态，不能被“用”。"}, {"text": "这次考试要用你的紧张。", "explanation": "这里应该用〈带来〉。“要用”后接的是可以使用的东西，「紧张」是情绪，不能被“用”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2a68c4-ed6c-459b-815e-decf2ac36fdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13310, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天上课要用了笔记本。", "corrected_sentence": "明天上课要用笔记本。", "error_description": "错误：“要用了”。正确：“要用”。“明天”指将来，表示将来需要使用时不能在“用”后加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2a68c4-ed6c-459b-815e-decf2ac36fdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13310, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "做蛋糕要用了烤箱。", "corrected_sentence": "做蛋糕要用烤箱。", "error_description": "错误：“要用了”。正确：“要用”。“做蛋糕”说的是一般做法，表示需要使用，“用”后不能加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2a68c4-ed6c-459b-815e-decf2ac36fdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13312, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "贴水", "is_correct": true, "explanation": "正确：金融术语，与“升水”构成标准的反义关系，指远期价格低于标准价。"}, {"text": "保持", "is_correct": false, "explanation": "与“升水”无反义关系，“保持”指维持原状，不对应价格变动方向。"}, {"text": "结算", "is_correct": false, "explanation": "与“升水”无反义关系，“结算”指计算并支付款项。"}, {"text": "报价", "is_correct": false, "explanation": "与“升水”无反义关系，“报价”指给出价格，不表示价格的升降方向。"}], "correct_answer": "贴水", "explanations": {"贴水": "正确：金融术语，与“升水”构成标准的反义关系，指远期价格低于标准价。", "保持": "与“升水”无反义关系，“保持”指维持原状，不对应价格变动方向。", "结算": "与“升水”无反义关系，“结算”指计算并支付款项。", "报价": "与“升水”无反义关系，“报价”指给出价格，不表示价格的升降方向。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f753777-3916-4e25-9a74-96a805513359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13312, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "贴水", "is_correct": true, "explanation": "正确：金融术语，与“升水”构成标准的反义关系。"}, {"text": "持平", "is_correct": false, "explanation": "与“升水”无反义关系，“持平”指价格不变，不是相反的价格变动。"}, {"text": "汇兑", "is_correct": false, "explanation": "与“升水”无反义关系，“汇兑”指货币兑换行为。"}, {"text": "支付", "is_correct": false, "explanation": "与“升水”无反义关系，“支付”指付款行为，不表示价格方向。"}], "correct_answer": "贴水", "explanations": {"贴水": "正确：金融术语，与“升水”构成标准的反义关系。", "持平": "与“升水”无反义关系，“持平”指价格不变，不是相反的价格变动。", "汇兑": "与“升水”无反义关系，“汇兑”指货币兑换行为。", "支付": "与“升水”无反义关系，“支付”指付款行为，不表示价格方向。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f753777-3916-4e25-9a74-96a805513359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13312, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "升水指在金融交易中，一种货币或商品的价格高于另一种标准价格，通常需要额外支付差价。", "primary_collocate": null, "pronunciation": "shēng shuǐ", "ipa": "ʂɤŋ˥ ʂweɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "两种货币的远期报价偏高，这种情形就叫升水。", "target_word": "升水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "远期美元比现在的美元贵，这叫升水。", "target_word": "升水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行说，明年的美元会升水。", "target_word": "升水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "远期价格比现在高，这就叫升水。", "target_word": "升水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "欧元对美元升水了，你要多付钱。", "target_word": "升水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "远期汇率比现在高，我们说它升水。", "target_word": "升水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，期货价格高于现货，就叫升水。", "target_word": "升水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "换钱时升水，你就要多付差价。", "target_word": "升水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月日元对美元一直升水。", "target_word": "升水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种货币现在升水，换钱要多付差价。", "target_word": "升水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "升水了", "label": "体标"}, {"form": "升水率", "label": "复合"}], "register": "专业", "sense_fingerprint": "金融·价格高于标准价·额外支付差价", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27dbee67-57fb-4045-a9fe-c7c814b0d92e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13312, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "升水", "is_correct": true, "explanation": "正确：shēng shuǐ，金融术语，指远期价格高于标准价，需要额外支付差价。"}, {"text": "省水", "is_correct": false, "explanation": "shěng（第三声）与 shēng（第一声）声调不同，意思是节约用水。"}, {"text": "升税", "is_correct": false, "explanation": "shuì（第四声）与 shuǐ（第三声）声调不同，意思是提高税收。"}, {"text": "盛水", "is_correct": false, "explanation": "shèng（第四声）与 shēng（第一声）声调不同，意思是装水。"}, {"text": "深水", "is_correct": false, "explanation": "shēn 与 shēng 的韵尾不同（n 与 ng），意思是水很深。"}], "explanations": {"升水": "正确：shēng shuǐ，金融术语，指远期价格高于标准价，需要额外支付差价。", "省水": "shěng（第三声）与 shēng（第一声）声调不同，意思是节约用水。", "升税": "shuì（第四声）与 shuǐ（第三声）声调不同，意思是提高税收。", "盛水": "shèng（第四声）与 shēng（第一声）声调不同，意思是装水。", "深水": "shēn 与 shēng 的韵尾不同（n 与 ng），意思是水很深。"}, "sentence_index": null, "correct_answer": "升水"}, "level_3": {"options": [{"text": "升水", "is_correct": true, "explanation": "正确：指远期价格高于现货，需要额外付差价。"}, {"text": "贴水", "is_correct": false, "explanation": "语义：贴水指价格低于标准，与“高于现货”相反，不能用于此处。"}, {"text": "上升", "is_correct": false, "explanation": "语义：“上升”是普通词语，不是金融术语“就叫”的专门名称，语义不合。"}, {"text": "结算", "is_correct": false, "explanation": "语义：“结算”指计算并支付款项，不是价格高于标准的名称。"}], "explanations": {"升水": "正确：指远期价格高于现货，需要额外付差价。", "贴水": "语义：贴水指价格低于标准，与“高于现货”相反，不能用于此处。", "上升": "语义：“上升”是普通词语，不是金融术语“就叫”的专门名称，语义不合。", "结算": "语义：“结算”指计算并支付款项，不是价格高于标准的名称。"}, "sentence_index": 0, "correct_answer": "升水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种衣服今年升水了。", "explanation": "这里应该用〈涨价〉。升水只用于金融中的远期价格，普通商品涨价不说“升水”。"}, {"text": "河里的水升水了，我们要赶快撤离。", "explanation": "这里应该用〈涨水〉。“升水”不指水位上升，用于水位语义不合。"}, {"text": "我的股票今天升水了。", "explanation": "这里应该用〈上涨〉。股票当天价格变高叫“上涨”；“升水”指远期或期货价格高于现货（标准）价格，不指价格本身的涨跌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f753777-3916-4e25-9a74-96a805513359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13312, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "升水", "is_correct": true, "explanation": "正确：指期货价格高于现货，需要额外付差价。"}, {"text": "下跌", "is_correct": false, "explanation": "语义：“下跌”指价格下降，与“高于现货”方向相反，不能用于此处。"}, {"text": "报价", "is_correct": false, "explanation": "搭配：“报价”指给出价格的行为，不能用来称呼期货价格高于现货这一状态。"}, {"text": "结算", "is_correct": false, "explanation": "语义：“结算”指计算并支付款项，与价格高于现货无关。"}], "explanations": {"升水": "正确：指期货价格高于现货，需要额外付差价。", "下跌": "语义：“下跌”指价格下降，与“高于现货”方向相反，不能用于此处。", "报价": "搭配：“报价”指给出价格的行为，不能用来称呼期货价格高于现货这一状态。", "结算": "语义：“结算”指计算并支付款项，与价格高于现货无关。"}, "sentence_index": 6, "correct_answer": "升水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的孩子这次考试升水了。", "explanation": "这里应该用〈进步〉。“升水”只用于货币远期价格，成绩变化不用“升水”。"}, {"text": "妈妈的工资今年升水了。", "explanation": "这里应该用〈涨工资〉。“升水”专指货币远期价格，工资变化不适用。"}, {"text": "这座山的高度下周会升水。", "explanation": "这里应该用〈增高〉。山体高度变化不用“升水”，升水是金融术语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f753777-3916-4e25-9a74-96a805513359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13312, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "远期英镑比即期英镑价格高，这就叫很升水。", "corrected_sentence": "远期英镑比即期英镑价格高，这就叫升水。", "error_description": "“升水”是动词，前面不能直接加程度副词“很”。错误形式“叫很升水”，正确形式“叫升水”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f753777-3916-4e25-9a74-96a805513359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13312, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下个月英镑被升水，换钱就要多付差价。", "corrected_sentence": "下个月英镑升水，换钱就要多付差价。", "error_description": "“升水”表示价格自行上升，不能用“被”字句。错误形式“英镑被升水”，正确形式“英镑升水”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f753777-3916-4e25-9a74-96a805513359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
