INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13313, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "增加重量或程度，使事物比原来更重或更严重。", "primary_collocate": null, "pronunciation": "jiā zhòng", "ipa": "tɕia˥ ʈʂʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这会加重全球的水资源短缺问题。", "target_word": "加重", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "吃太多盐会加重心脏的负担。", "target_word": "加重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的病加重了，今天不能上班。", "target_word": "加重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，别再加重孩子的学习压力了。", "target_word": "加重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生担心感冒会加重她的咳嗽。", "target_word": "加重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院决定加重对这个人的处罚。", "target_word": "加重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水太多，加重了城市的交通问题。", "target_word": "加重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话时加重了语气，大家都安静了。", "target_word": "加重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "背包里再放几本书，就会加重肩膀的负担。", "target_word": "加重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "检查结果显示，他的肝病加重了，需要住院。", "target_word": "加重", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "加重了", "label": "体标"}, {"form": "加重过", "label": "体标"}], "register": "中性", "sense_fingerprint": "使重量或程度增加，变得更重、更严重", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286b81e5-7ce8-4ad9-a3d1-740e7cf8bb39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13313, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "加重", "is_correct": true, "explanation": "加重 jiāzhòng，意思是增加重量或程度，使事物更重或更严重。"}, {"text": "家中", "is_correct": false, "explanation": "第二个音节的声调不同：zhōng（第一声）与 zhòng（第四声）不同，家中意思是在家里。"}, {"text": "家政", "is_correct": false, "explanation": "第二个音节的韵母不同：zhèng 与 zhòng 的韵母是 eng 与 ong，家政意思是家务管理。"}, {"text": "甲种", "is_correct": false, "explanation": "两个音节的声调都不同：jiǎzhǒng（第三声）与 jiāzhòng 不同，甲种意思是甲类。"}, {"text": "间种", "is_correct": false, "explanation": "间种 jiànzhòng：第一个音节韵母和声调都不同（jiàn 第四声，带韵尾 n），第二个音节相同；间种意思是间隔种植。"}], "explanations": {"加重": "加重 jiāzhòng，意思是增加重量或程度，使事物更重或更严重。", "家中": "第二个音节的声调不同：zhōng（第一声）与 zhòng（第四声）不同，家中意思是在家里。", "家政": "第二个音节的韵母不同：zhèng 与 zhòng 的韵母是 eng 与 ong，家政意思是家务管理。", "甲种": "两个音节的声调都不同：jiǎzhǒng（第三声）与 jiāzhòng 不同，甲种意思是甲类。", "间种": "间种 jiànzhòng：第一个音节韵母和声调都不同（jiàn 第四声，带韵尾 n），第二个音节相同；间种意思是间隔种植。"}, "sentence_index": null, "correct_answer": "加重"}, "level_3": {"options": [{"text": "加重", "is_correct": true, "explanation": "加重：与“这会”搭配，表示使水资源短缺问题更严重，符合语境。"}, {"text": "参加", "is_correct": false, "explanation": "配价：“参加”的宾语须是活动或组织，不能说参加“全球的水资源短缺问题”。"}, {"text": "保护", "is_correct": false, "explanation": "搭配：“保护”的对象是资源或环境，不能说保护“问题”。"}, {"text": "完成", "is_correct": false, "explanation": "搭配：“完成”搭配任务或工作，不能说完成“问题”。"}], "explanations": {"加重": "加重：与“这会”搭配，表示使水资源短缺问题更严重，符合语境。", "参加": "配价：“参加”的宾语须是活动或组织，不能说参加“全球的水资源短缺问题”。", "保护": "搭配：“保护”的对象是资源或环境，不能说保护“问题”。", "完成": "搭配：“完成”搭配任务或工作，不能说完成“问题”。"}, "sentence_index": 0, "correct_answer": "加重"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今年公司的员工人数加重了一倍。", "explanation": "这里应该用〈增加〉。加重只用于重量、负担或病情等变坏，人数这类数量要用增加。"}, {"text": "他对这件事的理解加重了。", "explanation": "这里应该用〈加深〉。加重指重量、负担或病情变得更重，抽象的理解要用加深。"}, {"text": "这次训练以后，他的抵抗力加重了。", "explanation": "这里应该用〈增强〉。加重用于重量、负担或病情，身体的抵抗力、能力要用增强。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13313, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "加重", "is_correct": true, "explanation": "加重：说雨水使交通问题更严重，与“雨水太多”的因果一致。"}, {"text": "解决", "is_correct": false, "explanation": "语义：“雨水太多”不能解决交通问题，与语境相反。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”的对象是地点或展览，不能说参观“问题”。"}, {"text": "研究", "is_correct": false, "explanation": "配价：“研究”需要人作主语，“雨水”不能研究交通问题。"}], "explanations": {"加重": "加重：说雨水使交通问题更严重，与“雨水太多”的因果一致。", "解决": "语义：“雨水太多”不能解决交通问题，与语境相反。", "参观": "搭配：“参观”的对象是地点或展览，不能说参观“问题”。", "研究": "配价：“研究”需要人作主语，“雨水”不能研究交通问题。"}, "sentence_index": 6, "correct_answer": "加重"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的口语水平加重了很多。", "explanation": "这里应该用〈提高〉。加重用于重量、负担或病情，口语水平、质量要用提高。"}, {"text": "这辆车的速度加重了许多。", "explanation": "这里应该用〈加快〉。加重说重量或负担变重，速度的变化要用加快。"}, {"text": "这次活动加重了大家之间的团结。", "explanation": "这里应该用〈加强〉。加重用于负担、病情等变坏，抽象的团结和关系要用加强。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13313, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "长时间玩手机会加重眼睛得疲劳。", "corrected_sentence": "长时间玩手机会加重眼睛的疲劳。", "error_description": "“加重”的宾语“眼睛的疲劳”中，修饰语要用“的”，不能用“得”（“得”是补语标记）。应说“加重眼睛的疲劳”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13313, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今天的头疼很加重了，我想早点回家。", "corrected_sentence": "今天的头疼加重了，我想早点回家。", "error_description": "副词“很”不能直接修饰动词“加重”，应去掉“很”，说“头疼加重了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
