INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13315, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "表示不止前面说的那样，还有更进一步的意思。", "primary_collocate": null, "pronunciation": "bù jǐn rú cǐ", "ipa": "pu˥˩ tɕin˨˩˦ ɻu˧˥ tsʰɨ˨˩˦", "syllable_count": 4, "sentences": [{"text": "这家工厂排出的废水很脏。不仅如此，它还常常排出很多黑烟。", "target_word": "不仅如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的菜很好吃。不仅如此，价格也不贵。", "target_word": "不仅如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他会说英语，不仅如此，还会说日语。", "target_word": "不仅如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王学习很努力。不仅如此，他还常常帮助同学。", "target_word": "不仅如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市风景很美，不仅如此，生活也很方便。", "target_word": "不仅如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书很有意思。不仅如此，它还很便宜。", "target_word": "不仅如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁很快。不仅如此，坐地铁还很便宜。", "target_word": "不仅如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跑得很快，不仅如此，跳得也很高。", "target_word": "不仅如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种水果很甜。不仅如此，对身体也很好。", "target_word": "不仅如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她会做饭，不仅如此，做得还特别好吃。", "target_word": "不仅如此", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "递进连接，表示除前面所说之外还有更进一步的内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286b81e5-7ce8-4ad9-a3d1-740e7cf8bb39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13315, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不仅如此", "is_correct": true, "explanation": "不仅如此：在“废水很脏”之外再补充一层同方向的情况——还排出黑烟。"}, {"text": "幸好", "is_correct": false, "explanation": "语义：“幸好”引出好的结果，“排出很多黑烟”是坏事，与语境矛盾。"}, {"text": "因此", "is_correct": false, "explanation": "语义：废水脏不是排出黑烟的原因，“因此”的因果关系不成立。"}, {"text": "否则", "is_correct": false, "explanation": "语义：“否则”引出假设不成立时的后果，这里只是补充事实。"}], "explanations": {"不仅如此": "不仅如此：在“废水很脏”之外再补充一层同方向的情况——还排出黑烟。", "幸好": "语义：“幸好”引出好的结果，“排出很多黑烟”是坏事，与语境矛盾。", "因此": "语义：废水脏不是排出黑烟的原因，“因此”的因果关系不成立。", "否则": "语义：“否则”引出假设不成立时的后果，这里只是补充事实。"}, "sentence_index": 0, "correct_answer": "不仅如此"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他想去公园，不仅如此，没有时间。", "explanation": "这里应该用〈但是〉。不仅如此表示在前文基础上再补充，这里前后是转折关系，要用但是。"}, {"text": "这次考试我很努力，不仅如此，没考好。", "explanation": "这里应该用〈不过〉。不仅如此表示递进补充，这里前后是转折关系，要用不过。"}, {"text": "他不是老师，不仅如此，是医生。", "explanation": "这里应该用〈而是〉。不仅如此是在肯定的基础上再补充，否定之后的纠正要用而是。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13315, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不仅如此", "is_correct": true, "explanation": "不仅如此：在“地铁很快”之外再补充一层，这里说坐地铁也便宜。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“很快”不是“便宜”的原因，“所以”引出的因果关系不成立。"}, {"text": "相反", "is_correct": false, "explanation": "语义：“还很便宜”是补充而不是相反，“相反”与语境矛盾。"}, {"text": "尤其是", "is_correct": false, "explanation": "语义：“尤其是”从前面提到的一类事物中突出一项，“便宜”不是“很快”中的一部分，不能这样连接。"}], "explanations": {"不仅如此": "不仅如此：在“地铁很快”之外再补充一层，这里说坐地铁也便宜。", "所以": "语义：“很快”不是“便宜”的原因，“所以”引出的因果关系不成立。", "相反": "语义：“还很便宜”是补充而不是相反，“相反”与语境矛盾。", "尤其是": "语义：“尤其是”从前面提到的一类事物中突出一项，“便宜”不是“很快”中的一部分，不能这样连接。"}, "sentence_index": 6, "correct_answer": "不仅如此"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "如果明天下雨，不仅如此，我们就不去了。", "explanation": "这里应该用〈那么〉。不仅如此表示在前文基础上补充，不能用来连接条件和结论，条件之后的结论要用那么。"}, {"text": "我吃完饭，不仅如此，去散步。", "explanation": "这里应该用〈然后〉。不仅如此表示补充，不表示动作的先后，吃完饭再去散步要用然后。"}, {"text": "他现在很有钱，不仅如此，以前很穷。", "explanation": "这里应该用〈但是〉。不仅如此表示补充递进，现在有钱和以前穷是转折对比，要用但是。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13315, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是一名医生，不仅如此，而是一位作家。", "corrected_sentence": "他是一名医生，不仅如此，还是一位作家。", "error_description": "“不仅如此”之后递进补充要用“还”，不能用“而是”；“而是”只用于否定之后的更正（如“不是A，而是B”），这里前面没有否定。应说“不仅如此，还是一位作家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13315, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他会弹钢琴，不仅如此，但是会唱歌。", "corrected_sentence": "他会弹钢琴，不仅如此，还会唱歌。", "error_description": "“不仅如此”要与“还”搭配表示递进，这里用“但是”表示转折，与前面的递进语境冲突，应说“还会唱歌”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
