INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13316, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指事物从内部或某个范围移出、清除掉，不再留在原来的地方。", "primary_collocate": null, "pronunciation": "pái chū", "ipa": "pʰai˧˥ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "这家工厂很有名。生产过程中排出的废水常常含有化学物质。", "target_word": "排出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂不能随便排出污水。", "target_word": "排出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风扇把热空气排出去了。", "target_word": "排出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地下室里的水很多，要用机器排出去。", "target_word": "排出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车排出的气体会污染空气。", "target_word": "排出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工厂每天排出大量废气。", "target_word": "排出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下水道排出了城里的雨水。", "target_word": "排出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "烟囱里排出了黑色的烟。", "target_word": "排出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发动机排出的热气很烫。", "target_word": "排出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用水泵把积水排出了。", "target_word": "排出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "排出了", "label": "体标"}, {"form": "排出过", "label": "体标"}, {"form": "排出物", "label": "复合"}], "register": "中性", "sense_fingerprint": "把物体、气体、液体从内部或某范围移出清除", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286b81e5-7ce8-4ad9-a3d1-740e7cf8bb39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13316, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "排出", "is_correct": true, "explanation": "排出 pái chū：把东西从内部移到外面，是本题的目标词。"}, {"text": "排除", "is_correct": false, "explanation": "排除 páichú：与“排出”仅第二音节声调不同（chú 为第二声），意思是消除。"}, {"text": "派出", "is_correct": false, "explanation": "派出 pàichū：与“排出”仅第一音节声调不同（pài 为第四声），意思是派遣。"}, {"text": "拍出", "is_correct": false, "explanation": "拍出 pāichū：与“排出”仅第一音节声调不同（pāi 为第一声），意思是拍摄得到，如拍出好照片。"}], "explanations": {"排出": "排出 pái chū：把东西从内部移到外面，是本题的目标词。", "排除": "排除 páichú：与“排出”仅第二音节声调不同（chú 为第二声），意思是消除。", "派出": "派出 pàichū：与“排出”仅第一音节声调不同（pài 为第四声），意思是派遣。", "拍出": "拍出 pāichū：与“排出”仅第一音节声调不同（pāi 为第一声），意思是拍摄得到，如拍出好照片。"}, "sentence_index": null, "correct_answer": "排出"}, "level_3": {"options": [{"text": "排出", "is_correct": true, "explanation": "排出：符合句意，表示生产过程中产生的废水被移出。"}, {"text": "喝", "is_correct": false, "explanation": "语义：废水受到污染，不能“喝”，与句中“含有化学物质”的语境相冲突。"}, {"text": "吃", "is_correct": false, "explanation": "语义：废水是液体，不能“吃”，与句意不符。"}, {"text": "吸收", "is_correct": false, "explanation": "搭配：“吸收”指吸取营养或能量，不用于废水这类排放物。"}], "explanations": {"排出": "排出：符合句意，表示生产过程中产生的废水被移出。", "喝": "语义：废水受到污染，不能“喝”，与句中“含有化学物质”的语境相冲突。", "吃": "语义：废水是液体，不能“吃”，与句意不符。", "吸收": "搭配：“吸收”指吸取营养或能量，不用于废水这类排放物。"}, "sentence_index": 0, "correct_answer": "排出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个问题已经排出了，我们不用再担心。", "explanation": "这里应该用〈排除〉。排出指把物体从内部移到外面，问题、可能性等要用排除。"}, {"text": "这台收音机排出了很大的声音。", "explanation": "这里应该用〈发出〉。排出指把物体从内部移出，声音、光线等要用发出。"}, {"text": "我们终于排出了这个难题。", "explanation": "这里应该用〈解决〉。排出用于物体、液体、气体等，难题要用解决。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13316, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "排出", "is_correct": true, "explanation": "排出：符合句意，表示雨水从下水道被排走。"}, {"text": "品尝", "is_correct": false, "explanation": "语义：下水道是设施，不能“品尝”雨水，与句意冲突。"}, {"text": "咽", "is_correct": false, "explanation": "搭配：“咽”说吞下食物，不能用于下水道接纳雨水。"}, {"text": "饮", "is_correct": false, "explanation": "语义：下水道不能“饮”水，“饮”与设施主语相冲突。"}], "explanations": {"排出": "排出：符合句意，表示雨水从下水道被排走。", "品尝": "语义：下水道是设施，不能“品尝”雨水，与句意冲突。", "咽": "搭配：“咽”说吞下食物，不能用于下水道接纳雨水。", "饮": "语义：下水道不能“饮”水，“饮”与设施主语相冲突。"}, "sentence_index": 6, "correct_answer": "排出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从书包里排出了一本书。", "explanation": "这里应该用〈拿出〉。排出用于废水、废气等从内部排除的东西，书要用手拿出，不能说排出。"}, {"text": "农民用棍子把田里的野猪排出去了。", "explanation": "这里应该用〈赶走〉。排出用于废水、废气等从内部排除的东西，野猪这样的动物要用赶走。"}, {"text": "他把头上的帽子排出来了。", "explanation": "这里应该用〈摘下〉。排出用于从内部移出的废物、气体等，帽子从头上取下要用摘下。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13316, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "管道把污水排出了去。", "corrected_sentence": "管道把污水排出去了。", "error_description": "体标位置错误：“了”应放在补语“去”之后，说“排出去了”，不能插在“出”和“去”之间说“排出了去”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13316, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家工厂曾经排出了过大量废气。", "corrected_sentence": "这家工厂曾经排出过大量废气。", "error_description": "体标重复：“了”和“过”不能同时用在“排出”后，“曾经”已表示经历，应说“排出过大量废气”，去掉多余的“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
