INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13317, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指在生产或生活中使用过、受到污染、不再干净的水。", "primary_collocate": null, "pronunciation": "fèi shuǐ", "ipa": "feɪ˥˩ ʂweɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这家工厂很有名。生产过程中排出的废水常常含有化学物质。", "target_word": "废水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些废水进入河流和土壤，造成严重的污染。", "target_word": "废水", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "工厂把废水排进了河里。", "target_word": "废水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂的废水必须先处理再排放。", "target_word": "废水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "废水有一股很难闻的臭味。", "target_word": "废水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们建了一个新设备来处理废水。", "target_word": "废水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边排出的废水让鱼都死了。", "target_word": "废水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院的废水也要经过处理。", "target_word": "废水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民发现河水变黑，是因为有人偷排废水。", "target_word": "废水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂的废水里有很多对人不好的东西。", "target_word": "废水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "工业废水", "label": "复合"}, {"form": "生活废水", "label": "复合"}], "register": "中性", "sense_fingerprint": "生产或生活中用过、被污染的水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286b81e5-7ce8-4ad9-a3d1-740e7cf8bb39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13317, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "废水", "is_correct": true, "explanation": "废水：符合句意，指生产过程中排出的受污染的水。"}, {"text": "矿泉水", "is_correct": false, "explanation": "语义：矿泉水是可以饮用的干净水，不会从生产过程中排出，且与“含有化学物质”的语境冲突。"}, {"text": "牛奶", "is_correct": false, "explanation": "搭配：“排出”多用于废水、废气等废弃物，不说排出牛奶。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料是供人饮用的食品，不是生产中排出的东西。"}], "explanations": {"废水": "废水：符合句意，指生产过程中排出的受污染的水。", "矿泉水": "语义：矿泉水是可以饮用的干净水，不会从生产过程中排出，且与“含有化学物质”的语境冲突。", "牛奶": "搭配：“排出”多用于废水、废气等废弃物，不说排出牛奶。", "饮料": "语义：饮料是供人饮用的食品，不是生产中排出的东西。"}, "sentence_index": 0, "correct_answer": "废水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "河里的废水清澈见底，非常干净。", "explanation": "这里应该用〈清水〉。废水指用过、受污染的水，不会清澈见底，清澈的水要用清水。"}, {"text": "我每天用废水洗脸和刷牙。", "explanation": "这里应该用〈自来水〉。废水受污染，洗脸刷牙要用干净的自来水。"}, {"text": "这些废水可以直接烧开饮用。", "explanation": "这里应该用〈饮用水〉。废水受污染，不能饮用，应说饮用水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13317, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "废水", "is_correct": true, "explanation": "废水：符合句意，指河边排出的受污染的水。"}, {"text": "果汁", "is_correct": false, "explanation": "语义：果汁是食品饮料，不会从河边排出，也不会让鱼死亡。"}, {"text": "饮用水", "is_correct": false, "explanation": "语义：饮用水是干净可喝的水，与“让鱼都死了”的污染语境冲突。"}, {"text": "汽水", "is_correct": false, "explanation": "搭配：“排出”不与汽水搭配，汽水不是排放物。"}], "explanations": {"废水": "废水：符合句意，指河边排出的受污染的水。", "果汁": "语义：果汁是食品饮料，不会从河边排出，也不会让鱼死亡。", "饮用水": "语义：饮用水是干净可喝的水，与“让鱼都死了”的污染语境冲突。", "汽水": "搭配：“排出”不与汽水搭配，汽水不是排放物。"}, "sentence_index": 6, "correct_answer": "废水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他擦掉额头上的废水。", "explanation": "这里应该用〈汗水〉。废水指用过、受污染的水，额头上的水应是汗水。"}, {"text": "山间的废水甘甜可口，村民常来打水。", "explanation": "这里应该用〈泉水〉。废水不干净，不会甘甜可口，山间的水应是泉水。"}, {"text": "屋檐下淌着融化的废水。", "explanation": "这里应该用〈雪水〉。废水是用过、受污染的水，屋檐下融化的雪水应说雪水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13317, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "管道里流出一朵废水。", "corrected_sentence": "管道里流出一股废水。", "error_description": "量词错误：“朵”用于花，液体流动应用“股”，应说“一股废水”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13317, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家工厂每天产生很多个废水。", "corrected_sentence": "这家工厂每天产生很多废水。", "error_description": "量词错误：“废水”是液体，不能用量词“个”修饰，“很多”后应直接接“废水”，说“很多废水”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
