INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13319, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13319, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "化学物质是指具有特定分子结构和化学性质的物质，例如水（H₂O）或食盐（NaCl）。", "primary_collocate": null, "pronunciation": "huà xué wù zhì", "ipa": "xwa˥˩ ɕɥe˧˥ u˥˩ ʈʂɻ̩˥˩", "syllable_count": 4, "sentences": [{"text": "不仅如此，生产过程中排出的废水常常含有化学物质。", "target_word": "化学物质", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这种化学物质对人的身体不好。", "target_word": "化学物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人在工作时要小心化学物质。", "target_word": "化学物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水果上有时会残留一些化学物质。", "target_word": "化学物质", "complexity_tier": "T3", "furigana": "shuǐ guǒ shàng yǒu shí huì cán liú yì xiē huà xué wù zhì", "sentence_source": "generated"}, {"text": "实验室里放着很多不同的化学物质。", "target_word": "化学物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司生产的化学物质卖到了国外。", "target_word": "化学物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些化学物质会让皮肤很痒。", "target_word": "化学物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要把化学物质倒进下水道。", "target_word": "化学物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家正在研究这种化学物质的作用。", "target_word": "化学物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "塑料里的化学物质可能会进入食物。", "target_word": "化学物质", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种化学物质", "label": "量词"}, {"form": "有害化学物质", "label": "复合"}], "register": "中性", "sense_fingerprint": "具有特定分子结构和化学性质的物质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286b81e5-7ce8-4ad9-a3d1-740e7cf8bb39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13319, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "化学物质", "is_correct": true, "explanation": "正确。“化学物质”指具有特定分子结构的物质，废水中含有的正是这类成分。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果是食物，不是排出的废水里常含的成分，与“废水”的语境不合。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语，与这句书面化的说明语域不合，也不指废水中的成分。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“含有”后接物质成分，“颜色”是属性，不能说“含有颜色”。"}], "explanations": {"化学物质": "正确。“化学物质”指具有特定分子结构的物质，废水中含有的正是这类成分。", "水果": "语义：水果是食物，不是排出的废水里常含的成分，与“废水”的语境不合。", "玩意儿": "语域：“玩意儿”是口语，与这句书面化的说明语域不合，也不指废水中的成分。", "颜色": "搭配：“含有”后接物质成分，“颜色”是属性，不能说“含有颜色”。"}, "sentence_index": 0, "correct_answer": "化学物质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的化学物质考了九十分。", "explanation": "这里应该用〈化学〉。“化学”是学科名称，可以说考几分；“化学物质”指物质，不能作为科目。"}, {"text": "实验室里放着一本化学物质。", "explanation": "这里应该用〈种〉。“本”用于书籍、册子，化学物质不用“本”计量。"}, {"text": "我的表哥是一位著名的化学物质。", "explanation": "这里应该用〈化学家〉。“化学物质”指物质，不指人；说人应该用“化学家”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13319, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头一般不会让皮肤发痒，句中的“让皮肤很痒”要求能引起刺激或过敏的成分。"}, {"text": "化学物质", "is_correct": true, "explanation": "正确。有些化学物质会刺激皮肤，句意成立。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是房间，不会让皮肤很痒，与“会让皮肤很痒”的主语不合。"}, {"text": "家伙", "is_correct": false, "explanation": "语域：“家伙”是口语说法，用在这种说明句中不合语域，且一般指人。"}], "explanations": {"石头": "语义：石头一般不会让皮肤发痒，句中的“让皮肤很痒”要求能引起刺激或过敏的成分。", "化学物质": "正确。有些化学物质会刺激皮肤，句意成立。", "教室": "语义：教室是房间，不会让皮肤很痒，与“会让皮肤很痒”的主语不合。", "家伙": "语域：“家伙”是口语说法，用在这种说明句中不合语域，且一般指人。"}, "sentence_index": 6, "correct_answer": "化学物质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人把一根化学物质扔进了河里。", "explanation": "这里应该用〈种〉。“根”用于细长的东西，如绳子、木棍，化学物质不用“根”计量。"}, {"text": "这位化学物质今天给我们上了一节课。", "explanation": "这里应该用〈化学老师〉。“化学物质”指物质，不能指人，也不能给人上课。"}, {"text": "两种液体混合后发生了化学物质。", "explanation": "这里应该用〈化学反应〉。发生的是反应或变化，“化学物质”是物质，不能说“发生化学物质”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13319, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂排放了一只化学物质。", "corrected_sentence": "这家工厂排放了一种化学物质。", "error_description": "量词错误：“化学物质”前应用“种”，“只”用于动物或成对、成个的东西，不能用于物质名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13319, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这批货里混进了一张有害的化学物质。", "corrected_sentence": "这批货里混进了一种有害的化学物质。", "error_description": "量词错误：“化学物质”前应用“种”，“张”用于纸、桌子等扁平的东西，不能用于物质名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
