INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13320, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "工业区是指城市或地区中集中布置工业企业的区域，通常有完善的基础设施和配套服务。", "primary_collocate": null, "pronunciation": "gōng yè qū", "ipa": "kʊŋ˥ jɛ˥˩ tɕʰy˥", "syllable_count": 3, "sentences": [{"text": "有时候，一条干净的河，流经工业区后就变得又黑又臭。", "target_word": "工业区", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这座城市的工业区在东边。", "target_word": "工业区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业区里有很多大工厂。", "target_word": "工业区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府想把工厂搬到工业区去。", "target_word": "工业区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业区的空气常常不太好。", "target_word": "工业区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天坐公交车去工业区上班。", "target_word": "工业区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的工业区有宽宽的路和完善的水电。", "target_word": "工业区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业区附近不适合建住宅。", "target_word": "工业区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市里计划在郊外建一个工业区。", "target_word": "工业区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在工业区旁边的人常常抱怨噪音。", "target_word": "工业区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个工业区", "label": "量词"}, {"form": "工业园区", "label": "复合"}], "register": "中性", "sense_fingerprint": "城市中集中布置工业企业、设施完善的区域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286b81e5-7ce8-4ad9-a3d1-740e7cf8bb39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13320, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "海洋", "is_correct": false, "explanation": "搭配：“流经”接的是河流途经的地域，河流应该“流入”海洋，不能说“流经海洋”。"}, {"text": "工业区", "is_correct": true, "explanation": "正确。“工业区”是工厂集中的区域，河水流经这里后被排放物污染。"}, {"text": "书本", "is_correct": false, "explanation": "语义：河流不能流经书本，句中的“流经”只能接地域。"}, {"text": "教室", "is_correct": false, "explanation": "语义：河流不会流经教室，教室不是河流途经的地方。"}], "explanations": {"海洋": "搭配：“流经”接的是河流途经的地域，河流应该“流入”海洋，不能说“流经海洋”。", "工业区": "正确。“工业区”是工厂集中的区域，河水流经这里后被排放物污染。", "书本": "语义：河流不能流经书本，句中的“流经”只能接地域。", "教室": "语义：河流不会流经教室，教室不是河流途经的地方。"}, "sentence_index": 0, "correct_answer": "工业区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天骑车去一条工业区上班。", "explanation": "这里应该用〈个〉。“条”用于河流、道路等细长的东西，不用于区域。"}, {"text": "我们家住在一只工业区旁边。", "explanation": "这里应该用〈个〉或〈片〉。“只”用于动物或成对、成个的小东西，不能用于区域。"}, {"text": "我们的工厂很小，只是一个工业区而已。", "explanation": "这里应该用〈作坊〉。“工业区”指许多工厂集中的区域，只有一家小作坊不能称为工业区。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13320, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "病房", "is_correct": false, "explanation": "语义：病房是医院里的房间，不会有宽宽的路和完善的水电。"}, {"text": "工业区", "is_correct": true, "explanation": "正确。“新的工业区”指新建的、配套完善的区域，道路和水电都是园区设施。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶是盛花的器具，不能说有宽宽的路和完善的水电。"}, {"text": "脸", "is_correct": false, "explanation": "体貌：“脸”是人的面部，不能说有路和水电，与指地方的语境不合。"}], "explanations": {"病房": "语义：病房是医院里的房间，不会有宽宽的路和完善的水电。", "工业区": "正确。“新的工业区”指新建的、配套完善的区域，道路和水电都是园区设施。", "花瓶": "语义：花瓶是盛花的器具，不能说有宽宽的路和完善的水电。", "脸": "体貌：“脸”是人的面部，不能说有路和水电，与指地方的语境不合。"}, "sentence_index": 6, "correct_answer": "工业区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工业区里种满了花草，周末孩子们都去那儿玩。", "explanation": "这里应该用〈公园〉。工业区是工厂集中的区域，种满花草、供孩子游玩的地方是公园。"}, {"text": "这盏工业区很亮。", "explanation": "这里应该用〈片〉。“盏”用于灯具，工业区不能用“盏”计量。"}, {"text": "这把工业区很大。", "explanation": "这里应该用〈片〉。“把”用于有柄或可握住的器具，工业区不能用“把”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13320, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市政府刚批准了一根新的工业区。", "corrected_sentence": "市政府刚批准了一个新的工业区。", "error_description": "量词错误：“工业区”应用“个”，“根”用于细长的东西，不能用于计量区域。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13320, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "郊外新建了一条工业区。", "corrected_sentence": "郊外新建了一个工业区。", "error_description": "量词错误：“条”用于河流、道路等细长的东西，“工业区”是区域，应用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9cad0d6-4d9e-4f54-a613-13755bf4f0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13321, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "白", "is_correct": true, "explanation": "白：与“黑”表示颜色时相对，是反义词。"}, {"text": "软", "is_correct": false, "explanation": "与“黑”无反义关系，“软”说质地松软，与颜色无关。"}, {"text": "轻", "is_correct": false, "explanation": "与“黑”无反义关系，“轻”说重量，与颜色无关。"}, {"text": "快", "is_correct": false, "explanation": "与“黑”无反义关系，“快”说速度，与颜色无关。"}], "correct_answer": "白", "explanations": {"白": "白：与“黑”表示颜色时相对，是反义词。", "软": "与“黑”无反义关系，“软”说质地松软，与颜色无关。", "轻": "与“黑”无反义关系，“轻”说重量，与颜色无关。", "快": "与“黑”无反义关系，“快”说速度，与颜色无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebeba8cc-411c-4429-af3d-55552548402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13321, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "白", "is_correct": true, "explanation": "白：与“黑”表示颜色时相对，是反义词。"}, {"text": "硬", "is_correct": false, "explanation": "与“黑”无反义关系，“硬”说质地，与颜色无关。"}, {"text": "远", "is_correct": false, "explanation": "与“黑”无反义关系，“远”说距离，与颜色无关。"}, {"text": "重", "is_correct": false, "explanation": "与“黑”无反义关系，“重”说重量，与颜色无关。"}], "correct_answer": "白", "explanations": {"白": "白：与“黑”表示颜色时相对，是反义词。", "硬": "与“黑”无反义关系，“硬”说质地，与颜色无关。", "远": "与“黑”无反义关系，“远”说距离，与颜色无关。", "重": "与“黑”无反义关系，“重”说重量，与颜色无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebeba8cc-411c-4429-af3d-55552548402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13321, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "像煤或墨的颜色，是物体完全吸收日光或与日光相似的光线时所呈现的颜色。", "primary_collocate": null, "pronunciation": "hēi", "ipa": "xei̯˥", "syllable_count": 1, "sentences": [{"text": "有时候，一条干净的河，流经工业区后就变得又黑又臭。", "target_word": "黑", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这块煤像墨一样黑，手一摸就脏了。", "target_word": "黑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的头发全白了，孩子的头发却很黑。", "target_word": "黑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他修了一天车，两只手都黑了。", "target_word": "黑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白衬衫掉进墨水里，一下子就变黑了。", "target_word": "黑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这杯咖啡很苦，颜色也很黑。", "target_word": "黑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的车是黑的，停在夜里很难看到。", "target_word": "黑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火烧过以后，墙变得又黑又脏。", "target_word": "黑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白纸上写黑字，看得最清楚。", "target_word": "黑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服洗了很多次，已经不黑了。", "target_word": "黑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "黑黑的", "label": "重叠"}, {"form": "漆黑", "label": "复合"}, {"form": "乌黑", "label": "复合"}], "register": "中性", "sense_fingerprint": "黑：像煤、墨一样的颜色，与白相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38c40daa-4341-4477-af69-d754cda5ea8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13321, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "黑", "is_correct": true, "explanation": "正确答案。黑 hēi（第一声），意思是像煤或墨一样的颜色。"}, {"text": "飞", "is_correct": false, "explanation": "fēi（第一声）与 hēi 声母不同（f／h），意思是飞翔。"}, {"text": "嗨", "is_correct": false, "explanation": "hāi（第一声）与 hēi 韵母不同（ai／ei），意思是打招呼时说的“嗨”。"}, {"text": "杯", "is_correct": false, "explanation": "bēi（第一声）与 hēi 声母不同（b／h），意思是杯子。"}, {"text": "喝", "is_correct": false, "explanation": "hē（第一声）与 hēi 只差韵尾 -i，意思是喝。"}], "explanations": {"黑": "正确答案。黑 hēi（第一声），意思是像煤或墨一样的颜色。", "飞": "fēi（第一声）与 hēi 声母不同（f／h），意思是飞翔。", "嗨": "hāi（第一声）与 hēi 韵母不同（ai／ei），意思是打招呼时说的“嗨”。", "杯": "bēi（第一声）与 hēi 声母不同（b／h），意思是杯子。", "喝": "hē（第一声）与 hēi 只差韵尾 -i，意思是喝。"}, "sentence_index": null, "correct_answer": "黑"}, "level_3": {"options": [{"text": "黑", "is_correct": true, "explanation": "正确。黑：工业污染使河水变黑，与“又……又臭”描写的污染状况相符。"}, {"text": "香", "is_correct": false, "explanation": "语义：“香”与“臭”相反，“又黑又香”前后矛盾，不能用来形容被污染的河。"}, {"text": "干净", "is_correct": false, "explanation": "语义：句中已说河“干净”，“又干净又臭”自相矛盾，也与“变得”所表示的变化不符。"}, {"text": "软", "is_correct": false, "explanation": "搭配：“软”说质地，不用来形容河水，“又软又臭”搭配不当。"}], "explanations": {"黑": "正确。黑：工业污染使河水变黑，与“又……又臭”描写的污染状况相符。", "香": "语义：“香”与“臭”相反，“又黑又香”前后矛盾，不能用来形容被污染的河。", "干净": "语义：句中已说河“干净”，“又干净又臭”自相矛盾，也与“变得”所表示的变化不符。", "软": "搭配：“软”说质地，不用来形容河水，“又软又臭”搭配不当。"}, "sentence_index": 0, "correct_answer": "黑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "房间里的光很黑，我们看不清字。", "explanation": "这里应该用〈暗〉。说光线的明暗用“暗／亮”，不说“光很黑”。"}, {"text": "月光很黑，照在湖面上。", "explanation": "这里应该用〈亮〉。月光是发出的光，不能说“很黑”，与“照在湖面上”矛盾。"}, {"text": "灯光很黑，照得满屋子都是光。", "explanation": "这里应该用〈亮〉。灯光明亮用“亮”，“黑”不能用来形容发光的灯光，前后也自相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebeba8cc-411c-4429-af3d-55552548402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13321, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "黑", "is_correct": true, "explanation": "正确答案。黑 hēi（第一声），意思是像煤或墨一样的颜色。"}, {"text": "灰", "is_correct": false, "explanation": "huī（第一声）与 hēi 韵母不同（ui／ei），是另一种颜色。"}, {"text": "回", "is_correct": false, "explanation": "huí（第二声）与 hēi 韵母、声调都不同，意思是回来。"}, {"text": "河", "is_correct": false, "explanation": "hé（第二声）与 hēi 少韵尾 -i，声调也不同，意思是河流。"}, {"text": "给", "is_correct": false, "explanation": "gěi（第三声）与 hēi 声母不同（g／h），声调也不同，意思是给予。"}], "explanations": {"黑": "正确答案。黑 hēi（第一声），意思是像煤或墨一样的颜色。", "灰": "huī（第一声）与 hēi 韵母不同（ui／ei），是另一种颜色。", "回": "huí（第二声）与 hēi 韵母、声调都不同，意思是回来。", "河": "hé（第二声）与 hēi 少韵尾 -i，声调也不同，意思是河流。", "给": "gěi（第三声）与 hēi 声母不同（g／h），声调也不同，意思是给予。"}, "sentence_index": null, "correct_answer": "黑"}, "level_3": {"options": [{"text": "黑", "is_correct": true, "explanation": "正确。黑：车身颜色深，夜里不易看见，与“很难看到”前后一致。"}, {"text": "白", "is_correct": false, "explanation": "语义：白色在夜里较醒目，与“很难看到”的语义矛盾。"}, {"text": "亮", "is_correct": false, "explanation": "语义：亮色的车在夜里容易被看见，与“很难看到”的语义矛盾。"}, {"text": "高", "is_correct": false, "explanation": "搭配：“高”说高矮，不用来描述车的颜色，“是……的”后接“高”与句意不协调。"}], "explanations": {"黑": "正确。黑：车身颜色深，夜里不易看见，与“很难看到”前后一致。", "白": "语义：白色在夜里较醒目，与“很难看到”的语义矛盾。", "亮": "语义：亮色的车在夜里容易被看见，与“很难看到”的语义矛盾。", "高": "搭配：“高”说高矮，不用来描述车的颜色，“是……的”后接“高”与句意不协调。"}, "sentence_index": 6, "correct_answer": "黑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个老板心很黑，常常克扣工人的工资。", "explanation": "这里“黑”表示心狠、不讲良心，是另一个义项。本词指颜色，不用来形容人的品行。"}, {"text": "他开的是黑车，没有营业执照。", "explanation": "这里“黑”表示非法、未经许可，是另一个义项。本词指颜色，不表示违法。"}, {"text": "我一想到欠的钱，眼前就一黑。", "explanation": "这里“黑”表示眼前发晕、看不清，是另一个义项。本词指颜色，不表示感觉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebeba8cc-411c-4429-af3d-55552548402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13321, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块煤黑像墨一样。", "corrected_sentence": "这块煤黑得像墨一样。", "error_description": "应为“黑得像墨一样”。“黑”是谓语，后面要用“得”引出补语“像墨一样”说明程度，不能直接说“黑像墨一样”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebeba8cc-411c-4429-af3d-55552548402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13321, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "锅底让烟熏了黑。", "corrected_sentence": "锅底让烟熏黑了。", "error_description": "应为“熏黑了”。“了”表示变化完成，应放在补语“黑”之后，不能放在“黑”之前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebeba8cc-411c-4429-af3d-55552548402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13322, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "香", "is_correct": true, "explanation": "香：与“臭”（表示气味）相反，是反义词。"}, {"text": "软", "is_correct": false, "explanation": "与“臭”无反义关系，“软”说质地，与气味无关。"}, {"text": "轻", "is_correct": false, "explanation": "与“臭”无反义关系，“轻”说重量，与气味无关。"}, {"text": "快", "is_correct": false, "explanation": "与“臭”无反义关系，“快”说速度，与气味无关。"}], "correct_answer": "香", "explanations": {"香": "香：与“臭”（表示气味）相反，是反义词。", "软": "与“臭”无反义关系，“软”说质地，与气味无关。", "轻": "与“臭”无反义关系，“轻”说重量，与气味无关。", "快": "与“臭”无反义关系，“快”说速度，与气味无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebeba8cc-411c-4429-af3d-55552548402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13322, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "香", "is_correct": true, "explanation": "香：与“臭”（表示气味）相反，是反义词。"}, {"text": "慢", "is_correct": false, "explanation": "与“臭”无反义关系，“慢”说速度，与气味无关。"}, {"text": "硬", "is_correct": false, "explanation": "与“臭”无反义关系，“硬”说质地，与气味无关。"}, {"text": "远", "is_correct": false, "explanation": "与“臭”无反义关系，“远”说距离，与气味无关。"}], "correct_answer": "香", "explanations": {"香": "香：与“臭”（表示气味）相反，是反义词。", "慢": "与“臭”无反义关系，“慢”说速度，与气味无关。", "硬": "与“臭”无反义关系，“硬”说质地，与气味无关。", "远": "与“臭”无反义关系，“远”说距离，与气味无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebeba8cc-411c-4429-af3d-55552548402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13322, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容气味难闻，让人不舒服，跟‘香’相反。", "primary_collocate": null, "pronunciation": "chòu", "ipa": "ʈʂʰoʊ̯˥˩", "syllable_count": 1, "sentences": [{"text": "有时候，一条干净的河，流经工业区后就变得又黑又臭。", "target_word": "臭", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这双袜子穿了三天，真臭。", "target_word": "臭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "垃圾放了一个星期，已经很臭了。", "target_word": "臭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房里的垃圾桶太臭了，快拿出去。", "target_word": "臭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼放在外面两天，已经臭了。", "target_word": "臭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他运动完没有洗澡，身上很臭。", "target_word": "臭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个厕所又脏又臭，我不想进去。", "target_word": "臭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这朵花很香，那双鞋却很臭。", "target_word": "臭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱坏了，里面的肉都变臭了。", "target_word": "臭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的脚怎么这么臭？快去洗洗。", "target_word": "臭", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "臭臭的", "label": "重叠"}, {"form": "恶臭", "label": "复合"}, {"form": "臭气", "label": "复合"}], "register": "中性", "sense_fingerprint": "臭：气味难闻，与香相反", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38c40daa-4341-4477-af69-d754cda5ea8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13322, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "臭", "is_correct": true, "explanation": "正确答案。臭 chòu（第四声），意思是气味难闻。"}, {"text": "愁", "is_correct": false, "explanation": "chóu（第二声）与 chòu 声调不同，意思是发愁。"}, {"text": "寿", "is_correct": false, "explanation": "shòu（第四声）与 chòu 声母不同（sh／ch），意思是寿命。"}, {"text": "抽", "is_correct": false, "explanation": "chōu（第一声）与 chòu 声调不同，意思是抽取。"}], "explanations": {"臭": "正确答案。臭 chòu（第四声），意思是气味难闻。", "愁": "chóu（第二声）与 chòu 声调不同，意思是发愁。", "寿": "shòu（第四声）与 chòu 声母不同（sh／ch），意思是寿命。", "抽": "chōu（第一声）与 chòu 声调不同，意思是抽取。"}, "sentence_index": null, "correct_answer": "臭"}, "level_3": {"options": [{"text": "臭", "is_correct": true, "explanation": "正确。臭：河水被污染后发出难闻的气味，与“又黑又……”描写的污染状况相符。"}, {"text": "香", "is_correct": false, "explanation": "语义：“香”与“臭”相反，“又黑又香”前后矛盾，不能形容被污染的河。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”说味道，不用来形容河水的气味，“又黑又甜”搭配不当。"}, {"text": "软", "is_correct": false, "explanation": "搭配：“软”说质地，不用来形容河水，“又黑又软”搭配不当。"}], "explanations": {"臭": "正确。臭：河水被污染后发出难闻的气味，与“又黑又……”描写的污染状况相符。", "香": "语义：“香”与“臭”相反，“又黑又香”前后矛盾，不能形容被污染的河。", "甜": "搭配：“甜”说味道，不用来形容河水的气味，“又黑又甜”搭配不当。", "软": "搭配：“软”说质地，不用来形容河水，“又黑又软”搭配不当。"}, "sentence_index": 0, "correct_answer": "臭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这朵花很臭，闻了让人心情很好。", "explanation": "这里应该用〈香〉。花的好闻用“香”，“臭”形容气味难闻，与“心情很好”矛盾。"}, {"text": "这杯果汁很臭，喝起来很清爽。", "explanation": "这里应该用〈甜〉。果汁的滋味用“甜”，“臭”只形容气味，不用来说味道。"}, {"text": "这锅汤很臭，大家都夸好喝。", "explanation": "这里应该用〈鲜〉。汤的鲜美用“鲜”，“臭”只说气味难闻，与“大家都夸好喝”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebeba8cc-411c-4429-af3d-55552548402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13322, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "臭", "is_correct": true, "explanation": "正确答案。臭 chòu（第四声），意思是气味难闻。"}, {"text": "丑", "is_correct": false, "explanation": "chǒu（第三声）与 chòu 声调不同，意思是丑陋。"}, {"text": "凑", "is_correct": false, "explanation": "còu（第四声）与 chòu 声母不同（c／ch），意思是凑集。"}, {"text": "仇", "is_correct": false, "explanation": "chóu（第二声）与 chòu 声调不同，意思是仇恨。"}], "explanations": {"臭": "正确答案。臭 chòu（第四声），意思是气味难闻。", "丑": "chǒu（第三声）与 chòu 声调不同，意思是丑陋。", "凑": "còu（第四声）与 chòu 声母不同（c／ch），意思是凑集。", "仇": "chóu（第二声）与 chòu 声调不同，意思是仇恨。"}, "sentence_index": null, "correct_answer": "臭"}, "level_3": {"options": [{"text": "臭", "is_correct": true, "explanation": "正确。臭：厕所脏乱，气味难闻，与“又脏又……”相符。"}, {"text": "好", "is_correct": false, "explanation": "语义：“又脏又好”自相矛盾，“好”与“脏”的描写不能并列。"}, {"text": "高", "is_correct": false, "explanation": "搭配：“高”说高矮，不用来形容厕所的状况，“又脏又高”搭配不当。"}, {"text": "轻", "is_correct": false, "explanation": "搭配：“轻”说重量，不用来形容厕所，“又脏又轻”搭配不当。"}], "explanations": {"臭": "正确。臭：厕所脏乱，气味难闻，与“又脏又……”相符。", "好": "语义：“又脏又好”自相矛盾，“好”与“脏”的描写不能并列。", "高": "搭配：“高”说高矮，不用来形容厕所的状况，“又脏又高”搭配不当。", "轻": "搭配：“轻”说重量，不用来形容厕所，“又脏又轻”搭配不当。"}, "sentence_index": 6, "correct_answer": "臭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的名声很臭，没人愿意跟他合作。", "explanation": "这里“臭”表示名声坏、让人讨厌，是另一个义项。本词指气味难闻，不用来说名声。"}, {"text": "他下棋很臭，每次都输给我。", "explanation": "这里“臭”是口语中“很差”的意思，是另一个义项。本词指气味难闻，不表示水平低。"}, {"text": "他臭美得很，天天照镜子。", "explanation": "这里“臭”出现在“臭美”中，表示自我欣赏、爱炫耀，是另一个词义。本词指气味难闻，不表示爱美。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebeba8cc-411c-4429-af3d-55552548402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13322, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这双袜子真的臭很。", "corrected_sentence": "这双袜子真的很臭。", "error_description": "应为“很臭”。“很”是修饰形容词“臭”的程度副词，应放在“臭”前面，不能放在后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebeba8cc-411c-4429-af3d-55552548402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13322, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这盒牛奶放了一天，已经了臭。", "corrected_sentence": "这盒牛奶放了一天，已经臭了。", "error_description": "应为“臭了”。“了”表示变化完成，应放在“臭”之后，不能放在“臭”之前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebeba8cc-411c-4429-af3d-55552548402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
