INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13326, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "向公众介绍商品、服务或某种观念，以引起注意或扩大影响。", "primary_collocate": null, "pronunciation": "guǎng gào", "ipa": "kwɑŋ˨˩˦ kɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "广告鼓励人们不断购买新的款式。", "target_word": "广告", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "公司花了很多钱做电视广告。", "target_word": "广告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这则广告用了一位有名的歌手。", "target_word": "广告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上的广告太多，我常常不看。", "target_word": "广告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的广告能让人记住一个品牌。", "target_word": "广告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在地铁站里投放了新广告。", "target_word": "广告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个广告影响了很多年轻人的选择。", "target_word": "广告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律不允许广告说假话。", "target_word": "广告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在一家公司负责写广告。", "target_word": "广告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看完广告，我就想去买一个。", "target_word": "广告", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一则广告", "label": "量词"}, {"form": "广告牌", "label": "复合"}, {"form": "广告词", "label": "复合"}], "register": "中性", "sense_fingerprint": "向公众介绍商品、服务或观念以扩大影响", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38c40daa-4341-4477-af69-d754cda5ea8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13326, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "广告", "is_correct": true, "explanation": "广告：推广商品的宣传，可以作“鼓励”的主语，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，没有意愿，不能“鼓励”人购买商品。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“鼓励”需要有意识的施事者作主语，石头不能充当。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是地理事物，不能对人进行鼓励或劝说。"}], "explanations": {"广告": "广告：推广商品的宣传，可以作“鼓励”的主语，符合句意。", "天气": "语义：天气是自然现象，没有意愿，不能“鼓励”人购买商品。", "石头": "配价：“鼓励”需要有意识的施事者作主语，石头不能充当。", "河流": "语义：河流是地理事物，不能对人进行鼓励或劝说。"}, "sentence_index": 0, "correct_answer": "广告"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在网上看到一只广告，觉得很烦。", "explanation": "量词错误：这里应该用〈则〉。“只”用于动物，不用来数广告，广告常用“则”或“个”。"}, {"text": "我的书包里有一把广告，一直没有扔。", "explanation": "量词错误：这里应该用〈张〉。“把”用于有柄的东西，纸质的广告要说“一张广告”。"}, {"text": "街口的电线杆上挂着一根广告。", "explanation": "量词错误：这里应该用〈张〉。“根”用于细长的东西，贴在或挂在杆子上的广告要说“一张广告”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebeba8cc-411c-4429-af3d-55552548402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13326, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "广告", "is_correct": true, "explanation": "广告：作为“影响”的主语，表示广告对年轻人的选择产生作用，符合句意。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，没有影响人选择的作用，句子说不通。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“影响选择”通常与观点、潮流、媒体等连用，窗户不能构成这种影响。"}, {"text": "地毯", "is_correct": false, "explanation": "语义：地毯是铺在地上的物品，不能影响人的选择。"}], "explanations": {"广告": "广告：作为“影响”的主语，表示广告对年轻人的选择产生作用，符合句意。", "桌子": "语义：桌子是家具，没有影响人选择的作用，句子说不通。", "窗户": "搭配：“影响选择”通常与观点、潮流、媒体等连用，窗户不能构成这种影响。", "地毯": "语义：地毯是铺在地上的物品，不能影响人的选择。"}, "sentence_index": 6, "correct_answer": "广告"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "报纸上有一则广告，说昨晚的大火造成了很多人受伤。", "explanation": "这里应该用〈报道〉。广告是为了推广商品、服务或观念，不用来客观报告已经发生的事件。"}, {"text": "电视里播了一则广告，宣布他的父亲去世了。", "explanation": "这里应该用〈讣告〉。广告用于推广，不用来宣布某人去世。"}, {"text": "村口的告示栏上贴着一则广告，宣布王大爷去世了。", "explanation": "这里应该用〈讣告〉。广告的作用是推广，不是宣布死讯，此处应换成讣告。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebeba8cc-411c-4429-af3d-55552548402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13326, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店在街上发了一只广告。", "corrected_sentence": "这家店在街上发了一则广告。", "error_description": "错误：“一只广告”，正确：“一则广告”。“只”是用于动物的量词，广告的量词应为“则”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebeba8cc-411c-4429-af3d-55552548402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13326, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在报纸上看到一座广告，觉得很有意思。", "corrected_sentence": "我在报纸上看到一则广告，觉得很有意思。", "error_description": "错误：“一座广告”，正确：“一则广告”。“座”用于山、建筑等大型固定的东西，广告的量词应为“则”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebeba8cc-411c-4429-af3d-55552548402b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
