INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13329, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过燃烧使物体消失或毁坏。", "primary_collocate": null, "pronunciation": "shāo diào", "ipa": "ʂaʊ˥ tjaʊ˥˩", "syllable_count": 2, "sentences": [{"text": "旧衣服大部分不会被回收，而是被烧掉或埋在地下。", "target_word": "烧掉", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他把没用的旧信都烧掉了。", "target_word": "烧掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火太大，房子一下子就烧掉了。", "target_word": "烧掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上很干，一点火就会烧掉很多树。", "target_word": "烧掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她生气地把照片放进火里烧掉。", "target_word": "烧掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那场大火烧掉了整个村子的房子。", "target_word": "烧掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷把写过字的纸放在火盆里烧掉了。", "target_word": "烧掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年秋天，一场火烧掉了山上的树林。", "target_word": "烧掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想把这些旧书烧掉，可是我不同意。", "target_word": "烧掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前人们常把树叶烧掉，现在这样做不对。", "target_word": "烧掉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "烧掉了", "label": "体标"}, {"form": "烧掉过", "label": "体标"}, {"form": "烧不掉", "label": "可能补语"}], "register": "中性", "sense_fingerprint": "用火烧使东西消失或毁坏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff18899e-4ea4-436c-9109-7ad54f9ec2c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13329, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "烧掉", "is_correct": true, "explanation": "正确：烧掉（shāo diào），指用火使东西消失或毁坏。"}, {"text": "少掉", "is_correct": false, "explanation": "shǎo（第三声）与 shāo（第一声）声调不同，意思是减少掉。"}, {"text": "烧到", "is_correct": false, "explanation": "dào 与 diào 的韵母不同（少了 i），意思是烧到、烧着。"}, {"text": "删掉", "is_correct": false, "explanation": "shān 与 shāo 韵母不同（an 与 ao），意思是删除。"}], "explanations": {"烧掉": "正确：烧掉（shāo diào），指用火使东西消失或毁坏。", "少掉": "shǎo（第三声）与 shāo（第一声）声调不同，意思是减少掉。", "烧到": "dào 与 diào 的韵母不同（少了 i），意思是烧到、烧着。", "删掉": "shān 与 shāo 韵母不同（an 与 ao），意思是删除。"}, "sentence_index": null, "correct_answer": "烧掉"}, "level_3": {"options": [{"text": "烧掉", "is_correct": true, "explanation": "正确：烧掉表示用火毁去，与“埋在地下”并列，说明旧衣服的处理方式。"}, {"text": "回收", "is_correct": false, "explanation": "语义：前句已说“不会被回收”，这里再说“被回收”自相矛盾。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”用于语言文字，旧衣服不能被翻译，与句意不合。"}, {"text": "投资", "is_correct": false, "explanation": "语义：衣物不能被“投资”，与后半句“埋在地下”的处理方式不合。"}], "explanations": {"烧掉": "正确：烧掉表示用火毁去，与“埋在地下”并列，说明旧衣服的处理方式。", "回收": "语义：前句已说“不会被回收”，这里再说“被回收”自相矛盾。", "翻译": "语义：“翻译”用于语言文字，旧衣服不能被翻译，与句意不合。", "投资": "语义：衣物不能被“投资”，与后半句“埋在地下”的处理方式不合。"}, "sentence_index": 0, "correct_answer": "烧掉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把水烧掉了，准备泡茶。", "explanation": "这里应该用〈烧开〉。烧掉指东西被烧成灰或消失，烧水只是加热到开，要用烧开。"}, {"text": "妈妈把面包烧掉了，马上端上桌。", "explanation": "这里应该用〈烧焦〉。烧掉指东西被烧成灰或消失，面包只是烧黑、还能吃，要用烧焦。"}, {"text": "他把铁块烧掉了，用钳子夹起来。", "explanation": "这里应该用〈烧红〉。烧掉指东西毁坏或消失，铁块加热到发红要用烧红。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2ab7dfa-654b-4063-bf97-c930409e912f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13329, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "烧掉", "is_correct": true, "explanation": "正确：烧掉表示用火毁去，符合“放在火盆里”的做法。"}, {"text": "收藏", "is_correct": false, "explanation": "语义：“收藏”是留存以便珍视，与“放在火盆里”的做法相反。"}, {"text": "读完", "is_correct": false, "explanation": "语义：“读完”要求把纸上内容看完，与“放在火盆里”的动作不合。"}, {"text": "装订", "is_correct": false, "explanation": "搭配：“装订”指把纸页订成册，不能与“放在火盆里”搭配。"}], "explanations": {"烧掉": "正确：烧掉表示用火毁去，符合“放在火盆里”的做法。", "收藏": "语义：“收藏”是留存以便珍视，与“放在火盆里”的做法相反。", "读完": "语义：“读完”要求把纸上内容看完，与“放在火盆里”的动作不合。", "装订": "搭配：“装订”指把纸页订成册，不能与“放在火盆里”搭配。"}, "sentence_index": 6, "correct_answer": "烧掉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这批陶器是用高温烧掉的，很结实。", "explanation": "这里应该用〈烧制〉。烧掉指东西被烧成灰或毁坏，烧制陶器是使其定型，要用烧制。"}, {"text": "妈妈把饺子烧掉了，端上桌。", "explanation": "这里应该用〈煮熟〉。烧掉指燃烧使东西毁坏，煮饺子是用水加热至熟，要用煮熟。"}, {"text": "他把牛奶烧掉了，倒进杯子里。", "explanation": "这里应该用〈烧热〉。烧掉指东西被烧毁，牛奶只需加热，要用烧热。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2ab7dfa-654b-4063-bf97-c930409e912f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13329, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把那些旧报纸烧掉着。", "corrected_sentence": "妈妈把那些旧报纸烧掉了。", "error_description": "体标错误：“烧掉”表示动作已经完成，应用“了”；“着”表示持续，不能用在这里。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2ab7dfa-654b-4063-bf97-c930409e912f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13329, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶把旧信放进火盆里烧掉着。", "corrected_sentence": "奶奶把旧信放进火盆里烧掉了。", "error_description": "体标错误：“烧掉”表示动作已经完成，应用“了”；“着”表示持续，不能用在这里。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2ab7dfa-654b-4063-bf97-c930409e912f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
