INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13330, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用土、沙、雪等盖住，使不显露出来。", "primary_collocate": null, "pronunciation": "mái", "ipa": "mai˧˥", "syllable_count": 1, "sentences": [{"text": "旧衣服大部分不会被回收，而是被烧掉或埋在地下。", "target_word": "埋", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "小狗把骨头埋在了院子里。", "target_word": "埋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在沙滩上把脚埋进沙子里。", "target_word": "埋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把死去的小鸟埋在树下。", "target_word": "埋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雪埋住了山路，车开不过去。", "target_word": "埋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海盗把一箱金子埋在岛上。", "target_word": "埋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天，农民把土豆埋在土里保存。", "target_word": "埋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在花园里埋了一只小盒子。", "target_word": "埋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷说，这棵树下埋着很多旧东西。", "target_word": "埋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震后房子倒了，下面埋着不少人。", "target_word": "埋", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "埋了", "label": "体标（了）"}, {"form": "埋着", "label": "体标（着）"}, {"form": "埋过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "埋-用土沙雪等盖住使不显露", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '892e6a23-674a-4223-9c9c-54e9c0f9d361') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13330, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "埋", "is_correct": true, "explanation": "埋：用土、沙、雪等盖住，使不显露出来。"}, {"text": "买", "is_correct": false, "explanation": "mǎi（第三声）与 mái（第二声）声调不同，意思是买。"}, {"text": "麦", "is_correct": false, "explanation": "mài（第四声）与 mái（第二声）声调不同，意思是麦子。"}, {"text": "煤", "is_correct": false, "explanation": "méi 与 mái 韵母不同（ei 与 ai），意思是煤炭。"}, {"text": "没", "is_correct": false, "explanation": "méi 与 mái 韵母不同，意思是没有。"}, {"text": "迈", "is_correct": false, "explanation": "mài（第四声）与 mái（第二声）声调不同，意思是迈步。"}], "explanations": {"埋": "埋：用土、沙、雪等盖住，使不显露出来。", "买": "mǎi（第三声）与 mái（第二声）声调不同，意思是买。", "麦": "mài（第四声）与 mái（第二声）声调不同，意思是麦子。", "煤": "méi 与 mái 韵母不同（ei 与 ai），意思是煤炭。", "没": "méi 与 mái 韵母不同，意思是没有。", "迈": "mài（第四声）与 mái（第二声）声调不同，意思是迈步。"}, "sentence_index": null, "correct_answer": "埋"}, "level_3": {"options": [{"text": "埋", "is_correct": true, "explanation": "埋：用土覆盖使不显露，与「在地下」搭配，符合句意。"}, {"text": "种", "is_correct": false, "explanation": "语义：种是栽植植物，旧衣服不能种在地下。"}, {"text": "织", "is_correct": false, "explanation": "搭配：织是编织物品的动作，不能表示放置在地下。"}, {"text": "切", "is_correct": false, "explanation": "语义：切是割开的动作，与「在地下」不合。"}], "explanations": {"埋": "埋：用土覆盖使不显露，与「在地下」搭配，符合句意。", "种": "语义：种是栽植植物，旧衣服不能种在地下。", "织": "搭配：织是编织物品的动作，不能表示放置在地下。", "切": "语义：切是割开的动作，与「在地下」不合。"}, "sentence_index": 0, "correct_answer": "埋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在故事的开头就埋下了一个伏笔。", "explanation": "这是抽象义「为将来打下基础」，与「用土盖住」不同，不用于埋东西。"}, {"text": "他们把垃圾埋进了天空里。", "explanation": "天空无法用土沙覆盖，「埋」用在这里不成立。"}, {"text": "他把一首歌埋在了树下。", "explanation": "埋用于能被土沙覆盖的实物，歌曲无形，不能埋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae14e5c-e07c-4bf1-9912-b238114359dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13330, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "埋", "is_correct": true, "explanation": "埋：用土、沙、雪等盖住，使不显露出来。"}, {"text": "卖", "is_correct": false, "explanation": "mài（第四声）与 mái（第二声）声调不同，意思是卖。"}, {"text": "梅", "is_correct": false, "explanation": "méi 与 mái 韵母不同，意思是梅花。"}, {"text": "媒", "is_correct": false, "explanation": "méi 与 mái 韵母不同，意思是媒介。"}, {"text": "脉", "is_correct": false, "explanation": "mài（第四声）与 mái（第二声）声调不同，意思是血管、脉络。"}], "explanations": {"埋": "埋：用土、沙、雪等盖住，使不显露出来。", "卖": "mài（第四声）与 mái（第二声）声调不同，意思是卖。", "梅": "méi 与 mái 韵母不同，意思是梅花。", "媒": "méi 与 mái 韵母不同，意思是媒介。", "脉": "mài（第四声）与 mái（第二声）声调不同，意思是血管、脉络。"}, "sentence_index": null, "correct_answer": "埋"}, "level_3": {"options": [{"text": "埋", "is_correct": true, "explanation": "埋：用土盖住以便保存，符合「在土里保存」的句意。"}, {"text": "煮", "is_correct": false, "explanation": "语义：煮需要加水加热，不能把土豆「煮在土里」。"}, {"text": "晒", "is_correct": false, "explanation": "语义：晒是利用阳光晾干，与「在土里保存」不合。"}, {"text": "刷", "is_correct": false, "explanation": "搭配：刷用于涂抹表面，不说「刷在土里」。"}], "explanations": {"埋": "埋：用土盖住以便保存，符合「在土里保存」的句意。", "煮": "语义：煮需要加水加热，不能把土豆「煮在土里」。", "晒": "语义：晒是利用阳光晾干，与「在土里保存」不合。", "刷": "搭配：刷用于涂抹表面，不说「刷在土里」。"}, "sentence_index": 6, "correct_answer": "埋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个误会为他们的分手埋下了祸根。", "explanation": "这是抽象义「为将来打下基础」，与「用土盖住」不同。"}, {"text": "他把画埋在了空中。", "explanation": "空中无法用土沙盖住，「埋」用在这里不成立。"}, {"text": "这阵风埋在了树下。", "explanation": "风是无形的，不能用土沙盖住，不能埋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae14e5c-e07c-4bf1-9912-b238114359dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13330, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把旧照片埋在院子里着。", "corrected_sentence": "他把旧照片埋在院子里了。", "error_description": "体标误用：「把」字句表示已完成的「埋」，句末应用「了」，不能用表示持续的「着」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae14e5c-e07c-4bf1-9912-b238114359dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13330, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把旧盒子埋了在花园里。", "corrected_sentence": "他把旧盒子埋在了花园里。", "error_description": "补语位置错误：「埋在」是动补结构，「了」应放在补语「在」之后，应说「埋在了花园里」，不能说「埋了在花园里」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae14e5c-e07c-4bf1-9912-b238114359dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
