INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13334, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "担负某项工作、系统或流程的责任，确保其正常运作，或对结果承担责任。", "primary_collocate": null, "pronunciation": "fù zé", "ipa": "fu˥˩ tsɤ˧˥", "syllable_count": 2, "sentences": [{"text": "一些国家已经开始推动环保法规，要求企业对供应链负责。", "target_word": "负责", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "小王负责公司的网络系统。", "target_word": "负责", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条生产线由老李负责，出了问题要找他。", "target_word": "负责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机房的设备一直由张工程师负责检查。", "target_word": "负责", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁负责今天的报销流程？", "target_word": "负责", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "经理要对整个项目的质量负责。", "target_word": "负责", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "如果系统出了问题，就找负责的工程师。", "target_word": "负责", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "仓库的出货流程由我们组负责。", "target_word": "负责", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他负责每天检查机器是不是正常。", "target_word": "负责", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这套软件出错了，开发团队必须负责。", "target_word": "负责", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "负责了", "label": "体标"}, {"form": "负责过", "label": "体标"}, {"form": "负责人", "label": "复合"}, {"form": "負責", "label": "繁体"}], "register": "中性", "sense_fingerprint": "担负某项工作或系统的责任，确保其正常运作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edc2b444-45c3-4e43-811d-0a9ab0a8e562') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13334, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出版", "is_correct": false, "explanation": "语义：“出版”指印行书刊，不能用来说企业对供应链的责任，句子不通。"}, {"text": "负责", "is_correct": true, "explanation": "正确：“要求企业对供应链负责”指企业对供应链承担责任，与环保法规的语境相符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，与环保法规和供应链的语境无关。"}, {"text": "游泳", "is_correct": false, "explanation": "配价：“游泳”是不及物动词，不能带“对＋供应链”这样的对象。"}], "explanations": {"出版": "语义：“出版”指印行书刊，不能用来说企业对供应链的责任，句子不通。", "负责": "正确：“要求企业对供应链负责”指企业对供应链承担责任，与环保法规的语境相符。", "唱": "语义：“唱”指发出歌声，与环保法规和供应链的语境无关。", "游泳": "配价：“游泳”是不及物动词，不能带“对＋供应链”这样的对象。"}, "sentence_index": 0, "correct_answer": "负责"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "张工程师一直负责机房的主任。", "explanation": "这里应该用〈担任〉。“负责”针对具体工作或事务，职务名词要用“担任”，不能说“负责”加职务。"}, {"text": "张工程师一直负责机房的压力。", "explanation": "这里应该用〈承受〉。“负责”针对工作和事务，压力是一种感受，应说“承受压力”。"}, {"text": "张工程师一直负责这座城市的心情。", "explanation": "这里应该用〈关注〉。“负责”针对具体工作或事务，心情不是可以负责的对象，应说“关注心情”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2a68c4-ed6c-459b-815e-decf2ac36fdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13334, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉的工程师”与“系统出了问题，就找……”的求助语境相悖。"}, {"text": "负责", "is_correct": true, "explanation": "正确：“负责的工程师”指负责该系统的工程师，与“出了问题就找”前后呼应。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”需要带食物作宾语，“吃的”不能直接指代工程师。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”与解决系统问题无关，句子语义荒谬。"}], "explanations": {"睡觉": "语义：“睡觉的工程师”与“系统出了问题，就找……”的求助语境相悖。", "负责": "正确：“负责的工程师”指负责该系统的工程师，与“出了问题就找”前后呼应。", "吃": "配价：“吃”需要带食物作宾语，“吃的”不能直接指代工程师。", "结婚": "语义：“结婚”与解决系统问题无关，句子语义荒谬。"}, "sentence_index": 6, "correct_answer": "负责"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "开发团队负责了歉意。", "explanation": "这里应该用〈表达〉。“负责”针对工作和事务，歉意是情感，应说“表达歉意”。"}, {"text": "开发团队负责了责任。", "explanation": "这里应该用〈承担〉。固定搭配是“承担责任”，“负责”后面要接工作或事务，不能直接接“责任”。"}, {"text": "开发团队向用户负责感谢。", "explanation": "这里应该用〈表示〉。“负责”只能以工作或事务作宾语，“感谢”是动作，不能作“负责”的宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2a68c4-ed6c-459b-815e-decf2ac36fdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13334, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们公司要产品的安全负责。", "corrected_sentence": "我们公司要对产品的安全负责。", "error_description": "“要……负责”中，负责的对象要用介词“对”引出。漏掉“对”，“要产品的安全负责”不成立；正确形式为“要对产品的安全负责”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2a68c4-ed6c-459b-815e-decf2ac36fdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13334, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他负责着过这个项目。", "corrected_sentence": "他负责过这个项目。", "error_description": "错误：“负责着过”。正确：“负责过”。表示曾经的经历只用“过”，不能同时加“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2a68c4-ed6c-459b-815e-decf2ac36fdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
