INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13335, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "产业是指国民经济中生产同类产品或提供同类服务的企业的集合，如工业、农业等。", "primary_collocate": null, "pronunciation": "chǎn yè", "ipa": "ʈʂʰan˨˩˦ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "要破解这一困局，必须从系统层面重构时尚产业的生态逻辑。", "target_word": "产业", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "农业是国家最重要的产业之一。", "target_word": "产业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个地区的主要产业是旅游。", "target_word": "产业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府想发展新的产业，帮助年轻人找工作。", "target_word": "产业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "传统产业需要新技术，才能继续发展。", "target_word": "产业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "汽车产业给这座城市带来了很多工作机会。", "target_word": "产业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "近年来，互联网产业发展得非常快。", "target_word": "产业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司想进入电影产业。", "target_word": "产业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了保护环境，这个产业必须减少污染。", "target_word": "产业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在服装产业工作了十年。", "target_word": "产业", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "产业链", "label": "复合"}, {"form": "产业园", "label": "复合"}, {"form": "產業", "label": "繁体"}], "register": "书面", "sense_fingerprint": "国民经济中生产同类产品或提供同类服务的企业的集合，如工业、农业", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e30e707f-e868-41d3-92c0-29d881cfc989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13335, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "产业", "is_correct": true, "explanation": "产业指国民经济中同类企业的集合，符合“时尚产业的生态逻辑”的语境。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”是人体的状态，“时尚体温的生态逻辑”搭配不通。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“心情”是个人情绪，不是可以被“重构”的生态系统。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是产业或系统，不存在“生态逻辑”。"}], "explanations": {"产业": "产业指国民经济中同类企业的集合，符合“时尚产业的生态逻辑”的语境。", "体温": "语义：“体温”是人体的状态，“时尚体温的生态逻辑”搭配不通。", "心情": "语义：“心情”是个人情绪，不是可以被“重构”的生态系统。", "天气": "语义：“天气”不是产业或系统，不存在“生态逻辑”。"}, "sentence_index": 0, "correct_answer": "产业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司是一个大产业。", "explanation": "这里应该用〈企业〉。产业指同类企业的总和，不能指一家公司。"}, {"text": "他的产业是医生。", "explanation": "这里应该用〈职业〉。产业指一类企业或行业的整体，不指个人从事的工作。"}, {"text": "这个产业有两千名学生。", "explanation": "这里应该用〈学校〉。产业是企业的集合，不能指拥有学生的学校。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c38b26c-bcfd-4c05-b256-f08815080b14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13335, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "产业", "is_correct": true, "explanation": "产业指同类企业的集合，可以“发展得很快”，符合“互联网产业”的语境。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是空间，不是可以“发展得非常快”的领域。"}, {"text": "心脏", "is_correct": false, "explanation": "语义：“心脏”是器官，不能作为“互联网”的发展对象。"}, {"text": "学费", "is_correct": false, "explanation": "搭配：“学费”通常说上涨或增长，不说“互联网学费发展得很快”。"}], "explanations": {"产业": "产业指同类企业的集合，可以“发展得很快”，符合“互联网产业”的语境。", "厨房": "语义：“厨房”是空间，不是可以“发展得非常快”的领域。", "心脏": "语义：“心脏”是器官，不能作为“互联网”的发展对象。", "学费": "搭配：“学费”通常说上涨或增长，不说“互联网学费发展得很快”。"}, "sentence_index": 6, "correct_answer": "产业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们周末去产业看电影。", "explanation": "这里应该用〈影院〉。产业指同类企业的集合，不是可以去看电影的场所。"}, {"text": "他每天在产业里做饭，饭菜很香。", "explanation": "这里应该用〈厨房〉。产业指同类企业的集合，不是做饭的地方。"}, {"text": "他很喜欢这个产业，每天都去那里买书。", "explanation": "这里应该用〈书店〉。产业指同类企业的集合，不是买书的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c38b26c-bcfd-4c05-b256-f08815080b14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13335, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个城市有一件重要的产业。", "corrected_sentence": "这个城市有一个重要的产业。", "error_description": "量词错误：“产业”应搭配量词“个”或“种”，不能用“件”。正确说法是“一个重要的产业”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c38b26c-bcfd-4c05-b256-f08815080b14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13335, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们想找一份汽车产业地工作。", "corrected_sentence": "他们想找一份汽车产业的工作。", "error_description": "「汽车产业」修饰名词「工作」时应用「的」，不能用「地」。「地」用于修饰动词，所以应说「汽车产业的工作」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c38b26c-bcfd-4c05-b256-f08815080b14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13336, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "衰落", "is_correct": true, "explanation": "“衰落”与“崛起”意义相反，指国家或力量由强变弱。"}, {"text": "游泳", "is_correct": false, "explanation": "“游泳”是体育动作，与“崛起”没有反义关系。"}, {"text": "思考", "is_correct": false, "explanation": "“思考”是心理活动，与“崛起”没有反义关系。"}, {"text": "睡觉", "is_correct": false, "explanation": "“睡觉”是日常动作，与“崛起”没有反义关系。"}], "correct_answer": "衰落", "explanations": {"衰落": "“衰落”与“崛起”意义相反，指国家或力量由强变弱。", "游泳": "“游泳”是体育动作，与“崛起”没有反义关系。", "思考": "“思考”是心理活动，与“崛起”没有反义关系。", "睡觉": "“睡觉”是日常动作，与“崛起”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7bf06a-50af-4fe3-aaf0-a17605044138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
