INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13337, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "将衣服套在身体上的动作；也指穿衣服的方式与打扮。", "primary_collocate": null, "pronunciation": "chuān yī", "ipa": "ʈʂʰwan˥ i˥", "syllable_count": 2, "sentences": [{"text": "在当代全球化经济图景中，快时尚产业的崛起不仅重塑了消费者的穿衣模式，更对地球脆弱的水资源系统施加了前所未有的压力。", "target_word": "穿衣", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "小孩子三岁就会自己穿衣。", "target_word": "穿衣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "早上起床后，我先洗脸，再穿衣。", "target_word": "穿衣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他穿衣很讲究。", "target_word": "穿衣", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "冬天穿衣要注意保暖。", "target_word": "穿衣", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈在旁边看着，让孩子慢慢自己穿衣。", "target_word": "穿衣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人的穿衣习惯都不一样。", "target_word": "穿衣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人行动不方便，穿衣时需要家人帮忙。", "target_word": "穿衣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个季节早晚很冷，穿衣要一层一层加。", "target_word": "穿衣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一边听音乐，一边穿衣，差点儿迟到了。", "target_word": "穿衣", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "穿衣镜", "label": "复合"}, {"form": "穿衣打扮", "label": "复合"}], "register": "中性", "sense_fingerprint": "把衣服套在身体上的动作，也指穿着打扮的方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e30e707f-e868-41d3-92c0-29d881cfc989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13337, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "穿衣", "is_correct": true, "explanation": "穿衣：把衣服穿到身上。"}, {"text": "船医", "is_correct": false, "explanation": "chuán（第二声）与 chuān（第一声）声调不同，意思是船上的医生。"}, {"text": "传艺", "is_correct": false, "explanation": "chuán 与 chuān 声调不同，yì 与 yī 声调也不同，意思是传授技艺。"}, {"text": "春衣", "is_correct": false, "explanation": "chūn 与 chuān 韵母不同（-un 与 -uan），意思是春天穿的衣服。"}, {"text": "传译", "is_correct": false, "explanation": "chuán 与 chuān 声调不同，yì 与 yī 声调也不同，意思是转达翻译。"}], "explanations": {"穿衣": "穿衣：把衣服穿到身上。", "船医": "chuán（第二声）与 chuān（第一声）声调不同，意思是船上的医生。", "传艺": "chuán 与 chuān 声调不同，yì 与 yī 声调也不同，意思是传授技艺。", "春衣": "chūn 与 chuān 韵母不同（-un 与 -uan），意思是春天穿的衣服。", "传译": "chuán 与 chuān 声调不同，yì 与 yī 声调也不同，意思是转达翻译。"}, "sentence_index": null, "correct_answer": "穿衣"}, "level_3": {"options": [{"text": "穿衣", "is_correct": true, "explanation": "穿衣：把衣服穿到身上，此处作定语修饰“模式”，符合“消费者的穿衣模式”。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”是体育活动，不能修饰“消费者的……模式”。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”是休闲动作，与快时尚产业和消费者的语境无关。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”需要“送给谁”的成分，不能直接作定语修饰“模式”。"}], "explanations": {"穿衣": "穿衣：把衣服穿到身上，此处作定语修饰“模式”，符合“消费者的穿衣模式”。", "游泳": "语义：“游泳”是体育活动，不能修饰“消费者的……模式”。", "散步": "语义：“散步”是休闲动作，与快时尚产业和消费者的语境无关。", "送": "配价：“送”需要“送给谁”的成分，不能直接作定语修饰“模式”。"}, "sentence_index": 0, "correct_answer": "穿衣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "洗澡前要先穿衣，再进浴室。", "explanation": "这里应该用〈脱衣〉。穿衣是把衣服穿到身上，洗澡前要先脱衣，不能说“穿衣”。"}, {"text": "睡觉前，他先穿衣，再上床。", "explanation": "这里应该用〈脱衣〉。穿衣是把衣服穿到身上，睡觉前上床应该脱衣。"}, {"text": "医生说要检查身体，请他先穿衣。", "explanation": "这里应该用〈脱衣〉。穿衣是把衣服穿到身上，检查身体前应该脱衣。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c38b26c-bcfd-4c05-b256-f08815080b14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13337, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "穿衣", "is_correct": true, "explanation": "穿衣：把衣服穿到身上，作定语修饰“习惯”，符合“每个人的穿衣习惯”。"}, {"text": "穿越", "is_correct": false, "explanation": "语义：“穿越”指穿过时空或空间，不能修饰“习惯”。"}, {"text": "穿梭", "is_correct": false, "explanation": "语义：“穿梭”指来回往返地移动，与“习惯”的意思不相关。"}, {"text": "穿透", "is_correct": false, "explanation": "搭配：“穿透”的对象是物体或障碍，“穿透习惯”不成立。"}], "explanations": {"穿衣": "穿衣：把衣服穿到身上，作定语修饰“习惯”，符合“每个人的穿衣习惯”。", "穿越": "语义：“穿越”指穿过时空或空间，不能修饰“习惯”。", "穿梭": "语义：“穿梭”指来回往返地移动，与“习惯”的意思不相关。", "穿透": "搭配：“穿透”的对象是物体或障碍，“穿透习惯”不成立。"}, "sentence_index": 6, "correct_answer": "穿衣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把这本书穿衣，然后放进了书包。", "explanation": "这里应该用〈装〉。穿衣的对象是人身上的衣物，书不能穿衣，应说“装”。"}, {"text": "她把这张纸穿衣，夹进了文件夹。", "explanation": "这里应该用〈夹〉。穿衣的对象是人身上的衣物，纸不能穿衣，应说“夹”。"}, {"text": "他把这盏灯穿衣，挂在了屋顶上。", "explanation": "这里应该用〈挂〉。穿衣的对象是人身上的衣物，灯不能穿衣，应说“挂”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c38b26c-bcfd-4c05-b256-f08815080b14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13337, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他穿衣好就出门了。", "corrected_sentence": "他穿好衣就出门了。", "error_description": "「穿衣」是离合词，结果补语「好」要放在「穿」和「衣」中间，说「穿好衣」，不能说「穿衣好」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c38b26c-bcfd-4c05-b256-f08815080b14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13337, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他穿衣得很快。", "corrected_sentence": "他穿衣穿得很快。", "error_description": "补语结构错误：带补语“得”的句子中，动词“穿”需要重复，应说“穿衣穿得很快”，不能只说“穿衣得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c38b26c-bcfd-4c05-b256-f08815080b14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
