INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13339, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f660ad-79eb-445b-b92d-728a763c4725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13339, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "合成纤维是以石油等为原料，经化学合成方法制成的化学纤维，常用于纺织衣物、绳索等。", "primary_collocate": null, "pronunciation": "hé chéng xiān wéi", "ipa": "xɤ˧˥ ʈʂʰɤŋ˧˥ ɕjɛn˥ weɪ˧˥", "syllable_count": 4, "sentences": [{"text": "纺织品的生产，尤其是棉质与合成纤维的加工，本质上是一个极度依赖水资源的工业流程。", "target_word": "合成纤维", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "合成纤维是用化学方法制成的，不是天然的。", "target_word": "合成纤维", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件运动衣是用合成纤维做的，干得很快。", "target_word": "合成纤维", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂用石油做原料，生产合成纤维。", "target_word": "合成纤维", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "合成纤维做的绳子很结实，不容易断。", "target_word": "合成纤维", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种地毯用的是合成纤维，不是羊毛。", "target_word": "合成纤维", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "合成纤维比棉花便宜，所以很多衣服都用它。", "target_word": "合成纤维", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和天然纤维相比，合成纤维更不容易发皱。", "target_word": "合成纤维", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对合成纤维过敏，只穿纯棉的衣服。", "target_word": "合成纤维", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们常用合成纤维制作帐篷和雨衣。", "target_word": "合成纤维", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "化纤", "label": "简称"}], "register": "中性", "sense_fingerprint": "以石油等为原料、化学合成制成的纤维，用于纺织衣物和绳索", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5fcd1e1-fe75-4807-99d7-b2e4db8a4067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13339, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "合成纤维", "is_correct": true, "explanation": "正确：“合成纤维”是纺织材料，与“棉质”并列，可以一起加工。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“加工”要求有实体的材料，不能说加工“天气”。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是场所，不是纺织材料，不能和棉质一起加工。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情是抽象的感受，不是可以加工的物质。"}], "explanations": {"合成纤维": "正确：“合成纤维”是纺织材料，与“棉质”并列，可以一起加工。", "天气": "搭配：“加工”要求有实体的材料，不能说加工“天气”。", "花园": "语义：花园是场所，不是纺织材料，不能和棉质一起加工。", "心情": "语义：心情是抽象的感受，不是可以加工的物质。"}, "sentence_index": 0, "correct_answer": "合成纤维"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "早餐吃燕麦，可以补充合成纤维。", "explanation": "这里应该用〈膳食纤维〉。合成纤维是纺织用的材料，不能吃，也不能补充营养。"}, {"text": "城市的监控摄像头用合成纤维联网。", "explanation": "这里应该用〈光纤〉。光纤用来传输光信号，合成纤维用于纺织，不能用来联网。"}, {"text": "这种粘胶纤维是用木浆做的，属于合成纤维。", "explanation": "这里应该用〈人造纤维〉。粘胶纤维以木浆为原料，属于人造纤维；合成纤维是用石油等原料经化学合成制成的，两者不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f660ad-79eb-445b-b92d-728a763c4725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13339, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "合成纤维", "is_correct": true, "explanation": "正确：“合成纤维”价格低于棉花，所以很多衣服都用它。"}, {"text": "大米", "is_correct": false, "explanation": "语义：大米是食物，不是衣料，衣服不会用大米做。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能用来做衣服，也不会比棉花便宜。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“用……做衣服”要求纤维或布料，不说用石头做衣服。"}], "explanations": {"合成纤维": "正确：“合成纤维”价格低于棉花，所以很多衣服都用它。", "大米": "语义：大米是食物，不是衣料，衣服不会用大米做。", "空气": "语义：空气不能用来做衣服，也不会比棉花便宜。", "石头": "搭配：“用……做衣服”要求纤维或布料，不说用石头做衣服。"}, "sentence_index": 6, "correct_answer": "合成纤维"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件毛衣是纯合成纤维的，是从羊身上剪下来的毛。", "explanation": "这里应该用〈羊毛〉。从羊身上剪下来的是天然的羊毛，合成纤维是用石油等原料化学合成的。"}, {"text": "棉花和蚕丝都是合成纤维。", "explanation": "这里应该用〈天然纤维〉。棉花和蚕丝来自植物和动物，是天然纤维，不是化学合成的。"}, {"text": "他用合成纤维做了一个硬硬的水桶。", "explanation": "这里应该用〈塑料〉。做硬水桶的材料是塑料，合成纤维是用来纺织的纤维材料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f660ad-79eb-445b-b92d-728a763c4725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13339, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂生产一种很耐用地合成纤维。", "corrected_sentence": "工厂生产一种很耐用的合成纤维。", "error_description": "修饰语错误：“很耐用”修饰名词“合成纤维”，应用“的”，不能用“地”。正确形式是“很耐用的合成纤维”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f660ad-79eb-445b-b92d-728a763c4725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13339, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把合成纤维织。", "corrected_sentence": "工人把合成纤维织成了布。", "error_description": "补语缺失：“把”字句中的动词后面需要补语，“把合成纤维织”不完整，应为“把合成纤维织成了布”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f660ad-79eb-445b-b92d-728a763c4725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
