INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13342, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f660ad-79eb-445b-b92d-728a763c4725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13342, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使物品或事物变得有条理、有秩序。", "primary_collocate": null, "pronunciation": "zhěng lǐ", "ipa": "ʈʂɤŋ˨˩˦ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "面对堆积多年的旧档案，他用了整整三天逐页核对、分类、标注，才把它们一一整理成有条理的卷宗。", "target_word": "整理", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "开会前，我先整理一下发言的思路。", "target_word": "整理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请同学们把课堂笔记整理好。", "target_word": "整理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他花了一个晚上整理这些旧资料。", "target_word": "整理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你整理一下这份名单，按姓名排列。", "target_word": "整理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写报告以前，要先整理好调查数据。", "target_word": "整理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把采访录音整理成了文字。", "target_word": "整理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们需要整理一下会议记录，再发给大家。", "target_word": "整理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理让小王整理去年的销售数据。", "target_word": "整理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "复习时，他一边读书一边整理重点。", "target_word": "整理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "整理了", "label": "体标"}, {"form": "整理过", "label": "体标"}, {"form": "整理整理", "label": "重叠"}], "register": "中性", "sense_fingerprint": "整理：把资料、思路、数据等事物理出条理和秩序", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5fcd1e1-fe75-4807-99d7-b2e4db8a4067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13342, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "整理", "is_correct": true, "explanation": "正确：“整理成有条理的卷宗”指把档案理顺、分类，符合句意。"}, {"text": "烘焙", "is_correct": false, "explanation": "语义：烘焙是烤制食品，不能把档案烘焙成卷宗。"}, {"text": "播种", "is_correct": false, "explanation": "语义：播种是栽种种子，与档案无关，不能播种成卷宗。"}, {"text": "修剪", "is_correct": false, "explanation": "搭配：修剪用于枝叶、毛发等，不能修剪档案成卷宗。"}], "explanations": {"整理": "正确：“整理成有条理的卷宗”指把档案理顺、分类，符合句意。", "烘焙": "语义：烘焙是烤制食品，不能把档案烘焙成卷宗。", "播种": "语义：播种是栽种种子，与档案无关，不能播种成卷宗。", "修剪": "搭配：修剪用于枝叶、毛发等，不能修剪档案成卷宗。"}, "sentence_index": 0, "correct_answer": "整理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生花了一个晚上整理病人。", "explanation": "这里应该用〈治疗〉。整理指把物品或资料理顺，不用于人，治疗病人要用“治疗”。"}, {"text": "厨师花了一个晚上整理汤。", "explanation": "这里应该用〈煮〉。整理用于物品或资料，烹制汤要用“煮”。"}, {"text": "他花了一个晚上整理这台坏掉的打印机。", "explanation": "这里应该用〈修理〉。整理是使物品有条理，不表示修好坏掉的机器，修好打印机要用“修理”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f660ad-79eb-445b-b92d-728a763c4725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13342, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "整理", "is_correct": true, "explanation": "正确：“整理成了文字”指把录音内容理顺后写成文字，符合句意。"}, {"text": "烘焙", "is_correct": false, "explanation": "语义：烘焙是烤制食品，不能把录音烘焙成文字。"}, {"text": "雕刻", "is_correct": false, "explanation": "搭配：“雕刻”的对象是木石等材料，不能与“采访录音”搭配。"}, {"text": "绘制", "is_correct": false, "explanation": "语义：绘制是画图，与把录音内容转为文字的意思不符。"}], "explanations": {"整理": "正确：“整理成了文字”指把录音内容理顺后写成文字，符合句意。", "烘焙": "语义：烘焙是烤制食品，不能把录音烘焙成文字。", "雕刻": "搭配：“雕刻”的对象是木石等材料，不能与“采访录音”搭配。", "绘制": "语义：绘制是画图，与把录音内容转为文字的意思不符。"}, "sentence_index": 6, "correct_answer": "整理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "厨师在整理面糊，准备做蛋糕。", "explanation": "这里应该用〈搅拌〉。整理是把物品理顺，搅拌面糊要用“搅拌”。"}, {"text": "火箭整理成功，飞上了天空。", "explanation": "这里应该用〈发射〉。整理不表示发射升空，火箭升空要用“发射”。"}, {"text": "猫整理了一只老鼠。", "explanation": "这里应该用〈捕捉〉。整理用于物品或资料，猫抓老鼠要用“捕捉”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f660ad-79eb-445b-b92d-728a763c4725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13342, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把资料整理的很清楚。", "corrected_sentence": "他把资料整理得很清楚。", "error_description": "错误：“整理的很清楚”。“整理”后接表示程度的补语时要用助词“得”，不能用“的”。正确形式是“整理得很清楚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f660ad-79eb-445b-b92d-728a763c4725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13342, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她正在整理过一批旧照片。", "corrected_sentence": "她正在整理一批旧照片。", "error_description": "错误：“正在整理过”。“正在”表示动作正在进行，“过”表示曾经经历，二者矛盾。正确形式是“正在整理一批旧照片”，去掉“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f660ad-79eb-445b-b92d-728a763c4725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
