INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13343, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在主要工作完成后，对产品、材料或数据进行进一步处理或加工。", "primary_collocate": null, "pronunciation": "hòu chǔ lǐ", "ipa": "xou˥˩ ʈʂʰu˨˩ li˨˩˦", "syllable_count": 3, "sentences": [{"text": "从棉花种植阶段的大量灌溉，到印染、整理等后处理环节的高耗水作业，每一吨纺织品的诞生往往伴随着数万升淡水的消耗。", "target_word": "后处理", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "照片拍完以后，还要做后处理。", "target_word": "后处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂的产品要经过后处理，才能出售。", "target_word": "后处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "视频拍好了，后处理时再加上字幕。", "target_word": "后处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数据收集完以后，后处理需要两天时间。", "target_word": "后处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "陶瓷烧好以后，后处理主要是打磨表面。", "target_word": "后处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件可以自动完成图片的后处理。", "target_word": "后处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "布料织好后，后处理能让它更柔软。", "target_word": "后处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "后处理做得好，布料穿起来更舒服。", "target_word": "后处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验结束以后，研究员开始做数据的后处理。", "target_word": "后处理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "后处理环节", "label": "复合"}, {"form": "后处理软件", "label": "复合"}, {"form": "後處理", "label": "繁体"}], "register": "书面", "sense_fingerprint": "后处理：主要工序之后对产品、材料、数据的进一步加工", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5fcd1e1-fe75-4807-99d7-b2e4db8a4067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13343, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "后处理", "is_correct": true, "explanation": "正确：后处理指主要工序之后的进一步加工，与“印染、整理”这类完工环节相符。"}, {"text": "纺纱", "is_correct": false, "explanation": "语义：纺纱是纺线的前段工序，与“印染、整理”这类后段环节不同类，句意不通。"}, {"text": "仓储", "is_correct": false, "explanation": "语义：仓储指存放货物，不是高耗水的作业，与“高耗水作业”的语境不符。"}, {"text": "装配", "is_correct": false, "explanation": "搭配：「装配」多指机械零件的组装，不能用来指纺织品的生产环节。"}], "explanations": {"后处理": "正确：后处理指主要工序之后的进一步加工，与“印染、整理”这类完工环节相符。", "纺纱": "语义：纺纱是纺线的前段工序，与“印染、整理”这类后段环节不同类，句意不通。", "仓储": "语义：仓储指存放货物，不是高耗水的作业，与“高耗水作业”的语境不符。", "装配": "搭配：「装配」多指机械零件的组装，不能用来指纺织品的生产环节。"}, "sentence_index": 0, "correct_answer": "后处理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂把棉花后处理成了布。", "explanation": "这里应该用〈加工〉。后处理指主要工序完成之后的进一步处理，不能表示把原料变成布料。"}, {"text": "这批零件还没加工，就先做后处理，去掉毛刺。", "explanation": "这里应该用〈前处理〉。后处理指主要工序完成之后的处理，加工之前不能说后处理。"}, {"text": "这家餐厅每天要给客人做后处理。", "explanation": "这里应该用〈服务〉。后处理针对产品、材料或数据，不能用于对客人提供的服务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f660ad-79eb-445b-b92d-728a763c4725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13343, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "后处理", "is_correct": true, "explanation": "正确：后处理指加工完成后的进一步处理，符合“自动完成”的语境。"}, {"text": "手绘", "is_correct": false, "explanation": "语义：手绘需要人工一笔一画完成，与“软件可以自动完成”矛盾。"}, {"text": "拍摄", "is_correct": false, "explanation": "语义：拍摄是用相机获取图像的动作，不是对已有图片的进一步加工，与“软件完成后处理”不符。"}, {"text": "人工", "is_correct": false, "explanation": "语义：人工指靠人力完成，与“软件自动完成”的意思相反。"}], "explanations": {"后处理": "正确：后处理指加工完成后的进一步处理，符合“自动完成”的语境。", "手绘": "语义：手绘需要人工一笔一画完成，与“软件可以自动完成”矛盾。", "拍摄": "语义：拍摄是用相机获取图像的动作，不是对已有图片的进一步加工，与“软件完成后处理”不符。", "人工": "语义：人工指靠人力完成，与“软件自动完成”的意思相反。"}, "sentence_index": 6, "correct_answer": "后处理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器昨天坏了，工人花了一上午后处理它。", "explanation": "这里应该用〈修理〉。后处理指对成品、材料或数据做进一步加工，不能用于修复坏了的机器。"}, {"text": "这家公司的后处理主要是做广告宣传。", "explanation": "这里应该用〈营销〉。后处理指对产品、材料或数据的进一步加工，不包括广告宣传这类营销活动。"}, {"text": "工厂把做好的布料后处理，变回了棉花。", "explanation": "这里应该用〈还原〉。后处理是进一步加工，不能指把成品变回原料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f660ad-79eb-445b-b92d-728a763c4725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13343, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这批零件出厂前都要做一只后处理，才能保证质量。", "corrected_sentence": "这批零件出厂前都要做一道后处理，才能保证质量。", "error_description": "错误形式：“一只后处理”；正确形式：“一道后处理”。“只”多用于动物或成对的物品，后处理是工序，应用量词“道”计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f660ad-79eb-445b-b92d-728a763c4725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13343, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "实验数据要先吃好后处理，才能分析。", "corrected_sentence": "实验数据要先做好后处理，才能分析。", "error_description": "动词搭配错误：“后处理”是对数据的进一步加工，应与“做”搭配；“吃”不能用于数据。正确形式为“要先做好后处理”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f660ad-79eb-445b-b92d-728a763c4725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
