INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13344, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指使用或消耗水的过程，通常用于描述农业、工业或日常生活中对水资源的利用和减少。", "primary_collocate": null, "pronunciation": "hào shuǐ", "ipa": "xɑʊ˥˩ ʂweɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "从棉花种植阶段的大量灌溉，到印染、整理等后处理环节的高耗水作业，每一吨纺织品的诞生往往伴随着数万升淡水的消耗。", "target_word": "耗水", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "种水稻特别耗水，所以农民要常常灌溉。", "target_word": "耗水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台旧洗衣机太耗水了，洗一次要用很多水。", "target_word": "耗水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "造纸厂每天耗水几百吨，附近的河水变少了。", "target_word": "耗水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛肉比蔬菜更耗水，养牛要用很多水。", "target_word": "耗水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草坪看起来很漂亮，可是非常耗水。", "target_word": "耗水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天花园里的花很耗水，每天都要浇。", "target_word": "耗水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座工厂用了新技术，不再那么耗水了。", "target_word": "耗水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗车店很耗水，所以他们开始循环用水。", "target_word": "耗水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这类工作太耗水，当地的水越来越少。", "target_word": "耗水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "耗水了", "label": "体标"}, {"form": "耗水量", "label": "复合"}, {"form": "高耗水", "label": "复合"}], "register": "书面", "sense_fingerprint": "耗水：农业、工业、生活中使用并消耗水资源", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5fcd1e1-fe75-4807-99d7-b2e4db8a4067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13344, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "耗水", "is_correct": true, "explanation": "正确：耗水（hào shuǐ），指消耗用水。"}, {"text": "汗水", "is_correct": false, "explanation": "hàn（第四声）与 hào（第四声）韵母不同（-an 与 -ao），意思是汗水。"}, {"text": "冒水", "is_correct": false, "explanation": "mào（第四声）与 hào（第四声）声母不同（m 与 h），意思是水往外冒。"}, {"text": "倒水", "is_correct": false, "explanation": "dào（第四声）与 hào（第四声）声母不同（d 与 h），意思是把水倒出。"}], "explanations": {"耗水": "正确：耗水（hào shuǐ），指消耗用水。", "汗水": "hàn（第四声）与 hào（第四声）韵母不同（-an 与 -ao），意思是汗水。", "冒水": "mào（第四声）与 hào（第四声）声母不同（m 与 h），意思是水往外冒。", "倒水": "dào（第四声）与 hào（第四声）声母不同（d 与 h），意思是把水倒出。"}, "sentence_index": null, "correct_answer": "耗水"}, "level_3": {"options": [{"text": "耗水", "is_correct": true, "explanation": "正确：「高耗水作业」指用水量大的作业，“耗水”在此构成“高耗水”。"}, {"text": "缺水", "is_correct": false, "explanation": "语义：「高缺水作业」说不通，缺水指水不够，与句中大量用水的语境相反。"}, {"text": "漏水", "is_correct": false, "explanation": "语义：漏水是水白白流失，不是加工作业的特征，与“淡水的消耗”的语境不合。"}, {"text": "省水", "is_correct": false, "explanation": "搭配：「高」修饰用水量，「省水」表示节约，二者不能搭配成“高省水作业”。"}], "explanations": {"耗水": "正确：「高耗水作业」指用水量大的作业，“耗水”在此构成“高耗水”。", "缺水": "语义：「高缺水作业」说不通，缺水指水不够，与句中大量用水的语境相反。", "漏水": "语义：漏水是水白白流失，不是加工作业的特征，与“淡水的消耗”的语境不合。", "省水": "搭配：「高」修饰用水量，「省水」表示节约，二者不能搭配成“高省水作业”。"}, "sentence_index": 0, "correct_answer": "耗水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们应该耗水。", "explanation": "这里应该用〈节约〉。耗水指用水过多、使水量减少，与“应该”所倡导的节水态度相反。"}, {"text": "工厂在水池里耗水，留着第二天用。", "explanation": "这里应该用〈蓄水〉。耗水指用掉水、使水量减少，不表示把水存起来备用。"}, {"text": "这辆汽车很耗水，每个月都要去加油站。", "explanation": "这里应该用〈耗油〉。汽车消耗的是燃油，耗水只指消耗水资源，不能用于燃料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f660ad-79eb-445b-b92d-728a763c4725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13344, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "耗水", "is_correct": true, "explanation": "正确：耗水指消耗用水，与“每天都要浇”的需要相符。"}, {"text": "怕水", "is_correct": false, "explanation": "语义：怕水与“每天都要浇”矛盾，花不会怕水还要天天浇。"}, {"text": "耐水", "is_correct": false, "explanation": "语义：耐水指能耐受水，与“每天都要浇”的需求矛盾。"}, {"text": "抗旱", "is_correct": false, "explanation": "语义：抗旱指耐受干旱，与“每天都要浇”的需求矛盾。"}], "explanations": {"耗水": "正确：耗水指消耗用水，与“每天都要浇”的需要相符。", "怕水": "语义：怕水与“每天都要浇”矛盾，花不会怕水还要天天浇。", "耐水": "语义：耐水指能耐受水，与“每天都要浇”的需求矛盾。", "抗旱": "语义：抗旱指耐受干旱，与“每天都要浇”的需求矛盾。"}, "sentence_index": 6, "correct_answer": "耗水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台冰箱很耗水，每月电费很高。", "explanation": "这里应该用〈耗电〉。冰箱用的是电，耗水指消耗水资源，不能用于电器的能耗。"}, {"text": "工厂在河边耗水，再供应给车间。", "explanation": "这里应该用〈取水〉。耗水表示水被用掉、水量减少，不表示从河边把水取来。"}, {"text": "这场会议太耗水了，开了整整三个小时。", "explanation": "这里应该用〈耗时〉。耗水指消耗水资源，不能用于会议或时间的消耗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f660ad-79eb-445b-b92d-728a763c4725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13344, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座工厂每天耗水三个，附近的河水少了很多。", "corrected_sentence": "这座工厂每天耗水三吨，附近的河水少了很多。", "error_description": "错误形式：“耗水三个”；正确形式：“耗水三吨”。水以“吨”“升”计量，“个”不能用于水。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f660ad-79eb-445b-b92d-728a763c4725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13344, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台机器改进以后，已经很不太耗水了。", "corrected_sentence": "这台机器改进以后，已经不太耗水了。", "error_description": "错误形式：“很不太耗水”；正确形式：“不太耗水”。“不太”本身已表示程度，前面不能再加“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f660ad-79eb-445b-b92d-728a763c4725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
