INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13345, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "学校老师布置给学生课后完成的练习或任务。", "primary_collocate": null, "pronunciation": "zuò yè", "ipa": "tswo˥˩ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "这份作业要求学生在两周内完成三篇读书笔记，并结合课堂讨论的内容，提出各自对文本的独立思考与质疑。", "target_word": "作业", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "教师布置的作业应当在当天完成。", "target_word": "作业", "complexity_tier": "T3", "furigana": "zuòyè", "sentence_source": "generated"}, {"text": "学生需要按时提交本周的数学作业。", "target_word": "作业", "complexity_tier": "T3", "furigana": "zuòyè", "sentence_source": "generated"}, {"text": "课后作业是巩固课堂知识的重要环节。", "target_word": "作业", "complexity_tier": "T3", "furigana": "zuòyè", "sentence_source": "generated"}, {"text": "完成作业的质量直接影响学习效果。", "target_word": "作业", "complexity_tier": "T3", "furigana": "zuòyè", "sentence_source": "generated"}, {"text": "教师批改作业时，常会标出错误之处。", "target_word": "作业", "complexity_tier": "T3", "furigana": "zuòyè", "sentence_source": "generated"}, {"text": "若作业未能按期上交，将扣除相应平时成绩。", "target_word": "作业", "complexity_tier": "T3", "furigana": "zuòyè", "sentence_source": "generated"}, {"text": "本学期的寒假作业包括阅读与写作两部分。", "target_word": "作业", "complexity_tier": "T3", "furigana": "zuòyè", "sentence_source": "generated"}, {"text": "学生应独立完成作业，不得抄袭他人答案。", "target_word": "作业", "complexity_tier": "T3", "furigana": "zuòyè", "sentence_source": "generated"}, {"text": "作业范围以课本第三单元为准。", "target_word": "作业", "complexity_tier": "T3", "furigana": "zuòyè", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "作業", "label": "繁体"}], "register": "书面", "sense_fingerprint": "作业：老师布置给学生课后完成的练习或任务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3730d27a-05b6-43d9-b563-68f34a3445ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13345, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "作业", "is_correct": true, "explanation": "正确：作业（zuòyè）指老师布置给学生的课后练习或任务。"}, {"text": "昨夜", "is_correct": false, "explanation": "zuó（第二声）与 zuò（第四声）声调不同，意思是昨天夜里。"}, {"text": "做客", "is_correct": false, "explanation": "kè 与 yè 声母不同（k 与 y），意思是到别人家里拜访。"}, {"text": "作恶", "is_correct": false, "explanation": "è 与 yè 声母不同（无声母与 y），意思是做坏事。"}], "explanations": {"作业": "正确：作业（zuòyè）指老师布置给学生的课后练习或任务。", "昨夜": "zuó（第二声）与 zuò（第四声）声调不同，意思是昨天夜里。", "做客": "kè 与 yè 声母不同（k 与 y），意思是到别人家里拜访。", "作恶": "è 与 yè 声母不同（无声母与 y），意思是做坏事。"}, "sentence_index": null, "correct_answer": "作业"}, "level_3": {"options": [{"text": "学业", "is_correct": false, "explanation": "语义：“学业”指学习的整体进程，不是可以“完成三篇读书笔记”的具体任务。"}, {"text": "作业", "is_correct": true, "explanation": "正确：“这份作业”指老师布置的具体读书任务，与“完成三篇读书笔记”相合。"}, {"text": "座位", "is_correct": false, "explanation": "语义：“座位”是就座的地方，不能被布置，也不能要求学生去完成。"}, {"text": "教室", "is_correct": false, "explanation": "语义：句中主语是布置给学生的任务，“教室”不能要求学生完成读书笔记。"}], "explanations": {"学业": "语义：“学业”指学习的整体进程，不是可以“完成三篇读书笔记”的具体任务。", "作业": "正确：“这份作业”指老师布置的具体读书任务，与“完成三篇读书笔记”相合。", "座位": "语义：“座位”是就座的地方，不能被布置，也不能要求学生去完成。", "教室": "语义：句中主语是布置给学生的任务，“教室”不能要求学生完成读书笔记。"}, "sentence_index": 0, "correct_answer": "作业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在一家银行找到了一份作业。", "explanation": "这里应该用〈工作〉。〈作业〉指学生课后的练习或生产现场的操作，求职得到的职位要用〈工作〉。"}, {"text": "这家餐厅的作业很好吃。", "explanation": "这里应该用〈菜〉。作业指学生的练习或生产现场的操作，不能用来指食物。"}, {"text": "我们一起去公园作业吧。", "explanation": "这里应该用〈散步〉。〈作业〉是名词，指老师布置的练习，不能表示去公园的活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52f73cdc-6b31-4015-ba53-595f929484c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13345, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "考勤", "is_correct": false, "explanation": "搭配：“上交”的对象是练习或报告，不能说“上交考勤”。"}, {"text": "作业", "is_correct": true, "explanation": "正确：“作业”可以“按期上交”，与“扣除平时成绩”的语境相合。"}, {"text": "座位", "is_correct": false, "explanation": "语义：“座位”不是可以提交的物品，与“按期上交”的逻辑不合。"}, {"text": "演讲", "is_correct": false, "explanation": "语义：演讲是口头表达，不能被“上交”，与句中的提交要求冲突。"}], "explanations": {"考勤": "搭配：“上交”的对象是练习或报告，不能说“上交考勤”。", "作业": "正确：“作业”可以“按期上交”，与“扣除平时成绩”的语境相合。", "座位": "语义：“座位”不是可以提交的物品，与“按期上交”的逻辑不合。", "演讲": "语义：演讲是口头表达，不能被“上交”，与句中的提交要求冲突。"}, "sentence_index": 6, "correct_answer": "作业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部作业很有名，很多人都读过。", "explanation": "这里应该用〈作品〉。作业指学生布置的练习，有名的文学或艺术创作要用作品。"}, {"text": "妈妈给我买了一件新作业。", "explanation": "这里应该用〈衣服〉。〈作业〉是老师布置的练习，不能买来穿。"}, {"text": "外面的作业很大，别出门了。", "explanation": "这里应该用〈雨〉。〈作业〉指课后练习，不能形容天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52f73cdc-6b31-4015-ba53-595f929484c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13345, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他昨晚做了一场作业，一直写到深夜。", "corrected_sentence": "他昨晚做了一份作业，一直写到深夜。", "error_description": "错误在于量词：“作业”应配“份”，“场”只用于活动、比赛等事件，不能用于作业。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52f73cdc-6b31-4015-ba53-595f929484c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13345, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一口气做完了一只作业。", "corrected_sentence": "他一口气做完了一份作业。", "error_description": "错误在于量词：“作业”应配“份”，“只”多用于动物或成对的物品，不能用于作业。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52f73cdc-6b31-4015-ba53-595f929484c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
