INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13346, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "纺织工业是指将纤维原料加工成纱线、织物等纺织品的工业部门。", "primary_collocate": null, "pronunciation": "fǎng zhī gōng yè", "ipa": "faŋ˨˩˦ ʈʂɨ˥˥ kʊŋ˥˥ jɛ˥˩", "syllable_count": 4, "sentences": [{"text": "在某些干旱频发的地区，纺织工业甚至成为加剧水资源短缺的关键因素，挤占了农业、饮用水与生态系统所需的水量。", "target_word": "纺织工业", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "纺织工业在这个城市已有一百多年的历史。", "target_word": "纺织工业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "江苏的纺织工业非常发达。", "target_word": "纺织工业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "纺织工业需要大量的棉花和工人。", "target_word": "纺织工业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着技术进步，纺织工业的生产效率提高了很多。", "target_word": "纺织工业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家靠纺织工业出口赚了很多钱。", "target_word": "纺织工业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "纺织工业会产生污水，必须认真处理。", "target_word": "纺织工业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府想帮助纺织工业使用更环保的技术。", "target_word": "纺织工业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他大学毕业后进入了纺织工业工作。", "target_word": "纺织工业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "纺织工业是我国重要的传统工业之一。", "target_word": "纺织工业", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "纺织业", "label": "简称"}, {"form": "紡織工業", "label": "繁体"}], "register": "书面", "sense_fingerprint": "纺织工业：把纤维加工成纱线、织物的工业部门", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3730d27a-05b6-43d9-b563-68f34a3445ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13346, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "教育", "is_correct": false, "explanation": "语义：“教育”不耗水，不能“挤占”水量，也不能成为水资源短缺的因素。"}, {"text": "纺织工业", "is_correct": true, "explanation": "正确：“纺织工业”是耗水的产业部门，能够“挤占”农业与饮用水的用水量。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆不是用水的生产部门，与“挤占水量”的语境不符。"}, {"text": "语言", "is_correct": false, "explanation": "搭配：“挤占……水量”的主语应是用水的产业，“语言”不能与之搭配。"}], "explanations": {"教育": "语义：“教育”不耗水，不能“挤占”水量，也不能成为水资源短缺的因素。", "纺织工业": "正确：“纺织工业”是耗水的产业部门，能够“挤占”农业与饮用水的用水量。", "图书馆": "语义：图书馆不是用水的生产部门，与“挤占水量”的语境不符。", "语言": "搭配：“挤占……水量”的主语应是用水的产业，“语言”不能与之搭配。"}, "sentence_index": 0, "correct_answer": "纺织工业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家商店专门卖各种纺织工业。", "explanation": "这里应该用〈纺织品〉。纺织工业是行业部门，商店卖的是纺织品。"}, {"text": "她用纺织工业织了一条围巾。", "explanation": "这里应该用〈纱线〉。纺织工业是行业名称，不能当原料使用，织围巾要用纱线。"}, {"text": "这家公司每年生产大量纺织工业。", "explanation": "这里应该用〈纺织机械〉。纺织工业是行业名称，工厂生产的是设备或产品，不能说生产纺织工业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52f73cdc-6b31-4015-ba53-595f929484c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13346, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小说", "is_correct": false, "explanation": "语义：小说是文学作品，不会产生污水，与句意相悖。"}, {"text": "纺织工业", "is_correct": true, "explanation": "正确：只有生产部门才会“产生污水”，与“必须认真处理”相合。"}, {"text": "音乐", "is_correct": false, "explanation": "搭配：“产生污水”不能与“音乐”搭配，音乐没有排放物。"}, {"text": "寓言", "is_correct": false, "explanation": "语义：寓言是故事体裁，不会产生污水，无法“认真处理”。"}], "explanations": {"小说": "语义：小说是文学作品，不会产生污水，与句意相悖。", "纺织工业": "正确：只有生产部门才会“产生污水”，与“必须认真处理”相合。", "音乐": "搭配：“产生污水”不能与“音乐”搭配，音乐没有排放物。", "寓言": "语义：寓言是故事体裁，不会产生污水，无法“认真处理”。"}, "sentence_index": 6, "correct_answer": "纺织工业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很讲究纺织工业。", "explanation": "这里应该用〈服饰〉。“讲究”用于衣服、装饰等，行业部门不能被讲究。"}, {"text": "这位设计师的纺织工业很有创意。", "explanation": "这里应该用〈设计〉。纺织工业是行业名称，有创意的是设计作品，不能用来形容行业。"}, {"text": "政府出台了新的纺织工业。", "explanation": "这里应该用〈政策〉。出台的是政策或法规，纺织工业是行业，不能被出台。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52f73cdc-6b31-4015-ba53-595f929484c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13346, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座城市的纺织工业很发展。", "corrected_sentence": "这座城市的纺织工业很发达。", "error_description": "错误在于“纺织工业”的谓语：形容工业水平高应说“很发达”，“发展”是动词，不能受“很”修饰作谓语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52f73cdc-6b31-4015-ba53-595f929484c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13346, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府决定扶持纺织工业的发达。", "corrected_sentence": "政府决定扶持纺织工业的发展。", "error_description": "错误在于搭配：“扶持”的是“纺织工业的发展”，“发达”是形容词，不能作“扶持”的对象。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52f73cdc-6b31-4015-ba53-595f929484c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
