INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13353, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "处在某个地方或位置。", "primary_collocate": null, "pronunciation": "wèi yú", "ipa": "weɪ˥˩ y˧˥", "syllable_count": 2, "sentences": [{"text": "学校位于城市的东边。", "target_word": "位于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公园位于河的北面。", "target_word": "位于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家位于一座小山下面。", "target_word": "位于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的公司位于市中心。", "target_word": "位于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家医院位于哪里？", "target_word": "位于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆位于二楼。", "target_word": "位于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子位于两座山中间。", "target_word": "位于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京位于中国的北部。", "target_word": "位于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的酒店位于海边。", "target_word": "位于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车站位于银行对面。", "target_word": "位于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "（建筑、地区等）处在某个位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eafd00e7-0c74-47ca-a160-5befa431b7b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13353, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "位于", "is_correct": true, "explanation": "位于（wèi yú）表示处在某个地方或位置，是正确答案。"}, {"text": "维语", "is_correct": false, "explanation": "维语（wéi yǔ）两个音节的声调都与位于（wèi yú）不同，意思是维吾尔语。"}, {"text": "位移", "is_correct": false, "explanation": "位移（wèi yí）与位于（wèi yú）只有韵母不同（yí 与 yú），意思是物体位置的改变。"}, {"text": "卫浴", "is_correct": false, "explanation": "卫浴（wèi yù）与位于（wèi yú）第二个音节声调不同（yù 第四声，yú 第二声），意思是卫生间和浴室。"}], "explanations": {"位于": "位于（wèi yú）表示处在某个地方或位置，是正确答案。", "维语": "维语（wéi yǔ）两个音节的声调都与位于（wèi yú）不同，意思是维吾尔语。", "位移": "位移（wèi yí）与位于（wèi yú）只有韵母不同（yí 与 yú），意思是物体位置的改变。", "卫浴": "卫浴（wèi yù）与位于（wèi yú）第二个音节声调不同（yù 第四声，yú 第二声），意思是卫生间和浴室。"}, "sentence_index": null, "correct_answer": "位于"}, "level_3": {"options": [{"text": "位于", "is_correct": true, "explanation": "位于表示处在某个位置，与“学校在城市东边”的意思相符。"}, {"text": "生活", "is_correct": false, "explanation": "语义：生活要求有生命的主语，学校不能“生活”。"}, {"text": "驻扎", "is_correct": false, "explanation": "搭配：“驻扎”的主语多为军队，不能说“学校驻扎”。"}, {"text": "发生", "is_correct": false, "explanation": "语义：“发生”指事件出现，学校是处所，不能作“发生”的主语。"}], "explanations": {"位于": "位于表示处在某个位置，与“学校在城市东边”的意思相符。", "生活": "语义：生活要求有生命的主语，学校不能“生活”。", "驻扎": "搭配：“驻扎”的主语多为军队，不能说“学校驻扎”。", "发生": "语义：“发生”指事件出现，学校是处所，不能作“发生”的主语。"}, "sentence_index": 0, "correct_answer": "位于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司位于困境中。", "explanation": "这里应该用〈处于〉。“位于”多指具体位置或地位（如“位于前列”），“困境”是状态，应说处于。"}, {"text": "爷爷位于沙发上看报纸。", "explanation": "这里应该用〈坐〉。位于只用于事物或机构的位置，人坐着的动作要用坐。"}, {"text": "我们位于学生宿舍里。", "explanation": "这里应该用〈住〉。位于说的是事物或机构的位置，人居住要用住。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27715830-11a4-4473-84d5-18c38b0de7ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13353, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "位于", "is_correct": true, "explanation": "位于（wèi yú）表示处在某个地方或位置，是正确答案。"}, {"text": "谓语", "is_correct": false, "explanation": "谓语（wèi yǔ）与位于只有第二个音节声调不同（yǔ 第三声，yú 第二声），意思是句子中说明主语的部分。"}, {"text": "未愈", "is_correct": false, "explanation": "未愈（wèi yù）与位于第二个音节声调不同（yù 第四声，yú 第二声），意思是伤病还没有好。"}, {"text": "微雨", "is_correct": false, "explanation": "微雨（wēi yǔ）两个音节的声调都与位于（wèi yú）不同，意思是小雨。"}], "explanations": {"位于": "位于（wèi yú）表示处在某个地方或位置，是正确答案。", "谓语": "谓语（wèi yǔ）与位于只有第二个音节声调不同（yǔ 第三声，yú 第二声），意思是句子中说明主语的部分。", "未愈": "未愈（wèi yù）与位于第二个音节声调不同（yù 第四声，yú 第二声），意思是伤病还没有好。", "微雨": "微雨（wēi yǔ）两个音节的声调都与位于（wèi yú）不同，意思是小雨。"}, "sentence_index": null, "correct_answer": "位于"}, "level_3": {"options": [{"text": "位于", "is_correct": true, "explanation": "位于表示处在某个位置，与“村子在两座山中间”的意思相符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”的主语须是人或动物，村子不能游泳，与“两座山中间”的语境不合。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”的主语须是人，村子不能散步。"}, {"text": "跳", "is_correct": false, "explanation": "语义：“跳”的主语须是能动的生物，村子不能跳。"}], "explanations": {"位于": "位于表示处在某个位置，与“村子在两座山中间”的意思相符。", "游泳": "语义：“游泳”的主语须是人或动物，村子不能游泳，与“两座山中间”的语境不合。", "散步": "语义：“散步”的主语须是人，村子不能散步。", "跳": "语义：“跳”的主语须是能动的生物，村子不能跳。"}, "sentence_index": 6, "correct_answer": "位于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爸爸位于门口。", "explanation": "这里应该用〈站〉。位于只说事物的位置，人站立的动作要用站。"}, {"text": "我位于床上看书。", "explanation": "这里应该用〈躺〉。位于只说事物的位置，人躺卧在床上要用躺。"}, {"text": "这个城市位于很多大学。", "explanation": "这里应该用〈有〉。位于说具体位置，“很多大学”这类存在要用有。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27715830-11a4-4473-84d5-18c38b0de7ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13353, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们的银行位于在火车站旁边。", "corrected_sentence": "我们的银行位于火车站旁边。", "error_description": "错误：“位于”后面又加了“在”，写成“位于在”。“位于”本身已表示处在某处，不能再加“在”，应去掉“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27715830-11a4-4473-84d5-18c38b0de7ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13353, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "书店位于了火车站对面。", "corrected_sentence": "书店位于火车站对面。", "error_description": "错误：“位于”后面多加了“了”，写成“位于了”。“位于”表示处在某处，是静态动词，不能加“了”，应去掉“了”，正确的是“书店位于火车站对面”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27715830-11a4-4473-84d5-18c38b0de7ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13354, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "强大", "is_correct": true, "explanation": "“强大”与“薄弱”意思相反，指力量足够，是反义词。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”形容明白、不模糊，与“薄弱”没有反义关系。"}, {"text": "高兴", "is_correct": false, "explanation": "“高兴”形容心情愉快，与“薄弱”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”形容没有声音或不吵闹，与“薄弱”没有反义关系。"}], "correct_answer": "强大", "explanations": {"强大": "“强大”与“薄弱”意思相反，指力量足够，是反义词。", "清楚": "“清楚”形容明白、不模糊，与“薄弱”没有反义关系。", "高兴": "“高兴”形容心情愉快，与“薄弱”没有反义关系。", "安静": "“安静”形容没有声音或不吵闹，与“薄弱”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27715830-11a4-4473-84d5-18c38b0de7ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13354, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "雄厚", "is_correct": true, "explanation": "“雄厚”与“薄弱”意思相反，指力量充足、基础扎实，是反义词。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”形容光线充足，与“薄弱”没有反义关系。"}, {"text": "温暖", "is_correct": false, "explanation": "“温暖”形容温度或感觉，与“薄弱”没有反义关系。"}, {"text": "宽阔", "is_correct": false, "explanation": "“宽阔”形容面积大，与“薄弱”没有反义关系。"}], "correct_answer": "雄厚", "explanations": {"雄厚": "“雄厚”与“薄弱”意思相反，指力量充足、基础扎实，是反义词。", "明亮": "“明亮”形容光线充足，与“薄弱”没有反义关系。", "温暖": "“温暖”形容温度或感觉，与“薄弱”没有反义关系。", "宽阔": "“宽阔”形容面积大，与“薄弱”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27715830-11a4-4473-84d5-18c38b0de7ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13354, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "力量、基础或条件不足，不够强。", "primary_collocate": null, "pronunciation": "báo ruò", "ipa": "pɑʊ˧˥ ʐwɔ˥˩", "syllable_count": 2, "sentences": [{"text": "更为严峻的是，全球许多纺织生产基地位于环境监管薄弱的发展中国家，其废水处理能力严重滞后。", "target_word": "薄弱", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个队的防守很薄弱，常常丢球。", "target_word": "薄弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的基础薄弱，所以要多练习。", "target_word": "薄弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农村的医疗条件还很薄弱。", "target_word": "薄弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个学校的师资力量比较薄弱。", "target_word": "薄弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的数学比较薄弱，每天都要做题。", "target_word": "薄弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司的管理很薄弱，经常出问题。", "target_word": "薄弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的法律意识太薄弱了，才会上当。", "target_word": "薄弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人的体质薄弱，天冷时容易生病。", "target_word": "薄弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家小公司实力薄弱，不敢接大项目。", "target_word": "薄弱", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "薄弱：力量、基础或条件不足，不够强", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eafd00e7-0c74-47ca-a160-5befa431b7b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13354, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "薄弱", "is_correct": true, "explanation": "“薄弱”表示力量或条件不足，与“环境监管不力”的语境相符。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：“明亮”形容光线或颜色，不能修饰“监管”。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：“高兴”形容人的心情，不能用来形容“监管”。"}, {"text": "甜蜜", "is_correct": false, "explanation": "搭配：“甜蜜”形容感情或滋味，不能修饰“监管”。"}], "explanations": {"薄弱": "“薄弱”表示力量或条件不足，与“环境监管不力”的语境相符。", "明亮": "搭配：“明亮”形容光线或颜色，不能修饰“监管”。", "高兴": "语义：“高兴”形容人的心情，不能用来形容“监管”。", "甜蜜": "搭配：“甜蜜”形容感情或滋味，不能修饰“监管”。"}, "sentence_index": 0, "correct_answer": "薄弱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "高山上的空气很薄弱，人容易呼吸困难。", "explanation": "这里应该用〈稀薄〉。薄弱指力量或条件不足，空气少要用稀薄。"}, {"text": "这个地区的人口很薄弱，学校很少。", "explanation": "这里应该用〈稀少〉。薄弱指力量或条件不足，数量少要用稀少。"}, {"text": "这张桌子的颜色很薄弱。", "explanation": "这里应该用〈浅〉。薄弱指力量、结构或条件不足，说颜色淡要用浅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27715830-11a4-4473-84d5-18c38b0de7ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13354, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "薄弱", "is_correct": true, "explanation": "“薄弱”表示管理等方面不够强，与“经常出问题”的语境相符。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不能修饰“管理”。"}, {"text": "幽默", "is_correct": false, "explanation": "语义：“幽默”形容人的谈吐或风格，管理不能幽默。"}, {"text": "美丽", "is_correct": false, "explanation": "体貌：“美丽”形容外貌，不能用来形容“管理”。"}], "explanations": {"薄弱": "“薄弱”表示管理等方面不够强，与“经常出问题”的语境相符。", "清脆": "搭配：“清脆”形容声音，不能修饰“管理”。", "幽默": "语义：“幽默”形容人的谈吐或风格，管理不能幽默。", "美丽": "体貌：“美丽”形容外貌，不能用来形容“管理”。"}, "sentence_index": 6, "correct_answer": "薄弱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每月的工资很薄弱，只能勉强生活。", "explanation": "这里应该用〈微薄〉。薄弱指力量或条件不足，收入少要用微薄。"}, {"text": "夜空中的星星很薄弱。", "explanation": "这里应该用〈稀疏〉。薄弱指力量或条件不足，星星分散、数量少要用稀疏。"}, {"text": "这个房间的面积很薄弱。", "explanation": "这里应该用〈狭小〉。薄弱指力量、结构或条件不足，说面积小要用狭小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27715830-11a4-4473-84d5-18c38b0de7ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13354, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的英语基础是薄弱，需要多读书。", "corrected_sentence": "他的英语基础很薄弱，需要多读书。", "error_description": "错误：形容词“薄弱”作谓语时前面不加“是”，一般用程度副词“很”。应说“很薄弱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27715830-11a4-4473-84d5-18c38b0de7ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13354, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所学校的师资力量比较很薄弱。", "corrected_sentence": "这所学校的师资力量很薄弱。", "error_description": "错误：程度副词重复，“比较”和“很”都表示程度，只用一个即可。正确说法是“很薄弱”或“比较薄弱”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27715830-11a4-4473-84d5-18c38b0de7ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
