INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13355, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "通过物理、化学或生物方法去除污水中的污染物，使其达到排放标准或可重复利用的过程。", "primary_collocate": null, "pronunciation": "fèi shuǐ chǔ lǐ", "ipa": "feɪ˥˩ ʂweɪ˨˩˦ ʈʂʰu˨˩˦ li˨˩˦", "syllable_count": 4, "sentences": [{"text": "更为严峻的是，全球许多纺织生产基地位于环境监管薄弱的发展中国家，其废水处理能力严重滞后。", "target_word": "废水处理", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家工厂的废水处理做得很好。", "target_word": "废水处理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "废水处理需要很多钱和技术。", "target_word": "废水处理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人们正在学习废水处理的方法。", "target_word": "废水处理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的废水处理可以保护河水。", "target_word": "废水处理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小镇的废水处理很差，河水很脏。", "target_word": "废水处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在大学学习废水处理，毕业后进了环保公司。", "target_word": "废水处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过废水处理，水可以重新用来浇花。", "target_word": "废水处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "企业必须做好废水处理，才能排放。", "target_word": "废水处理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "废水处理不好，鱼就会死。", "target_word": "废水处理", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "废水处理：去除污水污染物使其达标或再利用的过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eafd00e7-0c74-47ca-a160-5befa431b7b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13355, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "废水处理", "is_correct": true, "explanation": "正确。“其___能力”需要表示污水净化工作的名词，“废水处理能力”即净化污水的能力，与“严重滞后”相符。"}, {"text": "污泥", "is_correct": false, "explanation": "搭配：“污泥”是处理后的沉渣，属于物质，不能说“污泥能力”。"}, {"text": "纺织品", "is_correct": false, "explanation": "搭配：“纺织品”是产品，不能与“能力”搭配，“其纺织品能力”不成立。"}, {"text": "薪资", "is_correct": false, "explanation": "语义：句中讲的是环境监管与污水治理，“薪资”与此无关，“其薪资能力”说不通。"}], "explanations": {"废水处理": "正确。“其___能力”需要表示污水净化工作的名词，“废水处理能力”即净化污水的能力，与“严重滞后”相符。", "污泥": "搭配：“污泥”是处理后的沉渣，属于物质，不能说“污泥能力”。", "纺织品": "搭配：“纺织品”是产品，不能与“能力”搭配，“其纺织品能力”不成立。", "薪资": "语义：句中讲的是环境监管与污水治理，“薪资”与此无关，“其薪资能力”说不通。"}, "sentence_index": 0, "correct_answer": "废水处理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生正在为病人进行废水处理。", "explanation": "这里应该用〈治疗〉。“废水处理”只指净化污水，对象是污水；给病人诊治应说治疗，不能把人当作处理对象。"}, {"text": "我们家的自来水要先经过废水处理才能喝。", "explanation": "这里应该用〈净化〉。“废水处理”只针对污水；自来水是饮用水，要说净化或消毒，不能用这个词。"}, {"text": "这些旧报纸要先经过废水处理，然后才能回收。", "explanation": "这里应该用〈分类〉。“废水处理”只针对污水，旧报纸是固体废物，回收前要分类，不能说废水处理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27715830-11a4-4473-84d5-18c38b0de7ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13355, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "废水处理", "is_correct": true, "explanation": "正确。“学习废水处理”指学习污水净化的专业，与“毕业后进了环保公司”相符。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：“烹饪”与句末“环保公司”的工作领域没有关联，句意不通。"}, {"text": "实验室", "is_correct": false, "explanation": "配价：“学习”要求可学的内容作宾语，“实验室”是场所，不能作“学习”的对象。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“学习空气”不成立，“学习”的对象是知识或技能，“空气”是物质。"}], "explanations": {"废水处理": "正确。“学习废水处理”指学习污水净化的专业，与“毕业后进了环保公司”相符。", "烹饪": "语义：“烹饪”与句末“环保公司”的工作领域没有关联，句意不通。", "实验室": "配价：“学习”要求可学的内容作宾语，“实验室”是场所，不能作“学习”的对象。", "空气": "搭配：“学习空气”不成立，“学习”的对象是知识或技能，“空气”是物质。"}, "sentence_index": 6, "correct_answer": "废水处理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的自行车坏了，需要废水处理。", "explanation": "这里应该用〈修理〉。“废水处理”指污水净化，自行车坏了应说修理，不能用这个词。"}, {"text": "他每天都去理发店做废水处理。", "explanation": "这里应该用〈洗头〉。“废水处理”专指净化污水，理发店做的是洗头、剪发等服务，不能用这个词。"}, {"text": "这件新毛衣要先经过废水处理才能穿。", "explanation": "这里应该用〈清洗〉。“废水处理”只针对污水；衣物要说清洗，不能用这个词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27715830-11a4-4473-84d5-18c38b0de7ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13355, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们厂的废水处理做很好，河水很干净。", "corrected_sentence": "我们厂的废水处理做得很好，河水很干净。", "error_description": "补语错误：「做很好」应为「做得很好」。动词与程度补语之间要用“得”连接；错误处在“废水处理”所在的补语结构，漏掉了“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27715830-11a4-4473-84d5-18c38b0de7ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13355, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们参观了一家废水处理，学到了很多知识。", "corrected_sentence": "我们参观了一家废水处理厂，学到了很多知识。", "error_description": "中心语缺失：「一家废水处理」漏掉了中心语，应为「一家废水处理厂」。“废水处理”修饰名词“厂”，不能省去“厂”直接用来计量“家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27715830-11a4-4473-84d5-18c38b0de7ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13356, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "超前", "is_correct": true, "explanation": "正确。“超前”与“滞后”相对，指事物发展快于正常或预期的时间。"}, {"text": "保持", "is_correct": false, "explanation": "保持：表示维持原来的状态，与“滞后”的意思没有对立关系。"}, {"text": "参与", "is_correct": false, "explanation": "参与：表示加入某项活动，与“滞后”没有反义关系。"}, {"text": "承认", "is_correct": false, "explanation": "承认：表示认可某个事实，与“滞后”没有反义关系。"}], "correct_answer": "超前", "explanations": {"超前": "正确。“超前”与“滞后”相对，指事物发展快于正常或预期的时间。", "保持": "保持：表示维持原来的状态，与“滞后”的意思没有对立关系。", "参与": "参与：表示加入某项活动，与“滞后”没有反义关系。", "承认": "承认：表示认可某个事实，与“滞后”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95f2ec94-b73e-4562-8520-3e1028070cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13356, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "超前", "is_correct": true, "explanation": "正确。“超前”与“滞后”相对，指供应或发展快于正常时间。"}, {"text": "思考", "is_correct": false, "explanation": "思考：表示用脑子考虑问题，与“滞后”没有反义关系。"}, {"text": "收藏", "is_correct": false, "explanation": "收藏：表示妥善保存起来，与“滞后”没有反义关系。"}, {"text": "传播", "is_correct": false, "explanation": "传播：表示扩散开来，与“滞后”不是反义词。"}], "correct_answer": "超前", "explanations": {"超前": "正确。“超前”与“滞后”相对，指供应或发展快于正常时间。", "思考": "思考：表示用脑子考虑问题，与“滞后”没有反义关系。", "收藏": "收藏：表示妥善保存起来，与“滞后”没有反义关系。", "传播": "传播：表示扩散开来，与“滞后”不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95f2ec94-b73e-4562-8520-3e1028070cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13356, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "指事物发展或行动比通常或预期的时间晚。", "primary_collocate": null, "pronunciation": "zhì hòu", "ipa": "ʈʂʅ⁵¹ xoʊ̯⁵¹", "syllable_count": 2, "sentences": [{"text": "更为严峻的是，全球许多纺织生产基地位于环境监管薄弱的发展中国家，其废水处理能力严重滞后。", "target_word": "滞后", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个城市的交通建设比人口增长滞后。", "target_word": "滞后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的工作进度明显滞后，必须加快。", "target_word": "滞后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律的修订常常滞后于社会的变化。", "target_word": "滞后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农村的网络建设还比较滞后。", "target_word": "滞后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为下雨，工程比计划滞后了一个月。", "target_word": "滞后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工资的增长速度滞后于物价上涨。", "target_word": "滞后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂的设备太旧，技术已经滞后了。", "target_word": "滞后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的教学方法滞后，学生不感兴趣。", "target_word": "滞后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药品供应滞后，病人只好等着。", "target_word": "滞后", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "滞后了", "label": "体标"}, {"form": "滯後", "label": "繁体"}], "register": "书面", "sense_fingerprint": "事物发展或行动比预期或正常的时间晚", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64cd21cc-e9a4-402b-8f56-12dc24689644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13356, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "滞后", "is_correct": true, "explanation": "正确。滞后（zhì hòu）指事物发展或行动比正常或预期的时间晚。"}, {"text": "之后", "is_correct": false, "explanation": "zhī（第一声）与 zhì（第四声）声调不同，“之后”意思是某件事以后。"}, {"text": "事后", "is_correct": false, "explanation": "shì 与 zhì 声母不同（sh 与 zh），“事后”意思是事情发生以后。"}, {"text": "日后", "is_correct": false, "explanation": "rì 与 zhì 声母不同（r 与 zh），“日后”意思是将来的某个时候。"}], "explanations": {"滞后": "正确。滞后（zhì hòu）指事物发展或行动比正常或预期的时间晚。", "之后": "zhī（第一声）与 zhì（第四声）声调不同，“之后”意思是某件事以后。", "事后": "shì 与 zhì 声母不同（sh 与 zh），“事后”意思是事情发生以后。", "日后": "rì 与 zhì 声母不同（r 与 zh），“日后”意思是将来的某个时候。"}, "sentence_index": null, "correct_answer": "滞后"}, "level_3": {"options": [{"text": "滞后", "is_correct": true, "explanation": "正确。“严重滞后”说明能力远低于要求，符合句意。"}, {"text": "提高", "is_correct": false, "explanation": "语义：“严重”说明状况很糟，“提高”表示水平上升，两者在句中矛盾。"}, {"text": "超过", "is_correct": false, "explanation": "配价：“超过”后面要带比较对象，句中缺少成分，不能这样用。"}, {"text": "增长", "is_correct": false, "explanation": "语义：“增长”表示数量上升，与“严重”描述的负面状况不相符。"}], "explanations": {"滞后": "正确。“严重滞后”说明能力远低于要求，符合句意。", "提高": "语义：“严重”说明状况很糟，“提高”表示水平上升，两者在句中矛盾。", "超过": "配价：“超过”后面要带比较对象，句中缺少成分，不能这样用。", "增长": "语义：“增长”表示数量上升，与“严重”描述的负面状况不相符。"}, "sentence_index": 0, "correct_answer": "滞后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他做作业总是滞后。", "explanation": "这里应该用〈拖延〉。滞后描述事情的进程比正常时间慢，不用来形容人做事拖拉。"}, {"text": "他们队在比赛中滞后了三分。", "explanation": "这里应该用〈落后〉。滞后用于发展或进度赶不上，不用于比赛中的分数差距。"}, {"text": "这把椅子滞后，坐起来很不舒服。", "explanation": "这里应该用〈松动〉。滞后指发展或行动比预期慢，不用来形容椅子的状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95f2ec94-b73e-4562-8520-3e1028070cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13356, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "滞后", "is_correct": true, "explanation": "正确。“滞后于物价上涨”说明工资增长慢于物价，符合句意。"}, {"text": "滞留", "is_correct": false, "explanation": "语义：“滞留”表示停在某处不走，不能描述增长速度与物价的比较关系。"}, {"text": "隐藏", "is_correct": false, "explanation": "语义：“隐藏”与增长速度、物价的比较关系意思不通。"}, {"text": "竞争", "is_correct": false, "explanation": "配价：“竞争”要用“与”引出对象，不能说“竞争于物价上涨”。"}], "explanations": {"滞后": "正确。“滞后于物价上涨”说明工资增长慢于物价，符合句意。", "滞留": "语义：“滞留”表示停在某处不走，不能描述增长速度与物价的比较关系。", "隐藏": "语义：“隐藏”与增长速度、物价的比较关系意思不通。", "竞争": "配价：“竞争”要用“与”引出对象，不能说“竞争于物价上涨”。"}, "sentence_index": 6, "correct_answer": "滞后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "河水滞后在山谷里。", "explanation": "这里应该用〈滞留〉。滞后指事物的进程比预期慢，不用来说水停在某处。"}, {"text": "他总是走在队伍后面，滞后得很远。", "explanation": "这里应该用〈靠后〉。滞后说的是进程比正常时间慢，不用于描述人在队伍中的位置。"}, {"text": "这件衣服的颜色滞后了。", "explanation": "这里应该用〈变深〉或〈变淡〉。滞后用于发展和进程，颜色没有“滞后”的说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95f2ec94-b73e-4562-8520-3e1028070cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13356, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新系统的开发进度滞后在计划。", "corrected_sentence": "新系统的开发进度滞后于计划。", "error_description": "错误：“滞后在计划”用错了介词。正确：“滞后于计划”。“滞后”引出比较对象时要用“于”，不能用“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95f2ec94-b73e-4562-8520-3e1028070cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13356, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个项目滞后了了，需要加人。", "corrected_sentence": "这个项目滞后了，需要加人。", "error_description": "错误：“滞后”后面的“了”重复了。正确：“滞后了”。“了”只用一次，表示变化已经发生。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95f2ec94-b73e-4562-8520-3e1028070cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
