INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13357, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "重金属指密度较大的金属元素，如铅、汞、镉等，通常具有毒性，会污染环境并危害健康。", "primary_collocate": null, "pronunciation": "zhòng jīn shǔ", "ipa": "ʈʂʊŋ˥˩ tɕin˥ ʂu˨˩˦", "syllable_count": 3, "sentences": [{"text": "含有重金属、偶氮染料及有毒化学助剂的工业废水未经充分净化即排入河流与地下水系统，导致水体污染长期化、隐蔽化，对生物多样性及当地居民健康构成深远威胁。", "target_word": "重金属", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "铅和汞都是重金属。", "target_word": "重金属", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "河水里的重金属对身体不好。", "target_word": "重金属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条河的鱼含有重金属。", "target_word": "重金属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂排出的水里有重金属。", "target_word": "重金属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子不能吃含重金属的东西。", "target_word": "重金属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生检查了他血液中的重金属。", "target_word": "重金属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "重金属会污染土壤和水。", "target_word": "重金属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电池里有重金属，不能乱扔。", "target_word": "重金属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民担心田里的重金属太多。", "target_word": "重金属", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "重金属：铅、汞、镉等密度大、有毒的金属元素", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eafd00e7-0c74-47ca-a160-5befa431b7b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13357, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重金属", "is_correct": true, "explanation": "正确。“含有重金属、偶氮染料及有毒化学助剂”列举工业废水中的有毒污染物，“重金属”是其中一类。"}, {"text": "维生素", "is_correct": false, "explanation": "语义：维生素是营养素，不是工业废水中的有毒污染物，与“有毒化学助剂”并列不合句意。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“含有”的宾语应是物质，“时间”不能被“含有”，搭配不成立。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：“歌曲”不是废水成分，与其他污染物并列，句意不通。"}], "explanations": {"重金属": "正确。“含有重金属、偶氮染料及有毒化学助剂”列举工业废水中的有毒污染物，“重金属”是其中一类。", "维生素": "语义：维生素是营养素，不是工业废水中的有毒污染物，与“有毒化学助剂”并列不合句意。", "时间": "搭配：“含有”的宾语应是物质，“时间”不能被“含有”，搭配不成立。", "歌曲": "语义：“歌曲”不是废水成分，与其他污染物并列，句意不通。"}, "sentence_index": 0, "correct_answer": "重金属"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "铝是重金属，很适合用来做飞机。", "explanation": "这里应该用〈轻金属〉。铝密度小，属于轻金属；重金属指密度大、常有毒性的金属，铝不属于此类。"}, {"text": "这块石头很重，所以它是重金属。", "explanation": "石头不是金属元素，“重”只说明分量大，不能因此说它是重金属。"}, {"text": "镁是重金属，拿在手里很轻。", "explanation": "这里应该用〈轻金属〉。镁密度小，属于轻金属；重金属指密度大、常有毒性的金属，镁不属于此类。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27715830-11a4-4473-84d5-18c38b0de7ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13357, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重金属", "is_correct": true, "explanation": "正确。“血液中的重金属”指血液里积累的铅、汞等金属元素，是体检会检查的项目。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：“感冒”是疾病，不是血液中的成分，不能作“检查”的对象。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”是抽象的人格特征，不存在于血液中，句意不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是气象现象，不存在于血液中，医生也不能检查血液里的天气。"}], "explanations": {"重金属": "正确。“血液中的重金属”指血液里积累的铅、汞等金属元素，是体检会检查的项目。", "感冒": "语义：“感冒”是疾病，不是血液中的成分，不能作“检查”的对象。", "性格": "语义：“性格”是抽象的人格特征，不存在于血液中，句意不通。", "天气": "语义：“天气”是气象现象，不存在于血液中，医生也不能检查血液里的天气。"}, "sentence_index": 6, "correct_answer": "重金属"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这箱苹果的重金属是十公斤。", "explanation": "这里应该用〈重量〉。“重金属”指金属元素，表示质量要用“重量”。"}, {"text": "医生让病人每天吃一些重金属来补身体。", "explanation": "这里应该用〈营养素〉。重金属有毒，不是补身体的营养素，这里的用法错误。"}, {"text": "这种重金属可以用来洗澡。", "explanation": "这里应该用〈沐浴露〉。重金属有毒，不能当作沐浴露这类洗浴用品使用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27715830-11a4-4473-84d5-18c38b0de7ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13357, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "铅、汞、镉是三个重金属。", "corrected_sentence": "铅、汞、镉是三种重金属。", "error_description": "量词错误：「三个重金属」应为「三种重金属」。重金属是一类金属元素，清点种类要用“种”，不用通用量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27715830-11a4-4473-84d5-18c38b0de7ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13357, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条河里有一个重金属，污染很严重。", "corrected_sentence": "这条河里有一种重金属，污染很严重。", "error_description": "量词错误：「一个重金属」应为「一种重金属」。重金属是一类金属元素，计量类别要用“种”，不能用通用量词“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27715830-11a4-4473-84d5-18c38b0de7ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
