INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13358, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "分子中含有偶氮基（-N=N-）的合成染料，颜色鲜艳，广泛应用于纺织、印刷等行业。", "primary_collocate": null, "pronunciation": "ǒu dàn rǎn liào", "ipa": "oʊ̯²¹⁴ tan⁵¹ ʐan²¹⁴ liɑʊ̯⁵¹", "syllable_count": 4, "sentences": [{"text": "含有重金属、偶氮染料及有毒化学助剂的工业废水未经充分净化即排入河流与地下水系统，导致水体污染长期化、隐蔽化，对生物多样性及当地居民健康构成深远威胁。", "target_word": "偶氮染料", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种偶氮染料能把布染成红色。", "target_word": "偶氮染料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "偶氮染料的颜色很鲜艳。", "target_word": "偶氮染料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人在工厂里用偶氮染料染布。", "target_word": "偶氮染料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些偶氮染料对人体有害。", "target_word": "偶氮染料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂买了一批偶氮染料。", "target_word": "偶氮染料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "偶氮染料便宜，所以很多工厂都在用。", "target_word": "偶氮染料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "欧洲规定衣服里不能有某些偶氮染料。", "target_word": "偶氮染料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "偶氮染料染过的牛仔裤颜色很深。", "target_word": "偶氮染料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室正在检查布里有没有偶氮染料。", "target_word": "偶氮染料", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "批", "label": "量词"}], "register": "专业", "sense_fingerprint": "含偶氮基、用于纺织印刷的合成染料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64cd21cc-e9a4-402b-8f56-12dc24689644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13358, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "偶氮染料", "is_correct": true, "explanation": "正确。工业废水中可能含有偶氮染料这类化学污染物，与前文“重金属”并列，符合句意。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：花朵不是污染物，不能和“重金属”并列作为废水中的有害成分。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：音乐不是化学物质，句中把它当作废水成分意思不通。"}, {"text": "欢乐", "is_correct": false, "explanation": "搭配：“含有”后面一般接物质成分，不能说“含有欢乐”。"}], "explanations": {"偶氮染料": "正确。工业废水中可能含有偶氮染料这类化学污染物，与前文“重金属”并列，符合句意。", "花朵": "语义：花朵不是污染物，不能和“重金属”并列作为废水中的有害成分。", "音乐": "语义：音乐不是化学物质，句中把它当作废水成分意思不通。", "欢乐": "搭配：“含有”后面一般接物质成分，不能说“含有欢乐”。"}, "sentence_index": 0, "correct_answer": "偶氮染料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工厂用偶氮染料漂白布料。", "explanation": "这里应该用〈漂白剂〉。偶氮染料用于上色，不能用来漂白布料。"}, {"text": "工人用偶氮染料粘纸箱。", "explanation": "这里应该用〈胶水〉。偶氮染料用于染色，粘东西要用胶水。"}, {"text": "工人用偶氮染料擦窗户。", "explanation": "这里应该用〈清洁剂〉。偶氮染料用于上色，擦窗户要用清洁剂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95f2ec94-b73e-4562-8520-3e1028070cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13358, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偶氮染料", "is_correct": true, "explanation": "正确。偶氮染料价格低廉，所以很多工厂使用，符合句意。"}, {"text": "钻石", "is_correct": false, "explanation": "语义：钻石价格很高，与“便宜”的说法矛盾。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“便宜”用来说商品的价格，不说空气便宜。"}, {"text": "春天", "is_correct": false, "explanation": "语义：春天不是商品，不能说它便宜。"}], "explanations": {"偶氮染料": "正确。偶氮染料价格低廉，所以很多工厂使用，符合句意。", "钻石": "语义：钻石价格很高，与“便宜”的说法矛盾。", "空气": "搭配：“便宜”用来说商品的价格，不说空气便宜。", "春天": "语义：春天不是商品，不能说它便宜。"}, "sentence_index": 6, "correct_answer": "偶氮染料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用偶氮染料煮汤，味道很好。", "explanation": "这里应该用〈调料〉。偶氮染料是染色用的化学品，不能用来煮汤，调味要用调料。"}, {"text": "医生给病人打了一针偶氮染料。", "explanation": "这里应该用〈药剂〉。偶氮染料是染色用的化学品，不能用来打针，打针要用药剂。"}, {"text": "工人用偶氮染料盖了一座房子。", "explanation": "这里应该用〈水泥〉。偶氮染料用于染色，盖房子要用水泥、砖瓦等建材。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95f2ec94-b73e-4562-8520-3e1028070cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13358, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂昨天进了一本偶氮染料。", "corrected_sentence": "工厂昨天进了一桶偶氮染料。", "error_description": "错误：量词“本”用错了。正确：“一桶偶氮染料”。“本”用于书籍，偶氮染料这类物质要用“桶”“袋”“批”等计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95f2ec94-b73e-4562-8520-3e1028070cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13358, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂把偶氮染料们倒入河里了。", "corrected_sentence": "工厂把偶氮染料倒入河里了。", "error_description": "错误：“偶氮染料”后面加了“们”。正确：“偶氮染料”。“们”一般用于指人的名词，染料这类物质名词后面不能加。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95f2ec94-b73e-4562-8520-3e1028070cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13359, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无毒", "is_correct": true, "explanation": "与“有毒”相对，指不含对生命有害的物质，是这一义项的反义词。"}, {"text": "柔软", "is_correct": false, "explanation": "“柔软”与“坚硬”相对，与“有毒”的含义无反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”与“昏暗”相对，与“有毒”无反义关系。"}, {"text": "轻松", "is_correct": false, "explanation": "“轻松”与“沉重”相对，与“有毒”无反义关系。"}], "correct_answer": "无毒", "explanations": {"无毒": "与“有毒”相对，指不含对生命有害的物质，是这一义项的反义词。", "柔软": "“柔软”与“坚硬”相对，与“有毒”的含义无反义关系。", "明亮": "“明亮”与“昏暗”相对，与“有毒”无反义关系。", "轻松": "“轻松”与“沉重”相对，与“有毒”无反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95f2ec94-b73e-4562-8520-3e1028070cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13359, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无毒", "is_correct": true, "explanation": "与“有毒”相对，指不含对生命有害的物质，是这一义项的反义词。"}, {"text": "整齐", "is_correct": false, "explanation": "“整齐”与“杂乱”相对，与“有毒”不构成反义。"}, {"text": "丰富", "is_correct": false, "explanation": "“丰富”与“贫乏”相对，与“有毒”不构成反义。"}, {"text": "高大", "is_correct": false, "explanation": "“高大”与“矮小”相对，与“有毒”不构成反义。"}], "correct_answer": "无毒", "explanations": {"无毒": "与“有毒”相对，指不含对生命有害的物质，是这一义项的反义词。", "整齐": "“整齐”与“杂乱”相对，与“有毒”不构成反义。", "丰富": "“丰富”与“贫乏”相对，与“有毒”不构成反义。", "高大": "“高大”与“矮小”相对，与“有毒”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95f2ec94-b73e-4562-8520-3e1028070cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13359, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指含有对生命体有害的物质，可能引起中毒。", "primary_collocate": null, "pronunciation": "yǒu dú", "ipa": "joʊ̯²¹⁴ tu³⁵", "syllable_count": 2, "sentences": [{"text": "含有重金属、偶氮染料及有毒化学助剂的工业废水未经充分净化即排入河流与地下水系统，导致水体污染长期化、隐蔽化，对生物多样性及当地居民健康构成深远威胁。", "target_word": "有毒", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种蘑菇有毒，千万别吃。", "target_word": "有毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂排出的气体有毒。", "target_word": "有毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水里有毒的东西越来越多。", "target_word": "有毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说这种植物的叶子有毒。", "target_word": "有毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有毒的废水流进了小河。", "target_word": "有毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些蛇有毒，有些蛇无毒。", "target_word": "有毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条鱼有毒，厨师不敢做。", "target_word": "有毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子不小心喝了有毒的水。", "target_word": "有毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室里放着很多有毒的药品。", "target_word": "有毒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "有毒物质", "label": "复合"}, {"form": "有毒气体", "label": "复合"}], "register": "中性", "sense_fingerprint": "含有对生命体有害、可能致人中毒的物质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64cd21cc-e9a4-402b-8f56-12dc24689644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13359, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有毒", "is_correct": true, "explanation": "原句说工业废水含有有害的化学助剂，“有毒化学助剂”与之相符。"}, {"text": "无毒", "is_correct": false, "explanation": "语义：说“无毒化学助剂”，就与后文“导致水体污染、威胁健康”矛盾。"}, {"text": "有益", "is_correct": false, "explanation": "语义：“有益化学助剂”不会导致污染、威胁健康，与后文矛盾。"}, {"text": "纯净", "is_correct": false, "explanation": "搭配：“纯净”多用于水、空气，不说“纯净化学助剂”。"}], "explanations": {"有毒": "原句说工业废水含有有害的化学助剂，“有毒化学助剂”与之相符。", "无毒": "语义：说“无毒化学助剂”，就与后文“导致水体污染、威胁健康”矛盾。", "有益": "语义：“有益化学助剂”不会导致污染、威胁健康，与后文矛盾。", "纯净": "搭配：“纯净”多用于水、空气，不说“纯净化学助剂”。"}, "sentence_index": 0, "correct_answer": "有毒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这盏台灯很有毒，晚上照得人睡不着。", "explanation": "这里应该用〈刺眼〉。有毒指含毒素，灯光太亮要说刺眼，不是毒性。"}, {"text": "这条小路有毒，雨后很滑，大家最好别走。", "explanation": "这里应该用〈湿滑〉。有毒指含毒素，路面状况要说湿滑。"}, {"text": "他喝了不干净的水，有毒住院了。", "explanation": "这里应该用〈中毒〉。有毒形容物质，说人误饮误食后受害要用中毒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95f2ec94-b73e-4562-8520-3e1028070cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13359, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有毒", "is_correct": true, "explanation": "前半句说有的蛇有毒，后半句说有的蛇无毒，两者相对，“有毒”正确。"}, {"text": "有趣", "is_correct": false, "explanation": "语义：“有趣”与“无毒”不构成对比，前后分句说不通。"}, {"text": "多毛", "is_correct": false, "explanation": "体貌：蛇身上没有毛，不能说“多毛”。"}, {"text": "歹毒", "is_correct": false, "explanation": "搭配：“歹毒”多形容人心狠，不用来说蛇的毒性。"}], "explanations": {"有毒": "前半句说有的蛇有毒，后半句说有的蛇无毒，两者相对，“有毒”正确。", "有趣": "语义：“有趣”与“无毒”不构成对比，前后分句说不通。", "多毛": "体貌：蛇身上没有毛，不能说“多毛”。", "歹毒": "搭配：“歹毒”多形容人心狠，不用来说蛇的毒性。"}, "sentence_index": 6, "correct_answer": "有毒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他咳了好几天，医生说他有毒了。", "explanation": "这里应该用〈有病〉。有毒用来形容物质，说人身体不好要用有病或生病。"}, {"text": "这把刀有毒，切菜特别快。", "explanation": "这里应该用〈锋利〉。有毒指含毒素，刀切得快要说锋利。"}, {"text": "这把椅子有毒，坐上去就摇。", "explanation": "这里应该用〈松动〉。有毒指含毒素，椅子不稳要说松动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95f2ec94-b73e-4562-8520-3e1028070cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13359, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这盆花的根不有毒，别让孩子碰。", "corrected_sentence": "这盆花的根有毒，别让孩子碰。", "error_description": "错误：“不有毒”。正确：“有毒”（肯定）或“没有毒”（否定）。“有”的否定要用“没有”，不能在“有”前面加“不”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95f2ec94-b73e-4562-8520-3e1028070cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13359, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种蘑菇有毒，他吃了以后有毒住院了。", "corrected_sentence": "这种蘑菇有毒，他吃了以后中毒住院了。", "error_description": "错误：“有毒住院”。正确：“中毒住院”。“有毒”只用来形容物质，人误食后受害要说“中毒”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95f2ec94-b73e-4562-8520-3e1028070cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
