INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13361, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95f2ec94-b73e-4562-8520-3e1028070cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13361, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "工业生产过程中产生的废弃液体，通常含有有害物质。", "primary_collocate": null, "pronunciation": "gōng yè fèi shuǐ", "ipa": "kʊŋ˥ iɛ˥˩ feɪ˥˩ ʂueɪ˨˩˦", "syllable_count": 4, "sentences": [{"text": "含有重金属、偶氮染料及有毒化学助剂的工业废水未经充分净化即排入河流与地下水系统，导致水体污染长期化、隐蔽化，对生物多样性及当地居民健康构成深远威胁。", "target_word": "工业废水", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "工业废水不能直接排进河里。", "target_word": "工业废水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂建了处理工业废水的设备。", "target_word": "工业废水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业废水里常常有很多有害物质。", "target_word": "工业废水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人正在检查工业废水的水质。", "target_word": "工业废水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水变黑了，因为有人排放工业废水。", "target_word": "工业废水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府要求工厂处理好工业废水再排放。", "target_word": "工业废水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业废水污染了附近的农田。", "target_word": "工业废水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用新技术净化工业废水。", "target_word": "工业废水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家旁边有个化工厂，常排出工业废水。", "target_word": "工业废水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "工业生产排出的含有害物质的废弃液体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64cd21cc-e9a4-402b-8f56-12dc24689644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13361, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工业废水", "is_correct": true, "explanation": "正确。工业废水是工业生产排出的废液，与句中“含有重金属、有毒化学助剂，排入河流”的描述相符。"}, {"text": "自来水", "is_correct": false, "explanation": "语义：自来水是经过净化、可以饮用的水，与句中“未经充分净化”“含有重金属”的描述正好相反。"}, {"text": "工业废气", "is_correct": false, "explanation": "搭配：“排入河流与地下水系统”针对液体，废气不能排入水体，这个搭配不成立。"}, {"text": "饮用水", "is_correct": false, "explanation": "语义：饮用水应当干净安全，与句中“含有重金属、偶氮染料”的污染描述矛盾。"}], "explanations": {"工业废水": "正确。工业废水是工业生产排出的废液，与句中“含有重金属、有毒化学助剂，排入河流”的描述相符。", "自来水": "语义：自来水是经过净化、可以饮用的水，与句中“未经充分净化”“含有重金属”的描述正好相反。", "工业废气": "搭配：“排入河流与地下水系统”针对液体，废气不能排入水体，这个搭配不成立。", "饮用水": "语义：饮用水应当干净安全，与句中“含有重金属、偶氮染料”的污染描述矛盾。"}, "sentence_index": 0, "correct_answer": "工业废水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工厂每天需要大量工业废水。", "explanation": "这里应该用〈工业用水〉。工厂“需要”的是可以投入生产使用的水，工业废水是生产后排出的废液，不能作为需要的对象。"}, {"text": "城市每天要为居民供应大量工业废水。", "explanation": "这里应该用〈饮用水〉。“供应”的对象是可以使用的水，工业废水是排出的脏水，不能供应给居民。"}, {"text": "妈妈每天用工业废水煮饭。", "explanation": "这里应该用〈自来水〉。煮饭要用干净的水，工业废水含有害物质，不能用来做饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95f2ec94-b73e-4562-8520-3e1028070cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13361, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工业废水", "is_correct": true, "explanation": "正确。句意是政府要求工厂先把废水处理好再排放，只有工业废水符合这一语境。"}, {"text": "原材料", "is_correct": false, "explanation": "语义：原材料是生产的投入品，不需要“处理好再排放”，与句意冲突。"}, {"text": "煤炭", "is_correct": false, "explanation": "搭配：“排放”搭配的是废水、废气等废弃物，不能说“处理好煤炭再排放”。"}, {"text": "食品", "is_correct": false, "explanation": "语义：食品是供人食用的东西，不是需要处理后排放的废物，语义冲突。"}], "explanations": {"工业废水": "正确。句意是政府要求工厂先把废水处理好再排放，只有工业废水符合这一语境。", "原材料": "语义：原材料是生产的投入品，不需要“处理好再排放”，与句意冲突。", "煤炭": "搭配：“排放”搭配的是废水、废气等废弃物，不能说“处理好煤炭再排放”。", "食品": "语义：食品是供人食用的东西，不是需要处理后排放的废物，语义冲突。"}, "sentence_index": 6, "correct_answer": "工业废水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工厂每天要买大量工业废水。", "explanation": "这里应该用〈原料〉。工厂“买”的是生产用的原料，工业废水是要处理的排出物，不能买来用于生产。"}, {"text": "这家公司每天要向客户推销大量工业废水。", "explanation": "这里应该用〈产品〉。“推销”的对象是可以卖给客户的产品，工业废水是要处理的排出物，不能推销给客户。"}, {"text": "这家饭店每天要进货大量工业废水来做菜。", "explanation": "这里应该用〈食材〉。“进货做菜”用的是食材，工业废水是要处理的排出物，不能用来做菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95f2ec94-b73e-4562-8520-3e1028070cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13361, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂每天排放十个工业废水。", "corrected_sentence": "这家工厂每天排放十吨工业废水。", "error_description": "量词错误：工业废水是液体，按重量计量要用“吨”，不能用“个”。应说“十吨工业废水”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95f2ec94-b73e-4562-8520-3e1028070cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13361, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家化工厂每天排出三本工业废水。", "corrected_sentence": "这家化工厂每天排出三吨工业废水。", "error_description": "量词错误：“本”用于书本，工业废水是液体，应该用“吨”。应说“三吨工业废水”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95f2ec94-b73e-4562-8520-3e1028070cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
