INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13362, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "未曾经过；没有经过。", "primary_collocate": null, "pronunciation": "wèi jīng", "ipa": "ueɪ˥˩ tɕiŋ˥", "syllable_count": 2, "sentences": [{"text": "未经允许，不能进入实验室。", "target_word": "未经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "未经老师同意，学生不能离开教室。", "target_word": "未经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种水未经处理，不能直接喝。", "target_word": "未经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "未经检查的食品不能卖给客人。", "target_word": "未经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他未经考虑就答应了朋友。", "target_word": "未经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "未经本人同意，不得查看他的信。", "target_word": "未经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些药未经试验，不能给病人用。", "target_word": "未经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "未经父母允许，孩子不要出远门。", "target_word": "未经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂未经批准，不能建新的车间。", "target_word": "未经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章未经作者同意，不能转发。", "target_word": "未经", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "放在动词前，表示没有经过某个步骤或手续", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64cd21cc-e9a4-402b-8f56-12dc24689644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13362, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "未经", "is_correct": true, "explanation": "正确。“未经允许”表示没有取得许可，与“不能进入实验室”的限制相符。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示许可已取得，与后面“不能进入”的限制前提矛盾。"}, {"text": "总是", "is_correct": false, "explanation": "语义：“总是允许”与“不能进入”相矛盾，句意不通。"}, {"text": "立即", "is_correct": false, "explanation": "搭配：“立即允许”说明马上批准，与“未经允许就不能进入”的前提结构不搭配。"}], "explanations": {"未经": "正确。“未经允许”表示没有取得许可，与“不能进入实验室”的限制相符。", "已经": "语义：“已经”表示许可已取得，与后面“不能进入”的限制前提矛盾。", "总是": "语义：“总是允许”与“不能进入”相矛盾，句意不通。", "立即": "搭配：“立即允许”说明马上批准，与“未经允许就不能进入”的前提结构不搭配。"}, "sentence_index": 0, "correct_answer": "未经"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他未经去过北京。", "explanation": "这里应该用〈未曾〉。“未经”后接的是需要先经过的手续或同意，描述经历时应说“未曾去过”。"}, {"text": "我未经吃饭，就去上班了。", "explanation": "这里应该用〈还没〉。“未经”不用于日常行为的完成，表示还没做某事时应说“还没吃饭”。"}, {"text": "这位作家未经出版过三本书。", "explanation": "这里应该用〈已经〉。描述已经发生的经历要说“已经出版过”，“未经”不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95f2ec94-b73e-4562-8520-3e1028070cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13362, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "未经", "is_correct": true, "explanation": "正确。“未经试验”表示没有经过试验，与“不能给病人用”的结论相符。"}, {"text": "经常", "is_correct": false, "explanation": "语义：“经常试验”说明药常被试验，与“不能给病人用”的结论没有因果关系，句意不通。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”通常与否定词连用，“从来试验”不成立。"}, {"text": "顺便", "is_correct": false, "explanation": "语义：“顺便”表示附带去做，药品试验不能是附带的事，与句意冲突。"}], "explanations": {"未经": "正确。“未经试验”表示没有经过试验，与“不能给病人用”的结论相符。", "经常": "语义：“经常试验”说明药常被试验，与“不能给病人用”的结论没有因果关系，句意不通。", "从来": "搭配：“从来”通常与否定词连用，“从来试验”不成立。", "顺便": "语义：“顺便”表示附带去做，药品试验不能是附带的事，与句意冲突。"}, "sentence_index": 6, "correct_answer": "未经"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他未经按时到达公司。", "explanation": "这里应该用〈未能〉。“未经”表示没有经过某个手续，不能用来说明没有达到某个结果，应说“未能按时到达”。"}, {"text": "这次比赛他未经获胜。", "explanation": "这里应该用〈没有〉。获胜是结果，不是需要先经过的手续，应说“没有获胜”。"}, {"text": "他未经做过老师。", "explanation": "这里应该用〈曾经〉。描述经历时要说“曾经做过老师”，“未经”不能接已发生的经历。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95f2ec94-b73e-4562-8520-3e1028070cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13362, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "未经了许可，不能在这里停车。", "corrected_sentence": "未经许可，不能在这里停车。", "error_description": "体标错误：“未经”是副词，后面不能加“了”，应说“未经许可，不能在这里停车。”，不说“未经了许可”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95f2ec94-b73e-4562-8520-3e1028070cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13362, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他未经同意过就用了他的照片。", "corrected_sentence": "他未经同意就用了他的照片。", "error_description": "体标错误：“未经”后面接的动词“同意”不能带“过”，应说“未经同意就用了他的照片”，不说“未经同意过就用了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95f2ec94-b73e-4562-8520-3e1028070cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13363, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不足", "is_correct": true, "explanation": "不足：数量或条件达不到要求，与“充分”意思相反，是反义词。"}, {"text": "安静", "is_correct": false, "explanation": "安静：指没有声音或不吵闹，与“充分”没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚：指清晰明白，与“充分”没有反义关系。"}, {"text": "迅速", "is_correct": false, "explanation": "迅速：指速度快，与“充分”没有反义关系。"}], "correct_answer": "不足", "explanations": {"不足": "不足：数量或条件达不到要求，与“充分”意思相反，是反义词。", "安静": "安静：指没有声音或不吵闹，与“充分”没有反义关系。", "清楚": "清楚：指清晰明白，与“充分”没有反义关系。", "迅速": "迅速：指速度快，与“充分”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '108eb11f-d439-4516-a6e1-e06c1811a219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13363, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不足", "is_correct": true, "explanation": "不足：数量或条件达不到要求，与“充分”意思相反，是反义词。"}, {"text": "迟缓", "is_correct": false, "explanation": "迟缓：指动作或反应慢，与“充分”没有反义关系。"}, {"text": "高明", "is_correct": false, "explanation": "高明：指水平高、有见识，与“充分”没有反义关系。"}, {"text": "陌生", "is_correct": false, "explanation": "陌生：指不熟悉，与“充分”没有反义关系。"}], "correct_answer": "不足", "explanations": {"不足": "不足：数量或条件达不到要求，与“充分”意思相反，是反义词。", "迟缓": "迟缓：指动作或反应慢，与“充分”没有反义关系。", "高明": "高明：指水平高、有见识，与“充分”没有反义关系。", "陌生": "陌生：指不熟悉，与“充分”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '108eb11f-d439-4516-a6e1-e06c1811a219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13363, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "足够，完全满足需要或条件。", "primary_collocate": null, "pronunciation": "chōng fèn", "ipa": "tʂʰʊŋ˥ fən˥˩", "syllable_count": 2, "sentences": [{"text": "这次考试他准备得很充分。", "target_word": "充分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的理由不够充分，我不同意。", "target_word": "充分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给了我们充分的时间。", "target_word": "充分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们有充分的证据证明这件事。", "target_word": "充分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前，大家都做了充分的准备。", "target_word": "充分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法有充分的根据。", "target_word": "充分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的讨论很充分，大家都说了意见。", "target_word": "充分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们有充分的理由相信他会成功。", "target_word": "充分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "材料不充分，我们没法做决定。", "target_word": "充分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说你的检查还不够充分。", "target_word": "充分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "形容理由、证据、准备等足够，完全满足需要或条件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '515d04d6-e239-4e3c-b806-fb3653b41f00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13363, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "充分", "is_correct": true, "explanation": "充分（chōng fèn）指足够、完全满足需要或条件，是本题的目标词。"}, {"text": "春分", "is_correct": false, "explanation": "春分（chūn fēn）与充分（chōng fèn）第一音节韵母不同（ūn 对 ōng），第二音节声调也不同（fēn 对 fèn），意思是春天的节气，不是足够的意思。"}, {"text": "中分", "is_correct": false, "explanation": "中分（zhōng fèn）与充分（chōng fèn）声母不同（zh 对 ch），意思是头发从中间分开。"}, {"text": "冲犯", "is_correct": false, "explanation": "冲犯（chōng fàn）与充分（chōng fèn）第二音节韵母不同（a 对 en），声调相同，意思是冒犯。"}, {"text": "成分", "is_correct": false, "explanation": "成分（chéng fèn）与充分（chōng fèn）第一音节韵母与声调不同，意思是组成部分。"}, {"text": "冲锋", "is_correct": false, "explanation": "冲锋（chōng fēng）与充分（chōng fèn）第二音节韵母与声调不同，意思是向前猛冲。"}], "explanations": {"充分": "充分（chōng fèn）指足够、完全满足需要或条件，是本题的目标词。", "春分": "春分（chūn fēn）与充分（chōng fèn）第一音节韵母不同（ūn 对 ōng），第二音节声调也不同（fēn 对 fèn），意思是春天的节气，不是足够的意思。", "中分": "中分（zhōng fèn）与充分（chōng fèn）声母不同（zh 对 ch），意思是头发从中间分开。", "冲犯": "冲犯（chōng fàn）与充分（chōng fèn）第二音节韵母不同（a 对 en），声调相同，意思是冒犯。", "成分": "成分（chéng fèn）与充分（chōng fèn）第一音节韵母与声调不同，意思是组成部分。", "冲锋": "冲锋（chōng fēng）与充分（chōng fèn）第二音节韵母与声调不同，意思是向前猛冲。"}, "sentence_index": null, "correct_answer": "充分"}, "level_3": {"options": [{"text": "充分", "is_correct": true, "explanation": "充分：准备足够、完全到位，符合句意。"}, {"text": "富裕", "is_correct": false, "explanation": "搭配：“富裕”说的是经济条件，不能用来说准备的程度。"}, {"text": "严重", "is_correct": false, "explanation": "语义：“严重”说情况或后果很糟，与“准备得很”的积极语境不合。"}, {"text": "宽敞", "is_correct": false, "explanation": "搭配：“宽敞”形容空间大，不能用来形容准备的程度。"}], "explanations": {"充分": "充分：准备足够、完全到位，符合句意。", "富裕": "搭配：“富裕”说的是经济条件，不能用来说准备的程度。", "严重": "语义：“严重”说情况或后果很糟，与“准备得很”的积极语境不合。", "宽敞": "搭配：“宽敞”形容空间大，不能用来形容准备的程度。"}, "sentence_index": 0, "correct_answer": "充分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的汉语水平很充分。", "explanation": "这里应该用〈高〉。高说程度深；充分表示条件或准备足够，不用来说水平的高低。"}, {"text": "他的笑容很充分，大家都很喜欢。", "explanation": "这里应该用〈灿烂〉。灿烂说光彩或笑容明朗；充分说条件或准备足够，不用来形容笑容。"}, {"text": "他对家人的感情很充分。", "explanation": "这里应该用〈深厚〉。感情的程度用“深厚”来说；充分表示条件或准备足够，不用来形容感情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '108eb11f-d439-4516-a6e1-e06c1811a219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13363, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "充分", "is_correct": true, "explanation": "充分：讨论进行得完全到位，大家都说了意见，符合句意。"}, {"text": "冷清", "is_correct": false, "explanation": "语义：“冷清”指没什么人或活动，与“大家都说了意见”矛盾。"}, {"text": "昂贵", "is_correct": false, "explanation": "搭配：“昂贵”说价格高，不能用来形容讨论。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的身材外形，不能用来形容讨论。"}], "explanations": {"充分": "充分：讨论进行得完全到位，大家都说了意见，符合句意。", "冷清": "语义：“冷清”指没什么人或活动，与“大家都说了意见”矛盾。", "昂贵": "搭配：“昂贵”说价格高，不能用来形容讨论。", "高大": "体貌：“高大”形容人或物的身材外形，不能用来形容讨论。"}, "sentence_index": 6, "correct_answer": "充分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的研究方法很充分。", "explanation": "这里应该用〈严谨〉。严谨说做事周密认真；充分说条件或准备足够，不用来形容研究方法。"}, {"text": "这个孩子的身体很充分。", "explanation": "这里应该用〈健康〉。健康说身体状况好；充分说条件或准备足够，不用来形容身体。"}, {"text": "他是个很充分的人。", "explanation": "这里应该用〈能干〉。能干说人的能力强；充分说理由、证据、准备等事物足够，不用来形容人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '108eb11f-d439-4516-a6e1-e06c1811a219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13363, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个理由很非常充分，我们可以去。", "corrected_sentence": "这个理由很充分，我们可以去。", "error_description": "程度副词叠用：“很”和“非常”都表示程度高，不能同时修饰“充分”，应删去“非常”，说“很充分”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '108eb11f-d439-4516-a6e1-e06c1811a219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13363, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份证据还不够更充分，需要再查一查。", "corrected_sentence": "这份证据还不够充分，需要再查一查。", "error_description": "程度副词叠用：“不够”已表示程度不足，“更”不能与“不够”同时修饰“充分”，应删去“更”，说“还不够充分”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '108eb11f-d439-4516-a6e1-e06c1811a219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13364, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "污染", "is_correct": true, "explanation": "正确。「净化」使环境清洁，「污染」使环境受到杂质损害，二者意义相反。"}, {"text": "播种", "is_correct": false, "explanation": "与「净化」无反义关系；「播种」指撒种子，与清洁环境无关。"}, {"text": "旅行", "is_correct": false, "explanation": "与「净化」无反义关系；「旅行」指出游，与环境的清洁程度无关。"}, {"text": "跳舞", "is_correct": false, "explanation": "与「净化」无反义关系；「跳舞」是身体活动，与清除杂质无关。"}], "correct_answer": "污染", "explanations": {"污染": "正确。「净化」使环境清洁，「污染」使环境受到杂质损害，二者意义相反。", "播种": "与「净化」无反义关系；「播种」指撒种子，与清洁环境无关。", "旅行": "与「净化」无反义关系；「旅行」指出游，与环境的清洁程度无关。", "跳舞": "与「净化」无反义关系；「跳舞」是身体活动，与清除杂质无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45bd0aa-b3bc-4d3c-b5a0-4dd8d9b903d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13364, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "污染", "is_correct": true, "explanation": "正确。「净化」使环境清洁，「污染」使环境受到杂质损害，二者意义相反。"}, {"text": "烹饪", "is_correct": false, "explanation": "与「净化」无反义关系；「烹饪」指做饭，与清除杂质无关。"}, {"text": "收集", "is_correct": false, "explanation": "与「净化」无反义关系；「收集」指聚集物品，与环境的清洁程度无关。"}, {"text": "游泳", "is_correct": false, "explanation": "与「净化」无反义关系；「游泳」是身体活动，与清除杂质无关。"}], "correct_answer": "污染", "explanations": {"污染": "正确。「净化」使环境清洁，「污染」使环境受到杂质损害，二者意义相反。", "烹饪": "与「净化」无反义关系；「烹饪」指做饭，与清除杂质无关。", "收集": "与「净化」无反义关系；「收集」指聚集物品，与环境的清洁程度无关。", "游泳": "与「净化」无反义关系；「游泳」是身体活动，与清除杂质无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45bd0aa-b3bc-4d3c-b5a0-4dd8d9b903d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13364, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "清除杂质，使物体或环境变得纯净、清洁。", "primary_collocate": null, "pronunciation": "jìng huà", "ipa": "tɕiŋ˥˩ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "含有重金属、偶氮染料及有毒化学助剂的工业废水未经充分净化即排入河流与地下水系统，导致水体污染长期化、隐蔽化，对生物多样性及当地居民健康构成深远威胁。", "target_word": "净化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "树木可以净化空气，减少噪音，还能帮助小动物和小鸟找到家。", "target_word": "净化", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这台机器可以净化空气。", "target_word": "净化", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "工厂要先净化污水，再排到河里。", "target_word": "净化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "绿色植物能净化房间里的空气。", "target_word": "净化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们家用机器净化自来水。", "target_word": "净化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "污水净化以后，鱼又回来了。", "target_word": "净化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "湿地能净化水，也能保护小动物。", "target_word": "净化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们用沙子和石头净化河水。", "target_word": "净化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想买一台能净化空气的机器。", "target_word": "净化", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "净化了", "label": "体标"}, {"form": "净化过", "label": "体标"}, {"form": "净化器", "label": "复合"}], "register": "中性", "sense_fingerprint": "清除杂质，使空气、水等环境变纯净", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0ed7dbc-a6e5-40ee-911c-fb724370c835') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13364, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "净化", "is_correct": true, "explanation": "正确。「净化」指清除杂质，与「未经充分」「即排入河流」构成废水处理的语境。"}, {"text": "生长", "is_correct": false, "explanation": "语义：生长不能用于废水处理，「未经充分生长即排入河流」说不通。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：装饰与废水处理无关，「未经充分装饰即排入河流」不符合语境。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：欣赏不是废水处理的环节，与后面「排入河流与地下水系统」的污染语境矛盾。"}], "explanations": {"净化": "正确。「净化」指清除杂质，与「未经充分」「即排入河流」构成废水处理的语境。", "生长": "语义：生长不能用于废水处理，「未经充分生长即排入河流」说不通。", "装饰": "语义：装饰与废水处理无关，「未经充分装饰即排入河流」不符合语境。", "欣赏": "语义：欣赏不是废水处理的环节，与后面「排入河流与地下水系统」的污染语境矛盾。"}, "sentence_index": 0, "correct_answer": "净化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师先净化试卷，再发给学生。", "explanation": "这里应该用〈批改〉。试卷要批改，「净化」用于水、空气等环境，不用于试卷。"}, {"text": "司机先净化汽车，再出发。", "explanation": "这里应该用〈洗〉。洗车是去掉车身污物，「净化」用于水、空气等环境，不用于车辆。"}, {"text": "妈妈先净化桌子，再吃饭。", "explanation": "这里应该用〈擦〉。擦桌子是用布去掉表面污物，「净化」多用于水、空气，不说「净化桌子」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45bd0aa-b3bc-4d3c-b5a0-4dd8d9b903d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13364, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "净化", "is_correct": true, "explanation": "正确。「净化」表示去除污水中的杂质，「以后，鱼又回来了」说明水质变好。"}, {"text": "绘画", "is_correct": false, "explanation": "语义：绘画不能施于污水，「污水绘画以后」说不通。"}, {"text": "驾驶", "is_correct": false, "explanation": "语义：驾驶的对象是车辆等，不能用于污水，句子不通。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌不能作用于污水，与「鱼又回来了」的水质变化无关。"}], "explanations": {"净化": "正确。「净化」表示去除污水中的杂质，「以后，鱼又回来了」说明水质变好。", "绘画": "语义：绘画不能施于污水，「污水绘画以后」说不通。", "驾驶": "语义：驾驶的对象是车辆等，不能用于污水，句子不通。", "唱歌": "语义：唱歌不能作用于污水，与「鱼又回来了」的水质变化无关。"}, "sentence_index": 6, "correct_answer": "净化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈先净化面包，再切片。", "explanation": "这里应该用〈烤〉。烤面包是加热处理食物，「净化」指去除水、空气等的杂质，不用于食物加热。"}, {"text": "公司要净化产品质量，不能出问题。", "explanation": "这里应该用〈检验〉。产品质量要靠检验，「净化」指去除水、空气等的杂质，不用于质量检查。"}, {"text": "她每天净化手，然后吃饭。", "explanation": "这里应该用〈洗〉。洗手是去掉手上的污物，「净化」不用于人体部位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45bd0aa-b3bc-4d3c-b5a0-4dd8d9b903d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13364, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台机器把水净化很干净。", "corrected_sentence": "这台机器把水净化得很干净。", "error_description": "补语错误：「把水净化」后接状态补语需要用「得」，应为「净化得很干净」，不能省略「得」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45bd0aa-b3bc-4d3c-b5a0-4dd8d9b903d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13364, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人用过滤器把净化河水。", "corrected_sentence": "工人用过滤器净化河水。", "error_description": "把字错误：「把」字句需「把+宾语+动词」，此处「把」后直接接动词，「把净化河水」不通，应删去「把」，正确为「工人用过滤器净化河水」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45bd0aa-b3bc-4d3c-b5a0-4dd8d9b903d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
