INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13365, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示事情紧接着发生，相当于‘就’或‘便’", "primary_collocate": null, "pronunciation": "jí", "ipa": "tɕi˧˥", "syllable_count": 1, "sentences": [{"text": "他一回到家即打开电视。", "target_word": "即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议结束后，大家即回家了。", "target_word": "即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们收到信即回复你。", "target_word": "即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到这条消息，他即告诉了朋友。", "target_word": "即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你到了学校即给我打电话。", "target_word": "即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人一到，我们即开始吃饭。", "target_word": "即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说完，同学们即安静下来。", "target_word": "即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到铃声，学生们即进教室。", "target_word": "即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天一亮，他们即出发了。", "target_word": "即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理看完信，即同意了这个计划。", "target_word": "即", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "放在动词前，表示一件事之后紧接着做另一件事，相当于就、便", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '515d04d6-e239-4e3c-b806-fb3653b41f00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13365, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "即", "is_correct": true, "explanation": "即（jí）表示紧接着，是本题的目标词。"}, {"text": "鸡", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是鸡。"}, {"text": "几", "is_correct": false, "explanation": "jǐ（第三声）与 jí（第二声）声调不同，意思是几个、几次。"}, {"text": "记", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是记住、记录。"}], "explanations": {"即": "即（jí）表示紧接着，是本题的目标词。", "鸡": "jī（第一声）与 jí（第二声）声调不同，意思是鸡。", "几": "jǐ（第三声）与 jí（第二声）声调不同，意思是几个、几次。", "记": "jì（第四声）与 jí（第二声）声调不同，意思是记住、记录。"}, "sentence_index": null, "correct_answer": "即"}, "level_3": {"options": [{"text": "即", "is_correct": true, "explanation": "即：紧接着，表示回到家后马上开电视，符合句意。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”通常与否定词连用，表示一贯如此，不能直接修饰“打开电视”。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”指过去有过的经历，与“一回到家”紧接的动作不符。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”是程度副词，修饰形容词或心理动词，不能修饰“打开电视”这样的动作。"}], "explanations": {"即": "即：紧接着，表示回到家后马上开电视，符合句意。", "从来": "搭配：“从来”通常与否定词连用，表示一贯如此，不能直接修饰“打开电视”。", "曾经": "语义：“曾经”指过去有过的经历，与“一回到家”紧接的动作不符。", "非常": "搭配：“非常”是程度副词，修饰形容词或心理动词，不能修饰“打开电视”这样的动作。"}, "sentence_index": 0, "correct_answer": "即"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子听完故事，即很困。", "explanation": "这里应该用〈就〉。即表示紧接着，后面要接动作，不能接“很困”这样的状态；就可以接状态。"}, {"text": "他昨天很晚即回到家。", "explanation": "这里应该用〈才〉。才表示事情比预期晚；即表示紧接着发生，与“很晚”不能搭配。"}, {"text": "我一进门，爸爸即很高兴。", "explanation": "这里应该用〈就〉。即表示动作紧接着发生，后面要接动作，不能接“很高兴”这样的状态；就可以接状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '108eb11f-d439-4516-a6e1-e06c1811a219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13365, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "即", "is_correct": true, "explanation": "即（jí）表示紧接着，是本题的目标词。"}, {"text": "挤", "is_correct": false, "explanation": "jǐ（第三声）与 jí（第二声）声调不同，意思是挤压。"}, {"text": "季", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是季节。"}, {"text": "基", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是基础。"}], "explanations": {"即": "即（jí）表示紧接着，是本题的目标词。", "挤": "jǐ（第三声）与 jí（第二声）声调不同，意思是挤压。", "季": "jì（第四声）与 jí（第二声）声调不同，意思是季节。", "基": "jī（第一声）与 jí（第二声）声调不同，意思是基础。"}, "sentence_index": null, "correct_answer": "即"}, "level_3": {"options": [{"text": "即", "is_correct": true, "explanation": "即：紧接着，表示老师说完后同学们马上安静下来，符合句意。"}, {"text": "永远", "is_correct": false, "explanation": "语义：“永远”表示长久不变，与“说完就安静下来”的紧接关系不符。"}, {"text": "一直", "is_correct": false, "explanation": "搭配：“一直”表示持续，不与表示变化的“安静下来”搭配。"}, {"text": "仍然", "is_correct": false, "explanation": "语义：“仍然”表示状态延续，与“说完后安静下来”的变化不合。"}], "explanations": {"即": "即：紧接着，表示老师说完后同学们马上安静下来，符合句意。", "永远": "语义：“永远”表示长久不变，与“说完就安静下来”的紧接关系不符。", "一直": "搭配：“一直”表示持续，不与表示变化的“安静下来”搭配。", "仍然": "语义：“仍然”表示状态延续，与“说完后安静下来”的变化不合。"}, "sentence_index": 6, "correct_answer": "即"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我还没吃完饭，即去上学了。", "explanation": "这里的“即”表示紧接着发生，前面说“还没吃完饭”，就不能紧接着去上学；应说“吃完饭就去上学了”。"}, {"text": "他听了这个消息，即非常生气。", "explanation": "这里应该用〈就〉。即表示动作紧接着发生，后面要接动作，不能接“非常生气”这样的状态；就可以接状态。"}, {"text": "他一直即在图书馆学习。", "explanation": "这里的“即”表示紧接着发生，与表示持续的“一直”矛盾；应去掉“即”，说“他一直在图书馆学习”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '108eb11f-d439-4516-a6e1-e06c1811a219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13365, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一下课就即去食堂吃饭。", "corrected_sentence": "他一下课即去食堂吃饭。", "error_description": "重复副词：“就”和“即”都表示紧接着，不能同时用，应删去“就”，说“一下课即去”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '108eb11f-d439-4516-a6e1-e06c1811a219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13365, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一放学，我们才即去图书馆。", "corrected_sentence": "一放学，我们即去图书馆。", "error_description": "语义冲突：“才”表示事情比预期晚发生，“即”表示紧接着发生，二者意思相反，应删去“才”，说“我们即去”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '108eb11f-d439-4516-a6e1-e06c1811a219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
