INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13368, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指自然界中水的聚集形态，如河流、湖泊、海洋、地下水等。", "primary_collocate": null, "pronunciation": "shuǐ tǐ", "ipa": "ʂweɪ˨˩˦ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "含有重金属、偶氮染料及有毒化学助剂的工业废水未经充分净化即排入河流与地下水系统，导致水体污染长期化、隐蔽化，对生物多样性及当地居民健康构成深远威胁。", "target_word": "水体", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "河流和湖泊都是水体。", "target_word": "水体", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个水体里的鱼越来越少了。", "target_word": "水体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂排放废水，会污染附近的水体。", "target_word": "水体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家每天检测水体的温度。", "target_word": "水体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水体的颜色会随着季节变化。", "target_word": "水体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海洋是地球上最大的水体。", "target_word": "水体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水体里的氧气太少，鱼活不下去。", "target_word": "水体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "保护水体是每个人的责任。", "target_word": "水体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这片水体很深，不能游泳。", "target_word": "水体", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "水體", "label": "繁体"}, {"form": "水体污染", "label": "复合"}], "register": "书面语", "sense_fingerprint": "水体：自然界中河流、湖泊、海洋等水的聚集形态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '515d04d6-e239-4e3c-b806-fb3653b41f00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13368, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "水体", "is_correct": true, "explanation": "正确答案。水体指河流、湖泊、地下水等水的聚集形态。"}, {"text": "水底", "is_correct": false, "explanation": "dǐ（第三声）与 tǐ（第三声）声母不同（d 与 t），意思是水的底部，与“水体”不同。"}, {"text": "水洗", "is_correct": false, "explanation": "xǐ（第三声）与 tǐ（第三声）声母不同（x 与 t），意思是用水清洗。"}, {"text": "水里", "is_correct": false, "explanation": "lǐ（第三声）与 tǐ（第三声）声母不同（l 与 t），意思是在水中。"}], "explanations": {"水体": "正确答案。水体指河流、湖泊、地下水等水的聚集形态。", "水底": "dǐ（第三声）与 tǐ（第三声）声母不同（d 与 t），意思是水的底部，与“水体”不同。", "水洗": "xǐ（第三声）与 tǐ（第三声）声母不同（x 与 t），意思是用水清洗。", "水里": "lǐ（第三声）与 tǐ（第三声）声母不同（l 与 t），意思是在水中。"}, "sentence_index": null, "correct_answer": "水体"}, "level_3": {"options": [{"text": "水体", "is_correct": true, "explanation": "正确。“水体”指河流、地下水等水的聚集形态，可以被污染，与“污染”搭配自然。"}, {"text": "水费", "is_correct": false, "explanation": "搭配：“污染”的对象是环境或水域，“水费”是价钱，不能与“污染”搭配。"}, {"text": "水分", "is_correct": false, "explanation": "语义：“水分”指物体里含的水，这里说的是河流与地下水系统受到的污染，意思不合。"}, {"text": "水利", "is_correct": false, "explanation": "语义：“水利”指兴修水利的事业或工程，不指可以被污染的水域，搭配也不通。"}], "explanations": {"水体": "正确。“水体”指河流、地下水等水的聚集形态，可以被污染，与“污染”搭配自然。", "水费": "搭配：“污染”的对象是环境或水域，“水费”是价钱，不能与“污染”搭配。", "水分": "语义：“水分”指物体里含的水，这里说的是河流与地下水系统受到的污染，意思不合。", "水利": "语义：“水利”指兴修水利的事业或工程，不指可以被污染的水域，搭配也不通。"}, "sentence_index": 0, "correct_answer": "水体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "湖边有一本很大的水体。", "explanation": "这里应该用〈片〉。“本”用于书册，不能用来数水体。"}, {"text": "这把水体很深，不能游泳。", "explanation": "这里应该用〈片〉。“把”用于有柄的器具，不能用来数水体。"}, {"text": "这头水体很大，不能游泳。", "explanation": "这里应该用〈片〉。“头”用于牲畜，水体不能用“头”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '108eb11f-d439-4516-a6e1-e06c1811a219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13368, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水体", "is_correct": true, "explanation": "正确。“水体”指海洋这样大片的水域，可以用“最大的”来形容。"}, {"text": "水位", "is_correct": false, "explanation": "语义：“水位”指水面的高低，不指水域的范围或体积，不能说“最大的水位”指海洋。"}, {"text": "水质", "is_correct": false, "explanation": "搭配：“最大”修饰的是范围或体积，“水质”说的是水的好坏，不能说“最大的水质”。"}, {"text": "水族", "is_correct": false, "explanation": "语义：“水族”指水中的生物，不指海洋这样的水域，句子意思不通。"}], "explanations": {"水体": "正确。“水体”指海洋这样大片的水域，可以用“最大的”来形容。", "水位": "语义：“水位”指水面的高低，不指水域的范围或体积，不能说“最大的水位”指海洋。", "水质": "搭配：“最大”修饰的是范围或体积，“水质”说的是水的好坏，不能说“最大的水质”。", "水族": "语义：“水族”指水中的生物，不指海洋这样的水域，句子意思不通。"}, "sentence_index": 6, "correct_answer": "水体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "河水的水体很急，我们不能下去游泳。", "explanation": "这里应该用〈水流〉。水流说的是流动的速度，水体指水的聚集处，不能说“很急”。"}, {"text": "河面上溅起了很大的水体。", "explanation": "这里应该用〈水花〉。水花指水被溅起来的样子，水体是水的聚集处，不能说溅起。"}, {"text": "远处传来一阵水体。", "explanation": "这里应该用〈水声〉。水声指水发出的声音，水体指水域，不能用来指声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '108eb11f-d439-4516-a6e1-e06c1811a219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13368, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一片很干净水体。", "corrected_sentence": "这是一片很干净的水体。", "error_description": "错误在“很干净”和“水体”之间缺少“的”。“很干净”修饰名词时要加“的”，应说“很干净的水体”，不能说“很干净水体”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '108eb11f-d439-4516-a6e1-e06c1811a219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13368, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们水体里游泳，很危险。", "corrected_sentence": "我们在水体里游泳，很危险。", "error_description": "错误在于缺少“在”。表示在某个场所做某事，要用“在……里”，应说“在水体里游泳”，不能说“水体里游泳”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '108eb11f-d439-4516-a6e1-e06c1811a219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
