INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13369, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指某种状态或过程持续很长时间，逐渐变成长期存在的现象。", "primary_collocate": null, "pronunciation": "cháng qī huà", "ipa": "ʈʂʰaŋ˧˥ tɕʰi˥˥ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "含有重金属、偶氮染料及有毒化学助剂的工业废水未经充分净化即排入河流与地下水系统，导致水体污染长期化、隐蔽化，对生物多样性及当地居民健康构成深远威胁。", "target_word": "长期化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我们不希望这场战争长期化。", "target_word": "长期化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "病情长期化，让他很担心。", "target_word": "长期化", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这种污染可能会长期化。", "target_word": "长期化", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "价格上涨开始长期化了。", "target_word": "长期化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "问题长期化以后，就更难解决了。", "target_word": "长期化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专家提醒，失业问题正在长期化。", "target_word": "长期化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要及时治疗，避免疾病长期化。", "target_word": "长期化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经济困难长期化，会影响很多家庭。", "target_word": "长期化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "双方都不想让矛盾长期化。", "target_word": "长期化", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "長期化", "label": "繁体"}, {"form": "长期化了", "label": "体标"}], "register": "书面语", "sense_fingerprint": "长期化：状态或过程持续很久，逐渐变成长期存在的现象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '515d04d6-e239-4e3c-b806-fb3653b41f00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13369, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "长期化", "is_correct": true, "explanation": "正确。“导致……污染长期化”说的是污染持续很久，“长期化”与“污染”搭配自然。"}, {"text": "冷却", "is_correct": false, "explanation": "语义：“冷却”指降温，不指污染的状态变化，“污染冷却”意思不通。"}, {"text": "煮沸", "is_correct": false, "explanation": "搭配：“煮沸”的对象是水或食物，不能与“污染”搭配。"}, {"text": "降温", "is_correct": false, "explanation": "语义：“降温”指温度下降，不能用来说污染的变化，与“隐蔽化”并列也不通。"}], "explanations": {"长期化": "正确。“导致……污染长期化”说的是污染持续很久，“长期化”与“污染”搭配自然。", "冷却": "语义：“冷却”指降温，不指污染的状态变化，“污染冷却”意思不通。", "煮沸": "搭配：“煮沸”的对象是水或食物，不能与“污染”搭配。", "降温": "语义：“降温”指温度下降，不能用来说污染的变化，与“隐蔽化”并列也不通。"}, "sentence_index": 0, "correct_answer": "长期化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次会议被长期化了两个小时。", "explanation": "这里应该用〈延长〉。延长指时间变长，长期化指使状态长久存在，不能说“被长期化了两个小时”。"}, {"text": "他总是长期化作业。", "explanation": "这里应该用〈拖延〉。拖延指把事情往后推，长期化指状态长久存在，不能用于“作业”。"}, {"text": "这条河很长期化，我们游了一天。", "explanation": "这里应该用〈长〉。“长”形容距离或时间大；“长期化”指使状态长久存在，不能用来形容河。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '108eb11f-d439-4516-a6e1-e06c1811a219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13369, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "长期化", "is_correct": true, "explanation": "正确。“失业问题正在长期化”说的是问题持续存在，“长期化”与“正在”搭配自然。"}, {"text": "点燃", "is_correct": false, "explanation": "语义：“点燃”指使物体燃烧，不能用来说失业问题，“失业问题正在点燃”意思不通。"}, {"text": "烘干", "is_correct": false, "explanation": "语义：“烘干”指用热力使东西变干，不能用于“失业问题”，句子意思不通。"}, {"text": "打印", "is_correct": false, "explanation": "配价：“打印”的对象是文件或文字，不能以“问题”作宾语。"}], "explanations": {"长期化": "正确。“失业问题正在长期化”说的是问题持续存在，“长期化”与“正在”搭配自然。", "点燃": "语义：“点燃”指使物体燃烧，不能用来说失业问题，“失业问题正在点燃”意思不通。", "烘干": "语义：“烘干”指用热力使东西变干，不能用于“失业问题”，句子意思不通。", "打印": "配价：“打印”的对象是文件或文字，不能以“问题”作宾语。"}, "sentence_index": 6, "correct_answer": "长期化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司决定长期化市场。", "explanation": "这里应该用〈扩大〉。扩大指范围变大，长期化指使状态长久存在，不能用于“市场”。"}, {"text": "我们今天要长期化工期。", "explanation": "这里应该用〈缩短〉。缩短指时间变短，长期化指状态长久存在，不能用于“工期”。"}, {"text": "老板把会议长期化到了下周，大家都很失望。", "explanation": "这里应该用〈推迟〉。推迟指把时间往后移，长期化指使状态长久存在，不能用来把会议定到某个时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '108eb11f-d439-4516-a6e1-e06c1811a219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13369, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "不要让矛盾很长期化。", "corrected_sentence": "不要让矛盾长期化。", "error_description": "错误在“很”。“很”不能修饰动词“长期化”，应删去“很”，即“不要让矛盾长期化。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '108eb11f-d439-4516-a6e1-e06c1811a219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13369, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小毛病放着不管，会很长期化。", "corrected_sentence": "这个小毛病放着不管，会慢慢长期化。", "error_description": "错误在“很”。“很”修饰形容词或心理动词，“长期化”是表示变化过程的动词，应用“慢慢”修饰，不能说“很长期化”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '108eb11f-d439-4516-a6e1-e06c1811a219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13370, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "明显", "is_correct": true, "explanation": "反义：“明显”指容易看出，与“隐蔽”（不让人发现）意思相反。"}, {"text": "复杂", "is_correct": false, "explanation": "无关：“复杂”形容结构繁多，与隐藏、不易察觉没有反义关系。"}, {"text": "热闹", "is_correct": false, "explanation": "无关：“热闹”形容场面喧嚷，与隐蔽的意思没有反义关系。"}, {"text": "坚硬", "is_correct": false, "explanation": "无关：“坚硬”形容质地，与隐蔽的意思没有反义关系。"}], "correct_answer": "明显", "explanations": {"明显": "反义：“明显”指容易看出，与“隐蔽”（不让人发现）意思相反。", "复杂": "无关：“复杂”形容结构繁多，与隐藏、不易察觉没有反义关系。", "热闹": "无关：“热闹”形容场面喧嚷，与隐蔽的意思没有反义关系。", "坚硬": "无关：“坚硬”形容质地，与隐蔽的意思没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52471281-3756-4e87-a66a-c94079c46cb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13370, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "显眼", "is_correct": true, "explanation": "反义：“显眼”指容易被看见，与“隐蔽”（不易被发现）意思相反。"}, {"text": "迅速", "is_correct": false, "explanation": "无关：“迅速”形容速度快，与隐藏、可见性无关。"}, {"text": "清脆", "is_correct": false, "explanation": "无关：“清脆”形容声音，与隐蔽的意思没有反义关系。"}, {"text": "宽阔", "is_correct": false, "explanation": "无关：“宽阔”形容空间面积大，与隐蔽的意思没有反义关系。"}], "correct_answer": "显眼", "explanations": {"显眼": "反义：“显眼”指容易被看见，与“隐蔽”（不易被发现）意思相反。", "迅速": "无关：“迅速”形容速度快，与隐藏、可见性无关。", "清脆": "无关：“清脆”形容声音，与隐蔽的意思没有反义关系。", "宽阔": "无关：“宽阔”形容空间面积大，与隐蔽的意思没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52471281-3756-4e87-a66a-c94079c46cb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13370, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "隐藏起来，不让人发现或察觉。", "primary_collocate": null, "pronunciation": "yǐn bì", "ipa": "in˨˩˦ pi˥˩", "syllable_count": 2, "sentences": [{"text": "更严峻的是，若大量代理基于相似优化目标自发演化，可能催生群体性的行为趋同，进而形成“分布式认知霸权”——表面上去中心化的系统，实质上演变为隐蔽的价值导向网络。", "target_word": "隐蔽", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "含有重金属、偶氮染料及有毒化学助剂的工业废水未经充分净化即排入河流与地下水系统，导致水体污染长期化、隐蔽化，对生物多样性及当地居民健康构成深远威胁。", "target_word": "隐蔽", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个山洞的入口非常隐蔽。", "target_word": "隐蔽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把钱藏在一个很隐蔽的地方。", "target_word": "隐蔽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种病早期症状很隐蔽，不容易发现。", "target_word": "隐蔽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的行动十分隐蔽，没有人知道。", "target_word": "隐蔽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小偷选了一条隐蔽的小路离开。", "target_word": "隐蔽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "摄像头装得很隐蔽，客人都没看见。", "target_word": "隐蔽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题很隐蔽，检查了几次才找到。", "target_word": "隐蔽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林里有一个隐蔽的小木屋。", "target_word": "隐蔽", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "隐蔽性", "label": "复合词"}, {"form": "隐蔽化", "label": "复合词"}, {"form": "隱蔽", "label": "繁体"}], "register": "书面", "sense_fingerprint": "形容事物或行为藏得很深，不容易被人发现", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ff47f7-e50e-4937-9c6f-4d98586d83d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13370, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "隐蔽", "is_correct": true, "explanation": "隐蔽（yǐn bì）：隐藏起来，不让人发现或察觉，即本词条的意思。"}, {"text": "银币", "is_correct": false, "explanation": "银币（yín bì）与隐蔽的第一个音节不同：yín 为第二声，yǐn 为第三声，声调不同。银币意思是银质的硬币。"}, {"text": "影壁", "is_correct": false, "explanation": "影壁（yǐng bì）与隐蔽的第一个音节韵尾不同：in 与 ing 的韵尾不同，意思是中式建筑门前的照壁。"}, {"text": "紧闭", "is_correct": false, "explanation": "紧闭（jǐn bì）与隐蔽的第一个音节声母不同：j 与 y 不同，意思是关得很紧。"}, {"text": "引力", "is_correct": false, "explanation": "引力（yǐn lì）与隐蔽的第二个音节声母不同：l 与 b 不同，意思是物体之间相互吸引的力。"}], "explanations": {"隐蔽": "隐蔽（yǐn bì）：隐藏起来，不让人发现或察觉，即本词条的意思。", "银币": "银币（yín bì）与隐蔽的第一个音节不同：yín 为第二声，yǐn 为第三声，声调不同。银币意思是银质的硬币。", "影壁": "影壁（yǐng bì）与隐蔽的第一个音节韵尾不同：in 与 ing 的韵尾不同，意思是中式建筑门前的照壁。", "紧闭": "紧闭（jǐn bì）与隐蔽的第一个音节声母不同：j 与 y 不同，意思是关得很紧。", "引力": "引力（yǐn lì）与隐蔽的第二个音节声母不同：l 与 b 不同，意思是物体之间相互吸引的力。"}, "sentence_index": null, "correct_answer": "隐蔽"}, "level_3": {"options": [{"text": "隐蔽", "is_correct": true, "explanation": "正确。“隐蔽”指隐藏、不易察觉，与“表面上……实质上”的对照相合，只有它能形容这种藏起来的网络。"}, {"text": "公开", "is_correct": false, "explanation": "语义：“公开”指摆在明处，与“表面上去中心化，实质上演变为……网络”中暗含的隐性结构相矛盾。"}, {"text": "清澈", "is_correct": false, "explanation": "搭配：“清澈”多用来形容水、眼神等，不能修饰“价值导向网络”这样的抽象事物。"}, {"text": "明亮", "is_correct": false, "explanation": "语义：“明亮”描述可见的光线或外观，用来形容抽象的网络很不自然，也与“实质上”所强调的隐性之义相悖。"}], "explanations": {"隐蔽": "正确。“隐蔽”指隐藏、不易察觉，与“表面上……实质上”的对照相合，只有它能形容这种藏起来的网络。", "公开": "语义：“公开”指摆在明处，与“表面上去中心化，实质上演变为……网络”中暗含的隐性结构相矛盾。", "清澈": "搭配：“清澈”多用来形容水、眼神等，不能修饰“价值导向网络”这样的抽象事物。", "明亮": "语义：“明亮”描述可见的光线或外观，用来形容抽象的网络很不自然，也与“实质上”所强调的隐性之义相悖。"}, "sentence_index": 0, "correct_answer": "隐蔽"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的颜色很隐蔽，穿在身上特别显眼。", "explanation": "这里应该用〈鲜艳〉。“隐蔽”指不易被看见，与“特别显眼”的意思相反；形容颜色醒目要用“鲜艳”。"}, {"text": "这块路牌设计得很隐蔽，远远就能看见。", "explanation": "这里应该用〈醒目〉。“隐蔽”指藏起来不让人发现，形容路牌显眼要用“醒目”。"}, {"text": "他说话的声音很隐蔽，大家都能清楚地听到。", "explanation": "这里应该用〈洪亮〉。“隐蔽”指不被察觉，与“大家都能清楚地听到”矛盾；形容声音大要用“洪亮”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52471281-3756-4e87-a66a-c94079c46cb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13370, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "隐蔽", "is_correct": true, "explanation": "正确。“隐蔽”指不易被发现，符合小偷选择离开路线、不想被看见的意图。"}, {"text": "繁华", "is_correct": false, "explanation": "语义：“繁华”指街市热闹、店铺众多，小偷不会选择人来人往的路逃离。"}, {"text": "甜美", "is_correct": false, "explanation": "搭配：“甜美”多修饰声音、滋味或笑容，不能用来修饰“小路”。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”指人多声杂，与小偷暗中离开的情境相矛盾。"}], "explanations": {"隐蔽": "正确。“隐蔽”指不易被发现，符合小偷选择离开路线、不想被看见的意图。", "繁华": "语义：“繁华”指街市热闹、店铺众多，小偷不会选择人来人往的路逃离。", "甜美": "搭配：“甜美”多修饰声音、滋味或笑容，不能用来修饰“小路”。", "热闹": "语义：“热闹”指人多声杂，与小偷暗中离开的情境相矛盾。"}, "sentence_index": 6, "correct_answer": "隐蔽"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "远处传来隐蔽的歌声，很好听。", "explanation": "这里应该用〈隐约〉。“隐蔽”指不让人察觉，形容声音若有若无要用“隐约”。"}, {"text": "这个变化很隐蔽，大家一眼就看出来了。", "explanation": "这里应该用〈明显〉。“隐蔽”指不容易被察觉，说变化一眼就能看出，要用“明显”。"}, {"text": "这块石头的表面很隐蔽。", "explanation": "这里应该用〈粗糙〉。“隐蔽”指藏起来不被看见，描述表面质地要用“粗糙”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52471281-3756-4e87-a66a-c94079c46cb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13370, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他隐蔽的把钱藏了起来。", "corrected_sentence": "他隐蔽地把钱藏了起来。", "error_description": "“隐蔽”修饰动词“藏”时要用“地”，写作“隐蔽地”；这里误用了“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52471281-3756-4e87-a66a-c94079c46cb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13370, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把钱藏很隐蔽。", "corrected_sentence": "他把钱藏得很隐蔽。", "error_description": "“藏”后面接表示程度的补语“很隐蔽”时，中间必须用“得”引出，应写作“藏得很隐蔽”；漏掉“得”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52471281-3756-4e87-a66a-c94079c46cb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13372, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "良性循环", "is_correct": true, "explanation": "反义：恶性循环指坏事互相影响、越来越糟，良性循环指好事互相促进、越来越好，意义相反。"}, {"text": "天气预报", "is_correct": false, "explanation": "天气预报与恶性循环没有反义关系，二者不是对立概念。"}, {"text": "家庭生活", "is_correct": false, "explanation": "家庭生活与恶性循环没有反义关系，二者不构成对立。"}, {"text": "大学教育", "is_correct": false, "explanation": "大学教育与恶性循环没有反义关系，二者不构成对立。"}], "correct_answer": "良性循环", "explanations": {"良性循环": "反义：恶性循环指坏事互相影响、越来越糟，良性循环指好事互相促进、越来越好，意义相反。", "天气预报": "天气预报与恶性循环没有反义关系，二者不是对立概念。", "家庭生活": "家庭生活与恶性循环没有反义关系，二者不构成对立。", "大学教育": "大学教育与恶性循环没有反义关系，二者不构成对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c647000-6596-4914-878e-6fa34e140682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13372, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "良性循环", "is_correct": true, "explanation": "反义：恶性循环指坏事互相影响、越来越糟，良性循环指好事互相促进、越来越好，意义相反。"}, {"text": "公共交通", "is_correct": false, "explanation": "公共交通与恶性循环没有反义关系，二者不构成对立。"}, {"text": "旅游景点", "is_correct": false, "explanation": "旅游景点与恶性循环没有反义关系，二者不构成对立。"}, {"text": "图书馆", "is_correct": false, "explanation": "图书馆与恶性循环没有反义关系，二者不构成对立。"}], "correct_answer": "良性循环", "explanations": {"良性循环": "反义：恶性循环指坏事互相影响、越来越糟，良性循环指好事互相促进、越来越好，意义相反。", "公共交通": "公共交通与恶性循环没有反义关系，二者不构成对立。", "旅游景点": "旅游景点与恶性循环没有反义关系，二者不构成对立。", "图书馆": "图书馆与恶性循环没有反义关系，二者不构成对立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c647000-6596-4914-878e-6fa34e140682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13372, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "比喻一系列不好的事情互相影响，使情况变得更坏。", "primary_collocate": null, "pronunciation": "è xìng xún huán", "ipa": "ɤ˥˩ ɕiŋ˥˩ ɕyn˧˥ xwan˧˥", "syllable_count": 4, "sentences": [{"text": "钱越少越要借钱，借得越多钱越少，这一恶性循环让他很累。", "target_word": "恶性循环", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他越熬夜越累，越累越熬夜，这是恶性循环。", "target_word": "恶性循环", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没钱就找不到好工作，又因此更没钱，真是恶性循环。", "target_word": "恶性循环", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要想办法打破这个恶性循环。", "target_word": "恶性循环", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司亏钱，就减少员工，生意更差，成了恶性循环。", "target_word": "恶性循环", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不敢说话，别人不理他，他更不敢说话，这是恶性循环。", "target_word": "恶性循环", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气越热，空调用得越多，城市更热，形成恶性循环。", "target_word": "恶性循环", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "成绩差就更想玩手机，越玩成绩越差，这是恶性循环。", "target_word": "恶性循环", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "压力大就睡不好，睡不好压力更大，真是恶性循环。", "target_word": "恶性循环", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格一涨，大家少买，商店又涨价，恶性循环就开始了。", "target_word": "恶性循环", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "惡性循環", "label": "繁体"}], "register": "中性", "sense_fingerprint": "坏事互相影响、越来越糟的循环状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae3c29d2-8b53-4786-b4aa-4309f48b519c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13372, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "恶性循环", "is_correct": true, "explanation": "正确。恶性循环指坏事互相影响、越来越糟，与句中“借得越多钱越少”相符。"}, {"text": "良性循环", "is_correct": false, "explanation": "语义：良性循环指好事互相促进，与句中钱越来越少、让人很累的结果相矛盾。"}, {"text": "好习惯", "is_correct": false, "explanation": "语义：好习惯是积极的，与句中越来越糟的情况相矛盾。"}, {"text": "新家具", "is_correct": false, "explanation": "语义：新家具是具体物品，不能指钱越借越少的循环过程。"}], "explanations": {"恶性循环": "正确。恶性循环指坏事互相影响、越来越糟，与句中“借得越多钱越少”相符。", "良性循环": "语义：良性循环指好事互相促进，与句中钱越来越少、让人很累的结果相矛盾。", "好习惯": "语义：好习惯是积极的，与句中越来越糟的情况相矛盾。", "新家具": "语义：新家具是具体物品，不能指钱越借越少的循环过程。"}, "sentence_index": 0, "correct_answer": "恶性循环"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那起恶性循环造成了三人受伤。", "explanation": "这里应该用〈恶性事故〉。恶性循环指多件坏事互相推动、形成循环，一次事故不构成循环，应说“恶性事故”。"}, {"text": "我们的合作形成了恶性循环，双方收获越来越多。", "explanation": "这里应该用〈良性循环〉。恶性循环指坏事互相影响，描述收获增加的好结果时要用“良性循环”。"}, {"text": "医生说他得了恶性循环，需要马上手术。", "explanation": "这里应该用〈恶性肿瘤〉。恶性循环是比喻，指坏事互相影响，不指疾病本身，说病症要用“恶性肿瘤”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c647000-6596-4914-878e-6fa34e140682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13372, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "恶性循环", "is_correct": true, "explanation": "正确。恶性循环指坏事互相推动，与句中“城市更热”的结果相符。"}, {"text": "良性循环", "is_correct": false, "explanation": "语义：良性循环指好事互相促进，与句中“城市更热”的消极结果相矛盾。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“形成”的宾语应是状况或过程，“桌子”是具体物品，不能“形成”。"}, {"text": "身体", "is_correct": false, "explanation": "搭配：“形成”的宾语应是抽象的状况，“身体”不能被“形成”，搭配不当。"}], "explanations": {"恶性循环": "正确。恶性循环指坏事互相推动，与句中“城市更热”的结果相符。", "良性循环": "语义：良性循环指好事互相促进，与句中“城市更热”的消极结果相矛盾。", "桌子": "搭配：“形成”的宾语应是状况或过程，“桌子”是具体物品，不能“形成”。", "身体": "搭配：“形成”的宾语应是抽象的状况，“身体”不能被“形成”，搭配不当。"}, "sentence_index": 6, "correct_answer": "恶性循环"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天跑步，身体越来越好，这是恶性循环。", "explanation": "这里应该用〈良性循环〉。恶性循环指坏事互相影响、越来越糟，身体越来越好是好的结果。"}, {"text": "他是个很爱抱怨的恶性循环。", "explanation": "这里不能用来形容人。恶性循环指事情之间互相影响的过程，不能用来指一个人。"}, {"text": "这把椅子是一个恶性循环。", "explanation": "这里不能用来指物品。恶性循环指事情之间互相推动的过程，椅子这样的具体物品不能是恶性循环。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c647000-6596-4914-878e-6fa34e140682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13372, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "以前我们也陷入过一只恶性循环。", "corrected_sentence": "以前我们也陷入过一个恶性循环。", "error_description": "错误：量词“只”用错了。“恶性循环”是抽象过程，应说“一个恶性循环”，“只”多用于动物或成对的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c647000-6596-4914-878e-6fa34e140682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13372, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "城市越来越热，形成了一条恶性循环。", "corrected_sentence": "城市越来越热，形成了一个恶性循环。", "error_description": "错误：量词“条”用错了。“恶性循环”是抽象过程，应说“一个恶性循环”，“条”多用于细长的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c647000-6596-4914-878e-6fa34e140682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
