INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13373, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "时尚品牌指具有时尚设计和高知名度的品牌，通常引领潮流。", "primary_collocate": null, "pronunciation": "shí shàng pǐn pái", "ipa": "ʂɻ̩˧˥ ʂaŋ˥˩ pʰin˨˩˦ pʰaɪ˧˥", "syllable_count": 4, "sentences": [{"text": "这个时尚品牌价格便宜，衣服几乎每周都换新款。", "target_word": "时尚品牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个时尚品牌的新衣服很受年轻人欢迎。", "target_word": "时尚品牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢买时尚品牌的包和鞋。", "target_word": "时尚品牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家时尚品牌每年都会开几次发布会。", "target_word": "时尚品牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我朋友在一家有名的时尚品牌工作。", "target_word": "时尚品牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个时尚品牌的设计总是走在潮流前面。", "target_word": "时尚品牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个时尚品牌的店开在市中心，门口总有很多人。", "target_word": "时尚品牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想创建自己的时尚品牌，所以先学设计。", "target_word": "时尚品牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个时尚品牌请了很多明星做广告。", "target_word": "时尚品牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多时尚品牌每年春天都会推出新衣服。", "target_word": "时尚品牌", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "時尚品牌", "label": "繁体"}], "register": "中性", "sense_fingerprint": "设计新潮、知名度高、引领潮流的品牌", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae3c29d2-8b53-4786-b4aa-4309f48b519c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13373, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "时尚品牌", "is_correct": true, "explanation": "正确。时尚品牌指设计新潮、知名度高的品牌，与句中价格便宜、新款频出的语境相符。"}, {"text": "奢侈品牌", "is_correct": false, "explanation": "语义：奢侈品牌强调高价，与句中“价格便宜”相矛盾。"}, {"text": "老字号", "is_correct": false, "explanation": "语义：老字号强调历史悠久，与句中“几乎每周都换新款”的快速更新相矛盾。"}, {"text": "传统工艺", "is_correct": false, "explanation": "语义：传统工艺强调手工技艺，不会几乎每周换新款，与句中语境不符。"}], "explanations": {"时尚品牌": "正确。时尚品牌指设计新潮、知名度高的品牌，与句中价格便宜、新款频出的语境相符。", "奢侈品牌": "语义：奢侈品牌强调高价，与句中“价格便宜”相矛盾。", "老字号": "语义：老字号强调历史悠久，与句中“几乎每周都换新款”的快速更新相矛盾。", "传统工艺": "语义：传统工艺强调手工技艺，不会几乎每周换新款，与句中语境不符。"}, "sentence_index": 0, "correct_answer": "时尚品牌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我表姐每天吃一个时尚品牌当早饭。", "explanation": "这里应该用〈面包〉。时尚品牌是企业品牌，不是食物，不能用来吃。"}, {"text": "这个时尚品牌每天都要练习走秀。", "explanation": "这里应该用〈模特〉。时尚品牌是企业品牌，不能练习走秀，走秀练习的是模特。"}, {"text": "这个时尚品牌每年招收很多学生。", "explanation": "这里应该用〈设计学院〉。时尚品牌是企业品牌，不是学校，不能招收学生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c647000-6596-4914-878e-6fa34e140682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13373, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时尚品牌", "is_correct": true, "explanation": "正确。时尚品牌可以开店，与句中“店开在市中心，门口总有很多人”的语境相符。"}, {"text": "小学", "is_correct": false, "explanation": "语义：小学是学校，不开店，与句中“店”的语境不符。"}, {"text": "天气预报", "is_correct": false, "explanation": "语义：天气预报是信息，不是可以开店的机构，与句中语境不符。"}, {"text": "地质勘探", "is_correct": false, "explanation": "搭配：“那个……的店”中的名词应是可以开店的事物，“地质勘探”不能开店，搭配不当。"}], "explanations": {"时尚品牌": "正确。时尚品牌可以开店，与句中“店开在市中心，门口总有很多人”的语境相符。", "小学": "语义：小学是学校，不开店，与句中“店”的语境不符。", "天气预报": "语义：天气预报是信息，不是可以开店的机构，与句中语境不符。", "地质勘探": "搭配：“那个……的店”中的名词应是可以开店的事物，“地质勘探”不能开店，搭配不当。"}, "sentence_index": 6, "correct_answer": "时尚品牌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个时尚品牌昨天在公园里散步。", "explanation": "这里应该用〈设计师〉。时尚品牌是企业品牌，不是人，不能散步。"}, {"text": "这家银行是一个时尚品牌，很多人在那里存钱。", "explanation": "这里不能指金融机构。时尚品牌指服装、配饰等时尚产品的牌子，银行不属于这一范围。"}, {"text": "我们周末去时尚品牌看电影。", "explanation": "这里不能指场所。时尚品牌是牌子，不是电影院，不能用来指看电影的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c647000-6596-4914-878e-6fa34e140682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13373, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只时尚品牌曾经引领过潮流。", "corrected_sentence": "这个时尚品牌曾经引领过潮流。", "error_description": "错误：量词“只”用错了。“时尚品牌”应用量词“个”，“只”多用于动物或成对的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c647000-6596-4914-878e-6fa34e140682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13373, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他创建了一条时尚品牌，专门做女装。", "corrected_sentence": "他创建了一个时尚品牌，专门做女装。", "error_description": "错误：量词“条”用错了。“时尚品牌”应用量词“个”，“条”多用于细长的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c647000-6596-4914-878e-6fa34e140682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
