INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13374, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "新推出的产品。", "primary_collocate": null, "pronunciation": "xīn pǐn", "ipa": "ɕin˥ pʰin˨˩˦", "syllable_count": 2, "sentences": [{"text": "这家店的新品总是比老款贵，但很多人还是愿意买。", "target_word": "新品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店下个月会推出一批新品。", "target_word": "新品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机公司今天发布了新品。", "target_word": "新品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新品一上架，很多人就排队去买。", "target_word": "新品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈想先看看这家店的新品。", "target_word": "新品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这款新品的价格比旧的便宜。", "target_word": "新品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里，新品旁边写着“刚上市”。", "target_word": "新品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每个星期都去买咖啡店的新品。", "target_word": "新品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新品卖得很好，一天就卖完了。", "target_word": "新品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司开会，是为了讨论春季新品。", "target_word": "新品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "款", "label": "量词"}, {"form": "新品发布", "label": "复合"}], "register": "中性", "sense_fingerprint": "新推出的产品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae3c29d2-8b53-4786-b4aa-4309f48b519c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13374, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "新品", "is_correct": true, "explanation": "正确。新品指刚推出的新产品，与句中“比老款贵”的新旧比较相符。"}, {"text": "旧品", "is_correct": false, "explanation": "语义：旧品指旧有的产品，与句中“新品……比老款贵”的新品语境相反。"}, {"text": "废纸", "is_correct": false, "explanation": "语义：废纸是没用的东西，不会和老款比价格，也没人愿意买。"}, {"text": "赠品", "is_correct": false, "explanation": "语义：赠品是免费附送的东西，没有可比较的售价，与句中语境不符。"}], "explanations": {"新品": "正确。新品指刚推出的新产品，与句中“比老款贵”的新旧比较相符。", "旧品": "语义：旧品指旧有的产品，与句中“新品……比老款贵”的新品语境相反。", "废纸": "语义：废纸是没用的东西，不会和老款比价格，也没人愿意买。", "赠品": "语义：赠品是免费附送的东西，没有可比较的售价，与句中语境不符。"}, "sentence_index": 0, "correct_answer": "新品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司今年招了很多新品。", "explanation": "这里应该用〈新人〉。“新品”指新推出的商品，不能指新来的员工。"}, {"text": "我们班来了两个新品，是刚转来的同学。", "explanation": "这里应该用〈新同学〉。“新品”指新推出的商品，不能指人。"}, {"text": "今天的新品说明天会下雨。", "explanation": "这里应该用〈新闻〉。“新品”指新推出的商品，不是消息报道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c647000-6596-4914-878e-6fa34e140682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13374, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "新品", "is_correct": true, "explanation": "新品是刚推出的商品，货架旁写“刚上市”，语义吻合。"}, {"text": "旧货", "is_correct": false, "explanation": "语义：旧货是陈旧或二手的东西，与“刚上市”矛盾。"}, {"text": "滞销品", "is_correct": false, "explanation": "语义：滞销品卖不出去，与“刚上市”的标示矛盾。"}, {"text": "库存", "is_correct": false, "explanation": "搭配：库存指仓库里的存货，不会陈列在超市货架旁边。"}], "explanations": {"新品": "新品是刚推出的商品，货架旁写“刚上市”，语义吻合。", "旧货": "语义：旧货是陈旧或二手的东西，与“刚上市”矛盾。", "滞销品": "语义：滞销品卖不出去，与“刚上市”的标示矛盾。", "库存": "搭配：库存指仓库里的存货，不会陈列在超市货架旁边。"}, "sentence_index": 6, "correct_answer": "新品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们家刚添了一个新品，是个小弟弟。", "explanation": "这里应该用〈新生儿〉。“新品”指新推出的商品，不能指刚出生的婴儿。"}, {"text": "这座山上长满了新品，都是刚冒出来的小树。", "explanation": "这里应该用〈幼苗〉。“新品”指新推出的商品，不能指植物。"}, {"text": "这一窝小猫里，有一个新品，它最小。", "explanation": "这里应该用〈幼崽〉。“新品”指新推出的商品，不能指小动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c647000-6596-4914-878e-6fa34e140682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13374, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店周末推出了一只新品，很多人都来看。", "corrected_sentence": "这家店周末推出了一款新品，很多人都来看。", "error_description": "量词错误：“新品”是商品，应用量词“款”。错误形式是“一只新品”，“只”只用于动物；正确形式是“一款新品”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c647000-6596-4914-878e-6fa34e140682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13374, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两新品很受欢迎，大家都想买。", "corrected_sentence": "这两款新品很受欢迎，大家都想买。", "error_description": "量词缺失：“两”后面须有量词，“新品”前应加“款”。错误形式是“这两新品”，正确形式是“这两款新品”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c647000-6596-4914-878e-6fa34e140682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
