INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13377, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c647000-6596-4914-878e-6fa34e140682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13377, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "企业为满足消费者需求而进行的市场推广和销售活动。", "primary_collocate": null, "pronunciation": "yíng xiāo", "ipa": "iŋ˧˥ ɕiɑʊ˥", "syllable_count": 2, "sentences": [{"text": "快时尚品牌通过高频次的新品发布、低廉的价格策略与社交媒体营销，不断刺激消费者的购买欲望，使服装的生命周期急剧缩短。", "target_word": "营销", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家公司的营销做得很好。", "target_word": "营销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的营销能让更多人认识我们的产品。", "target_word": "营销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在一家公司做网络营销工作。", "target_word": "营销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司今年的营销计划已经定好了。", "target_word": "营销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小店也需要一些简单的营销办法。", "target_word": "营销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对营销很有兴趣。", "target_word": "营销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次营销活动吸引了很多年轻人。", "target_word": "营销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要重新想一下营销的办法。", "target_word": "营销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视广告是传统营销的一种方式。", "target_word": "营销", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "营销策略", "label": "复合"}, {"form": "营销活动", "label": "复合"}, {"form": "營銷", "label": "繁体"}], "register": "中性", "sense_fingerprint": "企业的市场推广和销售活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae3c29d2-8b53-4786-b4aa-4309f48b519c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13377, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "营销", "is_correct": true, "explanation": "正确。与“社交媒体”并列，指企业借社交媒体推广、促销产品，符合句意。"}, {"text": "教育", "is_correct": false, "explanation": "语义：“教育”指知识的传授，不能与“新品发布”“价格策略”并列，作为刺激购买欲望的手段。"}, {"text": "物流", "is_correct": false, "explanation": "搭配：“物流”指货物运输，不说“与社交媒体物流”，也不属于促销手段。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”与前文的促销手段无关，不能刺激消费者的购买欲望。"}], "explanations": {"营销": "正确。与“社交媒体”并列，指企业借社交媒体推广、促销产品，符合句意。", "教育": "语义：“教育”指知识的传授，不能与“新品发布”“价格策略”并列，作为刺激购买欲望的手段。", "物流": "搭配：“物流”指货物运输，不说“与社交媒体物流”，也不属于促销手段。", "天气": "语义：“天气”与前文的促销手段无关，不能刺激消费者的购买欲望。"}, "sentence_index": 0, "correct_answer": "营销"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这款手机的营销很圆，拿在手里很舒服。", "explanation": "这里应该用〈外形〉。营销是推广和销售的活动，没有形状；说手机外形圆、拿着舒服要用外形。"}, {"text": "这家公司的营销很会游泳。", "explanation": "这里的“营销”被当成了会游泳的人，应用〈员工〉。营销是推广和销售的活动，本身不会游泳；说人会游泳要用员工。"}, {"text": "我们公司想出了一把新营销。", "explanation": "这里应该用〈种〉。“把”用于有柄的器具，不用于营销这类抽象活动；说一种营销方式更自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c647000-6596-4914-878e-6fa34e140682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13377, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "营销", "is_correct": true, "explanation": "正确。“对……很有兴趣”可以接领域或活动，“营销”符合句意。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：“感冒”是疾病，人不会把它当作“很有兴趣”的对象。"}, {"text": "车祸", "is_correct": false, "explanation": "语义：“车祸”是伤亡事故，不能作为人感兴趣的对象，语气也不当。"}, {"text": "失眠", "is_correct": false, "explanation": "搭配：“对……很有兴趣”一般接事物或活动，“失眠”是身体状态，不能作兴趣的对象。"}], "explanations": {"营销": "正确。“对……很有兴趣”可以接领域或活动，“营销”符合句意。", "感冒": "语义：“感冒”是疾病，人不会把它当作“很有兴趣”的对象。", "车祸": "语义：“车祸”是伤亡事故，不能作为人感兴趣的对象，语气也不当。", "失眠": "搭配：“对……很有兴趣”一般接事物或活动，“失眠”是身体状态，不能作兴趣的对象。"}, "sentence_index": 6, "correct_answer": "营销"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司今年的营销很高兴。", "explanation": "这里应该用〈员工〉。营销是推广和销售的活动，不会感到高兴；说人高兴要用员工。"}, {"text": "这款手机的营销很重，我拿不动。", "explanation": "这里应该用〈重量〉。营销是推广和销售的活动，没有重量；说东西重要用重量。"}, {"text": "这是传统的一条营销。", "explanation": "这里应该用〈种〉。“条”用于细长的东西，不用于营销这类抽象活动；说一种传统营销更自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c647000-6596-4914-878e-6fa34e140682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13377, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把营销很有效。", "corrected_sentence": "这种营销很有效。", "error_description": "量词错误：营销是抽象活动，应用量词“种”，不能用“把”（“把”用于有柄的器具）。正确说法：这种营销很有效。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c647000-6596-4914-878e-6fa34e140682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13377, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她营销很感兴趣。", "corrected_sentence": "她对营销很感兴趣。", "error_description": "漏掉介词“对”：“感兴趣”的对象要由“对”引出，应说“她对营销很感兴趣”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c647000-6596-4914-878e-6fa34e140682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
