INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13378, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "作用于生物体或事物，使其产生反应、感受或情绪上的激动。", "primary_collocate": null, "pronunciation": "cì jī", "ipa": "tsʰɨ˥˩ tɕi˥", "syllable_count": 2, "sentences": [{"text": "快时尚品牌通过高频次的新品发布、低廉的价格策略与社交媒体营销，不断刺激消费者的购买欲望，使服装的生命周期急剧缩短。", "target_word": "刺激", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "价格下降刺激了人们的消费。", "target_word": "刺激", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冷水会刺激皮肤。", "target_word": "刺激", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "辣椒太辣，会刺激胃。", "target_word": "刺激", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个坏消息刺激了他，他开始努力学习。", "target_word": "刺激", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府想用新办法刺激经济。", "target_word": "刺激", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "强烈的光会刺激眼睛。", "target_word": "刺激", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打折活动刺激了顾客的购买欲望。", "target_word": "刺激", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "烟味刺激着我的鼻子。", "target_word": "刺激", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的话刺激他更加努力。", "target_word": "刺激", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "刺激了", "label": "体标"}, {"form": "刺激着", "label": "体标"}, {"form": "刺激性", "label": "复合"}], "register": "中性", "sense_fingerprint": "作用于人或事物，引起反应或情绪", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae3c29d2-8b53-4786-b4aa-4309f48b519c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13378, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "刺激", "is_correct": true, "explanation": "正确。“不断刺激消费者的购买欲望”表示促使其产生购买欲，与促销语境相合。"}, {"text": "抑制", "is_correct": false, "explanation": "语义：“抑制”是压制，与前文促销使购买欲增强的语境相反。"}, {"text": "修复", "is_correct": false, "explanation": "语义：“修复”用于修理损坏之物，不能用于购买欲望。"}, {"text": "赠送", "is_correct": false, "explanation": "搭配：“赠送”后接的是物品，不说“赠送消费者的购买欲望”。"}], "explanations": {"刺激": "正确。“不断刺激消费者的购买欲望”表示促使其产生购买欲，与促销语境相合。", "抑制": "语义：“抑制”是压制，与前文促销使购买欲增强的语境相反。", "修复": "语义：“修复”用于修理损坏之物，不能用于购买欲望。", "赠送": "搭配：“赠送”后接的是物品，不说“赠送消费者的购买欲望”。"}, "sentence_index": 0, "correct_answer": "刺激"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种药能刺激胃病。", "explanation": "这里应该用〈治疗〉。刺激是引起反应，不能用来对付疾病；治疗胃病要用治疗。"}, {"text": "止痛药能刺激疼痛。", "explanation": "这里应该用〈消除〉。刺激不能消除疼痛；止痛药是消除疼痛，要用消除。"}, {"text": "他很快刺激了那张桌子。", "explanation": "这里应该用〈擦〉。刺激用于引起生物的反应或作用，不能用来描述对桌子的动作；擦桌子要用擦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c647000-6596-4914-878e-6fa34e140682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13378, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "刺激", "is_correct": true, "explanation": "正确。“强烈的光会刺激眼睛”表示光引起眼睛的反应，符合句意。"}, {"text": "保护", "is_correct": false, "explanation": "语义：强烈的光不会保护眼睛，与句意相反。"}, {"text": "擦", "is_correct": false, "explanation": "语义：光不能用来“擦”眼睛，与句意不合。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”的对象是景物或艺术，不说“欣赏眼睛”。"}], "explanations": {"刺激": "正确。“强烈的光会刺激眼睛”表示光引起眼睛的反应，符合句意。", "保护": "语义：强烈的光不会保护眼睛，与句意相反。", "擦": "语义：光不能用来“擦”眼睛，与句意不合。", "欣赏": "搭配：“欣赏”的对象是景物或艺术，不说“欣赏眼睛”。"}, "sentence_index": 6, "correct_answer": "刺激"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈细心刺激生病的孩子。", "explanation": "这里应该用〈照顾〉。刺激是引起反应或作用，不能用来对待病人；照顾生病的孩子要用照顾。"}, {"text": "他刺激了冰箱里的饮料。", "explanation": "这里应该用〈冰镇〉。刺激是引起反应或作用，不能用来指给饮料降温；让饮料变凉要用冰镇。"}, {"text": "吸烟刺激健康。", "explanation": "这里应该用〈损害〉。刺激指引起反应，不能用来表示健康受到的伤害；说损害健康要用损害。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c647000-6596-4914-878e-6fa34e140682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13378, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨天的辣椒刺激了着我的胃。", "corrected_sentence": "昨天的辣椒刺激了我的胃。", "error_description": "体标错误：“了”与“着”不能同时标在同一个动词上，一句中只能用其一。应只用“了”，正确说法：昨天的辣椒刺激了我的胃。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c647000-6596-4914-878e-6fa34e140682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13378, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次降价把顾客的购买欲望刺激。", "corrected_sentence": "这次降价把顾客的购买欲望刺激了起来。", "error_description": "把字句错误：“把”字句中的动词“刺激”不能单独结尾，后面要有补充成分，如“了起来”。正确说法：这次降价把顾客的购买欲望刺激了起来。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c647000-6596-4914-878e-6fa34e140682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13379, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "缓慢", "is_correct": true, "explanation": "正确。“缓慢”与“急剧”反义，指变化速度慢、程度轻。"}, {"text": "清楚", "is_correct": false, "explanation": "语义：“清楚”形容明白、不模糊，与“急剧”的变化义无关。"}, {"text": "慷慨", "is_correct": false, "explanation": "语义：“慷慨”形容大方，与“急剧”的变化速度和程度无关。"}, {"text": "丰富", "is_correct": false, "explanation": "语义：“丰富”形容种类或数量多，与“急剧”的变化义无关。"}], "correct_answer": "缓慢", "explanations": {"缓慢": "正确。“缓慢”与“急剧”反义，指变化速度慢、程度轻。", "清楚": "语义：“清楚”形容明白、不模糊，与“急剧”的变化义无关。", "慷慨": "语义：“慷慨”形容大方，与“急剧”的变化速度和程度无关。", "丰富": "语义：“丰富”形容种类或数量多，与“急剧”的变化义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '721f3fbb-cfc5-4b10-8a1a-9a9c2a0e5c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13379, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "缓慢", "is_correct": true, "explanation": "正确。“缓慢”与“急剧”反义，指变化速度慢、程度轻。"}, {"text": "平安", "is_correct": false, "explanation": "语义：“平安”形容没有危险，与“急剧”的变化义无关。"}, {"text": "善良", "is_correct": false, "explanation": "语义：“善良”形容品性，与“急剧”无关。"}, {"text": "悠久", "is_correct": false, "explanation": "语义：“悠久”形容历史长，与“急剧”的变化义无关。"}], "correct_answer": "缓慢", "explanations": {"缓慢": "正确。“缓慢”与“急剧”反义，指变化速度慢、程度轻。", "平安": "语义：“平安”形容没有危险，与“急剧”的变化义无关。", "善良": "语义：“善良”形容品性，与“急剧”无关。", "悠久": "语义：“悠久”形容历史长，与“急剧”的变化义无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '721f3fbb-cfc5-4b10-8a1a-9a9c2a0e5c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13379, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容变化速度非常快、程度非常深。", "primary_collocate": null, "pronunciation": "jí jù", "ipa": "tɕi˧˥ tɕy˥˩", "syllable_count": 2, "sentences": [{"text": "快时尚品牌通过高频次的新品发布、低廉的价格策略与社交媒体营销，不断刺激消费者的购买欲望，使服装的生命周期急剧缩短。", "target_word": "急剧", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "天气变冷，气温急剧下降了。", "target_word": "急剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年，城市里的人口急剧增加。", "target_word": "急剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到那个坏消息，他的心跳急剧加快。", "target_word": "急剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，河里的水位急剧上升。", "target_word": "急剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机普及后，写信的人急剧减少了。", "target_word": "急剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，病人的病情急剧恶化了。", "target_word": "急剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一到冬天，这里的游客就急剧减少。", "target_word": "急剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买房子的人多了，房价急剧上涨。", "target_word": "急剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司换了老板，工作压力急剧增大。", "target_word": "急剧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "修饰数量、温度、状态等的变化，表示变化又快又大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a346198f-e365-43d8-90e1-ea9dbd7f312a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13379, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "急剧", "is_correct": true, "explanation": "正确。“急剧”指变化速度非常快、程度非常深。"}, {"text": "机具", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是机器和工具。"}, {"text": "积聚", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是逐渐聚集。"}, {"text": "几句", "is_correct": false, "explanation": "jǐ（第三声）与 jí（第二声）声调不同，意思是几个句子。"}], "explanations": {"急剧": "正确。“急剧”指变化速度非常快、程度非常深。", "机具": "jī（第一声）与 jí（第二声）声调不同，意思是机器和工具。", "积聚": "jī（第一声）与 jí（第二声）声调不同，意思是逐渐聚集。", "几句": "jǐ（第三声）与 jí（第二声）声调不同，意思是几个句子。"}, "sentence_index": null, "correct_answer": "急剧"}, "level_3": {"options": [{"text": "急剧", "is_correct": true, "explanation": "正确。“急剧”表示变化快、程度深，与“缩短”的剧烈变化相符。"}, {"text": "急忙", "is_correct": false, "explanation": "搭配：“急忙”修饰人的匆忙动作，不能修饰“生命周期”这类变化过程。"}, {"text": "顺便", "is_correct": false, "explanation": "语义：“顺便”表示附带做某事，与“使……缩短”的因果结果不符。"}, {"text": "亲自", "is_correct": false, "explanation": "搭配：“亲自”要求有意愿的人去做，“生命周期”不能亲自缩短。"}], "explanations": {"急剧": "正确。“急剧”表示变化快、程度深，与“缩短”的剧烈变化相符。", "急忙": "搭配：“急忙”修饰人的匆忙动作，不能修饰“生命周期”这类变化过程。", "顺便": "语义：“顺便”表示附带做某事，与“使……缩短”的因果结果不符。", "亲自": "搭配：“亲自”要求有意愿的人去做，“生命周期”不能亲自缩短。"}, "sentence_index": 0, "correct_answer": "急剧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他急剧走出了房间。", "explanation": "这里应该用〈迅速〉。“急剧”强调变化的速度与程度，描述人的动作要用“迅速”。"}, {"text": "我急剧告诉了大家这个消息。", "explanation": "这里应该用〈立刻〉。“急剧”只修饰变化过程，表示马上去做某事要用“立刻”。"}, {"text": "他急剧抬起了头。", "explanation": "这里应该用〈猛然〉。“急剧”形容变化的快慢和程度，不能修饰“抬头”这样的短暂动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '721f3fbb-cfc5-4b10-8a1a-9a9c2a0e5c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13379, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "急剧", "is_correct": true, "explanation": "正确。“急剧”表示病情变化快、程度深，与“恶化”相符。"}, {"text": "特意", "is_correct": false, "explanation": "语义：“特意”指有意去做某事，病情不会特意恶化。"}, {"text": "匆匆", "is_correct": false, "explanation": "搭配：“匆匆”形容匆忙地做事，不能修饰“恶化”这种状态。"}, {"text": "纷纷", "is_correct": false, "explanation": "配价：“纷纷”要求多个主体同时出现，“病情”只有一个。"}], "explanations": {"急剧": "正确。“急剧”表示病情变化快、程度深，与“恶化”相符。", "特意": "语义：“特意”指有意去做某事，病情不会特意恶化。", "匆匆": "搭配：“匆匆”形容匆忙地做事，不能修饰“恶化”这种状态。", "纷纷": "配价：“纷纷”要求多个主体同时出现，“病情”只有一个。"}, "sentence_index": 6, "correct_answer": "急剧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他患的是急剧肠炎。", "explanation": "这里应该用〈急性〉。“急剧”形容变化的快慢和程度，描述起病突然的病要用“急性”。"}, {"text": "他是一个急剧的人。", "explanation": "这里应该用〈急躁〉。“急剧”形容变化的速度和程度，不能描述人的性情；说人性子急要用“急躁”。"}, {"text": "他投来急剧的目光。", "explanation": "这里应该用〈急切〉。“急剧”形容变化，不能修饰目光；表示心情迫切要用“急切”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '721f3fbb-cfc5-4b10-8a1a-9a9c2a0e5c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13379, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "最近，物价急剧了上涨。", "corrected_sentence": "最近，物价急剧上涨。", "error_description": "“急剧”是修饰“上涨”的状语，后面不能加“了”。去掉“急剧”后面的“了”，应为“最近，物价急剧上涨。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '721f3fbb-cfc5-4b10-8a1a-9a9c2a0e5c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13379, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "油价急剧得上涨了。", "corrected_sentence": "油价急剧上涨了。", "error_description": "“急剧”作状语修饰动词时，后面可直接接动词或用“地”，不能用补语标记“得”。“急剧得上涨”错，应为“急剧上涨”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '721f3fbb-cfc5-4b10-8a1a-9a9c2a0e5c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
