INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13380, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "衣服和鞋袜等的总称，一般指衣服。", "primary_collocate": null, "pronunciation": "yī wù", "ipa": "i˥ u˥˩", "syllable_count": 2, "sentences": [{"text": "衣物从“耐用品”异化为“一次性消费品”，大量未被穿着或仅短时间使用的服装最终被填埋或焚烧，形成巨大的资源浪费。", "target_word": "衣物", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "下雨了，快把阳台上的衣物收进来。", "target_word": "衣物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天的衣物太多，我的柜子放不下。", "target_word": "衣物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把脏衣物放进了洗衣机里。", "target_word": "衣物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行的时候，我只带了几件衣物。", "target_word": "衣物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈每个周末都洗全家人的衣物。", "target_word": "衣物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店卖男女老少的各种衣物。", "target_word": "衣物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震后，志愿者给灾区送去了衣物和食品。", "target_word": "衣物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天冷了，夏天的衣物要收到箱子里。", "target_word": "衣物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把不穿的衣物送给了朋友。", "target_word": "衣物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "衣服、鞋袜等穿戴用品的总称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a346198f-e365-43d8-90e1-ea9dbd7f312a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13380, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "衣物", "is_correct": true, "explanation": "正确。“衣物”指衣服、鞋袜等穿戴用品的总称。"}, {"text": "遗物", "is_correct": false, "explanation": "yí（第二声）与 yī（第一声）声调不同，意思是死者留下的物品。"}, {"text": "异物", "is_correct": false, "explanation": "yì（第四声）与 yī（第一声）声调不同，意思是混入其中的外来物体。"}, {"text": "义务", "is_correct": false, "explanation": "yì（第四声）与 yī（第一声）声调不同，意思是应尽的责任。"}], "explanations": {"衣物": "正确。“衣物”指衣服、鞋袜等穿戴用品的总称。", "遗物": "yí（第二声）与 yī（第一声）声调不同，意思是死者留下的物品。", "异物": "yì（第四声）与 yī（第一声）声调不同，意思是混入其中的外来物体。", "义务": "yì（第四声）与 yī（第一声）声调不同，意思是应尽的责任。"}, "sentence_index": null, "correct_answer": "衣物"}, "level_3": {"options": [{"text": "衣物", "is_correct": true, "explanation": "正确。“衣物”指穿戴用品，与后文“穿着”和“服装”相符。"}, {"text": "家具", "is_correct": false, "explanation": "语义：“家具”不是穿戴用品，与后文“未被穿着”的服装不符。"}, {"text": "食物", "is_correct": false, "explanation": "搭配：“未被穿着”只能用于穿戴用品，不能用于食物。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：“饮料”不是穿戴用品，与“服装”和“穿着”的描述相矛盾。"}], "explanations": {"衣物": "正确。“衣物”指穿戴用品，与后文“穿着”和“服装”相符。", "家具": "语义：“家具”不是穿戴用品，与后文“未被穿着”的服装不符。", "食物": "搭配：“未被穿着”只能用于穿戴用品，不能用于食物。", "饮料": "语义：“饮料”不是穿戴用品，与“服装”和“穿着”的描述相矛盾。"}, "sentence_index": 0, "correct_answer": "衣物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一本衣物。", "explanation": "这里应该用〈件〉。“本”用于书籍、本子，衣物应用“件”或“套”。"}, {"text": "我买了一座衣物。", "explanation": "这里应该用〈件〉。“座”用于山、楼等大型物体，衣物应用“件”或“套”。"}, {"text": "我买了一朵衣物。", "explanation": "这里应该用〈件〉。“朵”用于花、云朵等，衣物应用“件”或“套”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '721f3fbb-cfc5-4b10-8a1a-9a9c2a0e5c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13380, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "衣物", "is_correct": true, "explanation": "正确。“衣物”是可售的穿戴用品，与“卖”和“各种”相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“卖”的对象是商品，“天气”不能拿来卖。"}, {"text": "病情", "is_correct": false, "explanation": "搭配：“各种”修饰可售物品，“病情”不能用“卖”。"}, {"text": "情绪", "is_correct": false, "explanation": "语义：“情绪”是人的心理状态，不能像商品一样卖给男女老少。"}], "explanations": {"衣物": "正确。“衣物”是可售的穿戴用品，与“卖”和“各种”相符。", "天气": "语义：“卖”的对象是商品，“天气”不能拿来卖。", "病情": "搭配：“各种”修饰可售物品，“病情”不能用“卖”。", "情绪": "语义：“情绪”是人的心理状态，不能像商品一样卖给男女老少。"}, "sentence_index": 6, "correct_answer": "衣物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了一颗衣物。", "explanation": "这里应该用〈件〉。“颗”用于粒状的东西，衣物应用“件”或“套”。"}, {"text": "她买了一片衣物。", "explanation": "这里应该用〈件〉。“片”用于薄而平的东西，衣物应用“件”或“套”。"}, {"text": "他买了一根衣物。", "explanation": "这里应该用〈件〉。“根”用于细长的东西，衣物应用“件”或“套”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '721f3fbb-cfc5-4b10-8a1a-9a9c2a0e5c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13380, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了三只衣物。", "corrected_sentence": "我买了三件衣物。", "error_description": "量词“只”不能计量“衣物”，“我买了三只衣物”错，应为“我买了三件衣物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '721f3fbb-cfc5-4b10-8a1a-9a9c2a0e5c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13380, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把旧衣物们捐给了山区。", "corrected_sentence": "我们把旧衣物捐给了山区。", "error_description": "“们”只加在指人的名词或代词后表示复数，“衣物”指物品，不能说“旧衣物们”。应为“旧衣物”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '721f3fbb-cfc5-4b10-8a1a-9a9c2a0e5c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
