INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13381, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '721f3fbb-cfc5-4b10-8a1a-9a9c2a0e5c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13381, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指能够使用较长时间、不易损坏的消费品。", "primary_collocate": null, "pronunciation": "nài yòng pǐn", "ipa": "naɪ˥˩ jʊŋ˥˩ pʰin˨˩˦", "syllable_count": 3, "sentences": [{"text": "衣物从“耐用品”异化为“一次性消费品”，大量未被穿着或仅短时间使用的服装最终被填埋或焚烧，形成巨大的资源浪费。", "target_word": "耐用品", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "冰箱和洗衣机都是家里的耐用品。", "target_word": "耐用品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "耐用品虽然贵，但是可以用很多年。", "target_word": "耐用品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买耐用品的时候，质量比价格更重要。", "target_word": "耐用品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店主要卖家具这类耐用品。", "target_word": "耐用品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视是耐用品，不用常常换。", "target_word": "耐用品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一年只买一两件耐用品。", "target_word": "耐用品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们收入高了，就愿意买更好的耐用品。", "target_word": "耐用品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车算不算耐用品？", "target_word": "耐用品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬新家以后，我们先买了几件耐用品。", "target_word": "耐用品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "可长期使用、不易坏的消费品，如家具、家电", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a346198f-e365-43d8-90e1-ea9dbd7f312a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13381, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "耐用品", "is_correct": true, "explanation": "“耐用品”指能长期使用的消费品，与后文“一次性消费品”形成对比，说明衣物原本是耐用的。"}, {"text": "一次性用品", "is_correct": false, "explanation": "语义：“一次性用品”与后文“一次性消费品”意思相同，“从一次性用品异化为一次性消费品”自相矛盾。"}, {"text": "食品", "is_correct": false, "explanation": "语义：衣物不可能从食品异化而来，“食品”与“衣物”不属于同类。"}, {"text": "纸巾", "is_correct": false, "explanation": "语义：“纸巾”本身就是一次性用品，不曾是耐用品，不能说“从纸巾异化为一次性消费品”。"}], "explanations": {"耐用品": "“耐用品”指能长期使用的消费品，与后文“一次性消费品”形成对比，说明衣物原本是耐用的。", "一次性用品": "语义：“一次性用品”与后文“一次性消费品”意思相同，“从一次性用品异化为一次性消费品”自相矛盾。", "食品": "语义：衣物不可能从食品异化而来，“食品”与“衣物”不属于同类。", "纸巾": "语义：“纸巾”本身就是一次性用品，不曾是耐用品，不能说“从纸巾异化为一次性消费品”。"}, "sentence_index": 0, "correct_answer": "耐用品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每个月都要买很多耐用品，比如牛奶和纸巾。", "explanation": "这里应该用〈消耗品〉。牛奶和纸巾用完就没了，属于消耗品；耐用品指能长期使用的东西。"}, {"text": "这位新来的工人是我们公司的耐用品。", "explanation": "这里误把“耐用品”用来形容人。“耐用品”指能长期使用、不易损坏的消费品，只能指物品；这里是把“耐用”的特点套到了人身上，不符合该词的用法。"}, {"text": "我们每天都要给办公室买很多耐用品，比如墨粉和打印纸。", "explanation": "这里应该用〈易耗品〉。墨粉和打印纸消耗很快，需要不断补充，属于易耗品；耐用品指能长期使用的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '721f3fbb-cfc5-4b10-8a1a-9a9c2a0e5c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13381, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "耐用品", "is_correct": true, "explanation": "“耐用品”是可以长期使用的物品，可以用“件”来计数，句意通顺。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是可以买来、用“件”计数的东西。"}, {"text": "水果", "is_correct": false, "explanation": "搭配：“件”一般不用来计数水果，应说“个”或“斤”。"}, {"text": "感情", "is_correct": false, "explanation": "语义：感情不能像商品一样买来，与“买”的意思不符。"}], "explanations": {"耐用品": "“耐用品”是可以长期使用的物品，可以用“件”来计数，句意通顺。", "空气": "语义：空气不是可以买来、用“件”计数的东西。", "水果": "搭配：“件”一般不用来计数水果，应说“个”或“斤”。", "感情": "语义：感情不能像商品一样买来，与“买”的意思不符。"}, "sentence_index": 6, "correct_answer": "耐用品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天早上都要去超市买耐用品，比如牙膏和洗发水。", "explanation": "这里应该用〈日用品〉。牙膏、洗发水每天都要用，用得快，需要经常买，属于日用品；“耐用品”指能长期使用、不易损坏的东西。"}, {"text": "这家超市的耐用品都是新鲜的，每天早上进货。", "explanation": "这里应该用〈食品〉。〈食品〉才会新鲜、每天进货；“耐用品”指能长期使用、不易损坏的消费品，不能用“新鲜”来形容。"}, {"text": "这些耐用品用完就扔，很方便。", "explanation": "这里应该用〈一次性用品〉。用完就扔的东西是一次性用品，与“耐用”的意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '721f3fbb-cfc5-4b10-8a1a-9a9c2a0e5c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13381, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本耐用品都很贵。", "corrected_sentence": "这些耐用品都很贵。", "error_description": "量词错误：“本”只用于书册等，不能计量“耐用品”，应改为“这些耐用品”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '721f3fbb-cfc5-4b10-8a1a-9a9c2a0e5c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
